import { GRID, PHYSICS, COLORS, POISONED_WATER_DURATION } from '../game/GameConfig.js';
import { planeOf, inSamePlane, objectOnPlane, tagInteriorPlane, isInteriorActive, updateProjectileTunnelPlane } from './PlaneSystem.js';
import { applyExitMutatingSwordHit } from './ExitSystem.js';
import { BoomerangMechanic } from './BoomerangMechanic.js';
import { WallRicochetMechanic } from './WallRicochetMechanic.js';
import { updateStuckArrows } from './StuckArrowMechanic.js';
import { WaterLavaHitMechanic } from './WaterLavaHitMechanic.js';
import { BackgroundObject } from '../entities/BackgroundObject.js';
import { GameAnimalMechanic } from '../entities/enemyMechanics/GameAnimalMechanic.js';
import { SniperMechanic } from '../entities/enemyMechanics/SniperMechanic.js';
import { ThiefMechanic } from '../entities/enemyMechanics/ThiefMechanic.js';
import { ReflectShieldMechanic } from '../entities/enemyMechanics/ReflectShieldMechanic.js';
import { ParryMechanic, PARRY_REFLECT_FRACTION } from '../entities/enemyMechanics/ParryMechanic.js';
import { queueDamageNumber as queueDamageNumberImpl, ageDamageTextQueue, reportDamageResult as reportDamageResultImpl } from './DamageNumberQueue.js';
import { applyTargetOverrides as applyTargetOverridesImpl } from './enemyTargeting.js';
import { updateEnemyMeleeAttack, resolveEnemyAttack, attackHitsBox, retireAfterTest } from '../game/Telegraph.js';
import { conductElectricity as conductElectricityImpl } from './ElectricConduction.js';
import { checkProximity as checkProximityImpl, applyAOEStatus as applyAOEStatusImpl, createExplosion as createExplosionImpl, detonateBombArrow } from './ExplosionEffects.js';
import { updateRollDamage as updateRollDamageImpl } from './RollDamageMechanic.js';
import { TongueAttackSystem } from './TongueAttackSystem.js';
import { createSplitProjectiles } from './SplitProjectiles.js';
import { tagCharmedProjectile, resolveCharmedMelee, resolveCharmedProjectile, resolveEnemySap } from './charmHits.js';
import { applyExtraOnHitEffects, applyOnHitStatusEffect } from './ExtraOnHitEffects.js';
import { applyMeleeStatusDamageBonus, getMeleeStatusBonusIndicator } from './MeleeStatusBonuses.js';
import { applyKeenAim } from './KeenAim.js';
import { projectileSailsOver, tagLaunchPit } from './pits.js';
import { vaultWallBlocksReach } from './vaultWalls.js';
import { knockbackTakenScale } from '../entities/knockbackTaken.js';

// Default maximum travel distance (in pixels) for gun bullets. Roughly 2/3 of a
// room — keeps cross-room sniping in check while still feeling powerful.
const DEFAULT_BULLET_RANGE = GRID.CELL_SIZE * 20;

export class CombatSystem {
  constructor(physicsSystem) {
    this.physicsSystem = physicsSystem;
    this.audioSystem = null; // wired by main.js after construction
    this.game = null;        // wired by main.js after construction; used for hutPlane tagging
    this.projectiles = [];
    this.enemyProjectiles = [];
    this.meleeAttacks = [];
    this.enemyMeleeAttacks = [];
    this.pendingMeleeAttacks = [];         // Player melee attacks waiting to spawn
    this.pendingEnemyProjectiles = [];     // Enemy projectiles waiting on delay
    this.damageNumbers = [];
    this.objectDestroyEvents = []; // { obj, effect } collected each frame
    this.impactEffects = [];       // { x, y, onHit, color } — elemental hit sparks
    this.newSteamClouds = [];      // { x, y, radius, timer } — generated by fire+water
    this.stuckArrows = [];         // { char, position, stuckTo, offset, color, isBurning }
    this.polymorphEvents = [];     // { enemy, outcome } — polymorph transformations to process
    this.aoeEffects = [];          // { type, x, y, radius, timer, color } — AOE visual effects (wand explosions)
    this.tongueAttackSystem = new TongueAttackSystem(this); // frog tongue: extend/hold/retract + hit resolution
    this.chainArcs = [];           // { x1, y1, x2, y2, color, timer, duration } — chain lightning visuals
    this.pendingDamageTexts = [];  // staggered floating text queue, see queueDamageNumber()
    this._textCooldowns = new Map(); // target (player) -> seconds until its next queued text can show
  }

  // Route object ignitions through FireSystem (owns spread + render dirty flag).
  // Falls back to direct ignite for headless harnesses where game isn't wired.
  _ignite(obj, duration = 5.0) {
    return this.game?.fireSystem
      ? this.game.fireSystem.igniteObject(obj, duration)
      : obj.ignite(duration);
  }

  /**
   * Per-frame target overrides, applied by the canonical enemy tick BEFORE
   * enemy.update() (bug #92 — targeting must precede the single tick).
   * Behavior lives in enemyTargeting.js (enemy-AI targeting, not combat
   * resolution); this delegate keeps the three call sites unchanged.
   * Returns true when it set the target (caller skips its own selection).
   */
  applyTargetOverrides(enemy, enemies, player, noiseSource = null) {
    return applyTargetOverridesImpl(enemy, enemies, player, noiseSource);
  }

  // Shared dodge/block/pierce/reflect damage-number reporting for enemy-initiated
  // hits that bypass the standard attack-object pipeline (sap, sniper beam/dagger).
  // See DamageNumberQueue.js for the full behavior — kept here as a thin
  // dispatch to stay under the architecture budget.
  _reportDamageResult(result, fallbackDamage, player, opts = {}) {
    return reportDamageResultImpl(this, result, fallbackDamage, player, opts);
  }

  // Staff-block-respecting damage application for enemy-initiated hits outside
  // the attack-object pipeline. Returns true if the hit killed the player.
  // `onLanded` runs only when the hit actually damaged a surviving player
  // (not blocked/dodged/immune) — the hook for riders like a sap tick's burn.
  _applyBlockableEnemyDamage(player, enemy, damage, damageSource, onLanded = null) {
    if (player.isStaffBlocking) {
      this.queueDamageNumber(player, 'BLOCK', player.position.x, player.position.y - GRID.CELL_SIZE, '#aaaaaa');
      return false;
    }
    const result = player.takeDamage(damage, damageSource);
    if (onLanded && result?.damaged) onLanded();
    return this._reportDamageResult(result, damage, player);
  }

  update(deltaTime, player, enemies, backgroundObjects = [], room = null) {
    // Red warrior damage roll: hits and knocks back enemies, smashes background objects
    this.updateRollDamage(player, enemies, backgroundObjects);

    // Update pending enemy projectiles (for delayed spawning like boss slam rings)
    for (let i = this.pendingEnemyProjectiles.length - 1; i >= 0; i--) {
      const pending = this.pendingEnemyProjectiles[i];
      pending.delay -= deltaTime;
      if (pending.delay <= 0) {
        // Launched now, so its height is fixed now (pits.js)
        tagLaunchPit(this.game?.activeRoom, pending, pending.owner);
        this.enemyProjectiles.push(pending);
        this.pendingEnemyProjectiles.splice(i, 1);
      }
    }

    // Update pending melee attacks (for delayed spawning like flail sweep)
    for (let i = this.pendingMeleeAttacks.length - 1; i >= 0; i--) {
      const pending = this.pendingMeleeAttacks[i];
      pending.delay -= deltaTime;

      if (pending.delay <= 0) {
        // Recalculate position from owner's current location so moving
        // multi-hit weapons (flail, arc, sweep, etc.) track the player
        const spawnPosition = (pending.relX !== undefined && pending.owner)
          ? { x: pending.owner.position.x + pending.relX, y: pending.owner.position.y + pending.relY }
          : pending.position;
        this.meleeAttacks.push({
          ...pending,
          position: spawnPosition,
          hasHit: false
        });
        this.pendingMeleeAttacks.splice(i, 1);
      }
    }

    // Update damage numbers
    for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
      const dmgNum = this.damageNumbers[i];

      dmgNum.timer += deltaTime;
      dmgNum.y -= dmgNum.riseSpeed * deltaTime;
      dmgNum.alpha = Math.max(0, 1 - (dmgNum.timer / dmgNum.duration));

      if (dmgNum.timer >= dmgNum.duration) {
        this.damageNumbers.splice(i, 1);
      }
    }

    // Staggered player combat text (CAN'T BLOCK/PIERCE/damage/heal) — see DamageNumberQueue.js.
    ageDamageTextQueue(this, deltaTime);

    // Update wand proximity failure indicators
    if (!this.wandProximityFailures) {
      this.wandProximityFailures = [];
    }
    for (let i = this.wandProximityFailures.length - 1; i >= 0; i--) {
      const failure = this.wandProximityFailures[i];
      failure.timer -= deltaTime;

      if (failure.timer <= 0) {
        this.wandProximityFailures.splice(i, 1);
      }
    }

    // Update AOE visual effects
    for (let i = this.aoeEffects.length - 1; i >= 0; i--) {
      const effect = this.aoeEffects[i];
      effect.timer -= deltaTime;

      if (effect.timer <= 0) {
        this.aoeEffects.splice(i, 1);
      }
    }

    // Update chain lightning arcs (short-lived visual fades)
    for (let i = this.chainArcs.length - 1; i >= 0; i--) {
      const arc = this.chainArcs[i];
      arc.timer -= deltaTime;
      if (arc.timer <= 0) {
        this.chainArcs.splice(i, 1);
      }
    }

    // Update projectiles
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const proj = this.projectiles[i];

      // Homing behavior
      if (proj.homing && enemies.length > 0) {
        let nearestEnemy = null;
        let nearestDist = Infinity;

        for (const enemy of enemies) {
          const dx = enemy.position.x - proj.position.x;
          const dy = enemy.position.y - proj.position.y;
          const dist = Math.sqrt(dx * dx + dy * dy);

          if (dist < nearestDist) {
            nearestEnemy = enemy;
            nearestDist = dist;
          }
        }

        if (nearestEnemy) {
          const dx = nearestEnemy.position.x - proj.position.x;
          const dy = nearestEnemy.position.y - proj.position.y;
          const angle = Math.atan2(dy, dx);
          const speed = Math.sqrt(proj.velocity.vx ** 2 + proj.velocity.vy ** 2);

          // Gradually turn towards target
          const turnRate = 3.0 * deltaTime;
          const currentAngle = Math.atan2(proj.velocity.vy, proj.velocity.vx);
          let angleDiff = angle - currentAngle;

          // Normalize angle difference
          while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
          while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

          const newAngle = currentAngle + angleDiff * turnRate;
          proj.velocity.vx = Math.cos(newAngle) * speed;
          proj.velocity.vy = Math.sin(newAngle) * speed;
          if (proj.drawAngle != null) proj.drawAngle = newAngle;
        }
      }

      // Apply deceleration to arrows (maintains speed initially, hard falloff at end)
      // Boomerangs skip deceleration — they maintain constant speed and return to player.
      if (proj.type === 'arrow' && !proj.boomerang) {
        // Store initial speed on first frame
        if (!proj.initialSpeed) {
          proj.initialSpeed = Math.sqrt(proj.velocity.vx ** 2 + proj.velocity.vy ** 2);
        }

        const speed = Math.sqrt(proj.velocity.vx ** 2 + proj.velocity.vy ** 2);

        if (speed > 0) {
          // Inverse decay: deceleration increases as arrow slows (hard falloff near end)
          const speedRatio = speed / proj.initialSpeed; // 1.0 at start, approaches 0 at end
          const decayStrength = Math.pow(1.0 - speedRatio, 2); // Gets stronger as arrow slows
          const baseDecay = 0.98; // Minimal decay at full speed
          const decayRate = baseDecay - (decayStrength * 0.15); // Max decay of 0.83 when nearly stopped

          const newSpeed = speed * Math.pow(decayRate, deltaTime * 60);

          // Apply deceleration along the velocity vector
          const scale = newSpeed / speed;
          proj.velocity.vx *= scale;
          proj.velocity.vy *= scale;

          // Arrow has stopped - create stuck arrow on ground
          if (newSpeed < 30) {
            if (proj.bombBlast) { detonateBombArrow(this.game, proj, enemies); this.projectiles.splice(i, 1); continue; }
            this.stuckArrows.push({
              char: proj.char,
              weaponChar: proj.weaponChar,
              stuckType: 'ground',
              pickupable: !!proj.weaponChar,
              position: { x: proj.position.x, y: proj.position.y },
              stuckTo: null, // Not stuck to anything, just on the ground
              offset: { x: 0, y: 0 },
              color: proj.color,
              isBurning: proj.onHit === 'burn',
              fireGenTimer: 0,
              lifetime: 8.0
            });
            this.projectiles.splice(i, 1);
            continue;
          }
        }
      }

      // Orbital looping bullets (e.g. Fester's Gun): velocity derived analytically so the
      // bullet revolves around a center point advancing along the straight firing line.
      if (proj.loopOmega) {
        const t = proj.loopTime;
        const { loopForward: fwd, loopPerp: perp, loopRadius: R, loopLinearSpeed: ls, loopOmega: omega } = proj;
        proj.velocity.vx = fwd.x * (ls + R * omega * Math.sin(omega * t)) + perp.x * R * omega * Math.cos(omega * t);
        proj.velocity.vy = fwd.y * (ls + R * omega * Math.sin(omega * t)) + perp.y * R * omega * Math.cos(omega * t);
        proj.drawAngle = Math.atan2(proj.velocity.vy, proj.velocity.vx);
        proj.loopTime += deltaTime;
      }

      if (proj.spinRate) proj.drawAngle += proj.spinRate * deltaTime; // Bolo Launcher's whirl

      // Boomerang flight: bounce-target homing, outbound timer, return-to-owner steering.
      if (proj.boomerang && BoomerangMechanic.updateFlight(proj, deltaTime, this)) {
        this.projectiles.splice(i, 1);
        continue;
      }

      // Wind Fields (Storm Eye) bend shots in flight
      this.game?.bossSystem?.windFieldSystem.pushProjectile(proj, deltaTime);

      // Move projectile
      proj.position.x += proj.velocity.vx * deltaTime;
      proj.position.y += proj.velocity.vy * deltaTime;

      // Distance cap (e.g. from rock ricochet) — despawn when exhausted
      if (proj.remainingDistance !== undefined) {
        const moveSpeed = Math.hypot(proj.velocity.vx, proj.velocity.vy);
        proj.remainingDistance -= moveSpeed * deltaTime;
        if (proj.remainingDistance <= 0) {
          this.projectiles.splice(i, 1);
          continue;
        }
      }

      // Update plane if in tunnel room
      if (room && room.tunnel && proj.plane !== undefined) {
        updateProjectileTunnelPlane(proj, room.tunnel);
      }

      // Check collision with room walls via collisionMap.
      // Ricochet projectiles skip this — they use checkRicochet() to bounce off
      // the room's border wall instead.
      // A raw hitsWall hit is tried against a tangential nudge first (see
      // WallRicochetMechanic.tryTangentialNudge) so a projectile merely flush
      // against a wall parallel to its flight path slides past instead of
      // registering a false collision; only a nudge-proof hit falls through
      // to the real wall-hit handling below.
      if (!proj.ricochet && WallRicochetMechanic.hitsWall(proj, room) &&
          !WallRicochetMechanic.tryTangentialNudge(proj, room)) {
        // Boomerangs bounce off walls into return mode instead of dying.
        if (proj.boomerang) {
          BoomerangMechanic.onWallHit(proj, deltaTime);
          continue;
        }
        // Bullets ricochet off interior structure walls (flat axis-aligned surfaces).
        // Border walls and out-of-grid still destroy. Fester's Gun's orbital-loop
        // bullets (loopOmega) are excluded — the analytic loop velocity recomputed
        // each frame fights the ricochet flip, so any wall kills the bullet instead.
        if (proj.type === 'bullet' && !proj.loopOmega && WallRicochetMechanic.tryStructureWallRicochet(proj, room, deltaTime, this)) {
          continue;
        }
        if (proj.bombBlast) { detonateBombArrow(this.game, proj, enemies); this.projectiles.splice(i, 1); continue; }
        // Arrows stick to walls on every layer — interiors included, where
        // _tagCombatHutPlane gives the stuck arrow its hutPlane so the
        // interior pass draws it.
        if (proj.type === 'arrow') {
          this.stuckArrows.push({
            char: proj.char,
            weaponChar: proj.weaponChar,
            stuckType: 'wall',
            pickupable: !!proj.weaponChar,
            position: { x: proj.position.x, y: proj.position.y },
            stuckTo: null,
            offset: { x: 0, y: 0 },
            color: proj.color,
            isBurning: proj.onHit === 'burn',
            fireGenTimer: 0,
            lifetime: 8.0
          });
        }
        this.projectiles.splice(i, 1);
        continue;
      }

      // Deflector triangles bend the bullet/arrow before any background-object
      // damage interaction can fire. Handled by cell occupancy (matches boulder
      // system) so the projectile no longer "hits" the deflector as a wall.
      if (this.game.boulderSystem?.redirectProjectile(proj)) continue;

      // Check collision with background objects
      let bgObjectHit = false;
      for (const obj of backgroundObjects) {
        if (obj.destroyed || obj.isRecipeSign) continue; // Skip destroyed and recipe signs
        if (proj.boomerang && proj._boomerangHitObjects?.has(obj)) continue; // already-struck switch — pass through
        if (!objectOnPlane(obj, planeOf(proj))) continue;

        if (this.checkProjectileCollisionWithObject(proj, obj)) {
          // Deflectors are routed above; skip the generic bullet-interaction path.
          if (obj.data?.boulderDeflector) continue;
          const result = obj.handleBulletCollision(proj);

          // Handle bullet behavior
          // Boomerangs ignore terrain slow (grass) — constant flight speed is core to the return loop.
          if (result.bulletBehavior === 'slow' && !proj.boomerang) {
            const mult = result.speedMultiplier !== undefined ? result.speedMultiplier : 0.5;
            if (result.speedMultiplier !== undefined) {
              // One-time slow per object (e.g. arrows through grass): only apply on first contact
              if (!proj.slowedByObjects) proj.slowedByObjects = new Set();
              if (!proj.slowedByObjects.has(obj)) {
                proj.slowedByObjects.add(obj);
                // Speed floor: grass clusters can't slow an arrow below 80% of its launch speed
                const currentSpeed = Math.hypot(proj.velocity.vx, proj.velocity.vy);
                const floorSpeed = (proj.initialSpeed || currentSpeed) * 0.80;
                if (currentSpeed * mult >= floorSpeed) {
                  proj.velocity.vx *= mult;
                  proj.velocity.vy *= mult;
                } else if (currentSpeed > floorSpeed) {
                  // Clamp to floor without overshooting
                  const scale = floorSpeed / currentSpeed;
                  proj.velocity.vx *= scale;
                  proj.velocity.vy *= scale;
                }
              }
            } else {
              proj.velocity.vx *= mult;
              proj.velocity.vy *= mult;
            }
          } else if (result.bulletBehavior === 'reflectBullet' || result.effect === 'reflectBullet') {
            // Reflect bullet
            this.reflectBullet(proj, obj);
          } else if (result.bulletBehavior === 'rockRicochet') {
            this.reflectBullet(proj, obj);
            // Halve the bullet's remaining travel range from this point
            const canvasW = GRID.COLS * GRID.CELL_SIZE;
            const canvasH = GRID.ROWS * GRID.CELL_SIZE;
            const vx = proj.velocity.vx;
            const vy = proj.velocity.vy;
            const tX = vx > 0 ? (canvasW - proj.position.x) / vx
                     : vx < 0 ? -proj.position.x / vx
                     : Infinity;
            const tY = vy > 0 ? (canvasH - proj.position.y) / vy
                     : vy < 0 ? -proj.position.y / vy
                     : Infinity;
            const speed = Math.hypot(vx, vy);
            const distToEdge = Math.min(tX, tY) * speed;
            const halved = isFinite(distToEdge) ? distToEdge * 0.5 : 0;
            proj.remainingDistance = proj.remainingDistance !== undefined
              ? Math.min(proj.remainingDistance, halved)
              : halved;
          }

          // Collect drop effects from destroyed objects
          if (result.effect && result.effect !== 'reflectBullet') {
            this.objectDestroyEvents.push({ obj, effect: result.effect });
          }

          // Chaff VFX when bullets or arrows hit grass (tall or cut) — 5% chance
          if ((proj.type === 'bullet' || proj.type === 'arrow') && (obj.char === '|' || obj.char === ',') && Math.random() < 0.05) {
            this.impactEffects.push({
              x: obj.position.x,
              y: obj.position.y,
              effect: 'chaff',
              color: '#667755'
            });
          }

          // Electric conduction (only for electric weapons)
          if (obj.isConductive() && proj.onHit === 'stun' && proj.electric) {
            const electricResult = this.conductElectricity(obj, proj.damage, enemies, player);
            if (electricResult?.playerDead) {
              return { playerDead: true };
            }
          }

          // Fire interactions — also spread to adjacent objects if this one is destroyed.
          // Ignitions route through FireSystem so the deterministic front + dirty flag own propagation.
          if (proj.onHit === 'burn' && obj.isFlammable()) {
            const ignited = this._ignite(obj);
            if (ignited) {
              this.createDamageNumber('!', obj.position.x, obj.position.y, '#ff4400');
            }
            if (obj.destroyAfterAnimation) {
              // Source object is dying; spread fire outward immediately
              for (const other of backgroundObjects) {
                if (other === obj || other.destroyed || !other.isFlammable()) continue;
                if (!objectOnPlane(other, planeOf(proj))) continue;
                const dx = other.position.x - obj.position.x;
                const dy = other.position.y - obj.position.y;
                if (dx * dx + dy * dy < 48 * 48) this._ignite(other);
              }
            }
          }
          // Emit impact effect for elemental projectiles (skip steam-producing objects — they have their own feedback)
          if (proj.onHit && !(obj.steamOnFire && obj.steamOnFire())) {
            this.impactEffects.push({ x: obj.position.x, y: obj.position.y, onHit: proj.onHit, color: proj.color });
          }

          // Water/lava elemental reactions (freeze/poison/electrify/steam, solidify-to-rock).
          WaterLavaHitMechanic.applyHit(proj, obj, backgroundObjects, this);

          // Destroy bullet if needed
          if (result.shouldDestroyBullet) {
            // Puzzle switches never destroy a boomerang — see BoomerangMechanic.onPuzzleSignalHit.
            if (proj.boomerang && obj.puzzleSignal) {
              BoomerangMechanic.onPuzzleSignalHit(proj, obj, backgroundObjects, this);
              break;
            }

            // Boomerangs bounce off blocking objects instead of being destroyed
            if (proj.boomerang && !proj.boomerangReturning) {
              proj.boomerangReturning = true;
              proj.boomerangRicochetReturn = true;
              break;
            }

            bgObjectHit = true;

            if (proj.bombBlast) { detonateBombArrow(this.game, proj, enemies); break; }
            // Create stuck arrow if this is an arrow hitting any background object
            if (proj.type === 'arrow') {
              this.stuckArrows.push({
                char: proj.char,
                weaponChar: proj.weaponChar,
                stuckType: 'object',
                pickupable: !!proj.weaponChar,
                position: { x: proj.position.x, y: proj.position.y },
                stuckTo: obj,
                offset: {
                  x: proj.position.x - obj.position.x,
                  y: proj.position.y - obj.position.y
                },
                color: proj.color,
                isBurning: proj.onHit === 'burn',
                fireGenTimer: 0,
                lifetime: 12.0,
                // A lodged boomerang carries its throw's ammo charge until
                // picked up or despawned — see BoomerangMechanic.releaseStuck.
                boomerang: !!proj.boomerang,
                owner: proj.owner
              });
            }
            break;
          }
        }
      }

      if (bgObjectHit) {
        // No boomerang refund here: it lodged as a stuck entry above, which
        // holds the charge until pickup/despawn.
        this.projectiles.splice(i, 1);
        continue;
      }

      // Ricochet behavior
      if (proj.ricochet) {
        const bounced = WallRicochetMechanic.checkRicochet(proj, room);
        if (bounced) {
          proj.ricochetCount = (proj.ricochetCount || 0) + 1;
          if (proj.ricochetCount >= (proj.maxRicochets || 3)) {
            this.projectiles.splice(i, 1);
            continue;
          }
          if (proj.keenAim) applyKeenAim(proj, enemies); // Pearl Slingshot: re-aim off every bounce
        }
      }

      // Check bounds
      if (WallRicochetMechanic.isOutOfBounds(proj)) {
        if (proj.boomerang) BoomerangMechanic._refundAmmo(proj);
        this.projectiles.splice(i, 1);
        continue;
      }

      // Check collision with enemies
      let hit = false;
      for (const enemy of enemies) {
        if (!inSamePlane(proj, enemy)) continue;
        // Sniper stays hittable while sniperHidden (invisible, not intangible) — a
        // player who tracks/guesses its position via the disturbed-object tell can
        // still land a hit; only the render layer conceals it (ExploreRenderer.renderEnemy).
        // Boomerang gating: normal return is inert; ricochet return stuns but deals no damage.
        if (proj.boomerang) {
          if (proj.boomerangReturning && !proj.boomerangRicochetReturn) continue;
          if (proj._boomerangHitEnemies && proj._boomerangHitEnemies.has(enemy)) continue;
        } else if (proj.pierce && proj.pierceHitEnemies?.has(enemy)) {
          // A piercing shot hits each enemy once. Its attackId counts as the
          // same burst, which slips through enemy iframes, so without this it
          // re-hit every frame it overlapped the body.
          continue;
        }

        // An enemy down in a Pit is under the shot (pits.js); an aloft one
        // (the Storm Eye's Thundercloud) is over it.
        if (projectileSailsOver(this.game?.activeRoom, enemy, proj) || enemy.aloft) continue;

        if (this.checkProjectileCollision(proj, enemy)) {
          // Missed shot — show MISS once per enemy and pass through. Bullet keeps traveling
          // (and can still hit other enemies normally; only this enemy was missed).
          if (proj.missed) {
            if (!proj._missedEnemies) proj._missedEnemies = new Set();
            if (!proj._missedEnemies.has(enemy)) {
              proj._missedEnemies.add(enemy);
              this.createDamageNumber('MISS', enemy.position.x, enemy.position.y, '#888888');
            }
            continue;
          }
          // Reflect shield (Mirror Imp, Ice Golem): bounce the shot back at the shooter
          if (ReflectShieldMechanic.tryReflect(enemy, proj, this)) {
            hit = true;   // Remove from player projectiles
            break;
          }

          // Special handling for transmutation bolt - polymorph enemy
          if (proj.type === 'transmutation_bolt') {
            // Store polymorph event to process after projectile loop
            this.polymorphEvents.push({
              enemy: enemy,
              position: enemy.position
            });
            hit = true;
            break;
          }

          // Boomerang ricochet return: stun only, no damage, passes through all enemies
          if (proj.boomerang && proj.boomerangRicochetReturn) {
            BoomerangMechanic.onRicochetReturnHit(proj, enemy, this);
            continue;
          }

          // Boomerang outbound ricochet (every hit after the first): knockback
          // only, no damage/stun. Only the very first enemy the boomerang
          // connects with takes damage and gets stunned; everything it
          // bounces into afterward just gets bonked out of the flight path.
          if (proj.boomerang && !proj.boomerangReturning && proj.boomerangHasHitFirst) {
            BoomerangMechanic.onRicochetHit(proj, enemy, enemies, this);
            continue;
          }

          if (proj.pierce && !proj.boomerang) proj.pierceHitEnemies?.add(enemy);

          // Calculate arrow speed falloff (damage decreases as arrow slows down)
          let speedMultiplier = 1.0;
          if (proj.type === 'arrow' && proj.initialSpeed) {
            const currentSpeed = Math.sqrt(proj.velocity.vx ** 2 + proj.velocity.vy ** 2);
            speedMultiplier = currentSpeed / proj.initialSpeed; // 1.0 at full speed, approaches 0 as arrow slows
          }

          // Apply elemental affinity modifier and speed falloff
          let elementalMod = enemy.getElementalModifier(proj.onHit);
          if (proj.electric) elementalMod *= enemy.getElementalModifier('shock');
          if (proj.isBlade) elementalMod *= enemy.getElementalModifier('blade');
          let adjustedDamage = Math.ceil(proj.damage * elementalMod * speedMultiplier);
          // A 0-damage projectile (fizzled spark, Freeze Ray) stays harmless
          // through the flat modifier below.
          // Green Ranger flat modifier (not scaled by speed falloff); excludes boomerangs.
          if (proj.owner && proj.owner.characterType === 'green' && !proj.boomerang && adjustedDamage > 0) {
            const enemyUndetected = enemy.detectionIndicatorTimer <= 0;
            const greenBonus = enemyUndetected ? proj.owner.greenIdleDamageBonus : -proj.owner.greenCombatDamagePenalty;
            adjustedDamage = Math.max(1, adjustedDamage + greenBonus);
          }

          // Handle immunity
          if (elementalMod === 0.0) {
            this.createDamageNumber('IMMUNE', enemy.position.x, enemy.position.y, '#cccccc');
            if (!proj.pierce) {
              hit = true;
              break;
            }
            // Boomerang: mark the immune enemy as hit and drop any lock on it,
            // otherwise per-frame homing would orbit it forever.
            if (proj.boomerang) BoomerangMechanic.onImmuneEnemy(proj, enemy);
            continue;
          }

          const critRoll = this._applyCritIfLucky(adjustedDamage, proj.owner, enemy);
          const finalDamage = critRoll.damage;
          // Told to takeDamage so its sleep-wake-on-damage rule doesn't clear
          // stacks this same hit is about to (re)apply — see Enemy.js.
          const reapplyingSleep = proj.onHit === 'sleep' || !!(proj.extraOnHit && proj.extraOnHit.includes('sleep'));
          // Damage-source identity: where the hit landed and what threw it.
          // Ordinary enemies ignore these keys; hit-location bosses (the
          // Hoardmaw's scale field and glint) are unhittable without them.
          // position is the hit box's TOP-LEFT (see checkProjectileCollision),
          // so the strike point is its center — passing the corner biases every
          // location lookup up-left by half a box.
          const damaged = enemy.takeDamage(finalDamage, proj.attackId, {
            reapplyingSleep,
            px: proj.position.x + (proj.width || GRID.CELL_SIZE) / 2,
            py: proj.position.y + (proj.height || GRID.CELL_SIZE) / 2,
            kind: 'projectile',
            weaponSubtype: proj.weaponSubtype,
          });
          if (damaged && damaged.dodged) {
            this.createDamageNumber('DODGE', enemy.position.x, enemy.position.y, '#ffffff');
          } else if (damaged !== false) {
            // Show damage number with color based on affinity (crit overrides color + scale)
            const damageColor = critRoll.isCrit ? '#ffff66' :
                               elementalMod < 1.0 ? '#888888' :   // Resisted
                               elementalMod > 1.0 ? '#ffff00' :   // Weakness
                               enemy.color;                       // Normal
            this.createDamageNumber(finalDamage, enemy.position.x, enemy.position.y, damageColor, critRoll.isCrit ? 1.7 : 1);

            if (critRoll.isCrit) {
              const critLabel = critRoll.isLucky ? 'LUCKY CRIT' : 'CRIT';
              this.createDamageNumber(critLabel, enemy.position.x, enemy.position.y - 14, '#ffff66');
            }

            // Show weakness indicator
            if (elementalMod > 1.0) {
              this.createDamageNumber('!', enemy.position.x, enemy.position.y - 12, '#ff4400');
            }

            // Moose (game animal): every arrow or bullet strike stacks a slowing effect
            if ((proj.type === 'arrow' || proj.type === 'bullet') && enemy.data?.gameAnimal?.role === 'moose') {
              GameAnimalMechanic.registerSlowHit(enemy);
            }

            // Apply status effects with affinity-modified duration.
            // Electric weapons carry onHit:'stun' in item data; the status
            // actually applied is 'zap' (electric identity — shake visual,
            // EFFECT_AFFINITY auto-immunity for electric enemies).
            const projStatus = (proj.onHit === 'stun' && proj.electric) ? 'zap' : proj.onHit;
            if (proj.onHit && enemy.shouldApplyStatusEffect(projStatus)) {
              const baseDuration = 3.0;
              const modifiedDuration = baseDuration * elementalMod;
              applyOnHitStatusEffect(enemy, projStatus, modifiedDuration);
              // Emit impact effect for visual feedback
              this.impactEffects.push({ x: enemy.position.x, y: enemy.position.y, onHit: proj.onHit, color: proj.color });
            } else if (proj.onHit && !enemy.shouldApplyStatusEffect(projStatus)) {
              this.createDamageNumber('RESIST', enemy.position.x, enemy.position.y - 12, '#888888');
            }

            // Extra onHit effects from equipped oils beyond the primary (see
            // Item.js's extraOnHit) — independent of the primary's own
            // immunity outcome above, each extra gets its own elemental check.
            applyExtraOnHitEffects(this, enemy, proj.extraOnHit, proj.color);

            // Apply knockback — boomerangs are excluded here: BoomerangMechanic
            // applies knockback itself, and only on ricochet hits (see
            // onRicochetHit), never on the first enemy hit.
            if (proj.knockback && !proj.boomerang) {
              this.applyKnockback(enemy, proj);
            }

            // Hitstop on confirmed projectile hit
            this.physicsSystem.applyHitstop(enemy, 0.06);
            if (proj.owner) this.physicsSystem.applyHitstop(proj.owner, 0.04);

            // Apply lifesteal to player (a 'lifesteal' immunity — bloodless
            // Skeletons — lets the hit land but heals nothing)
            if (proj.lifesteal && proj.owner === 'player' && enemy.shouldApplyStatusEffect('lifesteal')) {
              proj.owner.hp = Math.min(proj.owner.hp + proj.damage * proj.lifesteal, proj.owner.maxHp);
            }

            // Chain lightning effect
            if (proj.chain && proj.chainCount > 0) {
              this.game.lightningStrikeSystem.createChainLightning(proj, enemy, enemies);
            }

            // Explosion effect (the Explosive Bow's arrow is a Bomb instead)
            if (proj.bombBlast) detonateBombArrow(this.game, proj, enemies);
            if (proj.explode) {
              this.createExplosion(proj.position.x, proj.position.y, proj.explodeRadius || 30, proj.damage, enemies, backgroundObjects, 0, planeOf(proj));
            }
            this.game?.weaponEffectsSystem?.onProjectileHit(proj, enemy, enemies);

            // Boomerang first hit: record it, stun, defer return timer, chain
            // splash damage, then lock onto the nearest un-hit enemy in range
            // or flip to return. Every later ricochet hit is intercepted above
            // and never reaches this damage path.
            if (proj.boomerang) {
              BoomerangMechanic.onEnemyHit(proj, enemy, enemies, this);
              break;
            }
          }

          // Pierce projectiles don't get removed
          if (!proj.pierce) {
            hit = true;

            // Create stuck arrow if this is an arrow (boomerangs return — no stuck arrow)
            if (proj.type === 'arrow' && !proj.boomerang) {
              this.stuckArrows.push({
                char: proj.char,
                weaponChar: proj.weaponChar,
                stuckType: 'enemy',
                position: { x: proj.position.x, y: proj.position.y },
                stuckTo: enemy,
                offset: {
                  x: proj.position.x - enemy.position.x,
                  y: proj.position.y - enemy.position.y
                },
                color: proj.color,
                isBurning: proj.onHit === 'burn',
                fireGenTimer: 0
              });
            }
          }

          // Split projectiles
          if (proj.split && !proj.hasSplit) {
            this.projectiles.push(...createSplitProjectiles(proj));
            proj.hasSplit = true;
          }

          if (!proj.pierce) break;
        }
      }

      if (hit) {
        this.projectiles.splice(i, 1);
      }
    }

    // Update melee attacks
    for (let i = this.meleeAttacks.length - 1; i >= 0; i--) {
      const attack = this.meleeAttacks[i];

      attack.duration -= deltaTime;

      // Impact-burst fade: a separate, shorter countdown from strikeChar's own
      // flash duration (hammerRing's ✷) so it fades at the instant of impact
      // rather than lingering for the whole attack.duration flash.
      if (attack.strikeFlashTimer > 0) {
        attack.strikeFlashTimer = Math.max(0, attack.strikeFlashTimer - deltaTime);
      }

      if (attack.duration <= 0) {
        this.meleeAttacks.splice(i, 1);
        continue;
      }

      // Sword of the Letter / Chromablade: striking an exit tile cycles its
      // letter or color forward. See ExitSystem.applyExitMutatingSwordHit.
      applyExitMutatingSwordHit(attack, room);

      // Check collision with background objects (only on first frame)
      if (!attack.hasHitObject) {
        for (const obj of backgroundObjects) {
          if (obj.destroyed || obj.isRecipeSign) continue; // Skip destroyed and recipe signs
          if (!objectOnPlane(obj, attack.shooterPlane ?? 0)) continue;

          if (this.checkMeleeCollisionWithObject(attack, obj)) {
            if (attack.owner && vaultWallBlocksReach(room, attack.owner, obj)) continue;
            // Glittering rocks require a pickaxe — other weapons bounce off
            if (obj.data?.glitteringRock) {
              if (!attack.isPickaxe) {
                this.createDamageNumber('!', obj.position.x, obj.position.y, '#aaaaaa');
                continue;
              }
              const result = obj.takeDamage(attack.damage);
              if (result.effect) {
                this.objectDestroyEvents.push({ obj, effect: result.effect });
              }
              attack.hasHitObject = true;
              continue;
            }

            // Whip strikes on a Stump or Tree grab hold and reel the player in
            // — the Whip Trial's hook-post pull, generalized to ordinary
            // terrain once the player has learned the trick. Checked before
            // the material gates below so a whip swing grabs on instead of
            // thunking off (Tree) or chopping/harvesting (Stump);
            // PhysicsSystem.updateEntity's hookedByWhip handling owns the
            // actual traversal + i-frames, this only sets the target. Safe
            // above the gates because it only ever fires on 'Y'/'ŋ', and no
            // object with either char is obsidian, a rock, or a boulder.
            if (attack.weaponSubtype === 'whip' && (obj.char === 'Y' || obj.char === 'ŋ') && attack.owner) {
              attack.owner.hookedByWhip = { targetX: obj.position.x, targetY: obj.position.y };
              // Flash the grabbed object in the whip's own color — the
              // interaction cue that this hit latched on rather than
              // chopping/thunking (equipped whip variants each carry a
              // distinct color; see items.js).
              obj.flashColor(attack.color);
              continue;
            }

            // Onyx Hammer: an unbreakable rock leaves its cell rolling.
            if (this.game.boulderSystem?.rollFromRest(attack, obj)) {
              attack.hasHitObject = true;
              continue;
            }

            // Which weapons may damage this material at all — obsidian, rock,
            // boulder, tree. InteractionSystem owns the answer, next door to
            // resolveSmashDamage's "how much"; what is left here is the
            // feedback, because the damage number belongs to combat.
            const refusal = this.game.interactionSystem.resolveSmashRefusal(attack, obj);
            if (refusal) {
              // Fire talks its way past exactly one refusal: a Tree burns even
              // though it will not chop.
              if (refusal.fireBypass && attack.onHit === 'burn' && obj.isFlammable() && this._ignite(obj)) {
                this.createDamageNumber('!', obj.position.x, obj.position.y, '#ff4400');
              } else {
                this.createDamageNumber('!', obj.position.x, obj.position.y, '#aaaaaa');
              }
              continue;
            }

            // Blunt weapons can't damage objects, but still rustle grass; Brush
            // yields to anything, and allWeaponsDamage-flagged instances yield to anything too.
            // Rocks (0) are the standing exception (bug #10): smashing stone is
            // what a blunt weapon is for, and resolveSmashRefusal already let
            // the swing through — without this the payload below would eat it.
            if (!attack.isBlunt || obj.data.kind === 'brush' || obj.char === '0' || obj.allWeaponsDamage) {
              const smashDamage = this.game.interactionSystem.resolveSmashDamage(attack, obj);
              const result = obj.takeDamage(smashDamage, attack.isBlade);

              // Queue any effect (destructive or not — non-destructive effects like
              // 'cutGrass' need to reach handleObjectEffect to roll pollen / fairy spawns).
              if (result.effect) {
                this.objectDestroyEvents.push({ obj, effect: result.effect, attack });
              }

              // Bat: rare chance the weapon itself shatters on a rock hit.
              if (attack.weapon && this.game.interactionSystem.resolveSmashWeaponBreak(attack, obj)) {
                if (attack.owner?.destroyHeldItem?.(attack.weapon)) {
                  this.createDamageNumber('BREAK', obj.position.x, obj.position.y, '#ff6644');
                  this.game.audioSystem?.playSFX?.('bat_break');
                  this.game.menuSystem?.updateUI?.();
                }
              }

              // Fire weapons ignite flammable objects — spread outward if object is destroyed.
              // Ignitions route through FireSystem so the deterministic front + dirty flag own propagation.
              if (attack.onHit === 'burn' && obj.isFlammable()) {
                const ignited = this._ignite(obj);
                if (ignited) {
                  this.createDamageNumber('!', obj.position.x, obj.position.y, '#ff4400');
                }
                if (result.destroyed) {
                  for (const other of backgroundObjects) {
                    if (other === obj || other.destroyed || !other.isFlammable()) continue;
                    if (!objectOnPlane(other, attack.shooterPlane ?? 0)) continue;
                    const dx = other.position.x - obj.position.x;
                    const dy = other.position.y - obj.position.y;
                    if (dx * dx + dy * dy < 48 * 48) this._ignite(other);
                  }
                }
              }
              // Emit impact effect for elemental melee (skip steam-producing objects — they have their own feedback)
              if (attack.onHit && !(obj.steamOnFire && obj.steamOnFire())) {
                this.impactEffects.push({ x: obj.position.x, y: obj.position.y, onHit: attack.onHit, color: attack.color });
              }

              // Electric weapons conduct through conductive objects
              if (attack.onHit === 'stun' && attack.electric && obj.isConductive()) {
                this.conductElectricity(obj, attack.damage, enemies, player);
              }

              // Water state transitions from melee. Environmental terrain
              // (BackgroundObject.isEnvironmental()) never spawns a damage
              // number — each branch already has its own feedback: the flood
              // fill / tile's own color-state change, a steam cloud puff.
              if (obj.isWater && obj.isWater()) {
                if (attack.onHit === 'freeze') {
                  obj.setWaterState('frozen', Infinity); // Stays frozen until thawed by fire
                } else if (attack.onHit === 'poison') {
                  obj.setWaterState('poisoned', POISONED_WATER_DURATION);
                } else if (attack.onHit === 'stun' && attack.electric) {
                  this.game?.electricitySystem?.seedFromWeapon(obj, backgroundObjects, attack,
                    { tileDuration: 4.0, hutPlane: isInteriorActive(this.game) });
                } else if (attack.onHit === 'burn') {
                  if (obj.getWaterState() === 'frozen') {
                    obj.setWaterState('normal', 0); // Melt ice
                  } else {
                    // Fire hits liquid water → steam cloud
                    this.newSteamClouds.push({
                      x: obj.position.x + GRID.CELL_SIZE / 2,
                      y: obj.position.y + GRID.CELL_SIZE / 2,
                      radius: GRID.CELL_SIZE * 3,
                      timer: 7.0
                    });
                  }
                }
              }

              // Water attack hits lava → solidify to rock
              WaterLavaHitMechanic.freezeLava(obj, attack.onHit, this);

              // Fire melee hits deep snow → melt it (bug #302: only the fire
              // projectile path called into WaterLavaHitMechanic before this;
              // a fire-sword swing never did). See meltSnow for the shared
              // conversion logic.
              WaterLavaHitMechanic.meltSnow(obj, attack.onHit);
            }

            // Chaff VFX when melee hits grass (all weapons including blunt) — 5% chance
            if ((obj.char === '|' || obj.char === ',') && Math.random() < 0.05) {
              this.impactEffects.push({
                x: obj.position.x,
                y: obj.position.y,
                effect: 'chaff',
                color: '#667755'
              });
            }
          }
        }
        attack.hasHitObject = true;
      }

      // Check collision with enemies (only on first frame)
      if (!attack.hasHit) {
        for (const enemy of enemies) {
          if (planeOf(enemy) !== (attack.shooterPlane ?? 0)) continue;
          if (enemy.aloft) continue; // out of reach overhead (Storm Eye's Thundercloud)
          // Sniper stays hittable while sniperHidden — see the projectile-loop comment above.

          if (this.checkMeleeCollision(attack, enemy)) {
            // Parry mechanic (Duelist): reflect melee back at player.
            // Same catch rule as the player's Buckler parry (ParryMechanic.js).
            if (attack.owner && attack.isMelee !== false
                && ParryMechanic.catches(enemy, attack.owner.position, attack.owner)) {
              const reflectDmg = Math.ceil(attack.damage * (enemy.data.parryMechanic?.reflectDamage ? PARRY_REFLECT_FRACTION : 0));
              if (reflectDmg > 0 && attack.owner.takeDamage) {
                attack.owner.takeDamage(reflectDmg, { isBullet: false, isMelee: true });
                this.createDamageNumber('PARRY', enemy.position.x, enemy.position.y, '#eeeeff');
                this.createDamageNumber(reflectDmg, attack.owner.position.x, attack.owner.position.y, '#eeeeff');
              } else {
                this.createDamageNumber('PARRY', enemy.position.x, enemy.position.y, '#eeeeff');
              }
              attack.hasHit = true;
              // Counter-attack: schedule immediate melee retaliation
              if (enemy.data.parryMechanic?.counterAttack) {
                const counter = enemy.createMeleeAttack();
                if (counter) this.createEnemyAttack(counter);
              }
              // chargeOnParry: enter charge windup immediately after a successful parry
              if (enemy.data.parryMechanic?.chargeOnParry &&
                  enemy.data.chargeMechanic?.enabled &&
                  enemy.chargeState === 'idle') {
                enemy.chargeState = 'windup';
                enemy.chargeWindupTimer = enemy.data.chargeMechanic.chargeWindup * 0.6;
              }
              continue;
            }

            // Reflect shield (Mirror Imp) blocks ranged/arrow attacks — handled via projectile loop
            // Melee still bypasses shield

            const isWet = enemy.isWet && enemy.isWet();
            const isSnared = enemy.isSnared && enemy.isSnared();

            // Chaos Blade: resolve random onHit per arc hit before any elemental logic
            if (attack.randomOnHit) {
              attack.onHit = attack.randomOnHit[Math.floor(Math.random() * attack.randomOnHit.length)];
            }

            // Apply elemental affinity modifier
            let elementalMod = enemy.getElementalModifier(attack.onHit);
            if (attack.electric) elementalMod *= enemy.getElementalModifier('shock');
            if (attack.isBlade) elementalMod *= enemy.getElementalModifier('blade');

            // Green Ranger stealth modifier: bonus when enemy hasn't detected the player
            let totalDamage = attack.damage;

            // Spear distance crit: 3rd hitbox at full thrust range — guaranteed crit
            if (attack.distanceCrit) {
              totalDamage = Math.ceil(totalDamage * 1.5);
            }
            // A 0-damage swing (Flag) stays harmless — the Green flat bonus
            // only adjusts a hit that already does damage.
            if (attack.owner && attack.owner.characterType === 'green' && totalDamage > 0) {
              const enemyUndetected = enemy.detectionIndicatorTimer <= 0;
              const greenBonus = enemyUndetected ? attack.owner.greenIdleDamageBonus : -attack.owner.greenCombatDamagePenalty;
              totalDamage = Math.max(1, totalDamage + greenBonus);
            }

            // Backstab (assassin strike): multiplier when hitting an enemy that hasn't detected the player.
            // Cyan Rogue speciality — highest multiplier — but any character with backstabMultiplier > 1
            // benefits. Enemy is "unaware" when idle (not enraged, no memory chase, no active detection).
            if (attack.owner && (attack.owner.backstabMultiplier || 1.0) > 1.0) {
              const enemyUnaware = !enemy.enraged && !enemy.aggroMemoryActive && enemy.detectionIndicatorTimer <= 0;
              if (enemyUnaware) {
                totalDamage = Math.ceil(totalDamage * attack.owner.backstabMultiplier);
              }
            }

            // Wet enemies take bonus damage from electric and ice attacks
            const isFrozen = enemy.isFrozen();
            let statusDuration = 3.0;
            if (isWet && attack.onHit === 'stun') {
              totalDamage *= 2;      // Double damage from electricity on wet enemies
              statusDuration = 3.5;  // Extended stun
            } else if (isWet && attack.onHit === 'freeze') {
              totalDamage += Math.ceil(attack.damage * 0.5); // +50% from ice on wet enemies
              statusDuration = 5.0;  // Extended freeze pip (the Frozen lock keeps its own duration)
            }

            // Blunt-vs-frozen and blade-vs-snared damage bonuses (MeleeStatusBonuses.js)
            totalDamage = applyMeleeStatusDamageBonus(totalDamage, attack, { isFrozen, isSnared });

            // Apply elemental modifier to final damage
            totalDamage = Math.ceil(totalDamage * elementalMod);

            // Handle immunity
            if (elementalMod === 0.0) {
              this.createDamageNumber('IMMUNE', enemy.position.x, enemy.position.y, '#cccccc');
              continue;
            }

            const critRoll = this._applyCritIfLucky(totalDamage, attack.owner, enemy);
            const finalDamage = critRoll.damage;
            // Melee hitboxes normally carry no burst id (undefined → iframes
            // block every follow-up), so only an explicitly-bursted pattern
            // like the doubleHit stab combo can land more than once per swing.
            // reapplyingSleep tells takeDamage its sleep-wake-on-damage rule
            // shouldn't clear stacks this same hit is about to (re)apply.
            const reapplyingSleep = attack.onHit === 'sleep' || !!(attack.extraOnHit && attack.extraOnHit.includes('sleep'));
            // Damage-source identity — see the projectile call site above.
            const damaged = enemy.takeDamage(finalDamage, attack.attackId, {
              reapplyingSleep,
              px: attack.position.x + (attack.width || 0) / 2,
              py: attack.position.y + (attack.height || 0) / 2,
              kind: 'melee',
              weaponSubtype: attack.weaponSubtype,
            });
            if (damaged === true && attack.isBlade) enemy.killedByBlade = true;
            if (damaged && damaged.dodged) {
              this.createDamageNumber('DODGE', enemy.position.x, enemy.position.y, '#ffffff');
            } else if (damaged !== false) {
              // Generic hit-landed signal — FlailSystem resets its spin ramp on this.
              attack.hitConnected = true;
              // Show damage number with color based on affinity (crit overrides color + scale)
              const damageColor = critRoll.isCrit ? '#ffff66' :
                                 elementalMod < 1.0 ? '#888888' :   // Resisted
                                 elementalMod > 1.0 ? '#ffff00' :   // Weakness
                                 enemy.color;                       // Normal
              // Zero-damage hits (Rubber Bat) skip the number — the launch is the feedback
              if (finalDamage > 0) {
                this.createDamageNumber(finalDamage, enemy.position.x, enemy.position.y, damageColor, critRoll.isCrit ? 1.7 : 1);
              }

              if (critRoll.isCrit) {
                const critLabel = critRoll.isLucky ? 'LUCKY CRIT' : 'CRIT';
                this.createDamageNumber(critLabel, enemy.position.x, enemy.position.y - 14, '#ffff66');
              }

              // Show weakness indicator
              if (elementalMod > 1.0) {
                this.createDamageNumber('!', enemy.position.x, enemy.position.y - 12, '#ff4400');
              }

              // Apply status effects with affinity-modified duration.
              // Same stun→zap translation as the projectile path: electric
              // melee applies 'zap', keeping item data ('stun' + electric) as-is.
              const attackStatus = (attack.onHit === 'stun' && attack.electric) ? 'zap' : attack.onHit;
              if (attack.onHit && enemy.shouldApplyStatusEffect(attackStatus)) {
                // statusDurationScale: per-effect multiplier an attack can carry (Bat: dizzy ×2).
                const modifiedDuration = statusDuration * elementalMod * (attack.statusDurationScale?.[attackStatus] ?? 1);
                applyOnHitStatusEffect(enemy, attackStatus, modifiedDuration);
                // Emit impact effect for visual feedback
                this.impactEffects.push({ x: enemy.position.x, y: enemy.position.y, onHit: attack.onHit, color: attack.color });
              } else if (attack.onHit && !enemy.shouldApplyStatusEffect(attackStatus)) {
                this.createDamageNumber('RESIST', enemy.position.x, enemy.position.y - 12, '#888888');
              }

              // Extra onHit effects from equipped oils beyond the primary (see
              // Item.js's extraOnHit) — deliberately independent of the
              // primary's immunity outcome above.
              applyExtraOnHitEffects(this, enemy, attack.extraOnHit, attack.color, attack.statusDurationScale);

              // Whip disarm — the lash rips carried gear out of an armed
              // enemy's hands. Sets the same flag the electric jolt uses;
              // EnemyUpdateSystem polls it and scatters the inventory.
              if (attack.disarm && enemy.itemUsage && enemy.inventory?.length) {
                enemy.shouldDropItems = true;
                enemy._disarmed = true;
                this.createDamageNumber('DISARM', enemy.position.x, enemy.position.y - 14, '#ffcc66');
              }

              // Show electric indicator for wet-boosted hits
              if (isWet && attack.onHit === 'stun') {
                this.createDamageNumber('⚡', enemy.position.x, enemy.position.y - 12, '#ffff00');
              }

              // Show blunt-on-frozen / blade-on-snared bonus indicator
              const statusBonusIndicator = getMeleeStatusBonusIndicator(attack, { isFrozen, isSnared });
              if (statusBonusIndicator) {
                this.createDamageNumber(statusBonusIndicator.text, enemy.position.x, enemy.position.y - 12, statusBonusIndicator.color);
              }

              // Show distance crit indicator (spear full-extension bonus)
              if (attack.distanceCrit) {
                this.createDamageNumber('PIERCE', enemy.position.x, enemy.position.y - 14, '#ffff66');
              }

              // Venom Blade poison stacking: 3 hits triggers a burst
              if (attack.poisonStacks && attack.onHit === 'poison') {
                enemy.poisonStackCount = (enemy.poisonStackCount || 0) + 1;
                if (enemy.poisonStackCount >= 3) {
                  enemy.hp = Math.max(0, enemy.hp - 2);
                  enemy.poisonStackCount = 0;
                  this.createDamageNumber('BURST', enemy.position.x, enemy.position.y - 16, '#00ff88');
                  this.createDamageNumber(2, enemy.position.x, enemy.position.y, '#00ff88');
                }
              }

              // Apply knockback — spear uses exact facing direction, others use positional
              if (attack.knockback) {
                if (attack.facing) {
                  this.physicsSystem.applyKnockbackDir(enemy, attack.facing.x, attack.facing.y, attack.knockback * knockbackTakenScale(enemy, attack));
                } else {
                  this.applyKnockback(enemy, attack);
                }
              }

              // Bat launch (batCharge release sweep): BatSystem sends
              // non-heavy enemies flying along the contact angle.
              if (attack.batLaunch) {
                this.game?.batSystem?.applyLaunch(enemy, attack);
              }

              // Hitstop, recoil on confirmed melee hit
              this.physicsSystem.applyHitstop(enemy, attack.hitstop ?? 0.06);
              if (attack.owner) {
                this.physicsSystem.applyHitstop(attack.owner, 0.04);
                // Whips have no knockback recoil
                if (attack.weaponSubtype !== 'whip') {
                  const dx = attack.owner.position.x - enemy.position.x;
                  const dy = attack.owner.position.y - enemy.position.y;
                  this.physicsSystem.applyImpulse(attack.owner, dx, dy, 60);
                }
              }

              // Apply lifesteal ('lifesteal' immunity: the hit lands, nothing to drink)
              if (attack.lifesteal && attack.owner && enemy.shouldApplyStatusEffect('lifesteal')) {
                attack.owner.hp = Math.min(attack.owner.hp + attack.damage * attack.lifesteal, attack.owner.maxHp);
              }

              // Dagger: a confirmed hit refreshes the dodge-roll cooldown, and
              // the roll's end fires the next stab (triggerDaggerRollAttack) —
              // the chain is stab → roll → stab. The hit used to zero the stab
              // cooldown too, which let stab → stab repeat every windup and,
              // inside the post-roll guaranteed-crit window, stack 2× crits
              // with no recovery at all.
              if (attack.weaponSubtype === 'dagger' && attack.owner?.dodgeRoll) {
                attack.owner.dodgeRoll.cooldownTimer = 0;
              }

              // Chain lightning effect
              if (attack.chain) {
                this.game.lightningStrikeSystem.createChainLightning(attack, enemy, enemies);
              }

              // Explosion effect — at the hitbox's center cell, so a hit wider
              // than one cell (a shockwave's Impact Size) bursts on its carrier,
              // not at the box's top-left corner.
              if (attack.explode) {
                const inset = ((attack.width || GRID.CELL_SIZE) - GRID.CELL_SIZE) / 2;
                this.createExplosion(attack.position.x + inset, attack.position.y + inset, attack.explodeRadius || 40, attack.damage, enemies, backgroundObjects, 0, attack.shooterPlane ?? 0);
              }
              this.game?.weaponEffectsSystem?.onMeleeHit(attack, enemy, isFrozen);
            }
          }
        }

        // Errand NPC (feature-inbox): the one NeutralCharacter special-cased
        // as attackable. ErrandSystem owns the hit-check + conversion logic —
        // this is just the wiring hook, matching the enemy loop right above.
        this.game?.errandSystem?.checkAttackHit(attack, this, this.game, room);

        attack.hasHit = true;
      }
    }

    // Update enemy projectiles
    for (let i = this.enemyProjectiles.length - 1; i >= 0; i--) {
      const proj = this.enemyProjectiles[i];

      // Decrement lifetime for short-lived hitbox projectiles
      if (proj.lifetime !== undefined) {
        proj.lifetime -= deltaTime;
        if (proj.lifetime <= 0) {
          this.enemyProjectiles.splice(i, 1);
          continue;
        }
      }

      this.game?.bossSystem?.windFieldSystem.pushProjectile(proj, deltaTime);

      // Move projectile
      proj.position.x += proj.velocity.vx * deltaTime;
      proj.position.y += proj.velocity.vy * deltaTime;

      // Freeze water tiles as ice-stream projectile passes over them
      if (proj.freezesWater) {
        const scanR = GRID.CELL_SIZE * 1.2;
        const scanRSq = scanR * scanR;
        let hits = 0;
        for (const obj of backgroundObjects) {
          if (hits >= 2) break;
          if (obj.destroyed || !obj.isWater || !obj.isWater()) continue;
          if (!objectOnPlane(obj, planeOf(proj))) continue;
          if (obj.getWaterState() === 'frozen') continue;
          const dx = (obj.position.x + GRID.CELL_SIZE / 2) - proj.position.x;
          const dy = (obj.position.y + GRID.CELL_SIZE / 2) - proj.position.y;
          if (dx * dx + dy * dy <= scanRSq) {
            obj.setWaterState('frozen', Infinity);
            hits++;
          }
        }
      }

      // Update plane if in tunnel room
      if (room && room.tunnel && proj.plane !== undefined) {
        updateProjectileTunnelPlane(proj, room.tunnel);
      }

      // Check collision with room walls via collisionMap
      if (WallRicochetMechanic.hitsWall(proj, room)) {
        this.enemyProjectiles.splice(i, 1);
        continue;
      }

      // Check bounds
      if (WallRicochetMechanic.isOutOfBounds(proj)) {
        this.enemyProjectiles.splice(i, 1);
        continue;
      }

      // Deflector triangles also bend enemy projectiles, and the bend has to be
      // tested BEFORE the background-object loop below — exactly as the player
      // path does it. A deflector is a background object whose bulletInteraction
      // is 'block', so letting the loop run first destroys the shot on the
      // triangle instead of turning it. Reflected enemy projectiles skip player
      // collision (existing convention), so a deflected shot can no longer hurt
      // the player.
      if (this.game.boulderSystem?.redirectProjectile(proj)) continue;

      // Check collision with background objects (cave walls, etc.)
      for (const obj of backgroundObjects) {
        if (obj.destroyed || obj.isRecipeSign) continue; // Skip destroyed and recipe signs
        if (!objectOnPlane(obj, planeOf(proj))) continue;
        if (this.checkProjectileCollisionWithObject(proj, obj)) {
          // Deflectors are routed above; skip the generic bullet-interaction path.
          if (obj.data?.boulderDeflector) continue;
          const result = obj.handleBulletCollision(proj);
          if (result.shouldDestroyBullet) {
            this.enemyProjectiles.splice(i, 1);
            break;
          }
        }
      }
      if (!this.enemyProjectiles[i] || this.enemyProjectiles[i] !== proj) continue;

      // A charmed enemy's shot flies at the enemy it's fighting (charmHits.js)
      if (proj.charmedTarget) {
        if (resolveCharmedProjectile(this, proj) === 'hit') this.enemyProjectiles.splice(i, 1);
        continue;
      }

      if (!inSamePlane(proj, player)) continue;

      // Reflected boss projectiles travel back toward the boss; skip player collision
      if (proj.reflected) continue;

      // A player down in a Pit is under the shot (pits.js)
      if (projectileSailsOver(this.game?.activeRoom, player, proj)) continue;

      // Check collision with player
      if (this.checkProjectileCollisionWithPlayer(proj, player)) {
        let consumed = true; // whether to remove the projectile this frame
        if (player.isStaffBlocking) {
          // Staff block: deflect missile (consume without damage)
          this.createDamageNumber('BLOCK', player.position.x, player.position.y, '#aaaaaa');
          this.enemyProjectiles.splice(i, 1);
          continue;
        }
        // Build damage source object
        const damageSource = {
          isBullet: true,
          element: proj.onHit,
          attacker: proj.owner
        };
        const result = player.takeDamage(proj.damage, damageSource);

        if (result === false) {
          // Player is invulnerable (dodge roll, i-frames, god mode) — let projectile pass through
          consumed = false;
        } else {
          // Handle special results
          if (result.dodged) {
            this.createDamageNumber(result.lucky ? 'LUCKY DODGE' : 'DODGE',
                                    player.position.x, player.position.y,
                                    result.lucky ? '#ffff66' : '#ffff00');
          } else if (result.blocked) {
            this.createDamageNumber('BLOCK', player.position.x, player.position.y, '#aaaaaa');
          } else if (result.immune) {
            this.createDamageNumber('IMMUNE', player.position.x, player.position.y, '#00ffff');
          } else {
            this.createDamageNumber(result.actualDamage ?? proj.damage, player.position.x, player.position.y, player.color);

            // Rock projectiles tune their own force; everything else gets the default
            this.physicsSystem.applyKnockback(player, proj.position.x, proj.position.y, proj.knockbackForce || PHYSICS.DEFAULT_DAMAGE_KNOCKBACK);

            // Potion projectile: apply elemental status effect
            if (proj.type === 'potion_projectile' && proj.potionEffect) {
              if (proj.potionEffect === 'confusion') {
                player.confusionTimer = (player.confusionTimer || 0) + 3.0;
              } else if (proj.potionEffect === 'polymorph') {
                // Hag's curse — same generic entry point the stationary hut
                // Witch uses, cursed=true (deliberate hit, not accidental).
                this.game.polymorphSystem?.activatePolymorph(this.game, true);
              } else {
                player.applyStatusEffect?.(proj.potionEffect, 3.0);
              }
            }

            // A shot that carries a status (the Ice Wraith's Frost Line) adds its pip
            if (proj.statusOnHit) player.applyStatusEffect?.(proj.statusOnHit, 3.0);

            // Steam cloud: apply scald (burn+slow) in AOE
            if (proj.type === 'steam_cloud') {
              player.applyStatusEffect?.('burn', proj.scaldDuration || 2.5);
              player.applyStatusEffect?.('slow', proj.slowDuration || 3.0);
            }

            // Handle reflection
            if (result.reflect && result.attacker) {
              result.attacker.takeDamage(result.reflect);
              this.createDamageNumber(result.reflect, result.attacker.position.x, result.attacker.position.y, '#ff8800');
            }
          }

          if (result === true) {
            this.enemyProjectiles.splice(i, 1);
            return { playerDead: true };
          }

          // Create stuck arrow if this is an arrow (not a bullet/magic)
          if (proj.type === 'arrow') {
            this.stuckArrows.push({
              char: proj.char,
              stuckType: 'player',
              position: { x: proj.position.x, y: proj.position.y },
              stuckTo: player,
              offset: {
                x: proj.position.x - player.position.x,
                y: proj.position.y - player.position.y
              },
              color: proj.color,
              isBurning: proj.onHit === 'burn',
              fireGenTimer: 0
            });
          }
        }
        if (consumed) this.enemyProjectiles.splice(i, 1);
      }
    }

    // Update enemy melee attacks. Timers, windup blink, owner tracking, and
    // Telegraph pulse re-arming all live in the shared Telegraph module (the
    // enemy-editor sandbox steps the same code).
    //
    // Stepped on the enemy double-second clock, same as Enemy.update() — so an
    // attack's windupDuration (copied straight from the double-second
    // `attackWindup`) is measured against a clock that agrees with it, and an
    // authored Telegraph pulse delay means what the data says it means.
    for (let i = this.enemyMeleeAttacks.length - 1; i >= 0; i--) {
      const attack = this.enemyMeleeAttacks[i];

      // Expiry is resolved *after* the contact test, not before. A travelling
      // strike's final slice of travel lands on the same frame its duration runs
      // out, so dropping the attack first would silently discard the end of
      // every pass. Nothing changes for still attacks — they latch on their one
      // test frame long before this.
      const expired = updateEnemyMeleeAttack(attack, deltaTime * PHYSICS.ENEMY_TIMER_RATE);

      // Check collision with the player or the charmed target. A still attack
      // gets one test frame; a travelling strike keeps testing for the whole
      // pass, which retireAfterTest decides.
      if (!attack.hasHit && !attack.windupPhase) {
        let connected = false;

        if (attack.isCharmedAttack && attack.charmedTarget && attack.charmedTarget !== player) {
          connected = resolveCharmedMelee(this, attack); // charmHits.js
        } else if (planeOf(player) !== (attack.shooterPlane ?? 0)) {
          attack.hasHit = true; // Mark as processed so it doesn't linger
        } else {
          // Normal attack (or charmed fallback targeting player)
          connected = attackHitsBox(attack, player.getHitbox(),
                                    () => this.checkMeleeCollisionWithPlayer(attack, player));
          if (connected) {
            if (player.isStaffBlocking && !attack.isImpact) {
              this.createDamageNumber('BLOCK', player.position.x, player.position.y, '#aaaaaa');
            } else {
              // Build damage source object
              const damageSource = {
                isBullet: false,
                isMelee: true,
                element: attack.onHit,
                attacker: attack.owner
              };
              const result = player.takeDamage(attack.damage, damageSource);

              // Handle special results
              if (result.dodged) {
                this.createDamageNumber(result.lucky ? 'LUCKY DODGE' : 'DODGE',
                                        player.position.x, player.position.y,
                                        result.lucky ? '#ffff66' : '#ffff00');
              } else if (result.blocked) {
                this.createDamageNumber(result.guard ?? 'BLOCK', player.position.x, player.position.y, '#aaaaaa');
                if (result.reflect && result.attacker) {
                  result.attacker.takeDamage(result.reflect);
                  this.createDamageNumber(result.reflect, result.attacker.position.x, result.attacker.position.y, '#eeeeff');
                }
              } else if (result.immune) {
                this.createDamageNumber('IMMUNE', player.position.x, player.position.y, '#00ffff');
              } else if (result !== false) {
                if (attack.steal) {
                  ThiefMechanic.resolveTheft(attack, player, this);
                } else {
                  this.createDamageNumber(result.actualDamage ?? attack.damage, player.position.x, player.position.y, player.color);
                }

                // Apply knockback to player
                if (attack.knockback) {
                  this.physicsSystem.applyKnockback(
                    player,
                    attack.position.x, attack.position.y,
                    attack.knockback || 200
                  );
                }

                // Hitstop on confirmed player hit
                this.physicsSystem.applyHitstop(player, 0.06);

                // Enemy melee elemental follow-through (e.g. Plague Rat's poison bite)
                if (attack.onHit === 'poison') {
                  player.applyStatusEffect('poison', attack.poisonDuration ?? 4.0);
                }

                // Handle reflection
                if (result.reflect && result.attacker) {
                  result.attacker.takeDamage(result.reflect);
                  this.createDamageNumber(result.reflect, result.attacker.position.x, result.attacker.position.y, '#ff8800');
                }
              }

              if (result === true) {
                return { playerDead: true };
              }
            }
          }
        }
        retireAfterTest(attack, connected);
      }

      if (expired) this.enemyMeleeAttacks.splice(i, 1);
    }

    // DOT effect colors
    const DOT_COLORS = {
      burn: '#ff4400',
      poison: '#88ff00',
      wet: '#4488ff'  // slimes only (data.wetDot)
    };

    // Enemy attacks and DOT damage
    for (const enemy of enemies) {
      // Bug #92: the canonical enemy tick lives in main.js (surface loop) or
      // HutSystem/DungeonSystem (interiors). Consume its cached result here —
      // calling enemy.update() again doubled every enemy timer and swallowed
      // one-shot events ~50% of the time. Target overrides (charm/noise) now
      // run at the tick site via applyTargetOverrides().
      const updateResult = enemy._frameUpdateResult;
      enemy._frameUpdateResult = null;

      // Create damage numbers for DOT damage
      if (updateResult && updateResult.dotDamage) {
        for (const dotEvent of updateResult.dotDamage) {
          const color = DOT_COLORS[dotEvent.effect] || '#ffffff';
          this.createDamageNumber(dotEvent.damage, enemy.position.x, enemy.position.y, color);
        }
      }

      // Handle sap damage — no knockback here: the sapping enemy locks its
      // position to the player every frame, so any push is immediately undone
      // and would just cause jitter instead of a readable hit.
      if (updateResult && updateResult.sapDamage
          && !resolveEnemySap(this, enemy, updateResult.sapDamage, player)) {
        // Fire Bat: each landed sap tick sets the player burning
        const sapBurn = enemy.data.sapBurnDuration;
        const onSapLanded = sapBurn ? () => player.applyStatusEffect('burn', sapBurn) : null;
        if (this._applyBlockableEnemyDamage(player, enemy, updateResult.sapDamage.damage,
            { isBullet: false, element: null, attacker: enemy }, onSapLanded)) {
          return { playerDead: true };
        }
      }

      // Sniper: beam VFX spawn + beam/dagger damage resolution (kept in
      // SniperMechanic.js for cohesion; this file only owns dispatch).
      if (updateResult && (updateResult.sniperBeamFired || updateResult.sniperBeamHit || updateResult.sniperDaggerHit)) {
        if (SniperMechanic.consumeResult(this, enemy, updateResult, player)) {
          return { playerDead: true };
        }
      }

      // Whether the enemy attacks this frame, and the windup visual's lifecycle
      // behind it, both live in the shared Telegraph module (single canonical
      // implementation, also stepped by the enemy-editor sandbox). This file
      // spawns what comes back and owns nothing else about the decision.
      const attackData = resolveEnemyAttack(enemy, this.enemyMeleeAttacks);
      if (attackData) {
        this.createEnemyAttack(attackData);
      }
    }

    // Stuck arrows: follow hosts, expire, player pickup refunds, burn timer.
    updateStuckArrows(this.stuckArrows, deltaTime, player, this);

    // Update tongue attacks (frog) — extend/hold/retract + hit resolution lives in TongueAttackSystem
    const tongueResult = this.tongueAttackSystem.update(deltaTime, player);
    if (tongueResult) return tongueResult;

    const objectEffects = this.objectDestroyEvents.splice(0);
    const impactEffects = this.impactEffects.splice(0);
    const newSteamClouds = this.newSteamClouds.splice(0);
    const polymorphEvents = this.polymorphEvents.splice(0);

    // Tag any newly-spawned combat entities with the current interior state so
    // render helpers can filter by hutPlane (idempotent — already-tagged entities skipped).
    this._tagCombatHutPlane();

    return { playerDead: false, objectEffects, impactEffects, newSteamClouds, polymorphEvents };
  }

  // SPACE attack flow (EXPLORE): gem-wand mana gate, charge SFX on first
  // press, then route the attack. Caller has already verified
  // player.heldItem && player.canAttack() and that no higher-priority
  // interaction (pickup, captive, container) claimed the press.
  tryUseHeldWeapon() {
    const game = this.game;
    const player = game.player;

    // Gem wands gate the charge on mana availability before useHeldItem starts charging.
    if (player.heldItem.data?.gemWand && !game.magicSystem.tryStartCharge(player)) {
      return;
    }
    // Attack — melee AoE handles object damage directly via CombatSystem
    game.attackSequenceActive = true; // Mark that attack was initiated by button press (even if windup delays it)
    const wasBowCharging = player.heldItem.data.weaponType === 'BOW' && player.heldItem.isCharging;
    const wasGemCharging = player.heldItem.data?.gemWand && player.heldItem.isCharging;
    const attack = player.useHeldItem();
    // Play bow charge SFX when charging begins (use() sets isCharging on first press)
    if (!wasBowCharging && player.heldItem && player.heldItem.data.weaponType === 'BOW' && player.heldItem.isCharging) {
      game.audioSystem.playStoppableSFX('charge_bow');
    }
    // Gem-wand charge SFX, stretched to match this wand's chargeTime.
    if (!wasGemCharging && player.heldItem?.data?.gemWand && player.heldItem.isCharging) {
      game.audioSystem.playStoppableSFXStretched('wand_charge', player.heldItem.data.chargeTime);
    }
    // AoE melee held-windup SFX, stretched to the windup's real length
    // (windupDuration is in double-seconds). Only on the press that started the
    // windup; handleSpaceRelease stops it on an early let-go.
    const held = player.heldItem;
    if (held?.windupActive && held.windupTimer === held.windupDuration && held.holdsWindup()) {
      game.audioSystem.playStoppableSFXStretched('melee_charge', held.windupDuration / PHYSICS.WEAPON_TIMER_RATE);
    }
    if (attack) {
      this.createAttack(game.applyGreenDamageModifier(attack), game._activeEnemies());
      game.triggerGreenActionCooldown();
    }
  }

  createAttack(attackData, enemies = []) {
    if (!attackData) return;

    if (Array.isArray(attackData)) {
      // Multiple projectiles
      for (const data of attackData) {
        this.addAttack(data, enemies);
      }
    } else {
      return this.addAttack(attackData, enemies);
    }
  }

  addAttack(attackData, enemies = []) {
    if (attackData.type === 'bullet' || attackData.type === 'arrow' || attackData.type === 'transmutation_bolt') {
      const proj = {
        ...attackData,
        width: GRID.CELL_SIZE,
        height: GRID.CELL_SIZE,
        plane: attackData.shooterPlane !== undefined ? attackData.shooterPlane : 0 // Inherit plane from shooter
      };
      // Universal finite bullet range — arrows have their own deceleration model
      if (proj.type === 'bullet' && proj.remainingDistance === undefined) {
        proj.remainingDistance = attackData.bulletRange ?? DEFAULT_BULLET_RANGE;
      }
      // Per-shot accuracy roll — missed bullets pass through enemies with no damage,
      // showing "MISS". 1.0 (or undefined) always hits.
      if (proj.type === 'bullet' && attackData.accuracy !== undefined && attackData.accuracy < 1.0) {
        proj.missed = Math.random() > attackData.accuracy;
      }
      if (proj.keenAim) applyKeenAim(proj, enemies);
      // Untagged shots in this list are the player's own
      tagLaunchPit(this.game?.activeRoom, proj, attackData.owner ?? this.game?.player);
      this.projectiles.push(proj);
    } else if (attackData.type === 'melee') {
      // Check if this is a delayed attack (for sequential animations like flail sweep)
      if (attackData.delay && attackData.delay > 0) {
        this.pendingMeleeAttacks.push({
          ...attackData
        });
      } else {
        // Strike lunge: a weapon that commits the carrier's weight forward (the
        // hammer's hop) hands the impulse over on the attack itself. Applied once,
        // as the hitbox lands; friction and the carrier's own speed cap take it
        // from there.
        if (attackData.lunge && attackData.owner?.velocity) {
          attackData.owner.velocity.vx += attackData.lunge.vx;
          attackData.owner.velocity.vy += attackData.lunge.vy;
        }
        this.meleeAttacks.push({
          ...attackData,
          hasHit: false
        });
      }
    } else if (attackData.type === 'chaos_wand' || attackData.type === 'blind_wand') {
      // Wand attacks with proximity requirement
      // Check if at least one enemy is within proximity range
      const hasNearbyEnemy = this.checkProximity(attackData.position, attackData.proximityRequired, enemies, planeOf(attackData.owner));

      if (!hasNearbyEnemy) {
        // Proximity requirement not met - show red X feedback and don't consume attack
        // Store failed attempt for visual feedback (blinking circle showing requirement radius)
        this.wandProximityFailures = this.wandProximityFailures || [];
        this.wandProximityFailures.push({
          position: attackData.position,
          proximityRequired: attackData.proximityRequired,
          timer: 0.5, // Show for 0.5 seconds
          color: '#ff0000'
        });
        return false; // Indicate failure
      }

      // Proximity met - process wand attack
      if (attackData.type === 'chaos_wand') {
        // Create AOE explosion centered on player
        this.createExplosion(
          attackData.position.x,
          attackData.position.y,
          attackData.blastRadius,
          attackData.damage,
          enemies,
          [],
          attackData.damageMin, // Pass damage falloff
          planeOf(attackData.owner) // Plane of the wand's owner
        );
        // Add visual AOE effect
        this.aoeEffects.push({
          type: 'chaos',
          x: attackData.position.x,
          y: attackData.position.y,
          radius: attackData.blastRadius,
          timer: 0.3, // Show for 0.3 seconds
          color: attackData.color || '#9932cc'
        });
      } else if (attackData.type === 'blind_wand') {
        // Apply blind status to all enemies in radius
        const affectedCount = this.applyAOEStatus(
          attackData.position,
          attackData.effectRadius,
          'blind',
          attackData.effectDuration,
          enemies,
          planeOf(attackData.owner) // Plane of the wand's owner
        );
        // Add visual AOE effect
        this.aoeEffects.push({
          type: 'blind',
          x: attackData.position.x,
          y: attackData.position.y,
          radius: attackData.effectRadius,
          timer: 0.3, // Show for 0.3 seconds
          color: attackData.color || '#444444'
        });
      }

      return true; // Indicate success
    }
  }

  checkProjectileCollision(proj, enemy) {
    const projBox = {
      x: proj.position.x,
      y: proj.position.y,
      width: proj.width || GRID.CELL_SIZE,
      height: proj.height || GRID.CELL_SIZE
    };

    const enemyBox = enemy.getHitbox();

    return projBox.x < enemyBox.x + enemyBox.width &&
           projBox.x + projBox.width > enemyBox.x &&
           projBox.y < enemyBox.y + enemyBox.height &&
           projBox.y + projBox.height > enemyBox.y;
  }

  checkMeleeCollision(attack, enemy) {
    const attackBox = {
      x: attack.position.x,
      y: attack.position.y,
      width: attack.width,
      height: attack.height
    };

    const enemyBox = enemy.getHitbox();

    return attackBox.x < enemyBox.x + enemyBox.width &&
           attackBox.x + attackBox.width > enemyBox.x &&
           attackBox.y < enemyBox.y + enemyBox.height &&
           attackBox.y + attackBox.height > enemyBox.y;
  }

  checkMeleeCollisionWithObject(attack, obj) {
    // Segment-gated fixtures (Whip Trial hook posts) only count a hit from
    // the weapon's farthest reach segments — nearer segments miss outright.
    if (obj.minAttackSegment && (attack.segmentIndex || 0) < obj.minAttackSegment) return false;

    const attackBox = {
      x: attack.position.x,
      y: attack.position.y,
      width: attack.width,
      height: attack.height
    };

    const objBox = obj.getHitbox();

    return attackBox.x < objBox.x + objBox.width &&
           attackBox.x + attackBox.width > objBox.x &&
           attackBox.y < objBox.y + objBox.height &&
           attackBox.y + attackBox.height > objBox.y;
  }

  createEnemyAttack(attackData) {
    if (!attackData) return;

    if (Array.isArray(attackData)) {
      // Multi-element attack (multi-shot, fire breath, melee arc/sweep, etc).
      // Dispatch each element by type so e.g. a goblin's swung sword arc lands
      // in enemyMeleeAttacks rather than enemyProjectiles.
      for (const data of attackData) {
        this.createEnemyAttack(data);
      }
      return;
    }

    if (attackData.type === 'tongue') {
      this.tongueAttackSystem.spawn(attackData);
      return;
    }

    if (attackData.type === 'enemy_melee') {
      // Delay (e.g. multi-hit arc/sweep) is uncommon for enemy melee; ignore it
      // for now and fire each segment immediately. pendingMeleeAttacks is the
      // player-melee queue, so we can't reuse it here.
      this.enemyMeleeAttacks.push({ ...attackData, hasHit: false });
      return;
    }

    // Default: projectile (arrow, bolt, rock, magic, etc.)
    const proj = {
      ...attackData,
      width:  attackData.width  ?? GRID.CELL_SIZE,
      height: attackData.height ?? GRID.CELL_SIZE,
      plane: attackData.shooterPlane !== undefined ? attackData.shooterPlane : 0
    };
    if (attackData.delay && attackData.delay > 0) {
      this.pendingEnemyProjectiles.push(proj); // Pit-tagged on release (update)
    } else {
      tagLaunchPit(this.game?.activeRoom, proj, proj.owner);
      this.enemyProjectiles.push(proj);
    }
    tagCharmedProjectile(proj, this.game?.player);
  }

  checkProjectileCollisionWithPlayer(proj, player) {
    const hw = proj.width  || GRID.CELL_SIZE;
    const hh = proj.height || GRID.CELL_SIZE;
    const projBox = {
      x: proj.position.x + (GRID.CELL_SIZE - hw) / 2,
      y: proj.position.y + (GRID.CELL_SIZE - hh) / 2,
      width:  hw,
      height: hh
    };

    const playerBox = player.getHitbox();

    return projBox.x < playerBox.x + playerBox.width &&
           projBox.x + projBox.width > playerBox.x &&
           projBox.y < playerBox.y + playerBox.height &&
           projBox.y + projBox.height > playerBox.y;
  }

  checkMeleeCollisionWithPlayer(attack, player) {
    // Use more precise hitbox matching character size (not full tile)
    const widthReduction = attack.width * 0.5;
    const heightReduction = attack.height * 0.25;
    const attackBox = {
      x: attack.position.x + widthReduction / 2,
      y: attack.position.y + heightReduction / 2,
      width: attack.width - widthReduction,
      height: attack.height - heightReduction
    };

    const playerBox = player.getHitbox();

    return attackBox.x < playerBox.x + playerBox.width &&
           attackBox.x + attackBox.width > playerBox.x &&
           attackBox.y < playerBox.y + playerBox.height &&
           attackBox.y + attackBox.height > playerBox.y;
  }

  // Red Warrior's damage dodge-roll — see RollDamageMechanic.js. Extracted
  // to its own file (not a shared mechanic, just an architecture-budget
  // split); state (_rollHitEnemies/_rollHitObjects/_rollWasActive) stays on
  // this instance.
  updateRollDamage(player, enemies, backgroundObjects) {
    updateRollDamageImpl(this, player, enemies, backgroundObjects);
  }

  applyKnockback(enemy, attack) {
    this.physicsSystem.applyKnockback(
      enemy,
      attack.position.x, attack.position.y,
      (attack.knockback || 200) * knockbackTakenScale(enemy, attack)
    );
  }

  getChainArcs() {
    return this.chainArcs;
  }

  // Proximity check, AOE status application, and explosion damage/knockback
  // — logic lives in ExplosionEffects.js (extracted for CombatSystem's size
  // budget); these stay as public methods so existing callers (MagicSystem,
  // etc.) are unaffected.
  checkProximity(position, proximityRange, enemies, sourcePlane = 0) {
    return checkProximityImpl(position, proximityRange, enemies, sourcePlane);
  }

  applyAOEStatus(position, radius, statusType, duration, enemies, sourcePlane = 0) {
    return applyAOEStatusImpl(position, radius, statusType, duration, enemies, sourcePlane);
  }

  createExplosion(x, y, radius, damage, enemies, backgroundObjects = [], damageMin = 0, sourcePlane = 0) {
    return createExplosionImpl(this, x, y, radius, damage, enemies, backgroundObjects, damageMin, sourcePlane);
  }

  // Returns { damage, isCrit, isLucky }. Only player attacks roll crits, gated
  // by player.critChance (Lucky Coin / well ritual) or weapon's own critChance.
  // isLucky=true when the Lucky Coin/well is the crit source (shows "LUCKY CRIT");
  // isLucky=false when the weapon alone provides the chance (shows "CRIT").
  _applyCritIfLucky(damage, owner, enemy) {
    if (!owner?.quickSlots) return { damage, isCrit: false };
    let critChance = owner.critChance || 0;
    const isLucky = critChance > 0; // Lucky Coin or well is contributing
    const activeWeapon = owner.quickSlots[owner.activeSlotIndex];
    if (activeWeapon?.data?.critChance) {
      critChance = Math.max(critChance, activeWeapon.data.critChance);
    }
    // Post-dodge crit window: dagger-class weapons force a guaranteed crit.
    if (activeWeapon?.data?.weaponSubtype === 'dagger' && owner.postDodgeCritTimer > 0) {
      critChance = 1;
    }
    // Punishing a telegraphed swing: a hit that lands in the back half of the
    // enemy's windup is a guaranteed crit.
    if (enemy?.isInCritWindow?.()) {
      critChance = 1;
    }
    if (!(critChance > 0)) return { damage, isCrit: false };
    if (Math.random() >= critChance) return { damage, isCrit: false };
    const critMult = activeWeapon?.data?.weaponSubtype === 'dagger' ? 2 : 1.5;
    return { damage: Math.ceil(damage * critMult), isCrit: true, isLucky };
  }

  createDamageNumber(damage, x, y, color, scale = 1, duration = 1.0) {
    this.damageNumbers.push(tagInteriorPlane(this.game, {
      value: damage,
      x: x + GRID.CELL_SIZE / 2,
      y: y,
      alpha: 1.0,
      timer: 0,
      duration,
      riseSpeed: 30,  // pixels per second
      color: color,
      scale: scale
    }));
  }

  // Staggered player combat text — see DamageNumberQueue.js.
  queueDamageNumber(target, damage, x, y, color, scale = 1, duration = 1.0) {
    queueDamageNumberImpl(this, target, damage, x, y, color, scale, duration);
  }

  // Shared entry point for every heal source (hot spring, consumables, …) so
  // healing always shows the same green "+N" feedback damage number shows for damage.
  // `target` opts into the stagger queue (queueDamageNumber) — omit for a one-off
  // heal with nothing else competing for the same frame.
  showHeal(amount, x, y, target = null) {
    if (target) this.queueDamageNumber(target, `+${amount}`, x, y, COLORS.HEAL);
    else this.createDamageNumber(`+${amount}`, x, y, COLORS.HEAL);
  }

  clear() {
    // Boomerangs still in the air or lodged in the room being torn down hand
    // their charge back first — otherwise a room exit strands the bow's ammo.
    for (const proj of this.projectiles) {
      if (proj.boomerang) BoomerangMechanic._refundAmmo(proj);
    }
    for (const arrow of this.stuckArrows) BoomerangMechanic.releaseStuck(arrow);
    this.projectiles = [];
    this.enemyProjectiles = [];
    this.meleeAttacks = [];
    this.enemyMeleeAttacks = [];
    this.pendingMeleeAttacks = [];
    this.pendingEnemyProjectiles = [];
    this.damageNumbers = [];
    this.stuckArrows = [];
    this.tongueAttackSystem.reset();
    this.aoeEffects = [];
    this.chainArcs = [];
    this.polymorphEvents = [];
    this.impactEffects = [];
    this.newSteamClouds = [];
    this.objectDestroyEvents = [];
  }

  // The hutPlane value a combat entity spawned right now carries — and so
  // the layer the player is on, for anything that must match it.
  activeHutPlane() {
    return !!(this.game?.activeFloor || this.game?.player?.inMaze);
  }

  // Tag all combat entities with hutPlane based on current interior state
  // (game.activeFloor for hut/dungeon, player.inMaze for the maze — it has no
  // activeFloor of its own). Called at the end of update() so newly-spawned
  // entities get tagged before render; existing tags are left alone.
  _tagCombatHutPlane() {
    const hp = this.activeHutPlane();
    const arrays = [
      this.projectiles, this.enemyProjectiles,
      this.meleeAttacks, this.enemyMeleeAttacks,
      this.stuckArrows, this.tongueAttackSystem.tongueAttacks,
      this.chainArcs, this.aoeEffects,
      this.damageNumbers,
    ];
    for (const arr of arrays) {
      for (const e of arr) {
        if (e.hutPlane === undefined) e.hutPlane = hp;
      }
    }
  }

  getProjectiles() {
    return this.projectiles;
  }

  getEnemyProjectiles() {
    return this.enemyProjectiles;
  }

  getMeleeAttacks() {
    return this.meleeAttacks;
  }

  getEnemyMeleeAttacks() {
    return this.enemyMeleeAttacks;
  }

  getDamageNumbers() {
    return this.damageNumbers;
  }

  getStuckArrows() {
    return this.stuckArrows;
  }

  getTongueAttacks() {
    return this.tongueAttackSystem.tongueAttacks;
  }

  cancelPendingAttacksFrom(owner) {
    for (let i = this.pendingEnemyProjectiles.length - 1; i >= 0; i--) {
      if (this.pendingEnemyProjectiles[i].owner === owner) {
        this.pendingEnemyProjectiles.splice(i, 1);
      }
    }
  }

  checkProjectileCollisionWithObject(proj, obj) {
    const projBox = {
      x: proj.position.x,
      y: proj.position.y,
      width: proj.width || GRID.CELL_SIZE,
      height: proj.height || GRID.CELL_SIZE
    };

    const objBox = obj.getHitbox();

    return projBox.x < objBox.x + objBox.width &&
           projBox.x + projBox.width > objBox.x &&
           projBox.y < objBox.y + objBox.height &&
           projBox.y + projBox.height > objBox.y;
  }

  reflectBullet(bullet, obj) {
    // Calculate reflection angle with some randomness
    const angle = Math.atan2(bullet.velocity.vy, bullet.velocity.vx);
    const reflectedAngle = angle + Math.PI + (Math.random() - 0.5) * 1.0;

    const speed = Math.sqrt(bullet.velocity.vx ** 2 + bullet.velocity.vy ** 2);
    bullet.velocity.vx = Math.cos(reflectedAngle) * speed;
    bullet.velocity.vy = Math.sin(reflectedAngle) * speed;
    if (bullet.drawAngle != null) bullet.drawAngle = reflectedAngle;

    // Mark as reflected so it doesn't hit player
    bullet.reflected = true;

    // Placeholder ricochet SFX — wired via main.js; silently no-ops if unloaded.
    this.audioSystem?.playSFX?.('ricochet', 0.6);
  }

  conductElectricity(sourceObj, damage, enemies, player = null) {
    return conductElectricityImpl(this, sourceObj, damage, enemies, player);
  }
}
