// Cursed recipes: the crafting station only recognizes these during a Cursed
// Run (CraftingSystem.updateCrafting). Undead drop a scroll that shows one of
// them (CursedRunSystem.tryReadScroll); knowing a pair from an earlier run
// works just as well — the scroll is a hint, not a gate.
export const CURSED_RECIPES = [
  { left: 'b', right: 'F', result: '☠', name: 'Cursed Skull' },   // Bone + Fire = Cursed Skull
  { left: 'j', right: 'k', result: '⊷', name: 'Cursed Belt' },    // Jaw + Silk = Cursed Belt (two depths per exit)
];

export function findCursedRecipe(leftChar, rightChar) {
  return CURSED_RECIPES.find(r => (r.left === leftChar && r.right === rightChar)
                               || (r.left === rightChar && r.right === leftChar));
}

export function findRecipe(leftChar, rightChar) {
  // Try both orderings
  let recipe = RECIPES.find(r => r.left === leftChar && r.right === rightChar);
  if (!recipe) {
    recipe = RECIPES.find(r => r.left === rightChar && r.right === leftChar);
  }
  return recipe;
}

// Forge Recipes — Scale only works in fire. Any recipe with Scale as an input
// crafts at the Dragon Forge (ForgeSystem, green boss room after the Goo
// Dragon falls) and never at the REST station, which shows an ember tell
// instead. Derived from the input rather than a per-recipe field, so a new
// Scale recipe is gated without anyone remembering to tag it.
export const FORGE_INGREDIENT = 's';

export function requiresForge(recipe) {
  return !!recipe && (recipe.left === FORGE_INGREDIENT || recipe.right === FORGE_INGREDIENT);
}

export function getRecipeResult(leftChar, rightChar) {
  const recipe = findRecipe(leftChar, rightChar);
  return recipe ? recipe.result : null;
}

export function findRecipeByResult(resultChar) {
  const recipe = RECIPES.find(r => r.result === resultChar);
  return recipe ? { left: recipe.left, right: recipe.right } : null;
}
