/**
 * WellSystem — handles the W-room well ritual.
 *
 * The W exit letter generates a ROOM_TYPES.WELL room with a single circular
 * well at its center. The well accepts three offerings:
 *
 *   ¤  Infused Coin (consumable slot)  → activates the magic meter
 *   ★  Lucky Coin   (consumable slot)  → permanent half-power luck blessing
 *   ⊚  Frog Coin    (consumable slot)  → the Witch's frog curse (PolymorphSystem)
 *   c  Coin         (raw ingredient)    → zone-specific blessing, well stays usable
 *
 * Raw-coin rewards depend on the current zone:
 *   green  → luckBlessed (same half-power luck blessing as ★ vesting)
 *   yellow → scatters 2–3 Mana ingredients (𝑚) from the well
 *   red    → wellDamageBlessed (+1 damage on all attacks) — on the
 *            RED_WELL_COST-th coin into the same well; the coins before it
 *            get "NO RESPONSE" (a red wise-fellow saying hints at this)
 *   cyan   → stealthBlessed (enemies detect at reduced radius)
 *
 * The green/red/cyan blessings are run-flags and cannot stack — a repeat toss
 * lands silently (plink, no flash, no message). Yellow drops are repeatable.
 *
 * All offerings play the spinning-arc animation. Slot offerings (¤, ★, ⊚)
 * require the slot to be armed first (number key) then thrown with SPACE —
 * see tryOfferArmedSlot(), mirroring AlchemySystem.tryFillArmedBottle's
 * arm-then-SPACE shape — and land with a flash that consumes the well. Raw-coin
 * offerings flash only when a blessing is actually granted, and never consume
 * the well; they still auto-fire from proximity+SPACE via handleSpacePress().
 */

import { GRID, ROOM_TYPES } from '../game/GameConfig.js';

const PROXIMITY_RADIUS = GRID.CELL_SIZE * 3;     // player must be within 3 cells of well center
const ARC_DURATION = 0.55;                       // total seconds for the coin arc
const ARC_PEAK_HEIGHT = GRID.CELL_SIZE * 4;      // how high the arc peaks above the midpoint
const FLASH_DURATION = 0.6;                      // screen flash fade time
const RED_WELL_COST = 5;                         // raw coins a red well takes before it blesses
// Slot-offering type → the coin char it consumes from the slot.
const OFFERING_CHARS = { infused: '¤', lucky: '★', frog: '⊚' };

export class WellSystem {
  constructor(game) {
    this.game = game;
  }

  // Per-frame: animate any in-flight coin and tick the screen flash.
  update(dt) {
    const game = this.game;

    if (game.wellCoinAnim) {
      // Abort cleanly if the player warped out mid-arc — the coin is already
      // consumed (room.well.consumed = true) so the well stays inert, but we
      // skip activating the meter in a different room.
      if (game.wellCoinAnim.room && game.wellCoinAnim.room !== game.currentRoom) {
        game.wellCoinAnim = null;
      } else {
        game.wellCoinAnim.t += dt;
        game.wellCoinAnim.spinPhase += dt * 12; // spin speed
        if (game.wellCoinAnim.t >= ARC_DURATION) {
          const anim = game.wellCoinAnim;
          game.wellCoinAnim = null;
          this._completeRitual(anim);
        }
      }
    }

    if (game.wellFlashTimer > 0) {
      game.wellFlashTimer = Math.max(0, game.wellFlashTimer - dt);
    }
  }

  // Armed Infused/Lucky Coin (selected via number key) near a well — mirrors
  // AlchemySystem.tryFillArmedBottle's arm-then-SPACE shape rather than
  // auto-firing off proximity+SPACE alone. Must be checked BEFORE
  // ConsumableTriggerSystem.fireSelected(), same as the Bottle/fairy checks.
  tryOfferArmedSlot() {
    const game = this.game;
    const player = game.player;
    const room = game.currentRoom;

    if (!player || !room) return false;
    if (room.type !== ROOM_TYPES.WELL) return false;
    if (!room.well || room.well.consumed || game.wellCoinAnim) return false;

    const idx = player.selectedConsumableIndex ?? -1;
    if (idx < 0) return false;

    const offering = this._findOfferingSlot();
    if (!offering || offering.index !== idx) return false;

    const wellCx = room.well.centerX;
    const wellCy = room.well.centerY;
    const px = player.position.x + GRID.CELL_SIZE / 2;
    const py = player.position.y + GRID.CELL_SIZE / 2;
    const dx = px - wellCx;
    const dy = py - wellCy;
    if (dx * dx + dy * dy > PROXIMITY_RADIUS * PROXIMITY_RADIUS) return false;

    // Skip if this offering is redundant for the current state.
    if (offering.type === 'infused' && player.magicMeter?.active) return false;
    if (offering.type === 'lucky'   && player.luckBlessed)        return false;
    if (offering.type === 'frog'    && player.polymorphed)        return false;

    game.wellCoinAnim = {
      startX: px,
      startY: py,
      endX: wellCx,
      endY: wellCy,
      t: 0,
      spinPhase: 0,
      slotIndex: offering.index,
      offeringType: offering.type,   // 'infused' | 'lucky' | 'frog'
      room                            // anim aborts if player warps out
    };

    // Lock the well immediately so a second SPACE during the arc can't re-fire.
    room.well.consumed = true;
    player.selectedConsumableIndex = -1;
    return true;
  }

  // Returns true if it consumed the SPACE press (well + offering in range).
  handleSpacePress() {
    const game = this.game;
    const player = game.player;
    const room = game.currentRoom;

    if (!player || !room) return false;
    if (room.type !== ROOM_TYPES.WELL) return false;
    if (!room.well) return false;
    if (game.wellCoinAnim) return true; // ritual in progress, swallow input

    const wellCx = room.well.centerX;
    const wellCy = room.well.centerY;
    const px = player.position.x + GRID.CELL_SIZE / 2;
    const py = player.position.y + GRID.CELL_SIZE / 2;
    const dx = px - wellCx;
    const dy = py - wellCy;
    if (dx * dx + dy * dy > PROXIMITY_RADIUS * PROXIMITY_RADIUS) return false;

    // Raw coin probe (`c` ingredient): always available, doesn't consume the well.
    // Plays the spinning arc + hollow plink — the well's indifferent response
    // that nudges the player toward crafting the real offering.
    if (game.inventorySystem?.hasCoin()) {
      game.inventorySystem.removeCoin();
      game.wellCoinAnim = {
        startX: px,
        startY: py,
        endX: wellCx,
        endY: wellCy,
        t: 0,
        spinPhase: 0,
        slotIndex: -1,
        offeringType: 'raw',
        room
      };
      return true;
    }

    // Empty-handed SPACE: the well answers with a plain line. Not an NPC, so
    // this bypasses dialogueSystem.tryOpenNearby()'s npc-list scan and opens
    // directly against a position-only speaker stub.
    if (game.dialogueSystem?.open({ position: { x: wellCx, y: wellCy } }, ['Your voice echoes back.'])) {
      return true;
    }

    return false;
  }

  // ── Internal ──────────────────────────────────────────────────────────────

  // Returns the first slot holding a recognized offering, or null. Infused Coin
  // takes priority when several are equipped (the magic meter is the more
  // central ritual; players who want the lucky blessing can move the coins
  // around), then Lucky Coin, then Frog Coin.
  _findOfferingSlot() {
    const inv = this.game.inventorySystem;
    if (!inv) return null;
    const slots = inv.equippedConsumables || [];
    let luckyIndex = -1;
    let frogIndex = -1;
    for (let i = 0; i < slots.length; i++) {
      const ch = slots[i]?.data?.char;
      if (ch === '¤') return { index: i, type: 'infused' };
      if (ch === '★' && luckyIndex < 0) luckyIndex = i;
      if (ch === '⊚' && frogIndex < 0) frogIndex = i;
    }
    if (luckyIndex >= 0) return { index: luckyIndex, type: 'lucky' };
    if (frogIndex >= 0) return { index: frogIndex, type: 'frog' };
    return null;
  }

  // Grants the zone-specific raw-coin blessing. Returns true if something was
  // actually granted (drives the screen flash); false for redundant or quiet
  // tosses. The boolean blessings can't stack — a redundant toss lands silently.
  _grantCoinBlessing(anim) {
    const game = this.game;
    const player = game.player;
    const msg = (text) => game.menuSystem?.showPickupMessage?.(text);
    const zone = game.zoneSystem?.currentZone || 'green';

    switch (zone) {
      case 'green':
        if (player.luckBlessed) {
          return false;
        }
        player.luckBlessed = true;
        msg('FEELING LUCKY?');
        return true;

      case 'yellow': {
        // The well spits back a scatter of Mana ingredients (𝑚). Pickup
        // auto-fills the meter when active; stores as ingredients otherwise.
        const count = 2 + Math.floor(Math.random() * 2); // 2–3
        for (let i = 0; i < count; i++) {
          const angle = (i / count) * Math.PI * 2 + Math.random() * 0.8;
          game.lootSystem?.spawnIngredientDrop('𝑚', anim.endX, anim.endY, angle);
        }
        msg('MANA WELLS UP.');
        return true;
      }

      case 'red': {
        if (player.wellDamageBlessed) {
          return false;
        }
        // The red well answers only persistence: coins are counted on this
        // well, and every toss short of RED_WELL_COST gets no answer.
        const well = anim.room.well;
        well.coinsReceived += 1;
        if (well.coinsReceived < RED_WELL_COST) {
          msg('NO RESPONSE');
          return false;
        }
        player.wellDamageBlessed = true;
        msg('YOUR PERSISTENCE IS REWARDED');
        return true;
      }

      case 'cyan':
        if (player.stealthBlessed) {
          return false;
        }
        player.stealthBlessed = true;
        msg('FEELING QUIET?');
        return true;

      default:
        // Gray/blue wells stay indifferent.
        msg('THE WELL IS QUIET.');
        return false;
    }
  }

  _completeRitual(anim) {
    const game = this.game;
    const player = game.player;
    const inv = game.inventorySystem;
    if (!player || !inv) return;

    // The coin lands. Same plink for ¤, ★ and ⊚ — the well's voice doesn't
    // distinguish offerings, only the player's reward does.
    game.audioSystem?.playSFX?.('coin_plink');

    // Raw-coin toss: zone-specific blessing. The `c` ingredient was already
    // removed at SPACE press; the well itself is never consumed by this path.
    if (anim.offeringType === 'raw') {
      const granted = this._grantCoinBlessing(anim);
      if (granted) {
        game.wellFlashTimer = FLASH_DURATION;
        game.wellFlashDuration = FLASH_DURATION;
      }
      game.menuSystem?.updateUI?.();
      return;
    }

    // Consume the offering coin from its slot.
    const slotIndex = anim.slotIndex;
    const expectedChar = OFFERING_CHARS[anim.offeringType];
    if (inv.equippedConsumables[slotIndex]?.data?.char === expectedChar) {
      inv.equippedConsumables[slotIndex] = null;
    }
    if (player.equippedConsumables && player.equippedConsumables[slotIndex]?.data?.char === expectedChar) {
      player.equippedConsumables[slotIndex] = null;
    }

    if (anim.offeringType === 'frog') {
      // The Frog Coin carries the Witch's curse: the well hands it back as
      // frog form, cursed — exits forced open, cured by the Lake Rusalka or a
      // HEAL/UNCURSE wish. activatePolymorph plays the transform SFX.
      game.polymorphSystem?.activatePolymorph(game, true);
    } else if (anim.offeringType === 'lucky') {
      // Permanent half-power luck blessing for the rest of the run. Loot/exit
      // hooks read player.luckBlessed; the next applyEquipmentEffectsToPlayer
      // pass will leave the flag intact since it lives outside the recompute.
      player.luckBlessed = true;
      // Placeholder fanfare — reusing boss_defeat until a dedicated lucky cue exists.
      game.audioSystem?.playSFX?.('boss_defeat');
      game.menuSystem?.showPickupMessage?.('FEELING LUCKY.');
    } else {
      // Activate the magic meter on the slot we just cleared.
      game.magicSystem?.activateMagicMeter(player, slotIndex);

      // Top off the meter so the player can immediately try a wand if they have
      // one, and so the ritual feels rewarding rather than like they've taken on
      // a chore.
      if (player.magicMeter?.active) {
        player.magicMeter.current = player.magicMeter.max;
      }
      game.menuSystem?.showPickupMessage?.('THE WELL ANSWERS.');
    }

    // If another valid offering is still equipped, re-open the well so the
    // player can sequence both rituals (e.g. ¤ then ★ in the same visit).
    const next = this._findOfferingSlot();
    if (next) {
      const redundant =
        (next.type === 'infused' && player.magicMeter?.active) ||
        (next.type === 'lucky'   && player.luckBlessed) ||
        (next.type === 'frog'    && player.polymorphed);
      if (!redundant) anim.room.well.consumed = false;
    }

    game.wellFlashTimer = FLASH_DURATION;
    game.wellFlashDuration = FLASH_DURATION;
    game.menuSystem?.updateUI?.();
    game.renderer.backgroundDirty = true;
  }
}
