import { GRID } from '../game/GameConfig.js';
import { isFeed } from './feed.js';
import { NPCRat } from '../entities/NPCRat.js';
import { Ingredient } from '../entities/Ingredient.js';
import { planeOf, PLANE_SURFACE, tagInteriorPlane, isInteriorActive, canReachLoot, lootOnActiveLayer, lootOnSurface } from './PlaneSystem.js';
import { GolemCompanion } from '../entities/GolemCompanion.js';
import { GOLEM_TYPES, GOLEM_CAP } from '../data/golems.js';

// Grace period before a wild crow may loot-seek a piece of ground loot,
// timed from the first frame it's observed as a valid target (effectively
// its drop/spawn time, since eligibility doesn't flicker). Gives the player
// first look at anything that just hit the ground — including their own
// starting gear — instead of a crow instantly swooping on it.
const LOOT_SEEK_DELAY_MS = 2000;
// Dirt particles per second off a digging tamed rat (NPCRat Dig).
const DIG_DIRT_RATE = 6;

// Contact damage from an enraged wild crow's dive-bomb (see snareCrow /
// updateCrows) — a peck-strength hit, not a real threat on its own, but it
// stacks with however many other room crows got enraged by the same catch.
const CROW_ENRAGE_DAMAGE = 1;

// Companion behavior: the bread-feed pipeline and per-frame drivers for every
// befriendable creature — wild rat → NPCRat companion, wild crow → follower
// flock → shoulder companion. Companion rosters (game.tamedRats,
// game.companionCrows, game.followerCrows, game.fedCrowCount) stay on game:
// renderers read them directly, the same documented compromise as trap state
// (system owns logic, game holds data). Bread is a consumable now (items.js)
// — SHIFT (TossSystem) throws it to the ground as a pickup, which is the
// whole feed trigger; this file only drives what happens once a loaf lands.
export class CompanionSystem {
  constructor(game) {
    this.game = game;
  }

  // Wild rats seeking bread: assign unowned loaves → nearest wild rat each
  // frame, then check proximity, consume the loaf, remove the wild Enemy,
  // and spawn a fresh NPCRat in its place. Replacing rather than re-skinning
  // keeps the hostile Enemy AI cleanly out of the companion's behavior tree.
  updateBreadSeekingRats() {
    const game = this.game;
    // Dungeons have no wild rats to tame, and dungeon loaves are the
    // Hoardmaw's Help-register decoy material — the wild-taming pipeline
    // stays surface-only.
    if (game.player?.inDungeon) return;
    const enemies = game.currentRoom?.enemies;
    if (!enemies || enemies.length === 0) return;

    // Assign loaves to wild rats. A loaf is "owned" once any wild rat is
    // seeking it; other rats stick to their default AI until more bread drops.
    // Hut/maze interiors seed bread into game.items tagged with hutPlane /
    // mazePlane — those positions are in interior grid space (top-left ≈ the
    // outer-room origin) and must be excluded, or surface rats path to the
    // wrong coordinates and "eat" a loaf the player never dropped.
    const loaves = game.items.filter(it =>
      it && isFeed(it) && !it.consumed && !it.hutPlane && !it.mazePlane
    );
    if (loaves.length > 0) {
      const claimedLoaves = new Set();
      const claimedRats = new Set();
      for (const e of enemies) {
        if (!e.seekingBread) continue;
        const t = e.breadTarget;
        // Release the rat if its target vanished or is an interior-tagged loaf
        // (covers any stale assignment from before the surface-only filter
        // landed) — otherwise it'd march to the top-left forever.
        if (!t || t.consumed || t.hutPlane || t.mazePlane) {
          e.seekingBread = false;
          e.breadTarget = null;
          continue;
        }
        claimedLoaves.add(t);
        claimedRats.add(e);
      }
      for (const loaf of loaves) {
        if (claimedLoaves.has(loaf)) continue;
        let nearest = null;
        let nearestDistSq = Infinity;
        for (const r of enemies) {
          if (!r.data?.tameableByBread) continue;
          if (r.hp <= 0) continue;
          if (claimedRats.has(r)) continue;
          const dx = r.position.x - loaf.position.x;
          const dy = r.position.y - loaf.position.y;
          const d = dx * dx + dy * dy;
          if (d < nearestDistSq) { nearestDistSq = d; nearest = r; }
        }
        if (nearest) {
          nearest.seekingBread = true;
          nearest.breadTarget = loaf;
          nearest.breadSeekStartTime = performance.now();
          claimedRats.add(nearest);
          claimedLoaves.add(loaf);
        }
      }
    }

    // Tight overlap required — at 0.7 cells the white-flip fired while the rat
    // was still visibly approaching. 0.35 puts the centers inside each other's
    // sprite so the eat reads as physical contact.
    const EAT_DIST_SQ = (GRID.CELL_SIZE * 0.35) ** 2;
    // Minimum time between seeking-bread assignment and eat — guarantees a
    // visible "walk to the bread" beat even if the rat was already adjacent.
    const EAT_GRACE_MS = 350;
    const now = performance.now();
    for (let i = enemies.length - 1; i >= 0; i--) {
      const rat = enemies[i];
      if (!rat.seekingBread || !rat.breadTarget) continue;
      const loaf = rat.breadTarget;
      if (loaf.consumed || loaf.destroyed) {
        rat.seekingBread = false;
        rat.breadTarget = null;
        continue;
      }
      if (now - (rat.breadSeekStartTime || 0) < EAT_GRACE_MS) continue;
      const dx = loaf.position.x - rat.position.x;
      const dy = loaf.position.y - rat.position.y;
      if (dx * dx + dy * dy > EAT_DIST_SQ) continue;

      // Eat the loaf
      loaf.consumed = true;
      const lIdx = game.items.indexOf(loaf);
      if (lIdx !== -1) {
        game.physicsSystem.removeEntity(loaf);
        game.items.splice(lIdx, 1);
      }

      // Yank the wild Enemy out of every room.enemies-style cache and physics.
      enemies.splice(i, 1);
      const p0 = game.currentRoom?.enemiesPlane0;
      if (p0) {
        const idx = p0.indexOf(rat);
        if (idx !== -1) p0.splice(idx, 1);
      }
      const p1 = game.currentRoom?.enemiesPlane1;
      if (p1) {
        const idx = p1.indexOf(rat);
        if (idx !== -1) p1.splice(idx, 1);
      }
      game.physicsSystem.removeEntity(rat);

      // Spawn the companion at the wild rat's exact position so the visual
      // hand-off reads as the rat eating the bread and turning friendly.
      const npc = new NPCRat(rat.position.x, rat.position.y);
      npc.plane = rat.plane ?? 0;
      npc.setGame(game);
      npc.setRoom(game.currentRoom);
      npc.collisionMap = game.currentRoom?.collisionMap || null;
      npc.backgroundObjects = game.currentRoom?.backgroundObjects || null;
      game.tamedRats.push(npc);
      game.physicsSystem.addEntity(npc);

      // Promotion burst — small white sparkle so the moment reads visually.
      const ex = npc.position.x + GRID.CELL_SIZE / 2;
      const ey = npc.position.y + GRID.CELL_SIZE / 2;
      for (let k = 0; k < 10; k++) {
        const angle = (k / 10) * Math.PI * 2 + Math.random() * 0.3;
        const speed = 30 + Math.random() * 30;
        game.particles.push(tagInteriorPlane(game, {
          x: ex, y: ey,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed - 15,
          life: 0.5, maxLife: 0.5,
          char: '·', color: '#ffffff'
        }));
      }
      game.particles.push(tagInteriorPlane(game, {
        x: ex, y: ey - 4, vx: 0, vy: -22,
        life: 0.9, maxLife: 0.9, char: '♥', color: '#ff5577'
      }));
    }
  }

  // Per-frame NPCRat driver: run each rat's own update with the live enemies
  // list, surface damage numbers on hits, and despawn perma-fleeing rats that
  // have reached an exit.
  updateTamedRats(deltaTime) {
    const game = this.game;
    if (!game.tamedRats || game.tamedRats.length === 0) return;
    // Canonical active-layer enemy list — inside a dungeon floor this is the
    // floor's roster, so rats bite dungeon enemies instead of staring at the
    // frozen surface room's cache (the #130/#131 layer-leak family).
    const enemies = game._activeEnemies?.() || [];
    const siblings = game.tamedRats;
    for (let i = game.tamedRats.length - 1; i >= 0; i--) {
      const rat = game.tamedRats[i];
      if (rat.state === 'permaFlee' && rat.fleeReached) {
        game.physicsSystem.removeEntity(rat);
        game.tamedRats.splice(i, 1);
        continue;
      }
      const result = rat.update(deltaTime, enemies, game.player, siblings);
      if (result?.attacked) {
        const victim = result.attacked;
        game.combatSystem.createDamageNumber?.(result.damage ?? 1,
                                               victim.position.x, victim.position.y,
                                               victim.color || '#ffffff');
      }

      // Dig: dirt kicks up while the rat digs; a find pops out of the tile.
      if (rat.state === 'dig' && rat.digTimer > 0 && Math.random() < deltaTime * DIG_DIRT_RATE) {
        const dx = rat.position.x + GRID.CELL_SIZE / 2;
        const dy = rat.position.y + GRID.CELL_SIZE / 2;
        game.particles.push(tagInteriorPlane(game, {
          x: dx, y: dy,
          vx: (Math.random() - 0.5) * 40, vy: -20 - Math.random() * 20,
          life: 0.4, maxLife: 0.4, char: '.', color: '#664422'
        }));
      }
      if (result?.unearthed && game.lootSystem) {
        game.lootSystem.spawnIngredientDrop(result.unearthed, result.x, result.y, null, rat);
      }

      // Tamed rats collect non-gravitating ingredients they overlap (e.g. vault coins)
      if (rat.state !== 'permaFlee' && game.lootSystem) {
        const rw = rat.width || GRID.CELL_SIZE;
        const rh = rat.height || GRID.CELL_SIZE;
        for (let j = game.ingredients.length - 1; j >= 0; j--) {
          const ing = game.ingredients[j];
          if (!ing.noGravitate) continue;
          if (ing.pickedUp) continue;
          if (!canReachLoot(game, rat, ing)) continue;
          const dx = rat.position.x - ing.position.x;
          const dy = rat.position.y - ing.position.y;
          if (Math.abs(dx) < rw && Math.abs(dy) < rh) {
            game.lootSystem.collectIngredient(ing);
          }
        }
      }
    }
  }

  // Apply enemy melee + projectile hits to tamed rats. Mirrors
  // CampNPCSystem._applyEnemyDamage but operates over the multi-instance array.
  applyEnemyDamageToTamedRats() {
    const game = this.game;
    if (!game.tamedRats || game.tamedRats.length === 0) return;
    const cs = game.combatSystem;
    if (!cs) return;

    const projs = cs.enemyProjectiles || [];
    for (const rat of game.tamedRats) {
      if (rat.state === 'permaFlee') continue;
      // Gilded rats are damage-immune by design — the vault's reward.
      if (rat.gilded) continue;
      if (rat.invulnerabilityTimer > 0) continue;
      // Projectiles
      for (let i = projs.length - 1; i >= 0; i--) {
        const p = projs[i];
        if ((p.plane ?? 0) !== rat.plane) continue;
        const cx = rat.position.x + rat.width / 2;
        const cy = rat.position.y + rat.height / 2;
        const dx = p.position.x - cx;
        const dy = p.position.y - cy;
        const r = GRID.CELL_SIZE * 0.6 + Math.min(rat.width, rat.height) / 2;
        if (dx * dx + dy * dy < r * r) {
          rat.takeDamage(p.damage || 1, p.owner);
          projs.splice(i, 1);
          cs.createDamageNumber?.(p.damage || 1, rat.position.x, rat.position.y, rat.color);
          break;
        }
      }
      if (rat.invulnerabilityTimer > 0) continue;
      // Melee attack hitboxes
      const melee = cs.enemyMeleeAttacks || [];
      for (const m of melee) {
        if (m.windupPhase) continue;
        if (m.hasHit) continue;
        if ((m.plane ?? 0) !== rat.plane) continue;
        const ax = m.position.x;
        const ay = m.position.y;
        const aw = m.width || GRID.CELL_SIZE;
        const ah = m.height || GRID.CELL_SIZE;
        if (
          ax < rat.position.x + rat.width && ax + aw > rat.position.x &&
          ay < rat.position.y + rat.height && ay + ah > rat.position.y
        ) {
          m.hasHit = true;
          // Pass the swinging enemy, not the hitbox: the hitbox sits on top of
          // the rat, which gives the retreat no direction to run in.
          rat.takeDamage(m.damage || 1, m.owner);
          cs.createDamageNumber?.(m.damage || 1, rat.position.x, rat.position.y, rat.color);
          break;
        }
      }
    }
  }

  // Unified companion room-entry dispatch. Each companion type (crow, tamed
  // rat, camp NPC) owns its own onRoomEnter — this just walks the rosters and
  // calls each. Companion crows reuse companionShoulderIndex for their slot;
  // tamed rats pass (index, total) so they radial-spread around the player.
  snapAllCompanionsOnRoomEnter() {
    const game = this.game;
    if (!game.player) return;
    // A crow still mid-abandon-flight at the transition is gone, the same
    // as a perma-fleeing rat below — it does not follow into the new room.
    this._pruneAbandonedCrows(() => true);
    for (const c of game.companionCrows) c.onRoomEnter?.(game.player);
    // Perma-fleeing rats from the previous room don't come back — they've
    // abandoned the player and despawn at the transition.
    if (game.tamedRats?.length) {
      game.tamedRats = game.tamedRats.filter(r => r.state !== 'permaFlee');
    }
    const ratCount = game.tamedRats?.length || 0;
    for (let i = 0; i < ratCount; i++) {
      game.tamedRats[i].onRoomEnter?.(game.player, game, i, ratCount);
    }
    const golemCount = game.golems?.length || 0;
    for (let i = 0; i < golemCount; i++) {
      game.golems[i].onRoomEnter?.(game.player, game, i, golemCount);
    }
    game.companion?.onRoomEnter?.(game.player, game);
  }

  registerTamedRatsWithPhysics() {
    const game = this.game;
    if (!game.tamedRats || game.tamedRats.length === 0) return;
    for (const rat of game.tamedRats) {
      game.physicsSystem.addEntity(rat);
    }
  }

  registerGolemsWithPhysics() {
    const game = this.game;
    if (!game.golems || game.golems.length === 0) return;
    for (const golem of game.golems) {
      game.physicsSystem.addEntity(golem);
    }
  }

  // Combined call for the 3 main.js physics-registration sites (room entry,
  // dungeon floor swaps, etc.) — keeps each site to one line as the companion
  // roster count grows.
  registerCompanionsWithPhysics() {
    this.registerTamedRatsWithPhysics();
    this.registerGolemsWithPhysics();
  }

  // Summon a golem companion at the player's position — the "recipe → summon
  // on craft" design (feature-inbox #9): combining an ingredient with Mana at
  // the Combine Station spawns the companion immediately rather than yielding
  // an inventory item. Defensive GOLEM_CAP re-check: MenuSystem's caller
  // already gates on the cap via CraftingSystem.claimCraftedGolem, but this
  // stays safe to call from anywhere. Returns the new GolemCompanion, or null
  // if the cap is full or the type is unknown.
  spawnGolem(type) {
    const game = this.game;
    if (!GOLEM_TYPES[type]) return null;
    if (!game.golems) game.golems = [];
    if (game.golems.length >= GOLEM_CAP) return null;
    const golem = new GolemCompanion(type, game.player.position.x, game.player.position.y);
    golem.setGame(game);
    golem.setRoom(game.currentRoom);
    golem.setCollisionMap(game.currentRoom?.collisionMap || null);
    golem.setBackgroundObjects(game._activeBackgroundObjects() || null); // layer-guard-ok: routed read
    game.golems.push(golem);
    game.physicsSystem.addEntity(golem);
    return golem;
  }

  // Per-frame driver for the golem roster — same shape as updateTamedRats,
  // minus permaFlee handling (golems never flee). Handles both combat
  // ('chase'/'idle') and Mud Golem's 'dead'→resurrect countdown, plus
  // feature-inbox's ground-weapon pickup (golems don't scavenge ingredients,
  // only melee weapons — see GolemCompanion.findBetterGroundWeapon).
  updateGolems(deltaTime) {
    const game = this.game;
    if (!game.golems || game.golems.length === 0) return;
    const enemies = game._activeEnemies?.() || [];
    const siblings = game.golems;
    for (let i = game.golems.length - 1; i >= 0; i--) {
      const golem = game.golems[i];
      if (golem.state !== 'dead' && game.items?.length) {
        const weapon = golem.findBetterGroundWeapon(game.items.filter(it => lootOnActiveLayer(game, it)));
        if (weapon) {
          golem.equipWeapon(weapon);
          const idx = game.items.indexOf(weapon);
          if (idx !== -1) game.items.splice(idx, 1);
          game.physicsSystem.removeEntity(weapon);
        }
      }
      const result = golem.update(deltaTime, enemies, game.player, siblings);
      if (result?.attacked) {
        const victim = result.attacked;
        game.combatSystem.createDamageNumber?.(result.damage ?? 1,
                                               victim.position.x, victim.position.y,
                                               victim.color || '#ffffff');
      }
      if (result?.died && !result.resurrecting) {
        game.physicsSystem.removeEntity(golem);
        game.golems.splice(i, 1);
      }
    }
  }

  // Combined call for the main.js update loop — keeps that call site to one
  // line, mirroring registerCompanionsWithPhysics.
  updateGolemsAndDamage(deltaTime) {
    this.updateGolems(deltaTime);
    this.applyEnemyDamageToGolems();
  }

  // Apply enemy melee + projectile hits to golems. Mirrors
  // applyEnemyDamageToTamedRats over the golem roster.
  applyEnemyDamageToGolems() {
    const game = this.game;
    if (!game.golems || game.golems.length === 0) return;
    const cs = game.combatSystem;
    if (!cs) return;

    const projs = cs.enemyProjectiles || [];
    for (let gi = game.golems.length - 1; gi >= 0; gi--) {
      const golem = game.golems[gi];
      if (golem.state === 'dead') continue;
      if (golem.invulnerabilityTimer > 0) continue;
      let result = null;
      // Projectiles
      for (let i = projs.length - 1; i >= 0; i--) {
        const p = projs[i];
        if ((p.plane ?? 0) !== golem.plane) continue;
        const cx = golem.position.x + golem.width / 2;
        const cy = golem.position.y + golem.height / 2;
        const dx = p.position.x - cx;
        const dy = p.position.y - cy;
        const r = GRID.CELL_SIZE * 0.6 + Math.min(golem.width, golem.height) / 2;
        if (dx * dx + dy * dy < r * r) {
          result = golem.takeDamage(p.damage || 1, p.owner, p.onHit);
          projs.splice(i, 1);
          cs.createDamageNumber?.(p.damage || 1, golem.position.x, golem.position.y, golem.color);
          break;
        }
      }
      if (!result && golem.invulnerabilityTimer <= 0) {
        // Melee attack hitboxes
        const melee = cs.enemyMeleeAttacks || [];
        for (const m of melee) {
          if (m.windupPhase) continue;
          if (m.hasHit) continue;
          if ((m.plane ?? 0) !== golem.plane) continue;
          const ax = m.position.x;
          const ay = m.position.y;
          const aw = m.width || GRID.CELL_SIZE;
          const ah = m.height || GRID.CELL_SIZE;
          if (
            ax < golem.position.x + golem.width && ax + aw > golem.position.x &&
            ay < golem.position.y + golem.height && ay + ah > golem.position.y
          ) {
            m.hasHit = true;
            result = golem.takeDamage(m.damage || 1, m.owner, m.onHit);
            cs.createDamageNumber?.(m.damage || 1, golem.position.x, golem.position.y, golem.color);
            break;
          }
        }
      }
      if (result?.died && !result.resurrecting) {
        game.physicsSystem.removeEntity(golem);
        game.golems.splice(gi, 1);
      }
    }
  }

  // ─── Dungeon descent: pets enter floors mortal, gild at the vault ──────────
  // Companion presence across Interior types is an ADR-backlog candidate
  // (2026-08-24). DungeonSystem._activateFloor/_exitDungeon call these around
  // every floor swap, mirroring how the camp mercenary is snapped.

  // Teleport pets onto the newly-activated floor beside the player WITHOUT
  // healing — attrition persists across floors, which is what makes the
  // mortal descent a real escort risk. Crows re-orbit on their own; rats
  // need their collision/background references pointed at floor content.
  snapPetsIntoFloor(floor) {
    const game = this.game;
    if (!game.player) return;
    const total = (game.companionCrows?.length || 0) + (game.tamedRats?.length || 0) + (game.golems?.length || 0);
    let slot = 0;
    for (const crow of game.companionCrows || []) {
      this._placePetAtPlayerSlot(crow, game.player, slot++, total);
    }
    for (const rat of game.tamedRats || []) {
      this._placePetAtPlayerSlot(rat, game.player, slot++, total);
      rat.setCollisionMap(floor.collisionMap);
      rat.setBackgroundObjects(floor.backgroundObjects); // layer-guard-ok: router-injected
    }
    for (const golem of game.golems || []) {
      this._placePetAtPlayerSlot(golem, game.player, slot++, total);
      golem.setCollisionMap(floor.collisionMap);
      golem.setBackgroundObjects(floor.backgroundObjects); // layer-guard-ok: router-injected
    }
  }

  // Dungeon exit: bring pets back to surface coordinates beside the player,
  // restore their surface collision/background references (#141 discipline),
  // and clear any gilded state — the vault's reward does not leave with you.
  restorePetsFromFloor() {
    const game = this.game;
    if (!game.player) return;
    const total = (game.companionCrows?.length || 0) + (game.tamedRats?.length || 0) + (game.golems?.length || 0);
    let slot = 0;
    for (const crow of game.companionCrows || []) {
      this._placePetAtPlayerSlot(crow, game.player, slot++, total);
    }
    for (const rat of game.tamedRats || []) {
      this._placePetAtPlayerSlot(rat, game.player, slot++, total);
      rat.setCollisionMap(game.currentRoom?.collisionMap || null);
      rat.setBackgroundObjects(game.currentRoom?.backgroundObjects || null); // layer-guard-ok
    }
    for (const golem of game.golems || []) {
      this._placePetAtPlayerSlot(golem, game.player, slot++, total);
      golem.setCollisionMap(game.currentRoom?.collisionMap || null);
      golem.setBackgroundObjects(game.currentRoom?.backgroundObjects || null); // layer-guard-ok
    }
    this.setPetsGilded(false);
  }

  // Gilded flip for both pet rosters. Called by the dungeon boss system on
  // vault-floor arrival; cleared on dungeon exit via restorePetsFromFloor.
  // Golems don't participate — gilding is the vault's reward for the
  // bread-tamed pet rosters specifically, not every companion type.
  setPetsGilded(gilded) {
    const game = this.game;
    for (const crow of game.companionCrows || []) crow.gilded = gilded;
    for (const rat of game.tamedRats || []) rat.gilded = gilded;
  }

  // Radial placement around the player — same geometry as NPCRat.onRoomEnter,
  // minus the full per-room reset (HP/state deliberately untouched).
  _placePetAtPlayerSlot(pet, player, slot, total) {
    const angle = (slot / Math.max(total, 1)) * Math.PI * 2;
    const radius = GRID.CELL_SIZE * 1.1;
    pet.position.x = player.position.x + Math.cos(angle) * radius;
    pet.position.y = player.position.y + Math.sin(angle) * radius;
    pet.velocity.vx = 0;
    pet.velocity.vy = 0;
  }

  // Wild + follower crow driver: bread seeking, scare reactions, promotion.
  // Snare Trap catches a wild room crow (see TrapSystem's 'snare' effect):
  // roots the caught crow in place permanently and enrages every OTHER wild
  // crow in the room into dive-bombing the player — mirrors Enemy's "once
  // attacked, always aggro'd" permanence (Enemy.js `enraged`), just triggered
  // by a caught flockmate instead of a direct hit on the crow itself.
  snareCrow(crow) {
    if (!crow || crow.snared) return;
    crow.snared = true;
    crow.velocity.vx = 0;
    crow.velocity.vy = 0;
    const roomCrows = this.game.currentRoom?.crows || [];
    for (const other of roomCrows) {
      if (other === crow) continue;
      other.enraged = true;
    }
  }

  updateCrows(deltaTime) {
    const game = this.game;
    const crows = game.currentRoom?.crows || [];
    const followers = game.followerCrows || [];

    // Pull all on-ground bread loaves so crows can target them. Wild and
    // follower crows live in the surface Room, so only surface bread counts —
    // a loaf on an Interior floor sits at floor coordinates they can't reach.
    const breadItems = game.items.filter(it => it && isFeed(it) && !it.consumed && lootOnSurface(it));

    // Skip the whole pipeline when there's nothing to drive. Followers
    // without bread still need the weapon-threat scare pass below, so this
    // only short-circuits when both rosters are empty.
    if (crows.length === 0 && followers.length === 0) {
      return;
    }

    const bgObjects = game.currentRoom?.backgroundObjects || [];

    // Ground loot (nuisance theft target list): dropped ingredients plus
    // non-bread ground items. Bread is excluded — it has its own dedicated
    // seek/eat/promotion path below rather than being "stolen." Wild crows
    // are always plane 0 (surface) — gate through PlaneSystem so a crow
    // never "sees" loot sitting on another Plane or on an Interior's floor.
    const lootItems = [];
    const lootNow = performance.now();
    for (const ing of game.ingredients) {
      if (!ing || ing.consumed || ing.destroyed) continue;
      if (ing.pickupReadyAt && ing.pickupReadyAt > lootNow) continue;
      if (planeOf(ing) !== PLANE_SURFACE || !lootOnSurface(ing)) continue;
      if (ing._lootSeenAt == null) ing._lootSeenAt = lootNow;
      if (lootNow - ing._lootSeenAt < LOOT_SEEK_DELAY_MS) continue;
      lootItems.push(ing);
    }
    for (const it of game.items) {
      if (!it || it.consumed || it.destroyed || isFeed(it)) continue;
      if (it.pickupReadyAt && it.pickupReadyAt > lootNow) continue;
      if (planeOf(it) !== PLANE_SURFACE || !lootOnSurface(it)) continue;
      if (it._lootSeenAt == null) it._lootSeenAt = lootNow;
      if (lootNow - it._lootSeenAt < LOOT_SEEK_DELAY_MS) continue;
      lootItems.push(it);
    }

    // Grab handler: pull the stolen entity out of whichever roster it came
    // from and physics, then hand it to the crow's carry slot. Ingredients
    // stay glyph-only (carriedIngredient, same field a companion uses to
    // ferry a pickup back); a ground Item is kept as the live entity
    // (carriedItem) so its identity survives the steal-and-recover round trip.
    const onGrabLoot = (target, crow) => {
      const iIdx = game.ingredients.indexOf(target);
      if (iIdx !== -1) {
        game.ingredients.splice(iIdx, 1);
        game.physicsSystem.removeEntity(target);
        crow.carriedIngredient = target.char;
        return;
      }
      const tIdx = game.items.indexOf(target);
      if (tIdx !== -1) {
        game.items.splice(tIdx, 1);
        game.physicsSystem.removeEntity(target);
        crow.carriedItem = target;
      }
    };

    // Sets a stolen Item back down on the ground as itself (not re-wrapped
    // as an Ingredient) — used both when a weapon knocks it loose and when a
    // crow carrying one gets promoted to companion mid-theft.
    const dropItemToGround = (ref, x, y) => {
      ref.position.x = x;
      ref.position.y = y;
      // Brief grace so the drop-in-progress crow scare animation doesn't get
      // instantly re-vacuumed by the player's own pickup magnetism.
      ref.pickupReadyAt = performance.now() + 300;
      game.items.push(ref);
      game.physicsSystem.addEntity(ref);
    };

    // Materializes whatever _takeCarriedItem()/scare() handed back: a plain
    // glyph respawns as a fresh bounced Ingredient, an Item goes back down
    // as itself via dropItemToGround.
    const materializeDrop = (carried, crow) => {
      if (!carried) return;
      if (carried.kind === 'item') {
        dropItemToGround(carried.ref, crow.position.x, crow.position.y);
      } else {
        const drop = new Ingredient(carried.glyph, crow.position.x, crow.position.y);
        drop.startDropBounce(0.55);
        game.ingredients.push(drop);
        game.physicsSystem.addEntity(drop);
      }
      game.audioSystem?.playSFX?.('crow_drop');
    };

    // Player-as-threat: scares unfed crows on proximity. Fed crows (already
    // tame) skip this — they only flee actual weapon contact.
    // While bread is on the ground, the player is offering food, not
    // threatening — otherwise a nearby dropped loaf creates a scare loop:
    // crow seeks → enters scare radius → flees → returns → seeks → forever.
    // Weapon attacks below still scare.
    const surfaceLive = !isInteriorActive(game);
    const playerThreat = (surfaceLive && game.player && game.player.plane === 0 && breadItems.length === 0)
      ? { x: game.player.position.x, y: game.player.position.y }
      : null;

    // Weapon threats apply to fed and unfed crows alike. Covers melee/projectile
    // contact, in-flight thrown consumables (bombs, jars, flasks, skulls), and
    // fire (embers) — anything that reads as "under attack" scares the crow off.
    const weaponThreats = [];
    for (const atk of game.combatSystem.getMeleeAttacks()) {
      weaponThreats.push({ x: atk.position.x, y: atk.position.y });
    }
    for (const proj of game.combatSystem.getProjectiles()) {
      weaponThreats.push({ x: proj.position.x, y: proj.position.y });
    }
    for (const windup of game.inventorySystem.consumableWindups) {
      weaponThreats.push({ x: windup.x, y: windup.y });
    }
    for (const particle of game.particles) {
      if (particle.isEmber) weaponThreats.push({ x: particle.x, y: particle.y });
    }
    // Inside an Interior every attack, projectile and ember is on the floor,
    // at floor coordinates — nothing there threatens a crow on the surface.
    if (!surfaceLive) weaponThreats.length = 0;

    // Eat handler: remove the loaf, promote the eater to companion. Every
    // bread-eat adds one more companion — they accumulate. Other crows in the
    // room join the follower flock, drawn toward the feed point.
    const onAteBread = (loaf, crow) => {
      const idx = game.items.indexOf(loaf);
      if (idx !== -1) {
        game.physicsSystem.removeEntity(loaf);
        game.items.splice(idx, 1);
      }
      const ex = crow.position.x + GRID.CELL_SIZE / 2;
      const ey = crow.position.y + GRID.CELL_SIZE / 2;

      // Other room crows take off toward the feed point and join the flock.
      for (let i = crows.length - 1; i >= 0; i--) {
        const other = crows[i];
        if (other === crow) continue;
        other.becomeFollower(ex, ey);
        game.followerCrows.push(other);
        crows.splice(i, 1);
      }
      // Existing followers redirect interest to the new feed point.
      for (const f of game.followerCrows) {
        f.becomeFollower(ex, ey);
      }

      // Promote the eater. Pull it out of room.crows / follower flock if
      // present. Append to companion list — multiple companions are allowed.
      const cIdx = crows.indexOf(crow);
      if (cIdx !== -1) crows.splice(cIdx, 1);
      const fIdx = game.followerCrows.indexOf(crow);
      if (fIdx !== -1) game.followerCrows.splice(fIdx, 1);
      crow.becomeCompanion();

      // A companion is never scared, so scare()'s drop path can never fire
      // again — hand over whatever this crow was still carrying (a spawn
      // hoard, or a stolen ingredient/item from loot-seeking) right now, or
      // it would hang undropped forever. Ingredients go straight into the
      // player's pile like a stray ground pickup; a stolen Item is set back
      // down rather than silently force-equipped.
      const carried = crow._takeCarriedItem();
      if (carried?.kind === 'ingredient') {
        game.addIngredient(carried.glyph);
      } else if (carried) {
        materializeDrop(carried, crow);
      }

      crow.setGame(game);
      crow.companionShoulderIndex = game.companionCrows.length;
      game.companionCrows.push(crow);
      game.fedCrowCount = Math.min(3, (game.fedCrowCount || 0) + 1);

      // Promotion burst: feather puff + golden crumbs + rising heart.
      for (let i = 0; i < 14; i++) {
        const angle = (i / 14) * Math.PI * 2 + Math.random() * 0.3;
        const speed = 35 + Math.random() * 35;
        game.particles.push(tagInteriorPlane(game, {
          x: ex, y: ey,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed - 20,
          life: 0.55, maxLife: 0.55,
          char: i % 2 === 0 ? '*' : '·',
          color: i % 2 === 0 ? '#ffffff' : '#daa520'
        }));
      }
      game.particles.push(tagInteriorPlane(game, {
        x: ex, y: ey - 4, vx: 0, vy: -22,
        life: 0.9, maxLife: 0.9, char: '♥', color: '#ff5577'
      }));
    };

    for (const crow of [...crows]) {
      // Enraged (see snareCrow): dive-bombs the player instead of running the
      // wild idle/bread/loot/flee FSM. Reuses the companion dive machinery
      // (beginDive/updateDive) already on Crow — an enraged wild crow's
      // attack is mechanically identical to a companion's dive, just aimed
      // at the player instead of an enemy. Hits deal contact damage through
      // the same off-pipeline helper other enemy-initiated hits use (staff
      // block respected, dodge/immune reported).
      if (crow.enraged && !crow.snared) {
        if (crow.diveState === 'idle') {
          if (crow.diveCooldownTimer > 0) crow.diveCooldownTimer -= deltaTime;
          else if (game.player) crow.beginDive(game.player, { miss: Math.random() < 0.3 });
        } else {
          const hit = crow.updateDive(deltaTime);
          if (hit && game.player) {
            game.combatSystem._applyBlockableEnemyDamage(game.player, crow, CROW_ENRAGE_DAMAGE, 'crow-enraged');
          }
        }
        continue;
      }

      crow.update(deltaTime, bgObjects, crows, breadItems, onAteBread, lootItems, onGrabLoot);

      // Tagged threats: weapon contact counts as an attack and shakes
      // whatever the crow is carrying loose; player proximity only spooks
      // the crow into the air.
      const threats = [];
      if (playerThreat) threats.push({ x: playerThreat.x, y: playerThreat.y, isAttack: false });
      for (const t of weaponThreats) threats.push({ x: t.x, y: t.y, isAttack: true });
      for (const t of threats) {
        if (crow.isWithinScareRange(t.x, t.y)) {
          materializeDrop(crow.scare(t.x, t.y, t.isAttack), crow);
          break;
        }
      }

      if (crow.takeoffPending) {
        const variant = Math.random() < 0.5 ? 'crow_takeoff_1' : 'crow_takeoff_2';
        game.audioSystem?.playSFX(variant);
        crow.takeoffPending = false;
      }
    }

    // Followers break orbit to chase bread. Drives them through the same wild
    // seek/eat state machine; onAteBread promotes the eater to companion and
    // pulls it out of the follower list. updateFollowerCrows skips any that
    // entered 'seekingBread' this frame so they don't double-step.
    if (breadItems.length > 0 && followers.length > 0) {
      for (const f of [...followers]) {
        f.update(deltaTime, bgObjects, followers, breadItems, onAteBread);
      }
    }

    // Followers are already tame — no proximity scare (the flock trusts the
    // player) — but a weapon actually connecting is still an attack. Without
    // this, a crow that joined the flock (but hasn't personally eaten bread
    // yet, so it's still holding its spawn hoard or a stolen pickup) could
    // never be struck into dropping it: updateFollowerCrows drives followers
    // through updateAsFollower, which has no scare/threat handling at all.
    if (weaponThreats.length > 0 && followers.length > 0) {
      for (const crow of followers) {
        for (const t of weaponThreats) {
          if (crow.isWithinScareRange(t.x, t.y)) {
            materializeDrop(crow.scare(t.x, t.y, true), crow);
            break;
          }
        }
        if (crow.takeoffPending) {
          const variant = Math.random() < 0.5 ? 'crow_takeoff_1' : 'crow_takeoff_2';
          game.audioSystem?.playSFX(variant);
          crow.takeoffPending = false;
        }
      }
    }
  }

  updateCompanionCrow(deltaTime) {
    const game = this.game;
    if (!game.companionCrows || game.companionCrows.length === 0) return;
    const ctx = {
      player: game.player,
      // Companion crows travel with the player, so they fetch only loot on
      // the player's layer — never the frozen surface's from inside an Interior.
      ingredients: game.ingredients.filter(e => lootOnActiveLayer(game, e)),
      // Active-layer enemies (floor roster inside dungeons) — dive targeting
      // must see the enemies the player is actually fighting.
      enemies: game._activeEnemies?.() || [],
      items: game.items.filter(e => lootOnActiveLayer(game, e)),
      // Lift the ingredient off the ground but DON'T credit the player —
      // the companion ferries it back and deposits on perch. Returns true if
      // the world removal succeeded so the crow knows the pickup took.
      takeIngredient: (ing) => {
        if (!ing || ing.consumed) return false;
        ing.consumed = true;
        game.physicsSystem.removeEntity(ing);
        const idx = game.ingredients.indexOf(ing);
        if (idx !== -1) game.ingredients.splice(idx, 1);
        return true;
      },
      // Hand-off on perch: credit the player with the carried glyph. Optional
      // delivery pop so the player sees the trade happen.
      depositIngredient: (glyph, crow) => {
        if (!glyph) return;
        game.addIngredient(glyph);
        if (crow) {
          const cx = crow.position.x + GRID.CELL_SIZE / 2;
          const cy = crow.position.y + GRID.CELL_SIZE / 2;
          for (let i = 0; i < 5; i++) {
            const a = (i / 5) * Math.PI * 2;
            game.particles.push(tagInteriorPlane(game, {
              x: cx, y: cy,
              vx: Math.cos(a) * 25, vy: Math.sin(a) * 25 - 10,
              life: 0.35, maxLife: 0.35,
              char: '·', color: '#ffffff'
            }));
          }
        }
      },
      companionCount: game.companionCrows.length
    };
    for (let i = game.companionCrows.length - 1; i >= 0; i--) {
      const c = game.companionCrows[i];
      c.updateAsCompanion(deltaTime, ctx);
    }
    // Abandon flight finished — drop it from the roster for good. Mirrors
    // updateTamedRats' permaFlee prune.
    this._pruneAbandonedCrows(c => c.abandonReached);
    this._processCompanionDiveAttacks(deltaTime);
  }

  // Drop abandoning companion crows (those `isGone` accepts) from the roster
  // for good. Each one takes its standing with it: the fed count drops, so
  // wild crows stop auto-joining (autoJoinWildCrows) on the reputation of a
  // bond that no longer exists. The perch ring is then renumbered, or the
  // next fed crow takes `length` as its index and lands on a perch in use.
  _pruneAbandonedCrows(isGone) {
    const game = this.game;
    const before = game.companionCrows.length;
    game.companionCrows = game.companionCrows.filter(c => !(c.abandoning && isGone(c)));
    const removed = before - game.companionCrows.length;
    if (removed === 0) return;
    game.fedCrowCount = Math.max(0, (game.fedCrowCount || 0) - removed);
    game.companionCrows.forEach((crow, idx) => { crow.companionShoulderIndex = idx; });
  }

  // Apply enemy melee + projectile hits to companion crows. Mirrors
  // applyEnemyDamageToTamedRats/applyEnemyDamageToGolems over the crow
  // roster. Wild/follower crows are never targeted — only bonded companions
  // ride close enough to combat to eat hits.
  applyEnemyDamageToCompanionCrows() {
    const game = this.game;
    if (!game.companionCrows || game.companionCrows.length === 0) return;
    const cs = game.combatSystem;
    if (!cs) return;

    const projs = cs.enemyProjectiles || [];
    for (const crow of game.companionCrows) {
      if (crow.abandoning) continue;
      // Gilded crows are the vault's reward — nothing can hurt them.
      if (crow.gilded) continue;
      if (crow.invulnerabilityTimer > 0) continue;
      // Projectiles
      for (let i = projs.length - 1; i >= 0; i--) {
        const p = projs[i];
        if ((p.plane ?? 0) !== crow.plane) continue;
        const cx = crow.position.x + crow.width / 2;
        const cy = crow.position.y + crow.height / 2;
        const dx = p.position.x - cx;
        const dy = p.position.y - cy;
        const r = GRID.CELL_SIZE * 0.6 + Math.min(crow.width, crow.height) / 2;
        if (dx * dx + dy * dy < r * r) {
          crow.takeDamage(p.damage || 1, p.owner);
          projs.splice(i, 1);
          cs.createDamageNumber?.(p.damage || 1, crow.position.x, crow.position.y, crow.color);
          break;
        }
      }
      if (crow.invulnerabilityTimer > 0) continue;
      // Melee attack hitboxes
      const melee = cs.enemyMeleeAttacks || [];
      for (const m of melee) {
        if (m.windupPhase) continue;
        if (m.hasHit) continue;
        if ((m.plane ?? 0) !== crow.plane) continue;
        const ax = m.position.x;
        const ay = m.position.y;
        const aw = m.width || GRID.CELL_SIZE;
        const ah = m.height || GRID.CELL_SIZE;
        if (
          ax < crow.position.x + crow.width && ax + aw > crow.position.x &&
          ay < crow.position.y + crow.height && ay + ah > crow.position.y
        ) {
          m.hasHit = true;
          crow.takeDamage(m.damage || 1, m.owner);
          cs.createDamageNumber?.(m.damage || 1, crow.position.x, crow.position.y, crow.color);
          break;
        }
      }
    }
  }

  // Dive-attack coordination: at most ONE companion is in flight at a time.
  // Picks the first eligible orbiter that is off cooldown and launches it
  // with a miss-chance roll. Telegraph (windup, during which the crow keeps
  // orbiting) → dash → cooldown.
  _processCompanionDiveAttacks(deltaTime) {
    const game = this.game;
    // Global one-at-a-time gate: any companion currently winding up or
    // diving blocks new launches this frame.
    const anyEngaged = game.companionCrows.some(c => c.diveState && c.diveState !== 'idle');
    if (!anyEngaged) {
      for (const c of game.companionCrows) {
        if (c.diveCooldownTimer > 0) continue;
        if (c.companionTask !== 'enemy' || !c.companionTarget) continue;
        const t = c.companionTarget;
        if (!t || t.isDead || t.dead || t.hp <= 0) continue;
        // 45% miss rate — keeps dives feeling more like harassment than
        // a guaranteed strike, and gives the enemy room to counter.
        const miss = Math.random() < 0.45;
        c.beginDive(t, { miss });
        break;
      }
    }
    // Drive any in-flight dives and apply hits
    for (const c of game.companionCrows) {
      if (!c.diveState || c.diveState === 'idle') continue;
      const hitEnemy = c.updateDive(deltaTime);
      if (hitEnemy && !c.diveHasHit) {
        c.diveHasHit = true;
        const dmg = 1;
        if (typeof hitEnemy.takeDamage === 'function') {
          hitEnemy.takeDamage(dmg, game);
        }
        const attackVariant = `crow_attack_${1 + Math.floor(Math.random() * 3)}`;
        game.audioSystem?.playSFX?.(attackVariant);
        game.combatSystem.createDamageNumber(dmg, hitEnemy.position.x, hitEnemy.position.y, '#ffdd66');
        // Small impact burst
        const ix = hitEnemy.position.x + GRID.CELL_SIZE / 2;
        const iy = hitEnemy.position.y + GRID.CELL_SIZE / 2;
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * Math.PI * 2;
          game.particles.push(tagInteriorPlane(game, {
            x: ix, y: iy,
            vx: Math.cos(a) * 50, vy: Math.sin(a) * 50,
            life: 0.35, maxLife: 0.35,
            char: '·', color: '#ffffff'
          }));
        }
      }
    }
  }

  // Reputation effect: once the player has fed three crows, every wild crow
  // in a newly-entered room joins the follower flock immediately (no bread
  // needed). The flock still clears on the next room transition.
  autoJoinWildCrows() {
    const game = this.game;
    if ((game.fedCrowCount || 0) < 3) return;
    const crows = game.currentRoom?.crows;
    if (!crows || crows.length === 0) return;
    if (!game.player) return;
    const px = game.player.position.x + GRID.CELL_SIZE / 2;
    const py = game.player.position.y + GRID.CELL_SIZE / 2;
    for (const c of crows) {
      c.becomeFollower(px, py);
      game.followerCrows.push(c);
    }
    crows.length = 0;
  }

  updateFollowerCrows(deltaTime) {
    const game = this.game;
    if (!game.followerCrows || game.followerCrows.length === 0) return;
    const bgObjects = game.currentRoom?.backgroundObjects || [];
    const playerSpeed = game.player
      ? Math.hypot(game.player.velocity.vx, game.player.velocity.vy)
      : 0;
    const ctx = {
      player: game.player,
      backgroundObjects: bgObjects,
      playerSpeed,
      otherFollowers: game.followerCrows
    };
    for (const f of game.followerCrows) {
      // updateCrows already drove this frame's tick for bread-seekers.
      if (f.state === 'seekingBread') continue;
      f.updateAsFollower(deltaTime, ctx);
    }
  }
}
