import { GRID } from '../game/GameConfig.js';
import { BackgroundObject } from '../entities/BackgroundObject.js';
import { Item } from '../entities/Item.js';
import { Ingredient } from '../entities/Ingredient.js';
import { createWildFairy } from '../entities/FairyKing.js';
import { Hatter } from '../entities/Hatter.js';
import { ITEMS, ITEM_TYPES, INGREDIENTS, getItemData, isIngredient } from './items.js';
import { ZONES } from './zones.js';

/**
 * Neutral Room Scripts
 * Define lifecycle hooks: onGenerate, onInteract, onUpdate, onExit, and
 * optionally combatObjects(room) — the background objects weapons can hit.
 * A neutral room runs the shared world tick (Limited Explore), but its
 * decorations are not breakable unless the script names them here; the
 * default is none.
 */

export const NEUTRAL_ROOMS = {
  /**
   * Leshy Grove - Secret room from green zone chase event
   * 3x3 grid of tall grass, player can cut 3 of 9 for prizes
   */
  leshyGrove: {
    onGenerate(room, state) {
      // Initialize state
      state.cutsRemaining = 3;
      state.prizes = this.generatePrizes();

      const centerX = Math.floor(GRID.COLS / 2);
      const centerY = Math.floor(GRID.ROWS / 2);

      // ===== DECORATIVE BACKGROUND OBJECTS (just for looks) =====

      // Create magical forest clearing atmosphere with decorative objects
      // These are indestructible and purely visual - only the 3x3 grass grid is interactive

      // Ring of trees around the perimeter (slightly irregular for organic feel)
      const treePositions = [
        // North wall - varied spacing
        { x: 4, y: 3 }, { x: 8, y: 3 }, { x: 13, y: 3 }, { x: 18, y: 3 }, { x: 23, y: 3 }, { x: 26, y: 3 },
        // South wall - varied spacing
        { x: 5, y: 27 }, { x: 10, y: 27 }, { x: 14, y: 27 }, { x: 19, y: 27 }, { x: 24, y: 27 },
        // East wall - irregular
        { x: 27, y: 6 }, { x: 27, y: 10 }, { x: 27, y: 15 }, { x: 27, y: 20 }, { x: 27, y: 24 },
        // West wall - irregular
        { x: 3, y: 5 }, { x: 3, y: 9 }, { x: 3, y: 14 }, { x: 3, y: 19 }, { x: 3, y: 23 }
      ];

      for (const pos of treePositions) {
        const tree = new BackgroundObject('Y', pos.x * GRID.CELL_SIZE, pos.y * GRID.CELL_SIZE);
        tree.indestructible = true; // Decorative only
        room.backgroundObjects.push(tree);
      }

      // Scattered mushrooms (magical grove theme) - organic clustering
      const mushroomPositions = [
        { x: 7, y: 5 }, { x: 8, y: 6 }, { x: 23, y: 6 }, { x: 24, y: 7 },
        { x: 5, y: 11 }, { x: 6, y: 10 }, { x: 24, y: 11 }, { x: 25, y: 12 },
        { x: 5, y: 16 }, { x: 25, y: 14 }, { x: 6, y: 19 }, { x: 24, y: 21 },
        { x: 7, y: 24 }, { x: 9, y: 25 }, { x: 21, y: 24 }, { x: 23, y: 25 },
        { x: 12, y: 4 }, { x: 17, y: 5 }, { x: 11, y: 26 }, { x: 20, y: 26 }
      ];

      for (const pos of mushroomPositions) {
        const mushroom = new BackgroundObject('n', pos.x * GRID.CELL_SIZE, pos.y * GRID.CELL_SIZE);
        mushroom.indestructible = true; // Decorative only
        room.backgroundObjects.push(mushroom);
      }

      // Magical crystals scattered (glowing with mystical energy)
      const crystalPositions = [
        { x: 4, y: 4 }, { x: 26, y: 5 }, { x: 5, y: 26 }, { x: 25, y: 26 },
        { x: 8, y: 9 }, { x: 21, y: 8 }, { x: 9, y: 21 }, { x: 23, y: 23 },
        { x: 15, y: 4 }, { x: 15, y: 26 } // Two extra for mystical feel
      ];

      for (const pos of crystalPositions) {
        const crystal = new BackgroundObject('*', pos.x * GRID.CELL_SIZE, pos.y * GRID.CELL_SIZE);
        crystal.indestructible = true; // Decorative only
        room.backgroundObjects.push(crystal);
      }

      // Bushes scattered between trees (varied placement)
      const bushPositions = [
        { x: 6, y: 3 }, { x: 11, y: 3 }, { x: 16, y: 3 }, { x: 21, y: 3 },
        { x: 7, y: 27 }, { x: 12, y: 27 }, { x: 17, y: 27 }, { x: 22, y: 27 }, { x: 26, y: 27 },
        { x: 27, y: 8 }, { x: 27, y: 13 }, { x: 27, y: 17 }, { x: 27, y: 22 },
        { x: 3, y: 7 }, { x: 3, y: 11 }, { x: 3, y: 16 }, { x: 3, y: 20 }
      ];

      for (const pos of bushPositions) {
        const bush = new BackgroundObject('%', pos.x * GRID.CELL_SIZE, pos.y * GRID.CELL_SIZE);
        bush.indestructible = true; // Decorative only
        room.backgroundObjects.push(bush);
      }

      // Ancient stumps (adds character to the grove) - asymmetric placement
      const stumpPositions = [
        { x: 9, y: 9 }, { x: 21, y: 10 }, { x: 10, y: 20 }, { x: 20, y: 21 },
        { x: 11, y: 12 }, { x: 19, y: 14 }, { x: 12, y: 18 }, { x: 18, y: 16 },
        { x: 6, y: 8 }, { x: 24, y: 22 } // Two extra for variety
      ];

      for (const pos of stumpPositions) {
        const stump = new BackgroundObject('ŋ', pos.x * GRID.CELL_SIZE, pos.y * GRID.CELL_SIZE);
        stump.indestructible = true; // Decorative only
        room.backgroundObjects.push(stump);
      }

      // Brambles for natural undergrowth (organic clustering)
      const bramblePositions = [
        { x: 5, y: 5 }, { x: 6, y: 6 }, { x: 24, y: 5 }, { x: 25, y: 6 },
        { x: 5, y: 24 }, { x: 6, y: 25 }, { x: 24, y: 24 }, { x: 25, y: 25 },
        { x: 10, y: 8 }, { x: 20, y: 7 }, { x: 11, y: 22 }, { x: 19, y: 23 },
        { x: 7, y: 12 }, { x: 22, y: 14 }, { x: 8, y: 18 }, { x: 23, y: 16 }
      ];

      for (const pos of bramblePositions) {
        const bramble = new BackgroundObject('+', pos.x * GRID.CELL_SIZE, pos.y * GRID.CELL_SIZE);
        bramble.indestructible = true; // Decorative only
        room.backgroundObjects.push(bramble);
      }

      // ===== INTERACTIVE ELEMENT: 3x3 Grid of Grass Clusters (minigame) =====

      // Each "bunch" is a 5x5 cluster of grass blades
      // Create 9 clusters arranged in a 3x3 grid
      const clusterSpacing = GRID.CELL_SIZE * 6; // 6 cells between cluster centers
      const clusterSize = 5; // 5x5 grass blades per cluster
      state.cutClusters = new Set(); // Track which clusters have been cut

      // Record cluster center pixel coords so onRender can label missed clusters
      state.clusterCenters = [];

      const jitter = () => Math.floor(Math.random() * 7) - 3; // -3..3 inclusive

      let clusterIndex = 0;
      for (let row = -1; row <= 1; row++) {
        for (let col = -1; col <= 1; col++) {
          const clusterCenterX = centerX + col * 6;
          const clusterCenterY = centerY + row * 6;

          state.clusterCenters.push({
            x: clusterCenterX * GRID.CELL_SIZE + GRID.CELL_SIZE / 2,
            y: clusterCenterY * GRID.CELL_SIZE + GRID.CELL_SIZE / 2
          });

          // Create 5x5 cluster of grass blades
          for (let gy = -2; gy <= 2; gy++) {
            for (let gx = -2; gx <= 2; gx++) {
              const grassX = (clusterCenterX + gx) * GRID.CELL_SIZE;
              const grassY = (clusterCenterY + gy) * GRID.CELL_SIZE;

              // Paired stalks (mirrors RoomGenerator.generateGrassSwaths) — a
              // single blade looks too thin; the +6px twin gives the dense visual.
              const grass = new BackgroundObject('|', grassX, grassY);
              grass.leshyGrass = true;
              grass.clusterIndex = clusterIndex;
              grass.renderOffsetX = jitter();
              grass.renderOffsetY = jitter();

              const grass2 = new BackgroundObject('|', grassX + 6, grassY);
              grass2.leshyGrass = true;
              grass2.clusterIndex = clusterIndex;
              grass2.renderOffsetX = jitter();
              grass2.renderOffsetY = jitter();

              room.backgroundObjects.push(grass);
              room.backgroundObjects.push(grass2);
            }
          }

          clusterIndex++;
        }
      }
    },

    /**
     * Generate prize array: 9 ingredient bunches across 2 tiers.
     * 3 premium clusters (4-5 rare ingredients), 6 standard clusters (2-3 common ones).
     * Blessings are a separate system and are not items — handled in a future pass.
     */
    generatePrizes() {
      const prizes = [];

      // Rare ingredients (green-zone drops, crafting staples)
      const rarePool   = ['k', 'e', 'F', 'h', 'i']; // Silk, Eye, Fire Essence, Herb, Ice (Scale is epic-only)
      const commonPool = ['g', 'M', 'w', 'b', 'f', 't']; // Goo, Metal, Wing, Bone, Fur, Teeth

      // 3 premium bunches (signal the best picks)
      for (let i = 0; i < 3; i++) {
        const size = 4 + Math.floor(Math.random() * 2); // 4-5 items
        const bunch = [];
        for (let j = 0; j < size; j++) {
          bunch.push(rarePool[Math.floor(Math.random() * rarePool.length)]);
        }
        prizes.push(bunch);
      }

      // 6 standard bunches
      for (let i = 0; i < 6; i++) {
        const size = 2 + Math.floor(Math.random() * 2); // 2-3 items
        const bunch = [];
        for (let j = 0; j < size; j++) {
          bunch.push(commonPool[Math.floor(Math.random() * commonPool.length)]);
        }
        prizes.push(bunch);
      }

      // Shuffle so premium clusters are distributed among the 9
      for (let i = prizes.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [prizes[i], prizes[j]] = [prizes[j], prizes[i]];
      }

      return prizes;
    },

    onInteract(target, player, room, state) {
      // Check if target is a Leshy grass blade
      if (!target.leshyGrass || target.char !== '|') {
        return null; // Not a grass blade
      }

      // Check if player has cuts remaining
      if (state.cutsRemaining <= 0) {
        return null; // Don't cut if no cuts left
      }

      const clusterIndex = target.clusterIndex;

      // Check if this cluster has already been cut
      if (state.cutClusters.has(clusterIndex)) {
        return null; // Already cut this cluster
      }

      // Mark cluster as cut (prevents re-cutting)
      state.cutClusters.add(clusterIndex);

      // Cut ALL grass blades in this cluster
      let cutCount = 0;
      const clusterCenter = { x: 0, y: 0 };
      for (const obj of room.backgroundObjects) {
        if (obj.leshyGrass && obj.clusterIndex === clusterIndex && obj.char === '|') {
          // Accumulate positions for prize spawn point
          clusterCenter.x += obj.position.x;
          clusterCenter.y += obj.position.y;
          cutCount++;

          // Animate grass cutting
          if (obj.cutGrass) {
            obj.cutGrass();
          }
        }
      }

      // Calculate center of cluster for prize spawn
      if (cutCount > 0) {
        clusterCenter.x /= cutCount;
        clusterCenter.y /= cutCount;
      }

      // Spawn prize items at cluster center
      const prizeChars = state.prizes[clusterIndex];
      const spawnedItems = [];

      for (const char of prizeChars) {
        const itemData = getItemData(char);
        if (!itemData) {
          console.error(`[LESHY SPAWN] ERROR: Invalid char '${char}'`);
          continue;
        }

        // Create proper entity type (Ingredient vs Item)
        let entity;
        const isIngr = isIngredient(char);
        if (isIngr) {
          entity = new Ingredient(char, clusterCenter.x, clusterCenter.y);
          entity.pickupCooldown = 0.75; // Same cooldown as enemy drops — prevents instant magnet
        } else {
          entity = new Item(char, clusterCenter.x, clusterCenter.y);
        }

        // Add velocity for visual scatter effect
        entity.velocity = {
          vx: (Math.random() - 0.5) * 100,
          vy: (Math.random() - 0.5) * 100
        };
        spawnedItems.push(entity);
      }

      // Decrement cuts
      state.cutsRemaining--;

      // After 3 picks: auto-cut remaining clusters and start celebration
      if (state.cutsRemaining === 0) {
        for (const obj of room.backgroundObjects) {
          if (obj.leshyGrass && obj.char === '|') {
            obj.cutGrass();
          }
        }
        state.celebrationActive = true;
        state.celebrationTimer = 4.0;
        state.celebrationTime = 0;
      }

      // Return spawned items so they can be added to game
      return { spawnedItems };
    },

    onUpdate(deltaTime, room, player, state) {
      if (state.celebrationActive) {
        state.celebrationTimer -= deltaTime;
        state.celebrationTime = (state.celebrationTime || 0) + deltaTime;
        if (state.celebrationTimer <= 0) {
          state.celebrationActive = false;
        }
      }
    },

    onRender(renderer, room, player, state) {
      // Reveal what each un-picked cluster would have given, once all grass has been cut.
      if (state.cutsRemaining === 0 && state.clusterCenters && state.prizes) {
        for (let i = 0; i < state.clusterCenters.length; i++) {
          if (state.cutClusters && state.cutClusters.has(i)) continue;
          const center = state.clusterCenters[i];
          const prizeChars = state.prizes[i] || [];
          // Lay the chars out in a small horizontal row centered on the cluster.
          const spacing = GRID.CELL_SIZE * 0.7;
          const startX = center.x - ((prizeChars.length - 1) * spacing) / 2;
          for (let j = 0; j < prizeChars.length; j++) {
            renderer.drawTextWithAlpha(
              startX + j * spacing,
              center.y,
              prizeChars[j],
              '#888888',
              0.6
            );
          }
        }
      }

      if (!state.celebrationActive) return;

      const centerX = Math.floor(GRID.COLS / 2) * GRID.CELL_SIZE + GRID.CELL_SIZE / 2;
      const centerY = Math.floor(GRID.ROWS / 2) * GRID.CELL_SIZE + GRID.CELL_SIZE / 2;
      // Hop at ~5 cycles per second, 4px amplitude; fade out in the last 0.5s
      const bobOffset = Math.sin(state.celebrationTime * Math.PI * 10) * 4;
      const alpha = Math.min(1, state.celebrationTimer / 0.5);
      renderer.drawTextWithAlpha(centerX, centerY + bobOffset, 'l', '#00ff00', alpha);
    },

    onExit(room, player, state) {
      // Clean exit - no special logic needed
    }
  },

  /**
   * Oasis — yellow-zone secret reached by following a river's flow direction
   * for 3 consecutive rooms (see ZoneSystem.recordRiverFollow / main.js exit
   * handlers). Lake-style water terrain, one random consumable, and fairies
   * to catch in bottles. No enemies.
   */
  oasis: {
    onGenerate(room, state, roomGenerator) {
      // Yellow-zone cohesion: this secret is exclusive to the yellow zone's
      // river-follow chase, so it reads as part of that zone rather than a
      // disconnected green-bordered neutral room — same border color, same
      // ambient wind (room.windThemed, see SandstormSystem.bindToRoom).
      room.borderColor = ZONES.yellow.borderColor;
      room.windThemed = true;

      const nodes = [
        { col: 13, row: 14, radius: 7 },
        { col: 18, row: 17, radius: 5.5 }
      ];
      roomGenerator?.stampWaterBlobs(room, nodes, 2.0, 0.9);

      // Carve a river from the door the player entered through (mirrors
      // room.returnExit) into the nearer lake blob, so the water that led
      // here visually continues into the oasis instead of the lake looking
      // like an unrelated pool. Reuses the same wall-to-wall carver as the
      // yellow zone's forced river-follow chain (RoomGenerator._buildPath).
      const ENTRY_EDGE = { north: 'top', south: 'bottom', west: 'left', east: 'right' };
      const entryEdge = ENTRY_EDGE[room.returnExit] || 'bottom';
      if (roomGenerator) {
        const start = roomGenerator._pickEdgePoint(entryEdge);
        roomGenerator._buildPath(room, 'river', start, { col: nodes[0].col, row: nodes[0].row });
      }

      const centerX = Math.floor(GRID.COLS / 2) * GRID.CELL_SIZE;
      const centerY = Math.floor(GRID.ROWS / 2) * GRID.CELL_SIZE;

      // One random usable consumable beside the fairies, uniformly chosen —
      // no thematic curation. (A tier-2 weapon here was too strong a reward
      // for a secret that is also a free fairy refill.) Passives, oils, the
      // Bomb Bag, and the bottle/coin utility items are left out: the pick
      // should be something you throw or drink.
      const NOT_A_PICK = new Set(['cauldronInput', 'wellOffering', 'emptyBottle']);
      const consumables = Object.values(ITEMS).filter(item =>
        item.type === ITEM_TYPES.CONSUMABLE && item.effect && !item.passive
        && !item.oilEffect && !item.bombBag && !NOT_A_PICK.has(item.effect)
      );
      if (consumables.length > 0) {
        const chosen = consumables[Math.floor(Math.random() * consumables.length)];
        room.items.push(new Item(chosen.char, centerX, centerY - GRID.CELL_SIZE * 2));
      }

      // Fairies flutter indefinitely (no room-clear gate here — Oasis has no
      // enemies) and hold still since exits are always unlocked; touching one
      // with an equipped Empty Bottle catches it (InteractionSystem.checkFairyTouch).
      state.fairies = [
        createWildFairy(centerX - GRID.CELL_SIZE * 3, centerY, room.exits, { flutterDuration: Infinity }),
        createWildFairy(centerX + GRID.CELL_SIZE * 3, centerY, room.exits, { flutterDuration: Infinity })
      ];
      room.pendingNeutralCharacters = state.fairies;
    },

    onInteract(target, player, room, state) { return null; },

    onUpdate(dt, room, player, state) {},

    onExit(room, player, state) {}
  },

  /**
   * Sunken Ship — behind the Pearl pedestal's east exit (PearlSystem). Beach,
   * deep sea and a listing wreck; SunkenShipSystem lays it out and owns what
   * happens in it (the hold's glints, the
   * Slow Glint's secret south). Nothing here can be broken.
   */
  sunkenShip: {
    onGenerate(room, state, roomGenerator) {
      roomGenerator?.game?.sunkenShipSystem.build(room);
    },

    onInteract(target, player, room, state) { return null; },

    onUpdate(dt, room, player, state) {},

    onExit(room, player, state) {}
  },

  /**
   * Sunken Hold — the Sunken Ship's Inner Room, through its secret south.
   * Laid out by SunkenShipSystem.buildHold.
   */
  sunkenHold: {
    onGenerate(room, state, roomGenerator) {
      roomGenerator?.game?.sunkenShipSystem.buildHold(room);
    },

    onInteract(target, player, room, state) { return null; },

    onUpdate(dt, room, player, state) {},

    onExit(room, player, state) {}
  },

  /**
   * Three Room — the source. An emptied room, mist cleared, holding the three
   * slots in a pyramid and one shut way north. Typing here holds a
   * conversation instead of an observation (spells.js "The Three"). SPACE
   * near the door opens it; ThreeRoomSystem owns everything that happens
   * after that.
   */
  threeRoom: {
    onGenerate(room, state) {
      room.isThreeRoom = true;
      room.borderColor = '#666666';

      const cx = Math.floor(GRID.COLS / 2);

      // The slots — one object, not three. Each slot is a `[ ]` frame three
      // glyphs wide, and the frames are packed until they touch: the two base
      // frames sit shoulder to shoulder on one row, the apex straddles their
      // seam two rows above — packed side to side, but with a clear row under
      // the apex so the top of the triangle doesn't crowd the base pair. What
      // the player walks up to reads as a single carved thing with three holes
      // in it, not three pieces of furniture.
      //
      //        [ ]          ← apex, over the seam
      //                     ← one clear row, so the apex reads as its own
      //     [ ][ ]          ← base pair, touching
      //
      // Laid out in PIXELS about the room's center, deliberately NOT on the
      // cell grid. Two touching 3-glyph frames are six glyphs wide, so the
      // object's midline falls on a cell BOUNDARY while the apex's falls on a
      // cell CENTER — a cell-aligned layout is therefore off by half a cell on
      // one row or the other no matter which row is anchored, and that
      // half-cell is exactly the lopsided triangle this replaces. Half-cells
      // cost nothing here: background objects render at their pixel position
      // (NeutralRenderer) and the slots carry no collision.
      //
      // Centering it spawns nothing on top of the player: entry to the Three
      // Room always runs through animateExitWarp('north', ...), which
      // re-anchors the player on the SOUTH edge and walks them inward to about
      // row 25. They come up the room at the object, with the door beyond it.
      //
      // Only the CONTENT cell is a real BackgroundObject — it carries
      // `threeSlot` and is what SPACE finds. ThreeRoomRenderer draws the
      // brackets around it off the same pixel position, which keeps proximity
      // detection trivial and leaves the frame free to change (highlighted,
      // shaking, cracked) without touching collision or interaction.
      //
      // Slot order is the Power of 3's registers, and ThreeRoomSystem's
      // SLOT_FORMS/TRUE_THREE tables are indexed by it:
      //   0 apex  — Instinct   — takes a weapon
      //   1 left  — Experience — takes armor
      //   2 right — Convention — takes a consumable
      const cs = GRID.CELL_SIZE;
      const midX = GRID.WIDTH / 2;
      const midY = GRID.HEIGHT / 2;
      const slotCenters = [
        { x: midX,            y: midY - cs * 1.5 }, // apex  — Instinct
        { x: midX - cs * 1.5, y: midY + cs / 2 }, // left  — Experience
        { x: midX + cs * 1.5, y: midY + cs / 2 }  // right — Convention
      ];
      slotCenters.forEach((center, idx) => {
        // BackgroundObject positions are the top-left of a glyph cell, so the
        // center goes back half a cell in each axis to get there.
        const slot = new BackgroundObject(' ', center.x - cs / 2, center.y - cs / 2);
        slot.indestructible = true;
        slot.hasCollision = false;
        slot.color = '#887755';
        slot.animationColor = '#887755';
        slot.threeSlot = idx;
        room.backgroundObjects.push(slot);
      });

      // The shut way north. It opens; nothing good is behind it.
      const doorCol = cx;
      const doorRow = 2;
      const door = new BackgroundObject('∩', doorCol * GRID.CELL_SIZE, doorRow * GRID.CELL_SIZE);
      door.indestructible = true;
      door.structural = true;
      door.hasCollision = true;
      door.color = '#cccccc';
      door.animationColor = '#cccccc';
      door.threeDoor = true;
      door.threeDoorCell = { col: doorCol, row: doorRow };
      room.backgroundObjects.push(door);
      room.collisionMap[doorRow][doorCol] = true;
    },

    // Combat resolves against Death alone, so nothing else in the room can be
    // broken in the dark.
    combatObjects(room) { return room.backgroundObjects.filter(o => o.isDeath); },

    onInteract(target, player, room, state) { return null; },

    onUpdate(dt, room, player, state) {},

    onExit(room, player, state) {}
  },

  /**
   * Graveyard — south of REST, opened only by a Cursed Run.
   *
   * A divider runs unbroken across the room at the one-third line. The player
   * comes in through the north wall and stays in the top third; the Undead are
   * in the lower two, and there is no way down to them. The room is a window,
   * not a place to go — the only thing to do here is see how much of it is
   * filling up, which is the whole point of a curse you cannot walk back.
   *
   * Population is CursedRunSystem's, not the script's: it grows with the run
   * rather than with the room, so it has to outlive any single visit.
   */
  graveyard: {
    onGenerate(room, state) {
      room.isGraveyard = true;
      room.borderColor = '#4a4a4a';

      // One third down, so the top third is the player's and the lower two
      // thirds are theirs. The divider row itself belongs to neither.
      const dividerRow = Math.floor(GRID.ROWS / 3);
      room.graveyardDividerRow = dividerRow;

      for (let col = 1; col < GRID.COLS - 1; col++) {
        const wall = new BackgroundObject('█', col * GRID.CELL_SIZE, dividerRow * GRID.CELL_SIZE,
          { typeId: 'graveyard_divider' });
        wall.indestructible = true;
        wall.structural = true;
        wall.hasCollision = true;
        room.backgroundObjects.push(wall);
        room.collisionMap[dividerRow][col] = true;
      }
    },

    onInteract(target, player, room, state) { return null; },

    onUpdate(dt, room, player, state) {},

    onExit(room, player, state) {}
  },

  /**
   * Draw Room — secret gallery accessible via D-R-A-W exit sequence.
   * Dodge-rolling permanently marks grid cells as ASCII brush strokes.
   * Canvas is a pixel-resolution Map (key: "px,py") — one char per unique
   * pixel coordinate, bounded by room dimensions, not an entity list.
   */
  drawRoom: {
    onGenerate(room, state) {
      room.borderColor = '#cccccc';
      state.canvas = new Map();
    },

    onUpdate(dt, room, player, state) {
      if (!player.dodgeRoll?.active && !player.continuousRollActive) return;

      const px = Math.round(player.position.x + (player.width  ?? GRID.CELL_SIZE) / 2);
      const py = Math.round(player.position.y + (player.height ?? GRID.CELL_SIZE) / 2);
      const key = `${px},${py}`;

      if (!state.canvas.has(key)) {
        const chars = ['-', '=', '~', '.'];
        state.canvas.set(key, {
          char: chars[Math.floor(Math.random() * chars.length)],
          color: player.color
        });
      }
    },

    onRenderBefore(renderer, room, player, state) {
      if (!state.canvas?.size) return;

      const ctx = renderer.fgCtx;
      ctx.save();
      ctx.font = `${GRID.CELL_SIZE}px 'Unifont', monospace`;
      ctx.textBaseline = 'middle';
      ctx.textAlign = 'center';

      for (const [key, cell] of state.canvas) {
        const comma = key.indexOf(',');
        const x = +key.slice(0, comma);
        const y = +key.slice(comma + 1);
        ctx.fillStyle = cell.color;
        ctx.fillText(cell.char, x, y);
      }

      ctx.restore();
    },

    onRender(renderer, room, player, state) {},

    onInteract(target, player, room, state) { return null; },

    onExit(room, player, state) {}
  },

  /**
   * Tea Party — secret room reached via the T-E-A / E-A-T / A-T-E / H-A-T
   * exit sequences (data/exitLetters.js SECRET_PATTERNS). The Hatter sits at
   * the table; the table always holds one potion, picked uniformly from
   * every CONSUMABLE named "...Potion" (same uncurated-roll shape as
   * Oasis's consumable pick, above).
   */
  teaParty: {
    onGenerate(room, state) {
      room.borderColor = '#cc88ff';

      const centerX = Math.floor(GRID.COLS / 2);
      const centerY = Math.floor(GRID.ROWS / 2);

      const table = new BackgroundObject('⊡', centerX * GRID.CELL_SIZE, centerY * GRID.CELL_SIZE);
      room.backgroundObjects.push(table);

      const potions = Object.values(ITEMS).filter(
        item => item.type === ITEM_TYPES.CONSUMABLE && item.name.includes('Potion')
      );
      if (potions.length > 0) {
        const chosen = potions[Math.floor(Math.random() * potions.length)];
        const potion = new Item(chosen.char, centerX * GRID.CELL_SIZE, (centerY - 1) * GRID.CELL_SIZE);
        room.items.push(potion);
      }

      // Scripts with no `game` ref here stash characters via
      // pendingNeutralCharacters (see NeutralRoomSystem.generateNeutralRoom).
      room.pendingNeutralCharacters = [new Hatter((centerX + 2) * GRID.CELL_SIZE, centerY * GRID.CELL_SIZE)];

      // ── Chaotic clutter ──────────────────────────────────────────────────
      // Wonderland odds and ends scattered through the outer half of the
      // room, well clear of the table/Hatter. Angle+radius placement (not a
      // grid) for genuine scatter; glyph and color are each rolled
      // independently per piece so no two clumps read the same way.
      const CLUTTER_CHARS = ['♤', '♧', '♛', '◑', '✿', '◎', '✧', '⊔'];
      const CLUTTER_COLORS = [
        '#ff33aa', '#33ffcc', '#ff3355', '#ffcc33', '#cc66ff',
        '#33ccff', '#ffff66', '#66ccff', '#ff6600', '#00ff99'
      ];
      const CLUTTER_COUNT = 26;
      const INNER_CLEAR_RADIUS = 7; // cells — keeps the table/Hatter's footing clear
      const WALL_MARGIN = 2;        // stay this far off the walls
      const maxRadius = Math.min(centerX, centerY) - WALL_MARGIN;

      const occupied = new Set([`${centerX},${centerY}`, `${centerX + 2},${centerY}`]);
      let placed = 0, attempts = 0;
      while (placed < CLUTTER_COUNT && attempts < CLUTTER_COUNT * 20) {
        attempts++;
        const angle = Math.random() * Math.PI * 2;
        const radius = INNER_CLEAR_RADIUS + Math.random() * (maxRadius - INNER_CLEAR_RADIUS);
        const col = Math.round(centerX + Math.cos(angle) * radius);
        const row = Math.round(centerY + Math.sin(angle) * radius);
        if (col <= WALL_MARGIN || col >= GRID.COLS - 1 - WALL_MARGIN) continue;
        if (row <= WALL_MARGIN || row >= GRID.ROWS - 1 - WALL_MARGIN) continue;
        const key = `${col},${row}`;
        if (occupied.has(key)) continue;
        occupied.add(key);

        const clutter = new BackgroundObject(
          CLUTTER_CHARS[Math.floor(Math.random() * CLUTTER_CHARS.length)],
          col * GRID.CELL_SIZE, row * GRID.CELL_SIZE
        );
        clutter.color = CLUTTER_COLORS[Math.floor(Math.random() * CLUTTER_COLORS.length)];
        room.backgroundObjects.push(clutter);
        placed++;
      }
    },

    onInteract(target, player, room, state) { return null; },

    onUpdate(dt, room, player, state) {},

    onExit(room, player, state) {}
  }
};
