import { GRID, PHYSICS } from '../game/GameConfig.js';
import { BackgroundObject } from '../entities/BackgroundObject.js';
import { Enemy } from '../entities/Enemy.js';
import { Item } from '../entities/Item.js';
import { Ingredient } from '../entities/Ingredient.js';
import { getZoneRandomEnemy } from '../data/enemies.js';
import { applyZoneCombatModifiers } from '../data/zones.js';
import { WiseFellow } from '../entities/WiseFellow.js';
import { SHED_KEY_CHAR } from '../data/items.js';
import { Fisherman } from '../entities/Fisherman.js';
import { Witch } from '../entities/Witch.js';
import { WeaponsMaster } from '../entities/WeaponsMaster.js';
import { Shopkeeper } from '../entities/Shopkeeper.js';
import { WizardNPC } from '../entities/WizardNPC.js';
import { isInteriorActive } from './PlaneSystem.js';
import { HOT_WATER_CHAR } from '../data/alchemy.js';
import { hasKeyItem } from './keyItems.js';

// A bundle of Sticks — three laid side by side on the floor — turns up in
// most huts, so a run that needs firewood or a handle knows where to look.
const STICK_CHAR = '|';
const STICK_BUNDLE_SIZE = 3;
const STICK_BUNDLE_CHANCE = 0.6;
// A paid shop doesn't leave goods on its floor; the shed is the Frog Coin's.
const NO_STICK_BUNDLE_KINDS = new Set(['shopkeeper', 'shed']);

/**
 * HutSystem — manages hut interior entry/exit and interior state.
 *
 * Entry: player approaches the exterior door (∩) and presses SPACE.
 * Exit:  player approaches the interior exit door (∩) and presses SPACE.
 *
 * Coordinate contract:
 *   Interior pixel coords: 0–160 (10 cells × 16px)
 *   Canvas offset for rendering: 160px each side
 */

// Hut interior is intentionally small — a cozy 10×10 space (playable 8×8 cells).
// Dungeon interiors (DungeonSystem) use the full 24×24 grid. The Alchemy Hut
// is larger (12×12, to fit its 3 stations + 2 bottles) but still reads as a
// "hut" floor, not a dungeon — see isHutFloor().
const INTERIOR_COLS = 10;
const INTERIOR_ROWS = 10;

// Any floor at or under this size is a hut interior (HutSystem.update/
// nearInteriorExit/handleSpacePress all gate on this, not the literal 10×10
// default) — matches the threshold HutInteriorOverlay.js already uses to
// distinguish hut-style rendering from dungeon-style rendering.
const isHutFloor = (floor) => floor != null && floor.gridCols <= 12;

// Shopkeeper stall geometry: the alcove row (against the north wall, where
// the Shopkeeper stands) and the Counter row directly south of it that seals
// the alcove off. One constant shared between the two generateHutInterior
// blocks that need it so the stall can't drift out of sync.
const SHOPKEEPER_ALCOVE_ROW = 1;
const SHOPKEEPER_COUNTER_ROW = SHOPKEEPER_ALCOVE_ROW + 1;

// Proximity radius for door interaction (px from door center)
const DOOR_INTERACT_RADIUS = GRID.CELL_SIZE * 2;

export class HutSystem {
  constructor(game) {
    this.game = game;
    // The floor items the live hut floor was seeded with (bread, the Shed's
    // Frog Coin, the alchemy bottles) — handed to game.items on entry. On
    // exit these stay inside; anything else loose on the floor goes outside.
    this._seededFloorItems = new Set();
  }

  // ─── Interior Generation ─────────────────────────────────────────────────

  generateHutInterior(hutKind, depth, sizeOverride = null, zone = null) {
    const cols = sizeOverride?.cols ?? (hutKind === 'shed' ? 6 : INTERIOR_COLS);
    const rows = sizeOverride?.rows ?? (hutKind === 'shed' ? 6 : INTERIOR_ROWS);

    // Build collision map: border solid, interior open
    const collisionMap = [];
    for (let r = 0; r < rows; r++) {
      collisionMap[r] = [];
      for (let c = 0; c < cols; c++) {
        collisionMap[r][c] = (r === 0 || r === rows - 1 || c === 0 || c === cols - 1);
      }
    }

    // Background objects: simple border wall visuals + sparse decor
    const backgroundObjects = [];

    // Enemies and NPCs — filled in by the hutKind branches further down, but
    // declared up here because `cellOccupied` below closes over `npcs` and the
    // decor loop calls it before those branches run. Declaring them at the
    // point of use put `npcs` in the temporal dead zone for that call, so
    // generateHutInterior threw ReferenceError on EVERY hut and no hut could
    // be entered at all.
    const enemies = [];
    const npcs = [];

    // Spawn-occupancy helper: rejects walls AND cells already holding a
    // background object or item. Prevents items/decor from rendering on top
    // of fixed objects like the oil press.
    const NPC_EXCL_RADIUS = GRID.CELL_SIZE * 2;
    const cellOccupied = (col, row, items = []) => {
      if (collisionMap[row]?.[col]) return true;
      const x = col * GRID.CELL_SIZE;
      const y = row * GRID.CELL_SIZE;
      if (backgroundObjects.some(o => o.position.x === x && o.position.y === y)) return true;
      if (items.some(it => it.position.x === x && it.position.y === y)) return true;
      for (const npc of npcs) {
        const dx = x - npc.position.x;
        const dy = y - npc.position.y;
        if (dx * dx + dy * dy < NPC_EXCL_RADIUS * NPC_EXCL_RADIUS) return true;
      }
      return false;
    };

    // ── Fixed-position background objects first ──
    // Oil press: any hut can roll one. Rate bumped 0.10 → 0.12 when the old
    // guaranteed-press P room became the puzzle room. Settlement's dedicated
    // 'press' hut guarantees one instead (see branch below) and skips the
    // random roll so it never gets a second; the Alchemy Hut never rolls one.
    // Placed BEFORE decor/bread so those spawn loops can reject the press cell.
    const hasPress = hutKind !== 'press' && hutKind !== 'alchemy' && hutKind !== 'wise_man' && Math.random() < 0.12;
    if (hasPress || hutKind === 'press') {
      backgroundObjects.push(new BackgroundObject(
        '⊓',
        2 * GRID.CELL_SIZE,
        2 * GRID.CELL_SIZE
      ));
    }

    // Fireplace: same independent roll shape as the press (double its rate —
    // the player wasn't running into it often enough given its value), placed
    // at the opposite corner so the two can coexist in a randomly-rolled hut.
    // The Settlement's dedicated 'press' hut now guarantees BOTH appliances
    // in the same building (merged from a separate dedicated 'fireplace' hut
    // — two Settlement slots for two appliances that belong together) so it
    // skips the random roll same as the press does above. Starts unlit
    // (`burning: false`) — FireplaceSystem flips it on the first Stick and
    // the flag resets for free next visit since generateHutInterior rebuilds
    // this object from scratch.
    const hasFireplace = hutKind !== 'press' && hutKind !== 'alchemy' && hutKind !== 'wise_man' && Math.random() < 0.24;
    if (hasFireplace || hutKind === 'press') {
      const fireplace = new BackgroundObject(
        '⌂',
        (cols - 3) * GRID.CELL_SIZE,
        2 * GRID.CELL_SIZE
      );
      fireplace.burning = false;
      backgroundObjects.push(fireplace);
    }

    // Alchemy Hut: Water Trough (2x2, top-left), Cauldron (center, white),
    // Condenser (lower-left, purple), 2 pre-placed Empty Bottles. Stations
    // are read by AlchemySystem via proximity to these chars.
    if (hutKind === 'alchemy') {
      // Create 2x2 trough with still water appearance
      for (let ty = 0; ty < 2; ty++) {
        for (let tx = 0; tx < 2; tx++) {
          const trough = new BackgroundObject('≈', (2 + tx) * GRID.CELL_SIZE, (2 + ty) * GRID.CELL_SIZE);
          trough.isTrough = true;
          // Gentle still water: light blue with subtle white tint for reflection
          trough.color = '#5588dd';
          trough.animationColor = '#5588dd';
          backgroundObjects.push(trough);
        }
      }

      const cauldron = new BackgroundObject('Ω', Math.floor(cols / 2) * GRID.CELL_SIZE, Math.floor(rows / 2) * GRID.CELL_SIZE);
      cauldron.color = '#ffffff';
      backgroundObjects.push(cauldron);

      const condenser = new BackgroundObject('Ψ', 2 * GRID.CELL_SIZE, (rows - 4) * GRID.CELL_SIZE);
      condenser.color = '#cc88ff';
      backgroundObjects.push(condenser);
    }

    // Shopkeeper stall: a full-width Counter one row below the north wall
    // seals row 1 into its own alcove — bounded by the north border wall
    // above and the west/east border walls to the sides, the only remaining
    // approach is straight through the counter, which is solid. This is the
    // universal "NPC behind an impassable counter" shop convention: the
    // player can never stand next to the Shopkeeper, only interact across
    // the counter (see SHOP_INTERACTION_RANGE). Placed before the decor loop
    // below so cellOccupied() keeps decor/bread off the counter's cells; the
    // alcove row itself (row 1) is outside the decor loop's random row range
    // already, so it never needs its own exclusion check.
    if (hutKind === 'shopkeeper') {
      for (let c = 1; c <= cols - 2; c++) {
        backgroundObjects.push(new BackgroundObject('Π', c * GRID.CELL_SIZE, SHOPKEEPER_COUNTER_ROW * GRID.CELL_SIZE));
      }
    }

    // Wise Fellow's hut is laid out, not cluttered: a Shrine on the axis
    // directly north of where he sits, a Wild Flower to either side of it,
    // and two raked rows of Sand to the south split by a clear aisle from
    // the door. It skips the press/fireplace rolls above, the random decor
    // below, and the bread roll, so nothing breaks the symmetry. Placed
    // before the decor loop so cellOccupied() would respect it regardless.
    if (hutKind === 'wise_man') {
      const axisCol = Math.floor(cols / 2);
      const shrineRow = Math.floor(rows / 2) - 3;
      const place = (char, col, row) =>
        backgroundObjects.push(new BackgroundObject(char, col * GRID.CELL_SIZE, row * GRID.CELL_SIZE));
      place('$', axisCol, shrineRow);
      place('✿', axisCol - 2, shrineRow);
      place('✿', axisCol + 2, shrineRow);
      for (const row of [rows - 4, rows - 3]) {
        for (let col = 2; col <= cols - 2; col++) {
          if (col !== axisCol) place('.', col, row);
        }
      }
    }

    // Interior floor decor (very sparse — hut is small)
    const decorChars = ['n', '*', '8', '%'];
    const decorCount = hutKind === 'wise_man' ? 0 : 1 + Math.floor(Math.random() * 3);
    for (let i = 0; i < decorCount; i++) {
      for (let attempt = 0; attempt < 12; attempt++) {
        const col = 2 + Math.floor(Math.random() * (cols - 4));
        const row = 2 + Math.floor(Math.random() * (rows - 5));
        if (cellOccupied(col, row)) continue;
        const char = decorChars[Math.floor(Math.random() * decorChars.length)];
        backgroundObjects.push(new BackgroundObject(char, col * GRID.CELL_SIZE, row * GRID.CELL_SIZE));
        break;
      }
    }

    // Wizard Hut's summoning-circle ground point — set inside the 'wizard'
    // branch below, read by WizardSystem off the returned floor object.
    let wizardCirclePosition = null;

    // Enemies and NPCs — populated based on hutKind (declared above the
    // cellOccupied helper, which reads `npcs`).
    if (hutKind === 'enemy_encounter') {
      // 1–2 zone-appropriate enemies
      const spawnCount = 1 + Math.floor(Math.random() * 2);
      for (let i = 0; i < spawnCount; i++) {
        const zone = this.game.currentRoom?.zone || 'green';
        const enemyChar = getZoneRandomEnemy(depth, zone);
        if (!enemyChar) continue;
        let col = 2;
        let row = 2;
        for (let attempt = 0; attempt < 12; attempt++) {
          col = 2 + Math.floor(Math.random() * (cols - 4));
          row = 2 + Math.floor(Math.random() * (rows - 6));
          if (!cellOccupied(col, row)) break;
        }
        const enemy = new Enemy(enemyChar, col * GRID.CELL_SIZE, row * GRID.CELL_SIZE, depth);
        enemy.setCollisionMap(collisionMap);
        enemy.setBackgroundObjects(backgroundObjects);
        applyZoneCombatModifiers(enemy, zone);
        enemies.push(enemy);
      }

    } else if (hutKind === 'barrel_room') {
      // 3–5 barrels scattered in the interior — no enemies
      const barrelCount = 3 + Math.floor(Math.random() * 3);
      let placed = 0;
      let attempts = 0;
      while (placed < barrelCount && attempts < barrelCount * 6) {
        attempts++;
        const col = 2 + Math.floor(Math.random() * (cols - 4));
        const row = 2 + Math.floor(Math.random() * (rows - 5));
        if (cellOccupied(col, row)) continue;
        backgroundObjects.push(new BackgroundObject('p', col * GRID.CELL_SIZE, row * GRID.CELL_SIZE));
        placed++;
      }

    } else if (hutKind === 'wise_man') {
      // Wise fellow at interior center
      const zone = this.game.currentRoom?.zone || 'green';
      const centerCol = Math.floor(cols / 2);
      const centerRow = Math.floor(rows / 2) - 1;
      const wise = new WiseFellow(centerCol * GRID.CELL_SIZE, centerRow * GRID.CELL_SIZE);
      wise.setHint(zone, this.game.cursedRun);
      npcs.push(wise);

    } else if (hutKind === 'fisherman') {
      // Fisherman at interior center — fishing-loop tips via the dialogue box
      const zone = this.game.currentRoom?.zone || 'green';
      const centerCol = Math.floor(cols / 2);
      const centerRow = Math.floor(rows / 2) - 1;
      const fisher = new Fisherman(centerCol * GRID.CELL_SIZE, centerRow * GRID.CELL_SIZE);
      fisher.setZone(zone, { coinDemo: true });
      npcs.push(fisher);

    } else if (hutKind === 'witch') {
      // Witch at interior center
      const centerCol = Math.floor(cols / 2);
      const centerRow = Math.floor(rows / 2) - 1;
      npcs.push(new Witch(centerCol * GRID.CELL_SIZE, centerRow * GRID.CELL_SIZE));

    } else if (hutKind === 'weapons_master') {
      // Weapons Master at interior center
      const centerCol = Math.floor(cols / 2);
      const centerRow = Math.floor(rows / 2) - 1;
      npcs.push(new WeaponsMaster(centerCol * GRID.CELL_SIZE, centerRow * GRID.CELL_SIZE));

    } else if (hutKind === 'shopkeeper') {
      // Shopkeeper stands in the sealed alcove behind the Counter (row 1 —
      // see the fixed-position block above) and rolls its stock in its own
      // constructor. Never directly reachable; the player interacts across
      // the counter from row 3+ via SHOP_INTERACTION_RANGE.
      const centerCol = Math.floor(cols / 2);
      // zoneDepths seeds the first stock roll (only wares whose Home Zone
      // this run has reached, data/homeZone.js); zone is the physical Zone
      // this Settlement sits in and narrows the roll to that Zone's own
      // wares first (shopPricing.js's zoneCraftablePool) — a Green
      // Settlement and a Red Settlement stock different counters.
      npcs.push(new Shopkeeper(
        centerCol * GRID.CELL_SIZE,
        SHOPKEEPER_ALCOVE_ROW * GRID.CELL_SIZE,
        this.game.zoneDepths,
        zone
      ));

    } else if (hutKind === 'neutral_npc') {
      // Placeholder NPC: spawn the errand traveler. Seeds an errand if none active
      // so the room never feels empty. After a betrayal, _enterHut swaps it
      // for the hostile enemy (ErrandSystem.replaceBetrayedTravelers).
      const centerCol = Math.floor(cols / 2);
      const centerRow = Math.floor(rows / 2) - 1;
      const traveler = this.game.errandSystem?.createTraveler(
        centerCol * GRID.CELL_SIZE,
        centerRow * GRID.CELL_SIZE,
        { seed: true, player: this.game.player }
      );
      if (traveler) npcs.push(traveler);
    } else if (hutKind === 'wizard') {
      // Wizard at interior center; summoning circle 2 cells south of them —
      // the ground point WizardSystem's lightning strike lands on and the
      // golem appears at. Position cached on the returned floor object
      // (below) so WizardSystem doesn't have to re-derive it.
      const centerCol = Math.floor(cols / 2);
      const centerRow = Math.floor(rows / 2) - 1;
      npcs.push(new WizardNPC(centerCol * GRID.CELL_SIZE, centerRow * GRID.CELL_SIZE));

      const circleCol = centerCol;
      const circleRow = centerRow + 2;
      const circle = new BackgroundObject('◎', circleCol * GRID.CELL_SIZE, circleRow * GRID.CELL_SIZE);
      circle.color = '#aa66ff';
      backgroundObjects.push(circle);
      wizardCirclePosition = {
        x: circleCol * GRID.CELL_SIZE + GRID.CELL_SIZE / 2,
        y: circleRow * GRID.CELL_SIZE + GRID.CELL_SIZE / 2,
      };

    }

    // Bread loaves: occasional in huts (40% chance to spawn, 1–2 loaves) —
    // barrels are now the more reliable bread source (see spawnRandom in
    // InteractionSystem). Player picks them up off the floor; pressing the use
    // button later drops a loaf for crows. Items are seeded into
    // activeFloor.items and pushed into game.items on entry by _enterHut
    // (marked hutPlane).
    const breadItems = [];
    if (hutKind === 'shed') {
      // Frog Coin at center — the prize for getting in (small form, or the
      // Shed Key). Seeded here, after breadItems exists: it used to be pushed
      // from the NPC branch above, before the declaration, and threw.
      const centerCol = Math.floor(cols / 2);
      const centerRow = Math.floor(rows / 2);
      breadItems.push(new Item('⊚', centerCol * GRID.CELL_SIZE, centerRow * GRID.CELL_SIZE));
    } else if (hutKind === 'alchemy') {
      // 2 pre-placed Empty Bottles so the player can start brewing without
      // already owning one.
      let placed = 0;
      for (let attempt = 0; placed < 2 && attempt < 24; attempt++) {
        const col = 2 + Math.floor(Math.random() * (cols - 4));
        const row = 2 + Math.floor(Math.random() * (rows - 5));
        if (cellOccupied(col, row, breadItems)) continue;
        breadItems.push(new Item('B', col * GRID.CELL_SIZE, row * GRID.CELL_SIZE));
        placed++;
      }
    } else if (hutKind !== 'witch' && hutKind !== 'shopkeeper' && hutKind !== 'wise_man' && Math.random() < 0.40) {
      // Shopkeeper excluded: a free loaf on the floor of a paid shop reads
      // wrong, and the alcove behind the counter is off-limits anyway.
      const loafCount = 1 + (Math.random() < 0.15 ? 1 : 0);
      for (let i = 0; i < loafCount; i++) {
        for (let attempt = 0; attempt < 12; attempt++) {
          const col = 2 + Math.floor(Math.random() * (cols - 4));
          const row = 2 + Math.floor(Math.random() * (rows - 5));
          if (cellOccupied(col, row, breadItems)) continue;
          breadItems.push(new Item('⌬', col * GRID.CELL_SIZE, row * GRID.CELL_SIZE));
          break;
        }
      }
    }

    // Stick bundle: a row of three Sticks, kept clear of everything placed
    // above. Seeded like the bread (floor.ingredients, handed to
    // game.ingredients by InteriorManager.enterFloor).
    const floorIngredients = [];
    if (!NO_STICK_BUNDLE_KINDS.has(hutKind) && Math.random() < STICK_BUNDLE_CHANCE) {
      for (let attempt = 0; attempt < 16; attempt++) {
        const col = 2 + Math.floor(Math.random() * (cols - 4 - (STICK_BUNDLE_SIZE - 1)));
        const row = 2 + Math.floor(Math.random() * (rows - 5));
        const cells = Array.from({ length: STICK_BUNDLE_SIZE }, (_, i) => col + i);
        if (cells.some(c => cellOccupied(c, row, breadItems))) continue;
        for (const c of cells) {
          floorIngredients.push(new Ingredient(STICK_CHAR, c * GRID.CELL_SIZE, row * GRID.CELL_SIZE));
        }
        break;
      }
    }

    // Interior exit door at south-center border. The door cell stays solid so
    // neither the player nor enemies can walk through the wall — leaving the hut
    // is SPACE-only, and `nearInteriorExit()` uses a 2-cell proximity radius
    // so the player can stand one cell north of the door and still interact.
    const exitCol = Math.floor(cols / 2);
    const exitRow = rows - 1;
    const exitDoor = new BackgroundObject('∩', exitCol * GRID.CELL_SIZE, exitRow * GRID.CELL_SIZE);
    backgroundObjects.push(exitDoor);

    // Player spawn: just inside the south door
    const spawnPoint = {
      x: exitCol * GRID.CELL_SIZE,
      y: (exitRow - 2) * GRID.CELL_SIZE
    };

    // Viewport metadata: where the PiP panel renders on the main canvas.
    // Phase A only stores this; Phase B will route ExploreRenderer through it.
    const interiorPxW = cols * GRID.CELL_SIZE;
    const interiorPxH = rows * GRID.CELL_SIZE;
    const viewport = {
      offsetX: Math.floor((GRID.WIDTH  - interiorPxW) / 2),
      offsetY: Math.floor((GRID.HEIGHT - interiorPxH) / 2),
      gridCols: cols,
      gridRows: rows,
      cellSize: GRID.CELL_SIZE,
    };

    return {
      type: 'HUT_INTERIOR',
      gridCols: cols,
      gridRows: rows,
      collisionMap,
      backgroundObjects,
      enemies,
      npcs,
      items: breadItems,
      ingredients: floorIngredients,
      doors: [{ col: exitCol, row: exitRow, leadsTo: null }],
      hutKind,
      spawnPoint,
      exitCol,
      exitRow,
      viewport,
      wizardCirclePosition,
    };
  }

  // ─── Proximity Checks ────────────────────────────────────────────────────

  /**
   * Resolves which hut (if any) the player is near the exterior door of.
   * Settlement rooms hold several huts (`room.huts`); every other hut-bearing
   * room type still has the single `room.hut`. Normalizing here lets entry
   * logic stay a single loop regardless of room shape.
   */
  _findNearbyHut() {
    const { game } = this;
    if (!game.player || isInteriorActive(game)) return null;
    if ((game.player._hutEntryCooldown ?? 0) > 0) return null;
    // A Cavern is a hut record too (hutKind 'cavern'), but its door only
    // exists once a bomb has broken the Bombable Rock hiding it. Copied into a
    // fresh array so the Settlement's own room.huts list is never mutated.
    const cavern = game.currentRoom?.cavern;
    const huts = [
      ...(game.currentRoom?.huts ?? (game.currentRoom?.hut ? [game.currentRoom.hut] : [])),
      ...(cavern?.revealed ? [cavern] : []),
    ];
    for (const hut of huts) {
      if (!hut?.doorPosition) continue;
      // Witch huts on chicken legs are inaccessible until SIT/SITDOWN lowers them.
      if (hut.raised) continue;
      // Shed: only isSmall entities (frog form, tamed rat) fit its small
      // door, until the Shed Key opens it into a full door (_tryShedDoor).
      if (hut.hutKind === 'shed' && !hut.unlocked && !game.player.isSmall) continue;
      const { col, row } = hut.doorPosition;
      if (this._nearCell(game.player, col * GRID.CELL_SIZE, row * GRID.CELL_SIZE)) return hut;
    }
    return null;
  }

  /** Returns true if player is close enough to any exterior hut door to interact. */
  nearExteriorDoor() {
    return !!this._findNearbyHut();
  }

  /**
   * Lowers a raised witch hut in a stepped descent — one grid cell per beat —
   * removing chicken legs as the hut settles onto them. While the animation
   * plays `hut.raised` stays true so the door stays inaccessible; on the
   * final beat the collision map is rewritten and the hut becomes enterable.
   */
  lowerHut(room) {
    const hut = room?.hut;
    if (!hut?.raised) return false;
    if (hut._loweringInProgress) return false;
    hut._loweringInProgress = true;

    this.game.audioSystem?.playSFX('hut_lower');

    const shift = hut.verticalShift || 2;
    const C = GRID.CELL_SIZE;
    const STEP_DURATION = 0.15;

    // All hut pieces that need to slide down together: walls, door, and the
    // dark interior fill cells. Legs are handled separately (stripped row by
    // row as the hut covers them).
    const movables = [
      ...(hut.wallObjects || []),
      ...(hut.interiorObjects || []),
    ];
    if (hut.doorObject) movables.push(hut.doorObject);

    // Clear the OLD full footprint from the collision map up front so the
    // collision grid doesn't lag behind mid-step pixel positions. The map
    // will be rewritten for the NEW footprint in the finalize callback.
    const { minCol, maxCol, minRow, maxRow } = hut.exteriorBounds;
    for (let r = minRow; r <= maxRow; r++) {
      for (let c = minCol; c <= maxCol; c++) {
        if (room.collisionMap[r]) room.collisionMap[r][c] = false;
      }
    }

    // If the player is standing in any cell that the hut will occupy after
    // descending, slide them south to clear ground over the descent duration.
    // The lock prevents input/dodge from re-injecting them under the hut.
    const player = this.game.player;
    if (player) {
      const px = Math.floor(player.position.x / C);
      const py = Math.floor(player.position.y / C);
      const newMinRow = minRow + shift;
      const newMaxRow = maxRow + shift;
      const insideFootprint =
        px >= minCol && px <= maxCol &&
        py >= newMinRow - shift && py <= newMaxRow; // covers old + new spans
      if (insideFootprint) {
        const safeCol = hut.doorPosition.col;          // door column = open approach
        const safeRow = newMaxRow + 2;                 // 2 cells south of new south wall
        const totalDuration = STEP_DURATION * shift;
        this.game.animationSystem.play(player, [{
          type: 'moveTo',
          x: safeCol * C,
          y: safeRow * C,
          duration: totalDuration,
          easing: 'easeOut',
        }]);
      }
    }

    /** Removes the topmost remaining leg row (highest on screen = smallest row index). */
    const stripTopLegRow = () => {
      if (!hut.legObjects?.length) return;
      let topRow = Infinity;
      for (const leg of hut.legObjects) {
        const r = Math.round(leg.position.y / C);
        if (r < topRow) topRow = r;
      }
      for (let i = hut.legObjects.length - 1; i >= 0; i--) {
        const leg = hut.legObjects[i];
        if (Math.round(leg.position.y / C) === topRow) {
          const idx = room.backgroundObjects.indexOf(leg);
          if (idx !== -1) room.backgroundObjects.splice(idx, 1);
          hut.legObjects.splice(i, 1);
        }
      }
    };

    /** Snaps every wall + door + interior-fill object down by one full cell. */
    const snapDown = () => {
      for (const obj of movables) obj.position.y += C;
      this.game.renderer.backgroundDirty = true;
    };

    // Build the step sequence: snap → leg-row strip → wait, repeated `shift` times.
    const steps = [];
    for (let i = 0; i < shift; i++) {
      steps.push({ type: 'callback', fn: snapDown });
      steps.push({ type: 'callback', fn: stripTopLegRow });
      steps.push({ type: 'wait', duration: STEP_DURATION });
    }
    steps.push({
      type: 'callback',
      fn: () => {
        // Solidify the entire NEW footprint — walls, door cell, interior
        // fills. Door is impassable for all huts; entry is SPACE-only.
        const newMinRow = minRow + shift;
        const newMaxRow = maxRow + shift;
        for (let r = newMinRow; r <= newMaxRow; r++) {
          for (let c = minCol; c <= maxCol; c++) {
            if (room.collisionMap[r]) room.collisionMap[r][c] = true;
          }
        }
        hut.doorPosition.row += shift;
        hut.exteriorBounds.minRow = newMinRow;
        hut.exteriorBounds.maxRow = newMaxRow;
        hut.raised = false;
        hut.verticalShift = 0;
        hut._loweringInProgress = false;
        this.game.renderer.backgroundDirty = true;
      }
    });

    // AnimationSystem requires a target — use a throwaway host since each
    // callback orchestrates the actual wall/door/leg objects directly.
    const host = { position: { x: 0, y: 0 } };
    this.game.animationSystem.play(host, steps);
    return true;
  }

  /** Returns true if player is close enough to the interior exit door to interact. */
  nearInteriorExit() {
    const { game } = this;
    if (!game.player?.inHut || !game.activeFloor) return false;
    if (!isHutFloor(game.activeFloor)) return false;
    const { exitCol, exitRow } = game.activeFloor;
    return this._nearCell(game.player, exitCol * GRID.CELL_SIZE, exitRow * GRID.CELL_SIZE);
  }

  // ─── SPACE Interaction ────────────────────────────────────────────────────

  /**
   * SPACE near hut exterior door: enter the hut.
   * SPACE near interior exit door: exit the hut.
   * Returns true if handled (prevents default SPACE behavior).
   */
  handleSpacePress() {
    const { game } = this;
    if (!game.player) return false;
    if ((game.player._hutEntryCooldown ?? 0) > 0) return false;

    // Entry from exterior
    if (!game.player.inHut) {
      const hut = this._findNearbyHut();
      if (hut) {
        this._enterHut(hut);
        return true;
      }
      if (this._tryShedDoor()) return true;
    }

    // Exit from interior (hut only — dungeon handled by DungeonSystem)
    if (game.player.inHut && isHutFloor(game.activeFloor) && this.nearInteriorExit()) {
      this._exitHut();
      return true;
    }

    return false;
  }

  /**
   * SPACE at a Shed's small door while too big to fit through it. Holding the
   * Shed Key (the Errand traveler's completion reward) turns the small door
   * into a full Hut Door, which stays open for the rest of the room's life;
   * the key is kept, so every Shed in the run opens. Without it the door
   * reads LOCKED. Returns whether the press was consumed.
   */
  _tryShedDoor() {
    const { game } = this;
    const shed = (game.currentRoom?.huts ?? []).find(hut =>
      hut.hutKind === 'shed' && !hut.unlocked &&
      this._nearCell(game.player, hut.doorPosition.col * GRID.CELL_SIZE, hut.doorPosition.row * GRID.CELL_SIZE));
    if (!shed) return false;

    const door = shed.doorObject;
    if (!hasKeyItem(game.inventorySystem, SHED_KEY_CHAR, game)) {
      game.combatSystem.createDamageNumber('LOCKED', door.position.x, door.position.y - GRID.CELL_SIZE * 0.5, '#eeeeee');
      return true;
    }
    shed.unlocked = true;
    door.becomeHutDoor();
    return true;
  }

  // ─── Entry / Exit ────────────────────────────────────────────────────────

  _enterHut(hut) {
    const { game } = this;

    // Save exterior position
    game.player.hutExitPosition = {
      x: game.player.position.x,
      y: game.player.position.y
    };

    // Reuse cached interior if the player has been here before in this room
    // visit — preserves broken barrels, defeated enemies, NPC dialogue state, etc.
    let floor = hut.interiorState;
    if (!floor) {
      if (hut.hutKind === 'cavern') {
        floor = game.cavernSystem.generateCavernInterior();
      } else {
        const depth = game.getCurrentZoneDepth ? game.getCurrentZoneDepth() : 1;
        const sizeOverride = hut.hutKind === 'alchemy' ? { cols: 12, rows: 12 } : null;
        floor = this.generateHutInterior(hut.hutKind, depth, sizeOverride, game.currentRoom?.zone);
      }
      hut.interiorState = floor;
      hut.interiorGenerated = true;
    }

    this._seededFloorItems = new Set([...(floor.items ?? []), ...(floor.ingredients ?? [])]);
    game.interiorManager.enterFloor('hut', floor, floor.spawnPoint);

    // A cached floor can still hold the friendly traveler from before a
    // betrayal elsewhere — swap it for the hostile enemy, as an E room would.
    game.errandSystem.replaceBetrayedTravelers(floor.npcs, floor, game);

    // Alchemist hut presence is re-evaluated live on every entry (unlike the
    // rest of the cached interior) — see _syncAlchemistHutPresence.
    if (hut.hutKind === 'alchemy') this._syncAlchemistHutPresence(hut);
  }

  /**
   * Live gate on whether the rescued Alchemist is currently standing in his
   * hut. Unlike the rest of the cached interior (stations, decor), his
   * presence depends on state that can change between visits — imperatively
   * adds/removes the singleton from the cached floor's npcs array rather
   * than regenerating the interior.
   *
   *   - Pre-rescue: absent (nothing to sync).
   *   - Rescued, lesson not yet given: always present (first hut visit).
   *   - Lesson given: present only while the player currently carries a
   *     Bottle of Hot Water — otherwise he's out roaming (see roomFeatures
   *     maybeSpawnRoamingAlchemist).
   */
  _syncAlchemistHutPresence(hut) {
    const { game } = this;
    const alchemist = game.alchemistNPC;
    const floor = hut.interiorState;
    if (!floor || !alchemist?.rescued) return;
    floor.npcs = floor.npcs ?? [];

    const shouldBePresent = !alchemist.lessonGiven || this.playerCarriesHotWater();

    const idx = floor.npcs.indexOf(alchemist);
    if (shouldBePresent && idx === -1) {
      const centerCol = Math.floor(floor.gridCols / 2);
      const centerRow = Math.floor(floor.gridRows / 2) - 1;
      alchemist.position.x = centerCol * GRID.CELL_SIZE;
      alchemist.position.y = centerRow * GRID.CELL_SIZE;
      alchemist.placement = 'hut';
      floor.npcs.push(alchemist);
    } else if (!shouldBePresent && idx !== -1) {
      floor.npcs.splice(idx, 1);
      if (alchemist.placement === 'hut') alchemist.placement = null;
    }
  }

  /**
   * Whether the player holds a Bottle of Hot Water right now — equipped or in
   * the consumable inventory. Gates the Alchemist's hut presence above and his
   * "you brought it" line (AlchemistNPC.getDialogueLines), which is spoken
   * after the presence check and must not take it on trust.
   */
  playerCarriesHotWater() {
    const { game } = this;
    return !!(
      game.player.equippedConsumables?.some(it => it?.char === HOT_WATER_CHAR) ||
      game.inventorySystem.consumableInventory?.some(it => it?.char === HOT_WATER_CHAR));
  }

  _exitHut() {
    const { game } = this;
    const floor = game.activeFloor;
    const exitPosition = game.player.hutExitPosition;
    // Collected before exitFloor, which sweeps all hutPlane loot away.
    const floorItems = game.items.filter(i => i.hutPlane);
    const floorIngredients = game.ingredients.filter(i => i.hutPlane);
    game.interiorManager.exitFloor(exitPosition);
    this._carryFloorLootOutside(floor, floorItems, floorIngredients, exitPosition);
    // Brief cooldown so the door's proximity check doesn't immediately
    // re-trigger on the next frame.
    game.player._hutEntryCooldown = 0.5;
  }

  /**
   * Loot left lying on the hut floor comes out of the door with the player:
   * a weapon dropped for a swap, an enemy's drops, ingredients not yet picked
   * up. It scatters from the exit spot onto the surface Room. The floor's own
   * seeded items are the exception — they go back on the cached floor and
   * are there again on the next entry.
   */
  _carryFloorLootOutside(floor, floorItems, floorIngredients, exitPosition) {
    const { game } = this;
    const outside = [];
    for (const item of floorItems) {
      if (this._seededFloorItems.has(item) && Array.isArray(floor?.items)) floor.items.push(item);
      else outside.push(item);
    }
    const outsideIngredients = [];
    for (const ingredient of floorIngredients) {
      if (this._seededFloorItems.has(ingredient) && Array.isArray(floor?.ingredients)) floor.ingredients.push(ingredient);
      else outsideIngredients.push(ingredient);
    }
    this._seededFloorItems.clear();
    if (!exitPosition) return;

    const scatter = (entity) => {
      entity.hutPlane = false;
      entity.position.x = exitPosition.x;
      entity.position.y = exitPosition.y;
      const a = Math.random() * Math.PI * 2;
      const speed = 60 + Math.random() * 80;
      entity.velocity.vx = Math.cos(a) * speed;
      entity.velocity.vy = Math.sin(a) * speed;
      game.physicsSystem.addEntity(entity);
    };
    for (const item of outside) {
      scatter(item);
      game.items.push(item);
    }
    for (const ingredient of outsideIngredients) {
      scatter(ingredient);
      ingredient.pickupCooldown = 0.75;
      game.ingredients.push(ingredient);
    }
  }

  // ─── Update ───────────────────────────────────────────────────────────────

  update(dt) {
    const { game } = this;
    if (!game.player) return;

    // Tick re-entry cooldown (prevents immediate re-entry after exiting)
    if (game.player._hutEntryCooldown > 0) {
      game.player._hutEntryCooldown -= dt;
    }

    if (game.player.inHut && game.activeFloor) {
      // Only process if this is a hut interior (10-12 cols), not a dungeon (24 cols)
      if (!isHutFloor(game.activeFloor)) return;

      // Update interior enemies. The return value carries side-effect requests
      // (slime trail, fire/ice trail, goo spew, item attacks, aggro sound) that
      // the surface loop in main.js consumes — interior enemies need the same
      // routing or slime-affinity enemies emit no trail, etc.
      for (const enemy of game.activeFloor.enemies) {
        if (!game.combatSystem.applyTargetOverrides(enemy, game.activeFloor.enemies, game.player, game.activeNoiseSource)) {
          enemy.target = game.player;
        }
        // Canonical interior tick (bug #92): 2× rate (enemy timing data is
        // double-seconds), result cached for CombatSystem — which used to be
        // the duplicate second tick and now only consumes.
        const r = enemy.update(dt * PHYSICS.ENEMY_TIMER_RATE);
        enemy._frameUpdateResult = r;
        if (!r) continue;
        if (r.justAggrod) game.audioSystem?.playSFX(enemy.data?.sfx?.aggro ?? 'aggro');
        if (r.itemAttack) game.combatSystem.createEnemyAttack(r.itemAttack);
        if (r.shouldDropSlimeTrail) {
          const t = r.shouldDropSlimeTrail;
          game._dropSlimeTrail(t.x, t.y, t.plane);
        }
        if (r.shouldPlaceTrail && r.trailData) {
          const td = r.trailData;
          game._spawnEnemyTrailPuddle(td.x, td.y, td.type, td.radius, enemy.plane ?? 0, td.duration);
        }
      }

      // Process interior enemy deaths
      for (let i = game.activeFloor.enemies.length - 1; i >= 0; i--) {
        const enemy = game.activeFloor.enemies[i];
        if (enemy.hp <= 0) {
          game.audioSystem?.playSFX('destroy');

          // Spawn loot (LootSystem marks hutPlane when player.inHut)
          game.spawnLoot(enemy);

          // Death detritus (goo blobs for slimes, gray debris otherwise);
          // hutPlane so the overlay renders it. Inherits knockback velocity.
          game.worldEffectsSystem.spawnDeathDetritus(enemy, { hutPlane: true });

          game.physicsSystem.removeEntity(enemy);
          game.activeFloor.enemies.splice(i, 1);
        }
      }

      // Update interior background objects
      for (const obj of game.activeFloor.backgroundObjects) {
        obj.update(dt);
      }

      // Cavern torch glow bookkeeping (CavernSystem owns the Cavern floor)
      if (game.activeFloor.hutKind === 'cavern') this.game.cavernSystem.updateInterior(dt);

      // Update interior NPCs (WiseFellow, Witch, etc.)
      for (const npc of game.activeFloor.npcs) {
        npc.update(dt, this.game);
      }

      // Poll Witch trigger — activate polymorph on first contact; a Witch who
      // has released the player (Witch.onFrogLineTold) never curses again.
      for (const npc of game.activeFloor.npcs) {
        if (npc.triggered && !npc.released && !game.player.polymorphed) {
          this.game.polymorphSystem?.activatePolymorph(this.game, true);
        }
      }
    }
  }

  // ─── Helpers ─────────────────────────────────────────────────────────────

  _nearCell(player, cellPixelX, cellPixelY) {
    const C = GRID.CELL_SIZE;
    const px = player.position.x + C / 2;
    const py = player.position.y + C / 2;
    const cx = cellPixelX + C / 2;
    const cy = cellPixelY + C / 2;
    const dx = px - cx, dy = py - cy;
    return Math.sqrt(dx * dx + dy * dy) < DOOR_INTERACT_RADIUS;
  }
}
