import { Item, equippedDaggerOils } from '../entities/Item.js';
import { Puddle } from '../entities/Puddle.js';
import { createActivationBurst, createEmberBurst, createIceBurst } from '../entities/Particle.js';
import { GRID, BACKGROUND_OBJECT_VARIANTS } from '../game/GameConfig.js';
import { applyLavaContact } from './LavaContact.js';
import { MAX_PIPS } from './StatusEffects.js';
import { BackgroundObject } from '../entities/BackgroundObject.js';
import { isInteriorActive, tagInteriorPlane, planeOf } from './PlaneSystem.js';
import { createLightningSpire } from './LightningSpire.js';
import { createExplosionAftermath, createGooBurst } from './WorldEffectsSystem.js';
import { applyExtraOnHitEffects } from './ExtraOnHitEffects.js';

// True when any quick slot holds a weapon — the "armed" test for the
// thrown-weapon pointer.
function playerHoldsWeapon(player) {
  return !!player?.quickSlots?.some(slot => slot?.data?.type === 'WEAPON');
}

const MAX_CHARGE_TIME = 0.7; // seconds to reach max throw distance
const MIN_DIST = GRID.CELL_SIZE;       // 16px — tap distance
// Lower decel = weightier flight. Landing position is unchanged (v0=sqrt(2*decel*dist)),
// but total flight time = v0/decel = sqrt(2*dist/decel) increases as decel drops.
const THROW_DECEL = 350;               // px/s² deceleration
const SWITCH_BOUNCE_RESTITUTION = 0.7; // share of speed a thrown weapon keeps rebounding off a switch

// Per-subtype throw profile. Subtype implies intended use:
// - `maxDist`: full-charge throw distance (reticule cap)
// - `damageMult`: multiplier on weapon base damage at peak velocity
// - `minVelForDamage`: velocity below which a flight hit deals no damage
// - `maxDamageVel`: velocity at which damageMult is fully applied; falls off linearly toward minVel
const TRAP_MAX_DIST = GRID.CELL_SIZE * 4; // 64px — preserves prior trap behavior
// A thrown wire end reaches further than a thrown trap: the throw exists to span
// a gap the player can't walk, so at full charge it strings about a quarter of
// the room. Carries no damage — it's a rope end, not a projectile.
const WIRE_MAX_DIST = GRID.CELL_SIZE * 8; // 128px

// Fuse timing for enemy-placed traps (placeTrapAtPosition only — player-thrown
// traps arm via _armTrap and are out of scope). Real seconds: TrapSystem.update
// runs off the raw, undoubled deltaTime, unlike Enemy.update's ENEMY_TIMER_RATE
// doubling. Idle and unarmed for FUSE_IDLE, then blinks as a warning until it
// force-fires at FUSE_TOTAL — caps how many traps a Trap Goblin can stack.
// `_fireOneShotTrap` excludes `entry.owner` from every damage/status loop (see
// below), same as the proximity-trigger path in updatePlacedTraps — an
// enemy-placed trap never hurts the enemy that placed it, however it fires.
const TRAP_FUSE_IDLE = 5;
const TRAP_FUSE_TOTAL = 7;
const TRAP_FUSE_BLINK_INTERVAL = 0.4;

// An enemy-placed trap (Trap Goblin) can't be set off by any trigger path —
// proximity, melee, or projectile — for a beat after it lands. The goblin
// drops it mid-retreat, often right where the player (or another enemy)
// already is, and without this window the trap detonates on contact that
// predates the trap existing, not a real encounter with it.
const TRAP_SPAWN_IMMUNITY_MS = 1000;

// Trap type → placed Item char. Shared with TrapLayerMechanic so an enemy
// deciding what trap it just committed to can look up the same item data
// (effectRadius, etc.) that placeTrapAtPosition will spawn.
export const TRAP_TYPE_CHAR = { slow: '◉', fire: '^', freeze: '[', stun: '{' };
const THROW_PROFILES = {
  trap:    { maxDist: TRAP_MAX_DIST,      damageMult: 0,   minVelForDamage: 0,   maxDamageVel: 1 },
  wire:    { maxDist: WIRE_MAX_DIST,      damageMult: 0,   minVelForDamage: 0,   maxDamageVel: 1 },
  spear:   { maxDist: GRID.CELL_SIZE * 16, damageMult: 1.5, minVelForDamage: 120, maxDamageVel: 550 },
  dagger:  { maxDist: GRID.CELL_SIZE * 12, damageMult: 1.0, minVelForDamage: 100, maxDamageVel: 480 },
  sword:   { maxDist: GRID.CELL_SIZE * 8,  damageMult: 0.7, minVelForDamage: 100, maxDamageVel: 390 },
  axe:     { maxDist: GRID.CELL_SIZE * 8,  damageMult: 0.7, minVelForDamage: 100, maxDamageVel: 390 },
  hammer:  { maxDist: GRID.CELL_SIZE * 8,  damageMult: 0.6, minVelForDamage: 100, maxDamageVel: 390 },
  flail:   { maxDist: GRID.CELL_SIZE * 8,  damageMult: 0.6, minVelForDamage: 100, maxDamageVel: 390 },
  pickaxe: { maxDist: GRID.CELL_SIZE * 8,  damageMult: 0.6, minVelForDamage: 100, maxDamageVel: 390 },
  whip:    { maxDist: GRID.CELL_SIZE * 8,  damageMult: 0.5, minVelForDamage: 100, maxDamageVel: 390 },
  bow:     { maxDist: GRID.CELL_SIZE * 6,  damageMult: 0.3, minVelForDamage: 100, maxDamageVel: 340 },
  wand:    { maxDist: GRID.CELL_SIZE * 6,  damageMult: 0.3, minVelForDamage: 100, maxDamageVel: 340 },
  staff:   { maxDist: GRID.CELL_SIZE * 6,  damageMult: 0.3, minVelForDamage: 100, maxDamageVel: 340 },
  default: { maxDist: GRID.CELL_SIZE * 8,  damageMult: 0.4, minVelForDamage: 100, maxDamageVel: 390 },
};

function getThrowProfile(item) {
  const data = item?.data;
  if (!data) return THROW_PROFILES.default;
  if (data.wire) return THROW_PROFILES.wire; // wires are TRAP-typed but throw further
  if (data.type === 'TRAP') return THROW_PROFILES.trap;
  return THROW_PROFILES[data.weaponSubtype] || THROW_PROFILES.default;
}

// Traps stack by char in chest storage instead of occupying separate slots.
function mergeTrapIntoChest(arr, item) {
  const amount = item.count || 1;
  const existing = arr.find((i) => i !== item && i.char === item.char);
  if (existing) {
    existing.count = (existing.count || 1) + amount;
    return;
  }
  item.count = amount;
  arr.push(item);
}

// Splits one unit off a stacked trap entry: decrements in place and returns
// a fresh Item instance for the caller to equip/place.
function splitTrapFromStack(item) {
  item.count -= 1;
  return new Item(item.char, item.position.x, item.position.y);
}

// True if a trap of this char is already sitting in a quick slot — pickup
// should stack into held count rather than contest a slot.
export function trapAlreadyEquipped(player, item) {
  return item.data.type === 'TRAP' && player.quickSlots.some((slot) => slot?.char === item.char);
}

// Chest storage helpers shared by InventorySystem — traps merge/split by
// stack count, other item types behave as plain array entries.
export function addItemToChestArray(arr, item) {
  if (item?.data?.type === 'TRAP') mergeTrapIntoChest(arr, item);
  else arr.push(item);
}

export function removeItemFromChestArray(arr, item) {
  const idx = arr.indexOf(item);
  if (idx === -1) return null;
  if (item.data?.type === 'TRAP' && (item.count || 1) > 1) return splitTrapFromStack(item);
  arr.splice(idx, 1);
  return item;
}

export function chestEntryLabel(item) {
  const suffix = item.data?.type === 'TRAP' && item.count > 1 ? ` x${item.count}` : '';
  return `${item.char} - ${item.data.name}${suffix}`;
}

// Consumables flagged `data.stackable` (Meat Jerky, Bread, Firecracker, ...)
// merge into an existing same-char stack — carried in a quick slot or sitting
// loose in the pile — instead of taking a new slot of their own. A 2 HP Meat
// Jerky heal shouldn't cost a whole consumable slot any more than a single
// arrow should. Mirrors the TRAP chest-stacking helpers above (`item.count`);
// InventorySystem._consumeOneShotSlot is the matching unwind, decrementing
// count instead of clearing the slot. Returns the stack (with its updated
// count) on merge, or null if `item` isn't stackable or no existing stack was
// found — caller falls back to normal slot-claiming pickup in that case.
export function mergeStackableConsumable(equippedSlots, loosePile, item) {
  if (!item?.data?.stackable) return null;
  const existing =
    equippedSlots.find(s => s && s !== item && s.char === item.char) ||
    loosePile.find(i => i !== item && i.char === item.char);
  if (!existing) return null;
  existing.count = (existing.count || 1) + (item.count || 1);
  return existing;
}

export class TrapSystem {
  constructor(game) {
    this.game = game;
  }

  // Begin charging a throw.
  //   mode === 'deploy' — SPACE on a trap; the trap arms where it lands.
  //   mode === 'drop'   — SHIFT on any item; lands on the ground as a pickup
  //                       (weapons may damage en route, traps do NOT arm).
  //   source (optional) — where the projectile comes from when it isn't the
  //                       held item. Today: { kind: 'consumable', slotIndex }
  //                       for the Toss (SHIFT with a consumable armed —
  //                       TossSystem). Release routes on this descriptor.
  startTrapCharge(mode = 'deploy', source = null) {
    const profile = getThrowProfile(this.game.player?.heldItem);
    this.game.trapCharging = { timer: 0, maxDist: profile.maxDist, maxTime: MAX_CHARGE_TIME, mode, source };
  }

  // Cancel charge without throwing (state change, death, etc.).
  cancelTrapCharge() {
    this.game.trapCharging = null;
  }

  // ── Trap charges ──────────────────────────────────────────────────────────
  // A trap in a quick slot carries a per-room charge count rather than being
  // consumed outright. Charges are refilled on room entry from every copy the
  // player owns, so crafting more of a trap raises how many can be deployed.
  // Each copy is worth its authored `charges` (3 for most traps, 1 for the
  // one-per-room wires and remotes) — the same number a freshly crafted trap
  // shows, so the count doesn't drop on the first room entry (bug #414).

  // Can the held item be deployed right now?
  canUseTrap() {
    const item = this.game.player?.heldItem;
    if (!item || !item.data || item.data.type !== 'TRAP') return false;
    return item.charges > 0;
  }

  // Spend one charge, and advance to the next filled slot once they run out.
  markTrapUsed() {
    const player = this.game.player;
    const item = player?.heldItem;
    if (item?.charges != null) item.charges--;
    // Only advance to next slot when charges are depleted
    if (item?.charges === 0) {
      const nextFilled = player.quickSlots.findIndex((slot, idx) =>
        idx !== player.activeSlotIndex && slot !== null
      );
      if (nextFilled !== -1) {
        player.activeSlotIndex = nextFilled;
      }
    }
  }

  // Refill every quick-slotted trap's charges (called on room entry).
  resetTrapsForNewRoom() {
    const player = this.game.player;
    if (!player) return;
    for (const slot of player.quickSlots) {
      if (slot?.data?.type === 'TRAP') {
        slot.charges = this.roomCharges(slot);
      }
    }
  }

  // Lift every trap placed on the interior layer out of placedTraps and hand
  // them back. A dungeon floor keeps its own (DungeonSystem stores them on the
  // floor it is leaving); any other interior exit abandons them, the same as
  // the loot left on that floor.
  takeInteriorTraps() {
    const game = this.game;
    const taken = game.placedTraps.filter(e => e.interior === true);
    if (taken.length) game.placedTraps = game.placedTraps.filter(e => e.interior !== true);
    return taken;
  }

  // A slotted trap's full per-room charge count: authored charges per copy
  // owned, plus the character's trap affinity bonus (Gray Assassin's +1, the
  // same bonus Player.pickupItem grants a newly picked-up trap).
  roomCharges(item) {
    const perCopy = item.data.charges ?? 3;
    const bonus = this.game.player?.weaponAffinities?.trap?.additionalCharge ?? 0;
    return perCopy * this.countHeldTraps(item.char) + bonus;
  }

  // Total copies of a trap the player owns: quick slots plus chest storage
  // (including deposits still pending at the end of the room).
  countHeldTraps(char) {
    const player = this.game.player;
    const inventorySystem = this.game.inventorySystem;
    let count = player?.quickSlots.filter((s) => s?.char === char).length ?? 0;
    if (inventorySystem) {
      const sumStacked = (arr) => arr.reduce((sum, i) => (i.char === char ? sum + (i.count || 1) : sum), 0);
      count += sumStacked(inventorySystem.itemChest);
      count += sumStacked(inventorySystem.pendingChestDeposits);
    }
    return count;
  }

  update(deltaTime) {
    this.updateTrapCharge(deltaTime);
    this.updateInFlightTraps(deltaTime);
    // Any route back to an armed loadout (pickup, craft, chest) ends the
    // thrown-weapon pointer — checked here rather than at each arming site.
    if (this.game.thrownLastWeapon && playerHoldsWeapon(this.game.player)) {
      this.game.thrownLastWeapon = false;
    }
  }

  // Advance charge timer each frame.
  updateTrapCharge(deltaTime) {
    if (!this.game.trapCharging) return;
    this.game.trapCharging.timer = Math.min(
      this.game.trapCharging.timer + deltaTime,
      MAX_CHARGE_TIME
    );
  }

  // Returns the reticule pixel position for the current charge state, or null.
  getTrapReticulePos() {
    const game = this.game;
    if (!game.trapCharging || !game.player) return null;
    const ratio = game.trapCharging.timer / MAX_CHARGE_TIME;
    const maxDist = game.trapCharging.maxDist ?? TRAP_MAX_DIST;
    const dist = MIN_DIST + ratio * (maxDist - MIN_DIST);
    const f = game.player.facing;
    const len = Math.sqrt(f.x * f.x + f.y * f.y) || 1;
    const C = GRID.CELL_SIZE;
    return {
      x: game.player.position.x + C / 2 + (f.x / len) * dist,
      y: game.player.position.y + C / 2 + (f.y / len) * dist,
    };
  }

  // Execute the throw on key release. Mode decides the landing behavior:
  //   deploy → trap arms where it lands; a wire instead throws one end of itself,
  //            which anchors on landing (WireSystem.attachThrownEnd).
  //   drop   → item lands on the ground as a pickup (any item type).
  releaseTrapThrow() {
    const game = this.game;
    if (!game.trapCharging) return;

    // Toss release (source-descriptor branch of 'drop' — see TossSystem):
    // the armed consumable leaves its slot and lands as a ground pickup.
    // Checked before the held-item gate because a toss charge by definition
    // has empty hands.
    if (game.trapCharging.mode === 'drop' && game.trapCharging.source?.kind === 'consumable') {
      this._releaseTossThrow(game.trapCharging);
      return;
    }

    const heldItem = game.player.heldItem;
    if (!heldItem) { game.trapCharging = null; return; }

    const mode = game.trapCharging.mode || 'deploy';
    // Wires are TRAP-typed but never arm on landing — the item stays in hand and
    // only the thrown end travels, so WireSystem owns what happens where it stops.
    const throwsWireEnd = mode === 'deploy' && heldItem.data?.wire === true;
    const armsOnLanding = mode === 'deploy'
      && heldItem.data?.type === 'TRAP'
      && !heldItem.data?.wire;

    if (armsOnLanding && !this.canUseTrap()) { game.trapCharging = null; return; }

    const pos = this.getTrapReticulePos();
    game.trapCharging = null;
    if (!pos) return;

    const C = GRID.CELL_SIZE;
    const px = game.player.position.x + C / 2;
    const py = game.player.position.y + C / 2;
    const dx = pos.x - px, dy = pos.y - py;
    const dist = Math.sqrt(dx * dx + dy * dy) || 1;
    const v0 = Math.sqrt(2 * THROW_DECEL * dist);
    const profile = getThrowProfile(heldItem);

    const interior = isInteriorActive(game);

    if (throwsWireEnd) {
      // The wire itself stays in the quick slot — the player is paying out one end
      // of it, not letting go of the item. No damage, no arming: it flies until a
      // wall or its own decel stops it, then WireSystem anchors it there.
      const wireEnd = {
        kind: 'wire',
        x: px, y: py,
        vx: (dx / dist) * v0,
        vy: (dy / dist) * v0,
        decel: THROW_DECEL,
        targetX: pos.x, targetY: pos.y,
        char: heldItem.char,
        color: heldItem.color,
        plane: game.player.plane ?? 0,
        interior,
      };
      game.inFlightTraps.push(wireEnd);
      game.wireSystem?.onWireThrown(wireEnd);
    } else if (armsOnLanding) {
      game.inFlightTraps.push({
        kind: 'trap',
        x: px, y: py,
        vx: (dx / dist) * v0,
        vy: (dy / dist) * v0,
        decel: THROW_DECEL,
        targetX: pos.x, targetY: pos.y,
        char: heldItem.char,
        color: heldItem.color,
        trapData: heldItem.data,
        plane: game.player.plane ?? 0,
        interior,
      });
      this.markTrapUsed();
    } else if (heldItem.throwChargesRemaining > 0) {
      // Kunai: one from the bundle flies and the weapon stays in hand. `spent`
      // keeps it from landing as a pickup; the oils are snapshotted now.
      heldItem.throwChargesRemaining--;
      game.inFlightTraps.push({
        kind: 'weapon',
        x: px, y: py,
        vx: (dx / dist) * v0,
        vy: (dy / dist) * v0,
        decel: THROW_DECEL,
        targetX: pos.x, targetY: pos.y,
        char: heldItem.char,
        color: heldItem.color,
        rotation: 0,
        weaponItem: heldItem,
        spent: true,
        oilOnHits: equippedDaggerOils(game.player),
        profile,
        baseDamage: heldItem.data?.damage ?? 1,
        hitEnemies: new Set(),
        plane: game.player.plane ?? 0,
        inMaze: game.player.inMaze === true,
        interior,
      });
    } else {
      // Weapon throw: clear the active slot, item flies until it hits an enemy or stops
      const thrownItem = game.player.dropItem();
      if (!thrownItem) return;
      // Throwing the last weapon in the loadout lights the thrown-weapon
      // pointer (ThrownWeaponPointer.js) until the player is armed again.
      if (!playerHoldsWeapon(game.player)) game.thrownLastWeapon = true;
      // REST equipment slots draw glyphs to the background layer, which only
      // clears on a dirty mark — without this, the thrown item's glyph lingers
      // over the now-empty slot's number placeholder.
      game.renderer.markBackgroundDirty();
      // Directional glyphs (currently spear ↑) rotate to face throw direction.
      // ↑ points at -π/2 in canvas space, so add π/2 to the velocity angle.
      const subtype = thrownItem.data?.weaponSubtype;
      const rotation = subtype === 'spear' ? Math.atan2(dy, dx) + Math.PI / 2 : 0;
      game.inFlightTraps.push({
        kind: 'weapon',
        x: px, y: py,
        vx: (dx / dist) * v0,
        vy: (dy / dist) * v0,
        decel: THROW_DECEL,
        targetX: pos.x, targetY: pos.y,
        char: thrownItem.char,
        color: thrownItem.color,
        rotation,
        weaponItem: thrownItem,
        profile,
        baseDamage: thrownItem.data?.damage ?? 1,
        hitEnemies: new Set(),
        plane: game.player.plane ?? 0,
        inMaze: game.player.inMaze === true,
        interior,
      });
    }
    game.updateUI();
  }

  // Toss release: take the armed consumable from its slot and throw it as a
  // harmless projectile that lands as a ground pickup. Reuses the weapon-kind
  // flight so walls, deflection and the landing path behave identically —
  // _landThrownWeapon tags hutPlane, which is what makes staged goods persist
  // across floor swaps within a delve (dungeon-boss-green.md SHIFT Toss).
  _releaseTossThrow(charge) {
    const game = this.game;
    const player = game.player;
    const pos = this.getTrapReticulePos();
    game.trapCharging = null;
    if (!pos) return;
    const slotIndex = charge.source.slotIndex;
    const tossed = player.equippedConsumables?.[slotIndex];
    if (!tossed) return;

    // Stacked consumable (Bread, e.g.): tossing one loaf peels a single unit
    // off the stack — decrement in place and throw a fresh single-unit Item,
    // leaving the rest equipped. Mirrors InventorySystem._consumeOneShotSlot's
    // decrement for the heal path.
    let thrown = tossed;
    if (tossed.data?.stackable && (tossed.count || 1) > 1) {
      tossed.count -= 1;
      thrown = new Item(tossed.char, 0, 0);
    } else {
      // Clear the slot in both views (mirrors _consumeOneShotSlot's dual write)
      // and disarm the selection — the armed slot is empty now.
      player.equippedConsumables[slotIndex] = null;
      if (game.inventorySystem.equippedConsumables) {
        game.inventorySystem.equippedConsumables[slotIndex] = null;
      }
      player.selectedConsumableIndex = -1;
    }

    const C = GRID.CELL_SIZE;
    const px = player.position.x + C / 2;
    const py = player.position.y + C / 2;
    const dx = pos.x - px, dy = pos.y - py;
    const dist = Math.sqrt(dx * dx + dy * dy) || 1;
    const v0 = Math.sqrt(2 * THROW_DECEL * dist);
    const interior = isInteriorActive(game);
    game.inFlightTraps.push({
      kind: 'weapon',
      x: px, y: py,
      vx: (dx / dist) * v0,
      vy: (dy / dist) * v0,
      decel: THROW_DECEL,
      targetX: pos.x, targetY: pos.y,
      char: thrown.char,
      color: thrown.color,
      rotation: 0,
      weaponItem: thrown,
      harmless: true,   // remedies aren't weapons — fly through enemies, no hit checks
      profile: getThrowProfile(null),
      baseDamage: 0,
      hitEnemies: new Set(),
      plane: player.plane ?? 0,
      inMaze: player.inMaze === true,
      interior,
    });
    game.updateUI();
  }

  // Move in-flight throwables. Traps arm on stop; weapons hit enemies mid-flight then land as pickups.
  updateInFlightTraps(deltaTime) {
    const game = this.game;
    const C = GRID.CELL_SIZE;
    const playerInInterior = isInteriorActive(game);
    for (let i = game.inFlightTraps.length - 1; i >= 0; i--) {
      const t = game.inFlightTraps[i];
      if ((t.interior === true) !== playerInInterior) continue;
      const speed = Math.sqrt(t.vx * t.vx + t.vy * t.vy);
      const decelThisFrame = t.decel * deltaTime;
      // Thrown weapons and wire ends both stop dead at walls — a weapon would
      // otherwise land off-screen, and a wire end is meant to bite into the wall
      // it hits. Deployed traps still sail over and arm at the target.
      const stopsAtWalls = t.kind === 'weapon' || t.kind === 'wire';

      // Weapon mid-flight: enemy collision check against current position.
      // Harmless throws (Tossed consumables) skip it entirely — they sail
      // through enemies and just land.
      if (t.kind === 'weapon' && speed > 0 && !t.harmless) {
        this._checkThrownWeaponHit(t, speed);
        this._checkThrownWeaponSignalHit(t);
        this._checkThrownDaggerTargetHit(t);
        if (t.landed) {
          this._landThrownWeapon(t);
          game.inFlightTraps.splice(i, 1);
          continue;
        }
        // Deflector triangles bend the throw 90° (or U-turn off the legs).
        // Mirrors boulder/projectile redirection so the player learns one rule.
        this._tryThrownDeflect(t);
      }

      // Pinning spear carry: drag the carried enemy with the spear mid-flight
      if (t.carriedEnemy && !t.carriedEnemy.destroyed) {
        const enemy = t.carriedEnemy;

        if (this._spearHitsWall(t)) {
          // Spear embeds in wall — pin enemy at its current safe position (before drag into wall)
          enemy.pinnedDuration = 2.0;
          enemy.carriedBySpear = false;
          t.carriedEnemy = null;
          this._landThrownWeapon(t);
          game.inFlightTraps.splice(i, 1);
          continue;
        }

        enemy.position.x = t.x - C / 2;
        enemy.position.y = t.y - C / 2;
      }

      if (decelThisFrame >= speed) {
        const prevX = t.x, prevY = t.y;
        t.x = t.targetX;
        t.y = t.targetY;
        // Snap to target, but don't land weapons or wire ends inside walls
        if (stopsAtWalls && this._spearHitsWall(t)) {
          t.x = prevX;
          t.y = prevY;
        }
        // Spear stopped naturally — release carried enemy without pinning
        if (t.carriedEnemy) {
          t.carriedEnemy.carriedBySpear = false;
          t.carriedEnemy = null;
        }
        this._resolveLanding(t);
        game.inFlightTraps.splice(i, 1);
      } else {
        const prevX = t.x, prevY = t.y;
        const ratio = (speed - decelThisFrame) / speed;
        t.vx *= ratio;
        t.vy *= ratio;
        t.x += t.vx * deltaTime;
        t.y += t.vy * deltaTime;

        // Thrown weapons stop at walls instead of passing through and landing
        // off-screen; wire ends stop there because that wall is their anchor.
        if (stopsAtWalls && this._spearHitsWall(t)) {
          t.x = prevX;
          t.y = prevY;
          // Pinning spear: enemy is already at safe position from carry block drag — just release it
          if (t.carriedEnemy) {
            t.carriedEnemy.pinnedDuration = 2.0;
            t.carriedEnemy.carriedBySpear = false;
            t.carriedEnemy = null;
          }
          this._resolveLanding(t);
          game.inFlightTraps.splice(i, 1);
        }
      }
    }
  }

  // Dispatch a throwable that has come to rest: weapons drop as pickups, wire ends
  // anchor into the tripline being strung, traps arm where they land.
  _resolveLanding(t) {
    if (t.kind === 'weapon') this._landThrownWeapon(t);
    else if (t.kind === 'wire') this.game.wireSystem?.attachThrownEnd(t);
    else this._armTrap(t);
  }

  // Bend a thrown weapon off a deflector triangle by cell occupancy. Mirrors
  // CombatSystem's projectile path and BoulderSystem's lookup so all three
  // share one routing rule. Recomputes the trap's targetX/Y from the new
  // velocity so the natural decel→stop logic still lands the weapon correctly.
  _tryThrownDeflect(t) {
    if (t.interior === true) return false;          // interior throws aren't on the surface deflector grid
    const game = this.game;
    const bs = game.boulderSystem;
    if (!bs?.findDeflectorAt) return false;
    const deflector = bs.findDeflectorAt(t.x, t.y);
    if (!deflector) {
      if (t._lastDeflector) t._lastDeflector = null;
      return false;
    }
    if (t._lastDeflector === deflector) return false;
    const out = bs.deflectVelocity(deflector.data.deflectorElbow, t.vx, t.vy);
    if (!out) return false;
    const C = GRID.CELL_SIZE;
    const col = Math.floor(deflector.position.x / C);
    const row = Math.floor(deflector.position.y / C);
    t.x = col * C + C / 2;
    t.y = row * C + C / 2;
    t.vx = out.vx;
    t.vy = out.vy;
    // Linear decel → stop distance = v² / (2·decel). Repoint targetX/Y so the
    // throw will come to rest along the new heading instead of teleporting to
    // the original target on the final frame.
    const speed = Math.hypot(out.vx, out.vy);
    const stopDist = t.decel > 0 ? (speed * speed) / (2 * t.decel) : 0;
    t.targetX = t.x + (out.vx / speed) * stopDist;
    t.targetY = t.y + (out.vy / speed) * stopDist;
    t._lastDeflector = deflector;
    return true;
  }

  // Check if a spear's current position overlaps a room wall or solid background object.
  _spearHitsWall(t) {
    const game = this.game;
    const C = GRID.CELL_SIZE;
    // Pick the right collision source: interior throws hit the active floor's
    // walls/objects; surface throws hit the current room's.
    const interior = t.interior === true && game.activeFloor;
    const boundsW = interior ? game.activeFloor.gridCols * C : GRID.WIDTH;
    const boundsH = interior ? game.activeFloor.gridRows * C : GRID.HEIGHT;
    if (t.x < 0 || t.y < 0 || t.x >= boundsW || t.y >= boundsH) return true;
    const gridX = Math.floor(t.x / C);
    const gridY = Math.floor(t.y / C);
    const source = interior ? game.activeFloor : game.currentRoom;
    if (source?.collisionMap?.[gridY]?.[gridX]) return true;
    const bgObjs = source?.backgroundObjects;
    if (!bgObjs) return false;
    for (const obj of bgObjs) {
      if (obj.destroyed || !obj.data?.solid) continue;
      const box = obj.getHitbox();
      if (t.x >= box.x && t.x < box.x + box.width && t.y >= box.y && t.y < box.y + box.height) return true;
    }
    return false;
  }

  // Compute thrown-weapon damage from current velocity using the profile's threshold/cap/falloff.
  _thrownWeaponDamage(t, speed) {
    const { profile, baseDamage } = t;
    if (speed < profile.minVelForDamage) return 0;
    const range = Math.max(1, profile.maxDamageVel - profile.minVelForDamage);
    const t01 = Math.min(1, (speed - profile.minVelForDamage) / range);
    return Math.max(1, Math.round(baseDamage * profile.damageMult * t01));
  }

  /**
   * Strike any puzzleSignal fixture the flying weapon passes over. Enemies are
   * the only thing _checkThrownWeaponHit looks at, so without this a thrown
   * weapon sails straight through a switch — which is precisely the Barricade
   * that asks for a spear (the switch sits past every melee weapon's reach).
   *
   * Routed through takeDamage rather than by setting glitterHit directly: the
   * puzzleSignal short-circuit in there is the sanctioned contract, and it
   * keeps the fixture's HP and animation behaving the same for a thrown weapon
   * as for a swung one. A switch (kind 'switch') bounces the weapon back off
   * it (_bounceOffSwitch); every other puzzleSignal fixture is clipped and the
   * throw keeps flying.
   *
   * `t._lastSignal` is the fixture the weapon is still overlapping from last
   * frame, so one pass over a fixture reads as one strike (and one bounce)
   * rather than a strike every frame of the overlap.
   */
  _checkThrownWeaponSignalHit(t) {
    const game = this.game;
    const source = (t.interior === true && game.activeFloor) ? game.activeFloor : game.currentRoom;
    const objs = source?.backgroundObjects;
    if (!objs) return;
    const hitR = GRID.CELL_SIZE * 0.75;
    let overlapping = null;
    for (const obj of objs) {
      if (obj.destroyed || !obj.puzzleSignal) continue;
      const cx = obj.position.x + GRID.CELL_SIZE / 2;
      const cy = obj.position.y + GRID.CELL_SIZE / 2;
      const dx = cx - t.x, dy = cy - t.y;
      if (dx * dx + dy * dy > hitR * hitR) continue;
      overlapping = obj;
      if (t._lastSignal === obj) continue;
      obj.takeDamage(t.baseDamage || 1);
      if (obj.kind === 'switch') this._bounceOffSwitch(t, cx, cy);
      break;
    }
    t._lastSignal = overlapping;
  }

  /**
   * A thrown dagger counts as a shot against a Barricade Target. The Target's
   * `shotOnly` gate turns away everything but a gun's bullet or a bow's arrow,
   * and since Targets are solid, _spearHitsWall would otherwise stop the
   * dagger dead at the block. Here a flying dagger breaks the block it
   * reaches (passing `shot` the way handleBulletCollision does) and drops
   * where it struck: one dagger, one block.
   */
  _checkThrownDaggerTargetHit(t) {
    if (t.landed || t.weaponItem?.data?.weaponSubtype !== 'dagger') return;
    const game = this.game;
    const source = (t.interior === true && game.activeFloor) ? game.activeFloor : game.currentRoom;
    const objs = source?.backgroundObjects;
    if (!objs) return;
    for (const obj of objs) {
      if (obj.destroyed || !obj.data?.shotOnly) continue;
      const box = obj.getHitbox();
      if (t.x < box.x || t.x >= box.x + box.width || t.y < box.y || t.y >= box.y + box.height) continue;
      obj.takeDamage(1, false, { shot: true });
      t.landed = true;
      return;
    }
  }

  // Reflect a thrown weapon off a struck switch. The switch is treated as a
  // cell-sized block: whichever axis the weapon is further off-center along is
  // the face it struck, and only the velocity component heading into that face
  // flips. The rebound keeps SWITCH_BOUNCE_RESTITUTION of its speed, and
  // targetX/Y is repointed (as in _tryThrownDeflect) so the natural
  // decel→stop logic lands it along the new heading.
  _bounceOffSwitch(t, cx, cy) {
    const offX = t.x - cx, offY = t.y - cy;
    if (Math.abs(offX) >= Math.abs(offY)) {
      if (t.vx * offX < 0 || offX === 0) t.vx = -t.vx;
    } else if (t.vy * offY < 0) {
      t.vy = -t.vy;
    }
    t.vx *= SWITCH_BOUNCE_RESTITUTION;
    t.vy *= SWITCH_BOUNCE_RESTITUTION;
    const speed = Math.hypot(t.vx, t.vy);
    if (speed <= 0) return;
    const stopDist = t.decel > 0 ? (speed * speed) / (2 * t.decel) : 0;
    t.targetX = t.x + (t.vx / speed) * stopDist;
    t.targetY = t.y + (t.vy / speed) * stopDist;
  }

  // Detect enemy collision for a flying weapon. Marks t.landed on hit.
  _checkThrownWeaponHit(t, speed) {
    const game = this.game;
    const enemies = this._getActiveEnemies();
    if (!enemies.length) return;
    const C = GRID.CELL_SIZE;
    const hitR = C * 0.75;
    const playerPlane = t.plane ?? 0;
    for (const enemy of enemies) {
      if (!enemy || enemy.hp <= 0) continue;
      if ((enemy.plane ?? 0) !== playerPlane) continue;
      if (t.hitEnemies.has(enemy)) continue;
      const ex = enemy.position.x + C / 2;
      const ey = enemy.position.y + C / 2;
      const dx = ex - t.x;
      const dy = ey - t.y;
      if (dx * dx + dy * dy > hitR * hitR) continue;

      const dmg = this._thrownWeaponDamage(t, speed);
      if (dmg > 0) {
        enemy.takeDamage(dmg);
        game.combatSystem?.createDamageNumber?.(dmg, enemy.position.x, enemy.position.y, t.color || '#ffffff');
      }
      t.hitEnemies.add(enemy);
      if (t.oilOnHits?.length) applyExtraOnHitEffects(game.combatSystem, enemy, t.oilOnHits, t.color);

      // Pinning spear (Trident only): carry the enemy with the spear instead of landing immediately
      if (t.weaponItem?.data?.pinning) {
        t.carriedEnemy = enemy;
        enemy.carriedBySpear = true;
        return;
      }

      // All other spears root the hit enemy in place on impact — no carry, just pin.
      if (t.weaponItem?.data?.weaponSubtype === 'spear') {
        enemy.pinnedDuration = 2.0;
      }

      t.landed = true; // spear/non-spear alike stop on first enemy hit
      t.x = ex;
      t.y = ey;
      return;
    }
  }

  // Drop the thrown weapon as a floor pickup at its current position.
  _landThrownWeapon(t) {
    const game = this.game;
    const C = GRID.CELL_SIZE;
    const item = t.weaponItem;
    if (!item) return;
    // A Kunai from the bundle is gone once it lands; the weapon never left hand.
    if (t.spent) return;
    // Let FountainSystem intercept throws aimed at the pool
    if (game.fountainSystem?.checkWeaponLanding(t)) return;
    if (item.data?.throwBurst) this._throwBurst(t, item.data.throwBurst);
    item.position.x = t.x - C / 2;
    item.position.y = t.y - C / 2;
    item.velocity = { vx: 0, vy: 0 };
    item.pickupReadyAt = performance.now() + 600;
    item.plane = t.plane ?? 0;
    // Absolute (not additive) — an item that was picked up inside a hut keeps
    // hutPlane=true on its inventory entry, so re-throwing it on the surface
    // would otherwise carry the stale flag and confuse plane-aware scans
    // (e.g. surface rats ignoring SHIFT-thrown bread that was originally a
    // hut loaf).
    // hutPlane is the shared interior-floor tag (every Interior but the Maze
    // renders off game.activeFloor via the same overlay + hutPlane item filter),
    // so a weapon landing on any floor must carry it — otherwise it reads as
    // surface loot and the interior overlay never draws it.
    item.hutPlane = t.interior === true && t.inMaze !== true;
    item.mazePlane = t.inMaze === true;
    game.items.push(item);
    game.physicsSystem.addEntity(item);
  }

  // A thrown weapon with `throwBurst` (Icicle) bursts where it lands: every
  // enemy on its plane within `radius` takes the status at full pips (the
  // Freeze Trap's straight-to-Frozen hit). The weapon itself still lands.
  _throwBurst(t, burst) {
    const game = this.game;
    const C = GRID.CELL_SIZE;
    const plane = t.plane ?? 0;
    if (burst.onHit === 'freeze') {
      for (const p of createIceBurst(t.x, t.y)) game.particles.push(tagInteriorPlane(game, p));
    }
    for (const enemy of game._activeEnemies()) {
      if (planeOf(enemy) !== plane) continue;
      const dx = (enemy.position.x + C / 2) - t.x;
      const dy = (enemy.position.y + C / 2) - t.y;
      if (Math.sqrt(dx * dx + dy * dy) > burst.radius) continue;
      if (!enemy.shouldApplyStatusEffect?.(burst.onHit)) continue;
      enemy.applyStatusEffect(burst.onHit, burst.duration ?? 3, MAX_PIPS);
    }
  }

  // Place trap entity at landing position and emit burst particles.
  _armTrap(t) {
    const game = this.game;
    const C = GRID.CELL_SIZE;
    // The Lightning Rod lands as a real Lightning Spire on the active layer,
    // not a trap entry — every spire rule (catch, charge) applies to it as-is.
    if (t.trapData.placesLightningSpire) {
      const spire = createLightningSpire(t.x - C / 2, t.y - C / 2);
      spire.plane = t.plane;
      game._activeBackgroundObjects().push(spire);
      game.renderer?.markBackgroundDirty();
      for (const p of createActivationBurst(t.x, t.y, t.trapData.color || '#ffffff')) game.particles.push(tagInteriorPlane(game, p));
      return;
    }
    const placedTrapItem = new Item(t.char, t.x - C / 2, t.y - C / 2);
    placedTrapItem.isPlaced = true;
    placedTrapItem.plane = t.plane;
    const entry = {
      item: placedTrapItem,
      tickTimer: t.trapData.tickInterval || 0,
      activeDuration: t.trapData.activeDuration != null ? t.trapData.activeDuration : Infinity,
      affectedEnemies: new Set(),
      interior: t.interior === true,
      electricTriggered: false, // set by triggerElectricAt, resolved in checkElectricTriggers
    };
    if (t.trapData.remoteTrigger) {
      entry.blinkTimer = 0;
      entry.blinkVisible = true;
    }
    game.placedTraps.push(entry);
    for (const p of createActivationBurst(t.x, t.y, t.trapData.color || '#ffffff')) game.particles.push(tagInteriorPlane(game, p));
  }

  // Place a trap at an arbitrary world position (used by Trap Goblin enemy).
  // type: 'slow' → Slime Bomb (◉), 'fire' → Fire Trap (^)
  placeTrapAtPosition(x, y, type, plane = 0, owner = null) {
    const game = this.game;
    const char = TRAP_TYPE_CHAR[type] || '◉';

    const trapItem = new Item(char, x - GRID.CELL_SIZE / 2, y - GRID.CELL_SIZE / 2);
    trapItem.isPlaced = true;
    trapItem.plane = plane;

    game.placedTraps.push({
      item: trapItem,
      owner,
      tickTimer: trapItem.data?.tickInterval || 0,
      activeDuration: trapItem.data?.activeDuration != null ? trapItem.data.activeDuration : Infinity,
      affectedEnemies: new Set(),
      fuseTimer: 0,
      spawnedAt: performance.now(),
      // Same layer tag as a player-armed trap (_armTrap): a goblin on a hut or
      // dungeon floor lays its trap on that floor, not the surface.
      interior: isInteriorActive(game),
      electricTriggered: false, // set by triggerElectricAt, resolved in checkElectricTriggers
    });
  }

  // Delegates to the canonical game accessor (single source of truth).
  _getActiveEnemies() {
    return this.game._activeEnemies();
  }

  // True while an enemy-placed trap is still within its post-spawn grace
  // window — checked by every trigger path (proximity, melee, projectile)
  // so nothing can set it off in the instant it lands. The timed fuse
  // (TRAP_FUSE_TOTAL, far beyond this window) is unaffected — that's a
  // forced detonation, not a trigger.
  _isSpawnImmune(entry) {
    return entry.spawnedAt != null && performance.now() - entry.spawnedAt < TRAP_SPAWN_IMMUNITY_MS;
  }

  // Apply a trap hit to one enemy, respecting `trapData.affinity`. Affinity uses the
  // canonical elemental taxonomy (ice, fire, electric, goo, venom, …) — same namespace
  // as `enemy.affinities` and AFFINITY_POOLS. An enemy whose affinities include the
  // trap's affinity is IMMUNE: no damage, no status, IMMUNE floater shown. Traps with
  // no affinity (sleep, charm) always land. Damage <= 0 skips the damage step.
  _applyTrapHit(enemy, trapData, damage, color) {
    const game = this.game;
    const affinity = trapData.affinity;
    if (affinity && enemy.data?.affinities?.includes(affinity)) {
      game.combatSystem?.createDamageNumber?.('IMMUNE', enemy.position.x, enemy.position.y, '#cccccc');
      return false;
    }
    if (damage > 0) {
      enemy.takeDamage(damage);
      game.combatSystem?.createDamageNumber?.(damage, enemy.position.x, enemy.position.y, color);
    }
    return true;
  }

  updatePlacedTraps(deltaTime) {
    const game = this.game;
    if (!game.currentRoom) return;
    const enemies = this._getActiveEnemies();
    game.activeNoiseSource = null; // reset each frame
    const playerInInterior = isInteriorActive(game);

    for (let i = game.placedTraps.length - 1; i >= 0; i--) {
      const entry = game.placedTraps[i];
      if ((entry.interior === true) !== playerInInterior) continue;
      const { item } = entry;
      const trapData = item.data;
      const tx = item.position.x;
      const ty = item.position.y;

      // Remote bomb blink
      if (trapData.remoteTrigger) {
        entry.blinkTimer = (entry.blinkTimer || 0) + deltaTime;
        if (entry.blinkTimer >= 0.4) {
          entry.blinkTimer -= 0.4;
          entry.blinkVisible = !entry.blinkVisible;
        }
        continue; // Remote traps are only triggered by player, not by proximity
      }

      // Timed fuse — only enemy-placed traps carry one (entry.owner set by
      // placeTrapAtPosition; player-thrown traps never get a fuseTimer field).
      if (entry.fuseTimer != null) {
        entry.fuseTimer += deltaTime;
        if (entry.fuseTimer >= TRAP_FUSE_TOTAL) {
          this._fireOneShotTrap(entry, i, enemies);
          continue;
        }
        if (entry.fuseTimer >= TRAP_FUSE_IDLE) {
          entry.blinkTimer = (entry.blinkTimer || 0) + deltaTime;
          if (entry.blinkTimer >= TRAP_FUSE_BLINK_INTERVAL) {
            entry.blinkTimer -= TRAP_FUSE_BLINK_INTERVAL;
            entry.blinkVisible = !entry.blinkVisible;
          }
        }
      }

      if (trapData.oneShot) {
        // One-shot trap: triggered by enemy or player proximity (owner is immune).
        // The spawn grace only delays the trigger — it must never route a
        // one-shot into the persistent branch below, where a Stun Trap's
        // 'zap' effect would pulse as a Tesla Coil on its own placer.
        const armed = !this._isSpawnImmune(entry);
        let triggered = false;
        for (const enemy of (armed ? enemies : [])) {
          if (enemy === entry.owner) continue;
          const dx = enemy.position.x - tx;
          const dy = enemy.position.y - ty;
          if (Math.sqrt(dx * dx + dy * dy) <= trapData.triggerRadius) {
            triggered = true;
            break;
          }
        }
        // Player can also trigger traps by walking near them
        if (armed && !triggered && game.player && !trapData.remoteTrigger) {
          const pdx = (game.player.position.x + GRID.CELL_SIZE / 2) - (tx + GRID.CELL_SIZE / 2);
          const pdy = (game.player.position.y + GRID.CELL_SIZE / 2) - (ty + GRID.CELL_SIZE / 2);
          if (Math.sqrt(pdx * pdx + pdy * pdy) <= trapData.triggerRadius) {
            triggered = true;
          }
        }

        if (triggered) {
          this._fireOneShotTrap(entry, i, enemies);
        }
      } else {
        // Persistent placeable
        const effect = trapData.effect;

        if (effect === 'noise') {
          // Noise-maker: redirect enemies toward self; destroyed on enemy contact
          game.activeNoiseSource = { x: tx, y: ty, radius: trapData.effectRadius };
          // Destroy on enemy overlap (< 16 px)
          let destroyed = false;
          for (const enemy of enemies) {
            const dx = enemy.position.x - tx;
            const dy = enemy.position.y - ty;
            if (Math.sqrt(dx * dx + dy * dy) < 16) {
              destroyed = true;
              break;
            }
          }
          if (destroyed) {
            game.placedTraps.splice(i, 1);
          }

        } else if (effect === 'sleep') {
          // Music Box: apply sleep to enemies that enter radius while active. No affinity
          // (sleep has no elemental class) — every enemy is a valid target.
          // It plays for activeDuration seconds, then it is gone.
          entry.activeDuration -= deltaTime;
          if (entry.activeDuration <= 0) {
            game.placedTraps.splice(i, 1);
          } else {
            for (const enemy of enemies) {
              const dx = enemy.position.x - tx;
              const dy = enemy.position.y - ty;
              if (Math.sqrt(dx * dx + dy * dy) <= trapData.effectRadius) {
                if (!entry.affectedEnemies.has(enemy)) {
                  entry.affectedEnemies.add(enemy);
                  // Full Pip track: a single drowsy pip only slows; the box's
                  // promise is sleep, so it lands at pip 3 (AI halted).
                  enemy.applyStatusEffect('sleep', trapData.effectDuration, MAX_PIPS);
                }
              } else {
                // Enemy left radius — allow re-triggering if they re-enter
                entry.affectedEnemies.delete(enemy);
              }
            }
          }

        } else if (effect === 'zap') {
          // Tesla Coil: damage + zap every tickInterval seconds — each pulse is
          // full-strength current, so it lands at zap pip 3 (lock + disarm).
          // Electric-affinity enemies are IMMUNE (handled by _applyTrapHit + affinity gate).
          entry.tickTimer -= deltaTime;
          if (entry.tickTimer <= 0) {
            entry.tickTimer = trapData.tickInterval;
            // Each pulse is an electric source: it sets off other traps in its radius.
            this.triggerElectricAt(tx + GRID.CELL_SIZE / 2, ty + GRID.CELL_SIZE / 2, trapData.effectRadius, item.plane ?? 0);
            const zapDmg = trapData.damage || 2;
            for (const enemy of enemies) {
              const dx = enemy.position.x - tx;
              const dy = enemy.position.y - ty;
              if (Math.sqrt(dx * dx + dy * dy) > trapData.effectRadius) continue;
              if (!this._applyTrapHit(enemy, trapData, zapDmg, '#00ffff')) continue;
              enemy.applyStatusEffect('zap', trapData.stunDuration || 0.8, MAX_PIPS);
              // Lightning particle
              game.particles.push(tagInteriorPlane(game, {
                x: tx,
                y: ty,
                vx: (Math.random() - 0.5) * 60,
                vy: (Math.random() - 0.5) * 60,
                life: 0.3,
                maxLife: 0.3,
                char: '!',
                color: '#00ffff',
                isImpact: true
              }));
            }
          }

        }
      }
    }
  }

  // Fire a one-shot trap's effect and remove it from placedTraps.
  // Called by both proximity-trigger (updatePlacedTraps) and weapon-trigger (checkWeaponTriggers).
  _fireOneShotTrap(entry, index, enemies) {
    const game = this.game;
    const { item } = entry;
    const trapData = item.data;
    const tx = item.position.x;
    const ty = item.position.y;
    const cx = tx + GRID.CELL_SIZE / 2;
    const cy = ty + GRID.CELL_SIZE / 2;
    const r = trapData.effectRadius;
    // However this trap fires — proximity, weapon, or the timed fuse — it
    // never hurts the enemy that placed it. The proximity-trigger path
    // (updatePlacedTraps) already exempts entry.owner; every loop below does
    // the same so the exemption holds regardless of firing path.
    const targets = entry.owner ? enemies.filter((e) => e !== entry.owner) : enemies;

    if (trapData.effect === 'slow') {
      // Slime Bomb: blast deals 1+ damage and applies goo to enemies in radius. Slime-immune
      // enemies are filtered by _applyTrapHit via trapData.affinity='slime' (shows IMMUNE).
      const slowDmg = trapData.damage || 1;
      for (const enemy of targets) {
        const dx = (enemy.position.x + GRID.CELL_SIZE / 2) - cx;
        const dy = (enemy.position.y + GRID.CELL_SIZE / 2) - cy;
        if (Math.sqrt(dx * dx + dy * dy) > r) continue;
        if (!this._applyTrapHit(enemy, trapData, slowDmg, '#00ff00')) continue;
        enemy.applyStatusEffect('goo', 5.0);
      }
      if (game.player) {
        const pdx = (game.player.position.x + GRID.CELL_SIZE / 2) - cx;
        const pdy = (game.player.position.y + GRID.CELL_SIZE / 2) - cy;
        if (Math.sqrt(pdx * pdx + pdy * pdy) <= r) {
          game.player.applyStatusEffect?.('goo', 5.0);
        }
      }
      // Bursts like a slime dying: 8 goo blobs, one per compass direction, each
      // sliding out past the blast and laying slime trail behind it. Not an
      // explosive — no shake or smoke (createExplosionAftermath).
      const plane = item.plane ?? 0;
      game._dropSlimeTrail(cx, cy, plane);
      createGooBurst(game, cx, cy, { count: 8, reach: r * 1.5, plane });
      game.audioSystem?.playSFX('goo_hit');
    } else if (trapData.effect === 'freeze') {
      // Freeze Trap: damage + freeze enemies + freeze water/puddle tiles + scatter ice objects.
      // freezePermanent enemies (slimes) lock at Infinity duration and never thaw; other ice-weak
      // enemies (freeze >1.0) also get Infinity. Everyone else uses effectDuration. The trap is
      // an all-at-once hit: straight to freeze pip 3 (Frozen — full immobilization, not just
      // slow), matching the player-side trap below. Freeze-immune enemies are filtered by
      // _applyTrapHit via trapData.affinity='freeze'.
      for (const p of createIceBurst(cx, cy)) game.particles.push(tagInteriorPlane(game, p));
      const freezeDmg = trapData.damage || 1;
      for (const enemy of targets) {
        const dx = (enemy.position.x + GRID.CELL_SIZE / 2) - cx;
        const dy = (enemy.position.y + GRID.CELL_SIZE / 2) - cy;
        if (Math.sqrt(dx * dx + dy * dy) > r) continue;
        if (!this._applyTrapHit(enemy, trapData, freezeDmg, '#aaffff')) continue;
        const isIceWeak = enemy.getElementalModifier('freeze') > 1.0;
        const duration = (enemy.data.freezePermanent || isIceWeak) ? Infinity : trapData.effectDuration;
        enemy.applyStatusEffect('freeze', duration, 3); // straight to Frozen
      }

      const C = GRID.CELL_SIZE;
      // Active layer — ice tiles must land in the hut/dungeon the trap fired in, not the surface.
      const room = game.activeRoom;
      if (room?.backgroundObjects) {
        // Structural/special chars that shouldn't be visually frozen
        const SKIP_FREEZE = new Set(['!', '$', '.', '-', 'I', '<', '>', '^', 'v', '≡', '∩', '5', '3', '}', 'x']);
        const newObjects = [];

        for (const obj of room.backgroundObjects) {
          if (obj.destroyed) continue;
          const odx = (obj.position.x + C / 2) - cx;
          const ody = (obj.position.y + C / 2) - cy;
          if (Math.sqrt(odx * odx + ody * ody) > r) continue;

          if (obj.char === '=') {
            // Standing water → replace with frozen water tile
            obj.destroyed = true;
            const frozenWater = new BackgroundObject('~', obj.position.x, obj.position.y);
            frozenWater.setWaterState('frozen', Infinity);
            newObjects.push(frozenWater);
          } else if (obj.char === '~') {
            // Puddle → freeze in place
            obj.setWaterState('frozen', Infinity);
          } else if (!SKIP_FREEZE.has(obj.char)) {
            // Trees, bushes, rocks, crates, etc. → tint ice-blue and flag so the
            // cut-grass handler can produce an ice-burst on slicing frozen grass.
            obj.color = '#aaffff';
            obj.frozen = true;
          }
        }

        room.backgroundObjects.push(...newObjects);

        // Build occupancy set so scattered frozen water doesn't stack on existing objects
        const occupied = new Set(
          room.backgroundObjects
            .filter(o => !o.destroyed)
            .map(o => `${Math.floor(o.position.x / C)},${Math.floor(o.position.y / C)}`)
        );

        // Scatter frozen water tiles across open cells within radius (~30% density, max 14)
        const radiusCells = Math.ceil(r / C);
        const centerCol = Math.floor(cx / C);
        const centerRow = Math.floor(cy / C);
        let placed = 0;
        for (let dr = -radiusCells; dr <= radiusCells && placed < 14; dr++) {
          for (let dc = -radiusCells; dc <= radiusCells && placed < 14; dc++) {
            const ox = (centerCol + dc) * C + C / 2 - cx;
            const oy = (centerRow + dr) * C + C / 2 - cy;
            if (Math.sqrt(ox * ox + oy * oy) > r) continue;
            if (Math.random() > 0.30) continue;
            const key = `${centerCol + dc},${centerRow + dr}`;
            if (occupied.has(key)) continue;
            const frozenTile = new BackgroundObject('~', (centerCol + dc) * C, (centerRow + dr) * C);
            frozenTile.setWaterState('frozen', Infinity);
            room.backgroundObjects.push(frozenTile);
            occupied.add(key);
            placed++;
          }
        }
      }

      // Radial ice particle burst
      const iceColors = ['#aaffff', '#00ddff', '#ffffff'];
      const iceChars = ['*', '+', 'o', '.'];
      for (let i = 0; i < 18; i++) {
        const angle = (Math.PI * 2 * i) / 18 + (Math.random() - 0.5) * 0.3;
        const speed = 70 + Math.random() * 80;
        game.particles.push(tagInteriorPlane(game, {
          x: cx, y: cy,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          life: 0.5 + Math.random() * 0.35,
          maxLife: 0.85,
          char: iceChars[Math.floor(Math.random() * iceChars.length)],
          color: iceColors[Math.floor(Math.random() * iceColors.length)],
          isImpact: true
        }));
      }
    } else if (trapData.effect === 'remote') {
      // Remote Bomb: radial explosion damage + fire particles (friendly fire). Pure
      // concussive damage — no affinity gate, so fire-affinity enemies still take it.
      // The burn status follows but is also unconditional (lore: shrapnel ignites).
      const dmg = trapData.damage || 6;
      for (const enemy of targets) {
        const dx = (enemy.position.x + GRID.CELL_SIZE / 2) - cx;
        const dy = (enemy.position.y + GRID.CELL_SIZE / 2) - cy;
        if (Math.sqrt(dx * dx + dy * dy) <= r) {
          enemy.takeDamage(dmg);
          enemy.applyStatusEffect('burn', 3.0);
          game.combatSystem.createDamageNumber(dmg, enemy.position.x, enemy.position.y, '#ff6600');
        }
      }
      // Player takes damage if within blast radius
      if (game.player) {
        const pdx = (game.player.position.x + GRID.CELL_SIZE / 2) - cx;
        const pdy = (game.player.position.y + GRID.CELL_SIZE / 2) - cy;
        if (Math.sqrt(pdx * pdx + pdy * pdy) <= r) {
          const result = game.player.takeDamage(dmg, { type: 'explosion', cause: { name: trapData.name, char: trapData.char, color: trapData.color } });
          game.combatSystem.createDamageNumber(dmg, game.player.position.x, game.player.position.y, '#ff6600');
          game.physicsSystem.applyDamageKnockback(game.player, result, cx, cy, 300);
        }
      }
      // Radial fire particle burst
      const fireColors = ['#ff6600', '#ff4400', '#ffaa00', '#ffffff'];
      for (let i = 0; i < 24; i++) {
        const angle = (Math.PI * 2 * i) / 24 + (Math.random() - 0.5) * 0.4;
        const speed = 80 + Math.random() * 120;
        game.particles.push(tagInteriorPlane(game, {
          x: cx, y: cy,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          life: 0.4 + Math.random() * 0.4,
          maxLife: 0.8,
          char: ['*', '!', '+', '.'][Math.floor(Math.random() * 4)],
          color: fireColors[Math.floor(Math.random() * fireColors.length)],
          isImpact: true
        }));
      }
      createExplosionAftermath(game, cx, cy, { shake: 9, shakeDuration: 0.45, smoke: 14, spread: r * 0.5 });
      // A bomb is the only thing that opens a Bombable Rock (Cavern entrance).
      game.cavernSystem.bombBlast(cx, cy, r);
    } else if (trapData.effect === 'snare') {
      // Snare Trap: a beast-affinity enemy caught in the radius is rooted in place
      // permanently (reuses the Trident-pin immobilizer). Non-beasts walk through it
      // untouched — this is a hunter's snare, not a blast. No damage; the catch is the point.
      let caught = false;
      for (const enemy of targets) {
        const dx = (enemy.position.x + GRID.CELL_SIZE / 2) - cx;
        const dy = (enemy.position.y + GRID.CELL_SIZE / 2) - cy;
        if (Math.sqrt(dx * dx + dy * dy) > r) continue;
        if (!enemy.data?.affinities?.includes('beast')) continue;
        enemy.pinnedDuration = Infinity;
        enemy.velocity.vx = 0;
        enemy.velocity.vy = 0;
        caught = true;
        game.combatSystem.createDamageNumber('SNARED', enemy.position.x, enemy.position.y, '#8b6914');
      }
      // Wild crows are beast-adjacent fauna but never routed through `targets`
      // (they're not Enemy instances — see game.currentRoom.crows) — catch
      // them here instead. CompanionSystem.snareCrow roots the caught crow
      // and enrages the rest of the room's flock into dive-bombing the player.
      const roomCrows = game.currentRoom?.crows || [];
      for (const crow of roomCrows) {
        if (crow.snared) continue;
        const dx = (crow.position.x + GRID.CELL_SIZE / 2) - cx;
        const dy = (crow.position.y + GRID.CELL_SIZE / 2) - cy;
        if (Math.sqrt(dx * dx + dy * dy) > r) continue;
        game.companionSystem?.snareCrow(crow);
        caught = true;
        game.combatSystem.createDamageNumber('SNARED', crow.position.x, crow.position.y, '#8b6914');
        break; // one crow per trap trigger
      }
      if (!caught) {
        // Snapped shut on nothing it could hold — still consume the charge.
      }
    } else {
      // All other one-shot effects (burn, stun, sleep, charm): _applyTrapHit gates on affinity
      // (fire-immune enemies block the Fire Trap, electric-immune block Stun, etc.) — then
      // damage + status follow. Damage runs before the status so a sleep trap doesn't get
      // cleared the moment it's applied (Enemy.takeDamage clears already-active sleep).
      const effectDmg = trapData.damage || 1;
      const dmgColor = trapData.color || '#ffffff';

      // The Stun Trap's burst is an electric source: it sets off other traps in its radius.
      if (trapData.effect === 'zap') this.triggerElectricAt(cx, cy, r, item.plane ?? 0);

      // Fire Trap also ignites flammable bg objects in radius — environmental, not per-enemy.
      // Routed through FireSystem (owns spread + render dirty flag).
      const burnObjects = game._activeBackgroundObjects();
      if (trapData.effect === 'burn' && burnObjects) {
        for (const obj of burnObjects) {
          if (obj.destroyed || !obj.isFlammable) continue;
          const odx = obj.position.x - tx;
          const ody = obj.position.y - ty;
          if (Math.sqrt(odx * odx + ody * ody) <= r && obj.isFlammable()) {
            if (game.fireSystem) game.fireSystem.igniteObject(obj, 5.0);
            else obj.ignite(5.0);
          }
        }
      }

      for (const enemy of targets) {
        const dx = enemy.position.x - tx;
        const dy = enemy.position.y - ty;
        if (Math.sqrt(dx * dx + dy * dy) > r) continue;
        if (!this._applyTrapHit(enemy, trapData, effectDmg, dmgColor)) continue;
        // The Stun Trap's burst is an all-at-once hit: straight to zap pip 3
        // (lock + disarm), the way the Freeze Trap goes straight to Frozen.
        const pips = trapData.effect === 'zap' ? MAX_PIPS : null;
        enemy.applyStatusEffect(trapData.effect, trapData.effectDuration, pips);
      }
      if (game.player) {
        const pdx = (game.player.position.x + GRID.CELL_SIZE / 2) - cx;
        const pdy = (game.player.position.y + GRID.CELL_SIZE / 2) - cy;
        if (Math.sqrt(pdx * pdx + pdy * pdy) <= r) {
          if (trapData.effect === 'burn') {
            game.player.applyStatusEffect?.('burn', trapData.effectDuration);
          } else if (trapData.effect === 'freeze') {
            game.player.applyStatusEffect?.('freeze', trapData.effectDuration, 3); // straight to Frozen
          } else if (trapData.effect === 'zap') {
            game.player.applyStatusEffect?.('zap', trapData.effectDuration, MAX_PIPS); // lock + disarm
          }
        }
      }
    }

    // Burst particle effect at trap location
    if (trapData.effect === 'burn') {
      for (const p of createEmberBurst(cx, cy)) game.particles.push(tagInteriorPlane(game, p));
    } else {
      for (const p of createActivationBurst(cx, cy, trapData.color || '#ffffff')) game.particles.push(tagInteriorPlane(game, p));
    }
    game.placedTraps.splice(index, 1);
  }

  // Detonate all placed remote bombs. Called on SPACE press when remote bombs exist.
  detonateRemoteBombs() {
    const game = this.game;
    if (!game.currentRoom) return false;
    const enemies = this._getActiveEnemies();
    let detonated = false;
    for (let i = game.placedTraps.length - 1; i >= 0; i--) {
      const entry = game.placedTraps[i];
      if (entry.item.data.remoteTrigger) {
        this._fireOneShotTrap(entry, i, enemies);
        detonated = true;
      }
    }
    return detonated;
  }

  // Check if any player melee attack or projectile hits a placed one-shot trap and fires it.
  checkWeaponTriggers() {
    const game = this.game;
    if (!game.placedTraps.length || !game.combatSystem || !game.currentRoom) return;
    const enemies = this._getActiveEnemies();
    const C = GRID.CELL_SIZE;

    for (let i = game.placedTraps.length - 1; i >= 0; i--) {
      const entry = game.placedTraps[i];
      const trapData = entry.item.data;
      if (!trapData.oneShot) continue; // Only throwable one-shots can be weapon-detonated
      if (this._isSpawnImmune(entry)) continue;

      const tx = entry.item.position.x + C / 2;
      const ty = entry.item.position.y + C / 2;
      const hitR = C; // trap hitbox
      let hit = false;

      // Melee attacks
      for (const attack of game.combatSystem.meleeAttacks) {
        const atkR = (attack.radius || C) + hitR;
        const dx = tx - attack.position.x;
        const dy = ty - attack.position.y;
        if (dx * dx + dy * dy <= atkR * atkR) { hit = true; break; }
      }

      // Projectiles (any player bullet or arrow)
      if (!hit) {
        for (const proj of game.combatSystem.projectiles) {
          const dx = tx - proj.position.x;
          const dy = ty - proj.position.y;
          if (dx * dx + dy * dy <= hitR * hitR) { hit = true; break; }
        }
      }

      if (hit) this._fireOneShotTrap(entry, i, enemies);
    }
  }

  // ── Electric trigger ─────────────────────────────────────────────────────
  // Electricity sets off placed traps, the same way a weapon hit does. Two
  // kinds of source, both resolved in checkElectricTriggers:
  //   - Standing current, asked of ElectricitySystem.isLiveAt: electrified
  //     water or slime trail under the trap, or a charged object (lightning
  //     rod spire, charged metal) touching it.
  //   - Momentary bursts, marked by triggerElectricAt: a lightning strike, a
  //     Tesla Coil pulse, a Stun Trap going off. Marking (not firing on the
  //     spot) keeps the burst from splicing placedTraps under an iteration
  //     already in progress — updatePlacedTraps and _fireOneShotTrap both call
  //     it mid-loop — and lets one Stun Trap chain into the next a frame later.

  // Every one-shot trap is electric-triggerable except an electric trap
  // itself (Stun Trap): it IS the current, so current doesn't set it off.
  // Persistent placeables (Music Box, Noise-maker, Tesla Coil) have no
  // detonation to set off. The Remote Bomb IS triggerable — current reaching
  // it is the one way it goes off without the player's signal.
  _isElectricTriggerable(trapData) {
    return !!trapData.oneShot && !!trapData.effect && trapData.affinity !== 'electric';
  }

  /**
   * A momentary electric burst at (x, y) with `radius` px on `plane`: marks
   * every electric-triggerable trap of the active layer inside it to fire on
   * the next checkElectricTriggers pass.
   */
  triggerElectricAt(x, y, radius, plane = 0) {
    const game = this.game;
    const playerInInterior = isInteriorActive(game);
    const C = GRID.CELL_SIZE;
    for (const entry of game.placedTraps) {
      if ((entry.interior === true) !== playerInInterior) continue;
      if ((entry.item.plane ?? 0) !== plane) continue;
      if (!this._isElectricTriggerable(entry.item.data) || this._isSpawnImmune(entry)) continue;
      const dx = entry.item.position.x + C / 2 - x;
      const dy = entry.item.position.y + C / 2 - y;
      if (dx * dx + dy * dy <= radius * radius) entry.electricTriggered = true;
    }
  }

  // Fire every trap of the active layer that a burst marked or that sits in
  // live current. EXPLORE-only (see the rest-parity note at the call site).
  checkElectricTriggers() {
    const game = this.game;
    if (!game.placedTraps.length || !game.currentRoom) return;
    const electricity = game.electricitySystem;
    const enemies = this._getActiveEnemies();
    const playerInInterior = isInteriorActive(game);
    const C = GRID.CELL_SIZE;

    for (let i = game.placedTraps.length - 1; i >= 0; i--) {
      const entry = game.placedTraps[i];
      if ((entry.interior === true) !== playerInInterior) continue;
      const trapData = entry.item.data;
      if (!this._isElectricTriggerable(trapData) || this._isSpawnImmune(entry)) continue;
      const tx = entry.item.position.x + C / 2;
      const ty = entry.item.position.y + C / 2;
      const live = entry.electricTriggered ||
        !!electricity?.isLiveAt(tx, ty, entry.item.plane ?? 0);
      entry.electricTriggered = false;
      if (live) this._fireOneShotTrap(entry, i, enemies);
    }
  }

  // Apply per-frame effects for all active puddles based on their type.
  updatePuddles(deltaTime) {
    const game = this.game;
    if (!game.puddles?.length || !game.player) return;
    const playerPlane = game.player.plane ?? 0;
    // Bodies standing on any lava stamp this frame — collected so overlapping
    // stamps still burn each body once (LavaContact runs its own 1s tick).
    const onLava = new Set();

    for (let i = game.puddles.length - 1; i >= 0; i--) {
      const puddle = game.puddles[i];

      // Tick down lifetime for temporary puddles
      if (puddle.lifetime !== undefined) {
        puddle.lifetime -= deltaTime;
        if (puddle.lifetime <= 0) {
          puddle.expired = true;
          game.puddles.splice(i, 1);
          continue;
        }
      }

      if ((puddle.plane ?? 0) !== playerPlane) continue;

      switch (puddle.type) {
        case 'fire': this._applyFirePuddle(puddle, playerPlane); break;
        case 'ice':  this._applyIcePuddle(puddle, playerPlane);  break;
        case 'lava': this._collectLavaPuddle(puddle, playerPlane, onLava); break;
        // slimeTrail contact effects are applied in main.js (see updateExploreState).
        // Future types added here
      }
    }

    // A lava stamp (fire-imbued Giant Slime trail) is exactly a lava tile.
    // A lethal tick drops player hp to 0, which the explore death check catches.
    const lavaDamage = BACKGROUND_OBJECT_VARIANTS.lava.damage;
    for (const body of onLava) applyLavaContact(game, body, lavaDamage, deltaTime);
  }

  _collectLavaPuddle(puddle, playerPlane, onLava) {
    const game = this.game;
    // Fire armor (the player's fire affinity) walks a lava trail unharmed, the
    // way it ignores a fire puddle. Enemy fire affinity is LavaContact's check.
    if (!game.player.fireImmune && puddle.isEntityOnPuddle(game.player)) onLava.add(game.player);
    for (const enemy of (game.currentRoom?.enemies ?? [])) {
      if ((enemy.plane ?? 0) !== playerPlane) continue;
      if (puddle.isEntityOnPuddle(enemy)) onLava.add(enemy);
    }
  }

  _applyFirePuddle(puddle, playerPlane) {
    const game = this.game;
    // Refresh past the player's 1.5s burn tick rate so a tick actually fires
    // before it expires.
    if (puddle.isEntityOnPuddle(game.player) && !game.player.fireImmune) {
      game.player.applyStatusEffect?.('burn', 2.0);
    }
    for (const enemy of (game.currentRoom?.enemies ?? [])) {
      if ((enemy.plane ?? 0) !== playerPlane) continue;
      if (!puddle.isEntityOnPuddle(enemy)) continue;
      if (enemy.shouldApplyStatusEffect?.('burn')) {
        enemy.applyStatusEffect('burn', 3.0);
      }
    }
  }

  _applyIcePuddle(puddle, playerPlane) {
    const game = this.game;
    if (puddle.isEntityOnPuddle(game.player)) {
      // Ice patches slow the player. Player has no 'slow' status — `freeze` is
      // the slow-bearing key. Refresh each frame so movement resumes shortly
      // after stepping off; held at pip 1 (a level, not +1 per frame) so
      // standing on ice chills but never stacks up to Frozen.
      game.player.applyStatusEffect?.('freeze', 0.3, 1);
    }
    for (const enemy of (game.currentRoom?.enemies ?? [])) {
      if ((enemy.plane ?? 0) !== playerPlane) continue;
      if (!puddle.isEntityOnPuddle(enemy)) continue;
      // Same as the player: held at pip 1, never stacking up to Frozen.
      if (enemy.shouldApplyStatusEffect?.('freeze')) {
        enemy.applyStatusEffect('freeze', 0.5, 1);
      }
    }
  }

}
