import { GRID } from '../game/GameConfig.js';
import { inSamePlane, planeOf, objectOnPlane } from '../systems/PlaneSystem.js';
import { LavaShyMechanic } from './enemyMechanics/LavaShyMechanic.js';

// Every question an Enemy asks about what it can see, in one place.
//
// Three ray-casts against the collision map: whether a straight line is clear,
// where it is first blocked, and whether a target is visible given the enemy's
// facing cone. All three are geometry — they read the enemy's position, facing
// and collisionMap and return an answer. None of them changes state, moves
// anything, or spawns.
//
// Moved out of Enemy.js unchanged, for the same reason enemyMovement.js was: a
// ray-cast against a grid is not enemy behavior, and keeping it in the entity
// made the entity the place everything adjacent to it accumulated. Enemy keeps
// three one-line methods so the ~30 `this.hasVision(...)` call sites are
// untouched.
// Establishes an Enemy's sense thresholds from its data block, at construction.
//
// Vision length and cone width were hardcoded for every Enemy in the game until
// 2026-09-06 — one number nobody could author, which meant a slow brute and a
// hawk saw exactly the same distance. Aggro range came with it because the two
// are one decision: vision is the outer sense, aggro the commitment threshold
// inside it, and they have an invariant to keep between them.
export function initSenses(enemy) {
  const data = enemy.data;
  enemy.aggroRange = data.aggroRange || GRID.CELL_SIZE * 8;

  // The default is `max(8 cells, aggroRange)` rather than a flat 8 so that
  // vision is never shorter than aggro. 35 of the shipped 57 Enemies carry an
  // aggroRange past 8 cells, so a flat default would have quietly cut their
  // reach the moment the invariant below landed.
  enemy.visionLength = data.visionLength ?? Math.max(GRID.CELL_SIZE * 8, enemy.aggroRange);
  // Half-angle of the facing cone, in degrees — 65 is what every Enemy used
  // before this was authorable. 180 is a full sphere of awareness.
  enemy.visionHalfAngle = data.visionHalfAngle ?? 65;
  // Cached because `hasVision` compares against it per ray-cast, per frame.
  enemy.visionHalfAngleCos = Math.cos(enemy.visionHalfAngle * Math.PI / 180);

  // Invariant: an Enemy can never aggro onto something it cannot see that far.
  // An aggroRange past visionLength describes a band the Enemy reacts in but is
  // blind in, which is not a behavior anything should author by accident.
  // Authored vision wins; the aggro range yields.
  if (enemy.aggroRange > enemy.visionLength) enemy.aggroRange = enemy.visionLength;

  // Vector length for pathfinding probes around walls.
  enemy.navigationLength = GRID.CELL_SIZE * 6;

  // What it remembers seeing. A memory mark is the position sight last put the
  // target at, so it belongs with the sense that wrote it: every field here is
  // read back by the Search/Flee states as a stand-in for vision it no longer
  // has.
  enemy.lastKnownPosition = null; // Last known player position
  enemy.aggroMemoryActive = false; // Whether pursuing a memory mark
  enemy.memoryMarkSuspected = false; // true = heard/felt (investigating); false = confirmed sighting
  enemy.memoryMoveDelayTimer = 0; // Delay before moving to memory mark after losing sight
  enemy.memoryMoveDelay = 1.0; // 1 second delay before chasing memory
  enemy.memoryChaseTimer = 0; // Countdown while actively chasing memory mark; gives up at 0
  enemy.detectionIndicatorTimer = 0; // Show yellow ! when detecting/reacquiring player
  enemy.detectionIndicatorDuration = 1.0; // Show detection indicator for 1 second
  enemy.hadVisualContact = false; // Set true on first real sighting; gates proximity-only re-aggro
  enemy.memoryMarkPlane = 0;  // Plane player was on when memory mark was created
  enemy.memoryStaleTimer = 2.0; // Countdown (sec) before a cross-plane-stale mark expires
}

/**
 * Check if there's a clear line of sight along a vector
 * Uses ray casting to detect collisions
 */
export function hasLineOfSight(enemy, start, end, maxLength) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const distance = Math.sqrt(dx * dx + dy * dy);
  if (distance === 0) return true;
  const checkDist = Math.min(distance, maxLength);

  const nx = dx / distance;
  const ny = dy / distance;
  const C = GRID.CELL_SIZE;

  // DDA grid traversal — steps to every grid-line crossing so no cell is skipped,
  // including the diagonal-corner case where uniform sampling misses wall corners.
  let gx = Math.floor(start.x / C);
  let gy = Math.floor(start.y / C);

  const stepX = nx >= 0 ? 1 : -1;
  const stepY = ny >= 0 ? 1 : -1;

  // Distance along the ray to the first vertical / horizontal boundary
  const firstBoundX = nx >= 0 ? (gx + 1) * C : gx * C;
  const firstBoundY = ny >= 0 ? (gy + 1) * C : gy * C;
  let tMaxX = nx !== 0 ? Math.abs((firstBoundX - start.x) / nx) : Infinity;
  let tMaxY = ny !== 0 ? Math.abs((firstBoundY - start.y) / ny) : Infinity;
  const tDeltaX = nx !== 0 ? Math.abs(C / nx) : Infinity;
  const tDeltaY = ny !== 0 ? Math.abs(C / ny) : Infinity;

  // Use actual collision map dimensions so this works for both the 30×30 room grid
  // and smaller interior grids (e.g. 10×10 hut, 24×24 dungeon).
  const mapRows = enemy.collisionMap.length;
  const mapCols = enemy.collisionMap[0]?.length ?? GRID.COLS;

  // Lava-Shy enemies path around lava as if it were wall. The start cell is
  // exempt so one already standing in lava can still route its way out.
  const lavaShy = LavaShyMechanic.isEnabled(enemy);
  const startGx = gx, startGy = gy;
  const isLava = (cx, cy) => lavaShy && (cx !== startGx || cy !== startGy)
    && LavaShyMechanic.isLavaCell(enemy, cx, cy);

  // Check each cell the ray enters until checkDist is reached
  for (let safety = 0; safety < 128; safety++) {
    if (gx < 0 || gx >= mapCols || gy < 0 || gy >= mapRows) return false;
    if (enemy.collisionMap[gy][gx]) return false;
    if (isLava(gx, gy)) return false;

    const tNext = Math.min(tMaxX, tMaxY);
    if (tNext >= checkDist) break; // Reached the end without hitting anything

    const EPS = 1e-6;
    if (Math.abs(tMaxX - tMaxY) < EPS) {
      // Exact corner: ray hits two cell boundaries simultaneously.
      // Check all three newly entered cells to avoid the diagonal-corner miss.
      const cx = gx + stepX, cy = gy + stepY;
      if (cx < 0 || cx >= mapCols || cy < 0 || cy >= mapRows) return false;
      // Cross cell
      if (cy < 0 || cy >= mapRows || cx >= 0 && cx < mapCols && enemy.collisionMap[gy][cx]) return false;
      if (cx < 0 || cx >= mapCols || cy >= 0 && cy < mapRows && enemy.collisionMap[cy][gx]) return false;
      if (isLava(cx, gy) || isLava(gx, cy)) return false;
      tMaxX += tDeltaX;
      tMaxY += tDeltaY;
      gx = cx;
      gy = cy;
    } else if (tMaxX < tMaxY) {
      tMaxX += tDeltaX;
      gx += stepX;
    } else {
      tMaxY += tDeltaY;
      gy += stepY;
    }
  }

  return true;
}

/**
 * Find where line of sight is blocked (for visualization)
 * Returns the point where vision is obstructed, or the end point if clear
 */
export function getVisionObstructionPoint(enemy, start, end, maxLength) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const distance = Math.sqrt(dx * dx + dy * dy);
  if (distance === 0) return { x: end.x, y: end.y, blocked: false };
  const checkDist = Math.min(distance, maxLength);

  // Too far to see — return point at vision limit
  if (distance > maxLength) {
    const angle = Math.atan2(dy, dx);
    return {
      x: start.x + Math.cos(angle) * maxLength,
      y: start.y + Math.sin(angle) * maxLength,
      blocked: true
    };
  }

  // DDA traversal (same as hasLineOfSight) for accurate obstruction point.
  const nx = dx / distance;
  const ny = dy / distance;
  const C = GRID.CELL_SIZE;

  let gx = Math.floor(start.x / C);
  let gy = Math.floor(start.y / C);
  const stepX = nx >= 0 ? 1 : -1;
  const stepY = ny >= 0 ? 1 : -1;

  const firstBoundX = nx >= 0 ? (gx + 1) * C : gx * C;
  const firstBoundY = ny >= 0 ? (gy + 1) * C : gy * C;
  let tMaxX = nx !== 0 ? Math.abs((firstBoundX - start.x) / nx) : Infinity;
  let tMaxY = ny !== 0 ? Math.abs((firstBoundY - start.y) / ny) : Infinity;
  const tDeltaX = nx !== 0 ? Math.abs(C / nx) : Infinity;
  const tDeltaY = ny !== 0 ? Math.abs(C / ny) : Infinity;

  const mapRows = enemy.collisionMap ? enemy.collisionMap.length : GRID.ROWS;
  const mapCols = enemy.collisionMap?.[0]?.length ?? GRID.COLS;
  const isBlocked = (cgx, cgy) => {
    // Use actual collision-map dimensions so interior maps (24×24, 10×10) bound correctly.
    if (cgx < 0 || cgx >= mapCols || cgy < 0 || cgy >= mapRows) return true;
    if (enemy.collisionMap && enemy.collisionMap[cgy][cgx]) return true;
    if (enemy.backgroundObjects) {
      const myPlane = planeOf(enemy);
      for (const obj of enemy.backgroundObjects) {
        if (obj.destroyed) continue;
        if (!objectOnPlane(obj, myPlane)) continue;
        if (Math.floor(obj.position.x / C) === cgx && Math.floor(obj.position.y / C) === cgy) {
          if (obj.bulletInteraction === 'block' ||
              obj.bulletInteraction === 'interact-preserve' ||
              obj.bulletInteraction === 'interact-destroy') return true;
        }
      }
    }
    return false;
  };

  for (let safety = 0; safety < 128; safety++) {
    if (isBlocked(gx, gy)) {
      return { x: start.x + nx * Math.min(tMaxX, tMaxY), y: start.y + ny * Math.min(tMaxX, tMaxY), blocked: true };
    }

    const tNext = Math.min(tMaxX, tMaxY);
    if (tNext >= checkDist) break;

    const EPS = 1e-6;
    if (Math.abs(tMaxX - tMaxY) < EPS) {
      const cx = gx + stepX, cy = gy + stepY;
      if (isBlocked(cx, gy)) return { x: start.x + nx * tMaxX, y: start.y + ny * tMaxX, blocked: true };
      if (isBlocked(gx, cy)) return { x: start.x + nx * tMaxY, y: start.y + ny * tMaxY, blocked: true };
      tMaxX += tDeltaX; tMaxY += tDeltaY;
      gx = cx; gy = cy;
    } else if (tMaxX < tMaxY) {
      tMaxX += tDeltaX; gx += stepX;
    } else {
      tMaxY += tDeltaY; gy += stepY;
    }
  }

  return { x: end.x, y: end.y, blocked: false };
}

// Whether a single sampled point along a ray is obstructed by terrain — solid
// walls (collisionMap) or a vision-blocking background object (trees/solid
// props outright via bulletInteraction; tall grass only within its close-range
// rule). Shared by `hasVision` (which layers the facing cone, range cap and
// target-specific gates on top) and `hasVisionBarrier` (the bare geometry
// question, asked between two arbitrary points that aren't necessarily the
// enemy's target).
// Per-frame cell index of a background-object list, so a ray sample only
// tests the objects that could possibly answer for its cell instead of every
// object in the room. A grass-dense room holds ~1,700 objects; with several
// enemies each casting multi-sample rays every frame, the linear scan was the
// whole cost of the frame (measured 2026-10-22: G room, 16ms of enemy update,
// nearly all of it here).
//
// Each object is filed under every cell its own grid square or its grass
// hitbox (the ±quarter-cell box below) touches, and the per-object test in
// obstructsPoint runs unchanged on that short list — so the answer is the same
// as the full scan. Objects move (Push Rocks slide) and lists grow, so the
// index is rebuilt whenever the frame stamp or the list length changes;
// `beginVisionFrame()` advances the stamp once per enemy tick.
let visionFrame = 0;
const cellIndexCache = new WeakMap();
const CELL_KEY_STRIDE = 4096;

export function beginVisionFrame() {
  visionFrame++;
}

function cellIndexFor(objects) {
  const cached = cellIndexCache.get(objects);
  if (cached && cached.frame === visionFrame && cached.length === objects.length) {
    return cached.cells;
  }
  const C = GRID.CELL_SIZE;
  const halfExtent = C * 0.25;
  const cells = new Map();
  const file = (gx, gy, obj) => {
    const key = gy * CELL_KEY_STRIDE + gx;
    const list = cells.get(key);
    if (list) {
      if (list[list.length - 1] !== obj) list.push(obj);
    } else {
      cells.set(key, [obj]);
    }
  };
  for (const obj of objects) {
    if (obj.destroyed) continue;
    const cx = obj.position.x + C / 2;
    const cy = obj.position.y + C / 2;
    const x0 = Math.min(Math.floor(obj.position.x / C), Math.floor((cx - halfExtent) / C));
    const x1 = Math.max(Math.floor(obj.position.x / C), Math.floor((cx + halfExtent) / C));
    const y0 = Math.min(Math.floor(obj.position.y / C), Math.floor((cy - halfExtent) / C));
    const y1 = Math.max(Math.floor(obj.position.y / C), Math.floor((cy + halfExtent) / C));
    for (let gy = y0; gy <= y1; gy++) {
      for (let gx = x0; gx <= x1; gx++) file(gx, gy, obj);
    }
  }
  cellIndexCache.set(objects, { frame: visionFrame, length: objects.length, cells });
  return cells;
}

function obstructsPoint(enemy, checkX, checkY, gridX, gridY, distanceFromStart) {
  const mapRows = enemy.collisionMap ? enemy.collisionMap.length : GRID.ROWS;
  const mapCols = enemy.collisionMap?.[0]?.length ?? GRID.COLS;
  if (gridX < 0 || gridX >= mapCols || gridY < 0 || gridY >= mapRows) return true;
  if (enemy.collisionMap && enemy.collisionMap[gridY][gridX]) return true;

  if (enemy.backgroundObjects) {
    const myPlane = planeOf(enemy);
    const candidates = cellIndexFor(enemy.backgroundObjects).get(gridY * CELL_KEY_STRIDE + gridX);
    if (!candidates) return false;
    for (const obj of candidates) {
      if (obj.destroyed) continue;
      // Skip objects not present on this enemy's plane (e.g. surfaceOnly when underground).
      if (!objectOnPlane(obj, myPlane)) continue;

      // Vision-blockers (grass) use a half-cell × half-cell pixel hitbox
      // centered on the grass so dense swaths form a real visual barrier
      // rather than a sparse 1-cell-aligned check.
      const blocksV = obj.blocksVision && obj.blocksVision();
      if (blocksV) {
        const halfExtent = GRID.CELL_SIZE * 0.25;
        const cx = obj.position.x + GRID.CELL_SIZE / 2;
        const cy = obj.position.y + GRID.CELL_SIZE / 2;
        if (Math.abs(checkX - cx) <= halfExtent &&
            Math.abs(checkY - cy) <= halfExtent) {
          // Grass doesn't block vision at close range — enemy can sense nearby player.
          // 3-cell threshold: you can't hide from something standing right next to you.
          if (distanceFromStart > GRID.CELL_SIZE * 3) return true;
        }
      }

      const objGridX = Math.floor(obj.position.x / GRID.CELL_SIZE);
      const objGridY = Math.floor(obj.position.y / GRID.CELL_SIZE);
      if (objGridX === gridX && objGridY === gridY) {
        if (obj.bulletInteraction === 'block' ||
            obj.bulletInteraction === 'interact-preserve') {
          return true; // Solid object blocks vision
        }
      }
    }
  }

  return false;
}

/**
 * Check if enemy can see the target (vision check)
 * More restrictive than hasLineOfSight - includes background objects
 * Used for aggro/memory system, NOT navigation
 * PLANE-AWARE: Returns false if target is in different plane
 */
export function hasVision(enemy, start, end, maxLength, { ignoreCone = false } = {}) {
  // Cyan rogue hide roll — target is undetectable
  if (enemy.target && enemy.target.hidden) {
    return false;
  }

  // Moss Cloak 𐤒 — non-aggro enemies cannot see the player at any range.
  // `enraged` alone gates this, not `aggroMemoryActive`: Search sets the
  // latter on proximity alone (alert.js's "door two" needs no sight at all
  // to arm it), so treating it as aggro let a merely-searching enemy spot a
  // cloaked player through the cloak the instant it got in range. `enraged`
  // is the codebase's real aggro flag — set only by taking a hit, waking
  // from Dormant, or an always-hostile Mechanic — so only a genuinely
  // engaged enemy sees through the cloak; a searching one stays blind no
  // matter how close it gets.
  if (enemy.target && enemy.target.mossCloakActive && !enemy.enraged) {
    return false;
  }

  // CRITICAL: Check if target is in same plane
  // If target has a position property, it's likely the player object
  if (enemy.target && !inSamePlane(enemy, enemy.target)) {
    return false;
  }

  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const distance = Math.sqrt(dx * dx + dy * dy);
  const checkDistance = Math.min(distance, maxLength);

  // Too far to see
  if (distance > maxLength) {
    return false;
  }

  // ── Vision cone gate ────────────────────────────────────────────────────
  // Non-alerted enemies can only see within ±`visionHalfAngle`° of their facing
  // direction (65° unless the Enemy authors otherwise).
  // Alerted enemies (enraged or memory-chasing) have already turned toward the
  // player via velocity, so their cone naturally tracks. ignoreCone bypasses
  // this for sound-based detection (omnidirectional hearing).
  if (!enemy.enraged && !enemy.aggroMemoryActive && !ignoreCone) {
    // Per-Enemy since 2026-09-06 (`data.visionHalfAngle`, cached as a cosine on
    // the Enemy). The `??` fallback covers callers that are not Enemies — the
    // boss part entities (TurtleHead, GooHead, Hoardmaw) build their own stat
    // blocks and never run Enemy's constructor.
    const HALF_CONE_COS = enemy.visionHalfAngleCos ?? Math.cos(65 * Math.PI / 180); // ~0.423 at 65°
    const PROXIMITY_OVERRIDE = GRID.CELL_SIZE * 1.5;    // Knife-edge: bypass cone
    if (distance > PROXIMITY_OVERRIDE) {
      const dot = (dx / distance) * Math.cos(enemy.facingAngle)
                + (dy / distance) * Math.sin(enemy.facingAngle);
      if (dot < HALF_CONE_COS) return false;
    }
  }

  // Sample points along the vector
  const samples = Math.ceil(checkDistance / (GRID.CELL_SIZE / 2));

  for (let i = 1; i <= samples; i++) {
    const t = i / samples;
    const checkX = start.x + dx * t;
    const checkY = start.y + dy * t;

    // Convert to grid coordinates
    const gridX = Math.floor(checkX / GRID.CELL_SIZE);
    const gridY = Math.floor(checkY / GRID.CELL_SIZE);

    // Check if out of bounds, walls, and background objects (trees, boulders,
    // tall grass, etc.) — use the actual collision map dimensions so dungeon/hut
    // interiors (24×24, 10×10) bound correctly instead of falling through to
    // GRID.COLS/ROWS and hitting undefined cells (which evaluate falsy and
    // silently skip the wall check).
    if (obstructsPoint(enemy, checkX, checkY, gridX, gridY, distance)) {
      return false;
    }

    // Check steam clouds (block vision through steam)
    if (enemy.steamClouds) {
      for (const cloud of enemy.steamClouds) {
        const sdx = checkX - cloud.x, sdy = checkY - cloud.y;
        if (sdx * sdx + sdy * sdy <= cloud.radius * cloud.radius) {
          return false;
        }
      }
    }
  }

  return true; // Clear vision
}

/**
 * Whether terrain — a wall, or a vision-blocking background object (trees and
 * other solid props outright; tall grass within its close-range rule) — sits
 * anywhere between two arbitrary points. The pure geometry question, with none
 * of `hasVision`'s facing cone, range-as-visibility, or target-specific gates
 * (hidden/mossCloak/plane): those all describe whether the enemy has *noticed*
 * something, which doesn't apply when the two points aren't the enemy and its
 * target — e.g. Flee's wall-seeking scan, asking whether a candidate heading
 * would put cover between the mark and the enemy.
 */
export function hasVisionBarrier(enemy, start, end, maxLength) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const distance = Math.sqrt(dx * dx + dy * dy);
  if (distance === 0) return false;
  const checkDistance = Math.min(distance, maxLength);

  const samples = Math.ceil(checkDistance / (GRID.CELL_SIZE / 2));
  for (let i = 1; i <= samples; i++) {
    const t = i / samples;
    const checkX = start.x + dx * t;
    const checkY = start.y + dy * t;
    const gridX = Math.floor(checkX / GRID.CELL_SIZE);
    const gridY = Math.floor(checkY / GRID.CELL_SIZE);
    if (obstructsPoint(enemy, checkX, checkY, gridX, gridY, distance)) return true;
  }

  return false;
}

// States where the target is already acquired, not merely being noticed.
const IN_COMBAT_STATES = ['approach', 'anticipate', 'strike', 'recover'];

/**
 * The spine's `canSee` — same ray-cast as `hasVision`, except the facing cone
 * only applies before contact is made.
 *
 * Approach through Recover already have the target — the facing cone is a
 * detection concept for an enemy deciding whether it has noticed you
 * (Alert/Dormant), not one for maintaining contact once it has. Gating canSee
 * on it during combat was feeding Approach and Search into each other every
 * frame: Approach clears aggroMemoryActive the instant it sees the target,
 * which re-arms the cone; velocity-derived facingAngle lags a tight turn and
 * fails that cone on the very next frame; the failure reads as lost sight and
 * hands off to Search, which grants cone-free vision via aggroMemoryActive and
 * hands straight back — one flip per frame, forever.
 */
export function spineCanSee(enemy, currentState, targetPos, maxLength) {
  const ignoreCone = IN_COMBAT_STATES.includes(currentState);
  return hasVision(enemy, enemy.position, targetPos, maxLength, { ignoreCone });
}

/**
 * Whether the target is standing in tall grass thick enough to hide in.
 *
 * Concealment is a vision question, not a terrain one — it is the only reason an
 * enemy with a clear line and an in-range target still fails to notice it — so it
 * belongs beside the ray-casts rather than beside the enemy's own footing checks.
 */
export function isTargetInTallGrass(enemy) {
  if (!enemy.target || !enemy.backgroundObjects) return false;
  const cs = GRID.CELL_SIZE;
  const px = Math.floor(enemy.target.position.x / cs);
  const py = Math.floor(enemy.target.position.y / cs);
  // RoomGenerator emits two '|' BackgroundObjects per visual blade, so we
  // count raw instances in target's cell + 4 cardinal neighbours. ≥ 6
  // means ~3 visual blades, matching the renderer's concealment rule so
  // idle proximity detection lines up with what the player can see.
  let onCell = 0;
  let nearby = 0;
  for (const obj of enemy.backgroundObjects) {
    if (obj.destroyed || obj.char !== '|') continue;
    const ox = Math.floor(obj.position.x / cs);
    const oy = Math.floor(obj.position.y / cs);
    const dx = Math.abs(ox - px);
    const dy = Math.abs(oy - py);
    if (dx === 0 && dy === 0) onCell++;
    if (dx + dy <= 1) nearby++;
  }
  return onCell > 0 && nearby >= 6;
}
