import { EXIT_LETTERS, SECRET_PATTERNS } from '../data/exitLetters.js';
import { LETTER_TEMPLATES } from '../data/letterTemplates.js';
import { ZONES, ZONE_COLORS } from '../data/zones.js';
import { GRID } from '../game/GameConfig.js';
import { isInteriorActive } from './PlaneSystem.js';

// Letters whose weights get boosted when the player has the well-vested luck
// blessing. V (Vault), ? (Mystery), C (Camp) — all desirable stops that make
// luck feel like it's reshaping the run, not just fattening the loot table.
const LUCKY_BOOST = { 'V': 2.5, '?': 2.0, 'C': 1.5 };

// Green is the starting zone — it always dangles an alternative-color exit to
// teach the player that color = destination. Every other zone tempts more
// rarely: only SOMETIMES does an un-progressed room offer a way out of the
// current color, so staying put feels like the default rather than a refusal.
const ALT_EXIT_CHANCE_NON_GREEN = 0.5;

// A zone change (its first alt-color exit) is only offered every this many
// depths — L3, L6, L9 — matching the enemy difficulty steps. Completed zones,
// the post-Goo-Dragon rule, forced zones (Ridge north, gray) and warps don't
// go through this check.
const ZONE_CHANGE_DEPTH_STEP = 3;
function offersZoneChangeAt(depth) {
  return depth > 0 && depth % ZONE_CHANGE_DEPTH_STEP === 0;
}

// A Dungeon ('D') exit is only offered from rooms on the same L3/L6/L9 beat,
// and from L6 on that beat guarantees one. The Compass's 3-follow streak
// (CompassSystem) and letter sequences (B-A-D, G-O-O-D) place a 'D'
// directly and are deliberately exempt — they are earned, not rolled.
const DUNGEON_DEPTH_STEP = 3;
const DUNGEON_GUARANTEED_DEPTH = 6;

// A Settlement 'S' is offered at least once in every this many exit sets.
const SETTLEMENT_MAX_GAP = 5;
function offersDungeonAt(depth) {
  return depth > 0 && depth % DUNGEON_DEPTH_STEP === 0;
}

// Exit slots are ordered [north, east, west] everywhere in this file. Some
// letter templates close one of those slots during room generation (Ocean's
// wall of water eats the east exit — RoomGenerator.generateOceanTerrain reads
// the same exitRules and overwrites room.exits.east with false), which happens
// AFTER this file has already handed out letters and colors. Anything picked
// at random here has to skip those slots, or it lands on an exit the player
// will never be able to walk through.
const EXIT_RULE_SLOT = { disableNorth: 0, disableEast: 1, disableWest: 2 };

// Reverse lookup: which zone does an exit color represent? Colors are unique
// per zone in ZONE_COLORS, so this is safe both ways.
function zoneForColor(color) {
  return Object.keys(ZONE_COLORS).find(z => ZONE_COLORS[z] === color) ?? null;
}

// SECRET_PATTERNS' `sequence.offerSteps` may be authored as a single class
// word (shorthand for "every non-head step shares this class") instead of an
// explicit per-step array. Expand it here so callers only ever deal with the
// array form. tools/check-data.js normalizes the same way for validation.
export function normalizeOfferSteps(offerSteps, stepCount) {
  if (typeof offerSteps === 'string') return Array(stepCount).fill(offerSteps);
  return offerSteps;
}

function closedSlotsForLetter(currentLetter) {
  const rules = currentLetter ? LETTER_TEMPLATES[currentLetter]?.exitRules : null;
  if (!rules) return new Set();
  return new Set(
    Object.entries(EXIT_RULE_SLOT).filter(([rule]) => rules[rule]).map(([, slot]) => slot)
  );
}

// Random slot index that isn't going to be closed by the room's own template.
// Falls back to a plain random pick if every slot is closed (no template does
// that today, and a room with no exits at all has bigger problems).
function randomOpenSlot(closedSlots) {
  const open = [0, 1, 2].filter(i => !closedSlots.has(i));
  if (open.length === 0) return Math.floor(Math.random() * 3);
  return open[Math.floor(Math.random() * open.length)];
}

// Walks the alphabet forward from `currentLetter`, returning the first letter
// that is a defined entry in EXIT_LETTERS. Wraps A→...→Z→A. Non-alphabet
// inputs (e.g. '?') start the search from before 'A'. Used by the
// Sword of the Letter to cycle exit destinations on hit.
export function cycleExitLetter(currentLetter) {
  const startCode = /^[A-Z]$/.test(currentLetter) ? currentLetter.charCodeAt(0) : 64;
  for (let i = 1; i <= 26; i++) {
    const next = String.fromCharCode(((startCode - 65 + i) % 26) + 65);
    if (EXIT_LETTERS[next]) return next;
  }
  return currentLetter;
}

// Fixed progression order for the Chromablade's color cycle — the same
// green/yellow/red/cyan reading order as the zone danger ramp. Gray and blue
// are deliberately excluded: they're reached by dedicated mechanics (mist,
// the pearl offering), not by walking a color trail, so the blade only ever
// cycles among the four colors a path of consecutive same-color exits can
// actually resolve to (see ZoneSystem.peekZoneTransition).
const CHROMA_CYCLE = [ZONE_COLORS.green, ZONE_COLORS.yellow, ZONE_COLORS.red, ZONE_COLORS.cyan];

// Walks CHROMA_CYCLE forward from `currentColor`, wrapping around. An
// unrecognized input (gray, blue, a fairy-dusted pink) starts the cycle over
// at green rather than erroring. Used by the Chromablade — the Sword of the
// Letter's companion weapon — to cycle an exit's COLOR instead of its letter,
// which retargets the zone that exit's color-matching streak will resolve to
// (ZoneSystem.recordExit reads exit.color, not exit.letter).
export function cycleExitColor(currentColor) {
  const idx = CHROMA_CYCLE.indexOf(currentColor);
  return CHROMA_CYCLE[(idx + 1) % CHROMA_CYCLE.length];
}

// ── Exit-letter mutation surface ──────────────────────────────────────────────
// Single source of truth for exit letter slot positions and mutations. Used by
// the Sword of the Letter (cycles letters on hit) and the Fairy fountain
// (fairies dust an exit, mutating its letter to 'F'). Any future mechanic that
// rewrites exit letters at runtime should go through mutateExitLetter so the
// renderer (and future systems) can react to mutations via exit.mutationSource.

export const EXIT_SLOT_POSITIONS = {
  north: { col: Math.floor(GRID.COLS / 2), row: 1 },
  east:  { col: GRID.COLS - 2,             row: Math.floor(GRID.ROWS / 2) },
  west:  { col: 1,                         row: Math.floor(GRID.ROWS / 2) },
  south: { col: Math.floor(GRID.COLS / 2), row: GRID.ROWS - 2 }
};

export function getExitSlotPosition(direction) {
  return EXIT_SLOT_POSITIONS[direction] || null;
}

/**
 * Is this cell an exit letter's own tile? The letter is the only thing the room
 * says about where that way out leads, so the tile is restricted: nothing the
 * world stamps by grid coordinate may land on it and cover the signage up. A
 * layout that wants the lane works around the tile rather than over it (see
 * BarricadeSystem.laneCells, which notches its footprint here).
 *
 * All four slots are tested rather than the one a caller has in hand — the rule
 * belongs to the tile, not to whichever lane happens to be reaching for it.
 */
export function isExitLetterTile(col, row) {
  for (const slot of Object.values(EXIT_SLOT_POSITIONS)) {
    if (slot.col === col && slot.row === row) return true;
  }
  return false;
}

// How close (pixels, center-to-center) an entity must get to an open exit's
// doorway before it counts as "at the exit" for despawn purposes — same
// tolerance as the player's own lenient exit-crossing checks.
export const EXIT_DESPAWN_REACH = GRID.CELL_SIZE * 1.5;

// How many cells past the doorway an exit-despawn walk animation lands
// before the walker is considered offscreen and safe to remove.
const EXIT_DESPAWN_OFFSET_CELLS = 3;

// Returns the direction ('north'/'south'/'east'/'west') of the nearest open
// exit within EXIT_DESPAWN_REACH of (x, y) in pixels, or null if none
// qualifies. Lock-agnostic like findExitAtPoint — callers gate on
// room.exitsLocked themselves. Used by the generic enemy exit-despawn check
// (EnemyUpdateSystem) so any enemy that ends up next to an open exit can be
// routed through it, not just a specific mechanic.
export function findNearbyOpenExitDirection(room, x, y) {
  if (!room?.exits) return null;
  let best = null, bestDist = Infinity;
  for (const dir of ['north', 'south', 'east', 'west']) {
    const exit = room.exits[dir];
    if (dir === 'south' ? !exit : !exit?.letter) continue;
    const slot = EXIT_SLOT_POSITIONS[dir];
    const sx = slot.col * GRID.CELL_SIZE + GRID.CELL_SIZE / 2;
    const sy = slot.row * GRID.CELL_SIZE + GRID.CELL_SIZE / 2;
    const d = Math.hypot(x - sx, y - sy);
    if (d < bestDist) { bestDist = d; best = dir; }
  }
  return bestDist <= EXIT_DESPAWN_REACH ? best : null;
}

// A point several cells beyond the doorway in `direction` — where a
// walk-through-the-exit despawn animation should land before the walker is
// removed from play.
export function getExitDespawnPoint(direction) {
  const slot = EXIT_SLOT_POSITIONS[direction];
  if (!slot) return null;
  const cs = GRID.CELL_SIZE;
  const offset = EXIT_DESPAWN_OFFSET_CELLS;
  switch (direction) {
    case 'north': return { x: slot.col * cs, y: (slot.row - offset) * cs };
    case 'south': return { x: slot.col * cs, y: (slot.row + offset) * cs };
    case 'east':  return { x: (slot.col + offset) * cs, y: slot.row * cs };
    case 'west':  return { x: (slot.col - offset) * cs, y: slot.row * cs };
    default: return null;
  }
}

// Returns { direction, exit } for the first exit letter slot whose cell
// overlaps the given rect (x, y in pixels; width/height default to 0 for a
// point test, which still falls inside the cell). Returns null if no overlap
// or if the room has no exits.
export function findExitAtPoint(room, x, y, width = 0, height = 0) {
  if (!room || !room.exits) return null;
  const cs = GRID.CELL_SIZE;
  for (const [dir, slot] of Object.entries(EXIT_SLOT_POSITIONS)) {
    const exit = room.exits[dir];
    if (!exit || !exit.letter) continue;
    const lx = slot.col * cs;
    const ly = slot.row * cs;
    if (x < lx + cs && x + width > lx && y < ly + cs && y + height > ly) {
      return { direction: dir, exit };
    }
  }
  return null;
}

// Lenient exit trigger. Each exit gap is exactly one cell (player-width) wide,
// so the positional crossing checks in updateExploreState only fire once the
// player squeezes pixel-perfectly into the opening. This catches the common
// case where the player is pressed against the wall beside the gap and actively
// holding the key toward it — "close enough, touching the gap, pressing the
// right way" leaves the room without fiddly alignment. `keys` is the WASD
// intent map; callers still apply the exit guards (locked exits, plane, exit
// existence) at the call site.
export function isPressingIntoExitGap(player, keys, direction) {
  if (!player || !keys) return false;
  const cs = GRID.CELL_SIZE;
  const centerX = Math.floor(GRID.COLS / 2);
  const centerY = Math.floor(GRID.ROWS / 2);
  const left = player.position.x;
  const right = player.position.x + player.width;
  const top = player.position.y;
  const bottom = player.position.y + player.height;
  const TOL = 3; // px of slack for "touching" the wall
  // Player box must overlap the gap lane on the perpendicular axis (horizontal
  // for N/S, vertical for E/W) — i.e. genuinely touching the gap.
  const overlapsCol = left < (centerX + 1) * cs && right > centerX * cs;
  const overlapsRow = top < (centerY + 1) * cs && bottom > centerY * cs;
  switch (direction) {
    case 'north': return keys.w && overlapsCol && top <= cs + TOL;
    case 'south': return keys.s && overlapsCol && bottom >= (GRID.ROWS - 1) * cs - TOL;
    case 'east':  return keys.d && overlapsRow && right >= (GRID.COLS - 1) * cs - TOL;
    case 'west':  return keys.a && overlapsRow && left <= cs + TOL;
    default: return false;
  }
}

// Mutates an exit's letter in place and tags the mutation so the renderer
// (and any future system) can react. Source examples: 'sword', 'fairyDust'.
// Returns true if the letter actually changed.
export function mutateExitLetter(exit, newLetter, { source = null } = {}) {
  if (!exit || !newLetter) return false;
  if (exit.letter === newLetter) return false;
  exit.letter = newLetter;
  exit.mutated = true;
  exit.mutationSource = source;
  return true;
}

// Mutates an exit's COLOR in place, tagged the same way as mutateExitLetter
// (shared exit.mutated/exit.mutationSource fields — the renderer's fairyDust
// tint check is the only current reader and only fires on that one source
// string, so a 'chromablade' source is inert to it). Source: 'chromablade'.
// Returns true if the color actually changed. Mutating exit.color here is
// what makes the change stick for zone-transition purposes: ZoneSystem
// .recordExit() reads exit.color at the moment the player actually leaves
// through the exit, so a Chromablade hit that lands before that crossing
// changes which color streak (and therefore which zone) the exit counts
// toward — same "signage IS the destination" contract the letter sword uses.
export function mutateExitColor(exit, newColor, { source = null } = {}) {
  if (!exit || !newColor) return false;
  if (exit.color === newColor) return false;
  exit.color = newColor;
  exit.mutated = true;
  exit.mutationSource = source;
  return true;
}

// Single call site for the two exit-mutating swords — Sword of the Letter
// (cycles exit.letter) and Chromablade (cycles exit.color). Called once per
// frame per melee attack from CombatSystem's attack-update loop; each flag is
// independently gated by its own attack.hasCycledXxx one-shot so an attack
// carrying both flags (it never does today, but nothing stops a future
// weapon) would resolve both. Lives here rather than inline in CombatSystem
// so the two weapons' resolution logic sits next to the mutation primitives
// (mutateExitLetter/mutateExitColor) it calls.
export function applyExitMutatingSwordHit(attack, room) {
  if (!room || !room.exits) return;

  if (attack.cyclesExitLetter && !attack.hasCycledLetter) {
    const hit = findExitAtPoint(room, attack.position.x, attack.position.y, attack.width, attack.height);
    if (hit) {
      const next = cycleExitLetter(hit.exit.letter);
      if (mutateExitLetter(hit.exit, next, { source: 'sword' })) {
        attack.hasCycledLetter = true;
      }
    }
  }

  if (attack.cyclesExitColor && !attack.hasCycledColor) {
    const hit = findExitAtPoint(room, attack.position.x, attack.position.y, attack.width, attack.height);
    if (hit) {
      const next = cycleExitColor(hit.exit.color);
      if (mutateExitColor(hit.exit, next, { source: 'chromablade' })) {
        attack.hasCycledColor = true;
      }
    }
  }
}

export class ExitSystem {
  constructor(zoneSystem, game = null) {
    this.zoneSystem = zoneSystem;
    this.game = game;
    // Exit sets offered in a row with no 'S' on them — see
    // _guaranteeSettlementExit. Run-scoped (RESET_REGISTRY).
    this.exitSetsSinceSettlement = 0;
  }

  /**
   * Letters one slot will not take, checked on every reroll. Slots are ordered
   * [north, east, west] here as everywhere else in this file.
   */
  _slotRefuses(slot, letter, currentDepth, zoneType) {
    // 'O' (Ocean) cannot be a west exit — entering from the west would put the
    // player in the ocean.
    if (slot === 2 && letter === 'O') return true;

    // 'R' (Ridge) cannot be the north exit when the room behind it would stand
    // on the run's second consecutive north. Crossing a Ridge is a promise:
    // its north always climbs into the gray zone (generateRidgeRoomImpl forces
    // it). A Ridge reached on the second north has its own north answered by
    // the Three Room instead, so the bridge the player paid an errand for would
    // deliver them somewhere the room said it never went. Offering it on the
    // third north is harmless — that traversal is intercepted before any room
    // is built, so the Ridge is never stood in.
    if (slot === 0 && letter === 'R' &&
        this.game?.threeRoomSystem?.nextRoomsNorthReachesTheThree()) return true;

    // 'R' (Ridge) also cannot land at the depth the pre-boss or pre-miniboss
    // gate hijacks: both gates overwrite the CLEARED room's own north exit
    // with a forced 'B' door (ExitSystem's pre-boss gate at bossDepth - 1,
    // ZoneSystem.applyPreMinibossGate at depth 8), clobbering Ridge's own
    // designed north exit (which must always force a transition to gray) —
    // reads as "unable to cross ridge" with no other way forward (#284).
    if (letter === 'R' && currentDepth != null) {
      const nextDepth = currentDepth + 1;
      const bossDepth = ZONES[zoneType]?.bossDepth;
      if (bossDepth != null && nextDepth === bossDepth - 1) return true;
      if (zoneType !== 'gray' && nextDepth === 8) return true;
    }

    // After the Goo Dragon, every exit must wear a still-undefeated zone
    // Boss's color (assignPostDragonColors). A letter hard-gated against
    // every one of those zones (e.g. green-only 'G'/'Q') could only ever
    // be dressed in a color its own gate refuses — reroll it instead.
    const remaining = this._postDragonExitZones(zoneType);
    if (remaining && !remaining.some(z => EXIT_LETTERS[letter]?.zoneBoosts?.[z] !== 0)) return true;

    return false;
  }

  /**
   * The zones an exit may lead to under the post-Goo-Dragon rule, or null
   * when the rule doesn't apply: the Goo Dragon still stands, the current
   * zone has no color drift of its own (gray is sticky), or no zone Boss is left standing (then the ordinary
   * completed-zone coloring runs and the north exit turns gray instead —
   * see generateExits).
   */
  _postDragonExitZones(zoneType) {
    if (!this.zoneSystem?.isGooDragonDefeated?.()) return null;
    if (!ZONES[zoneType]?.alternativeZones?.length) return null;
    const remaining = this.zoneSystem.undefeatedBossZones();
    return remaining.length > 0 ? remaining : null;
  }

  /** All zone Bosses down: the north exit of every drifting zone leads to gray. */
  _northLeadsToGray(zoneType) {
    return !!this.zoneSystem?.allZoneBossesDefeated?.() &&
      (ZONES[zoneType]?.alternativeZones?.length ?? 0) > 0;
  }

  /** Repaints an existing north exit gray + forceZone when _northLeadsToGray holds. */
  _pointNorthAtGray(exits, zoneType) {
    if (!this._northLeadsToGray(zoneType) || !exits?.north?.letter) return;
    exits.north = { ...exits.north, color: ZONE_COLORS.gray, forceZone: 'gray' };
  }

  /**
   * From L6 on the dungeon beat (see offersDungeonAt), one exit is always a
   * 'D'. It never takes the north slot: the pre-boss gate (bossDepth - 1 = 9
   * in the colored zones) overwrites the cleared room's north exit with a
   * forced 'B', and _pointNorthAtGray can repaint north toward gray. 'D' is
   * gated against no zone, so it can't break a streak _keepStreakSlotOpen kept.
   */
  _guaranteeDungeonExit(letters, closedSlots, forcedBossIndex, currentDepth, currentLetter) {
    if (currentDepth == null || currentDepth < DUNGEON_GUARANTEED_DEPTH || !offersDungeonAt(currentDepth)) return;
    if (currentLetter === 'D' || letters.includes('D')) return;
    const candidates = [1, 2].filter(i => i !== forcedBossIndex && !closedSlots.has(i));
    if (candidates.length === 0) return;
    letters[candidates[Math.floor(Math.random() * candidates.length)]] = 'D';
  }

  /**
   * A Settlement is on offer at least once in every SETTLEMENT_MAX_GAP exit
   * sets: when the previous sets all went by without an 'S', one east/west
   * slot is forced to 'S' — north only when both sides are taken and it does
   * not lead to gray. The forced 'B' and a guaranteed 'D' are never replaced. Gray has no
   * Settlement. The counter itself is advanced on the final letters at the
   * end of generateExits, so a sequence override that lands on the 'S' slot
   * simply leaves the guarantee owed for the next set.
   */
  _guaranteeSettlementExit(letters, closedSlots, forcedBossIndex, currentLetter, zoneType) {
    if (zoneType === 'gray' || currentLetter === 'S' || letters.includes('S')) return;
    if (this.exitSetsSinceSettlement < SETTLEMENT_MAX_GAP - 1) return;
    const open = i => i !== forcedBossIndex && !closedSlots.has(i) && letters[i] !== 'D';
    let candidates = [1, 2].filter(open);
    // Both sides taken (forced 'B' + guaranteed 'D'): north, unless it leads to gray.
    if (candidates.length === 0 && open(0) && !this._northLeadsToGray(zoneType)) candidates = [0];
    if (candidates.length === 0) return;
    letters[candidates[Math.floor(Math.random() * candidates.length)]] = 'S';
  }

  /**
   * The forced miniboss 'B' takes one of the three slots, leaving only two to
   * carry an in-progress color streak. When both remaining letters are
   * hard-gated against the streak's zone (e.g. green-only G/Q/M), the streak
   * would silently die — reroll one of them to a letter that allows it.
   */
  _keepStreakSlotOpen(letters, closedSlots, forcedBossIndex, progressionColor, currentDepth, zoneType, currentLetter) {
    const progressionZone = progressionColor ? zoneForColor(progressionColor) : null;
    if (!progressionZone || progressionColor === ZONES[zoneType]?.exitColor) return;
    const allows = letter => EXIT_LETTERS[letter]?.zoneBoosts?.[progressionZone] !== 0;
    const candidates = [0, 1, 2].filter(i => i !== forcedBossIndex && !closedSlots.has(i));
    if (candidates.length === 0 || candidates.some(i => allows(letters[i]))) return;

    const slot = candidates[Math.floor(Math.random() * candidates.length)];
    for (let attempts = 0; attempts < 50; attempts++) {
      const letter = this.selectExitLetter(currentDepth, zoneType);
      if (allows(letter) && !letters.includes(letter) && letter !== currentLetter &&
          !this._slotRefuses(slot, letter, currentDepth, zoneType)) {
        letters[slot] = letter;
        return;
      }
    }
  }

  generateExits(currentDepth, roomType, zoneType, progressionColor = null, currentLetter = null) {
    // Generate 3 UNIQUE letters (no duplicates, never the same letter as the room we're in)
    const letters = [];
    const maxAttempts = 50; // Prevent infinite loop

    for (let i = 0; i < 3; i++) {
      let attempts = 0;
      let letter;

      do {
        letter = this.selectExitLetter(currentDepth, zoneType);
        attempts++;
      } while (
        attempts < maxAttempts &&
        (letters.includes(letter) || letter === currentLetter || this._slotRefuses(i, letter, currentDepth, zoneType))
      );

      letters.push(letter);
    }

    // Guarantee the miniboss ('B') exit is always on offer from L5 onward
    // until this zone's miniboss has been cleared this run (gray excluded,
    // same as the miniboss gating elsewhere).
    const closedSlots = closedSlotsForLetter(currentLetter);

    let forcedBossIndex = -1;
    if (currentDepth >= 5 && zoneType !== 'gray' && currentLetter !== 'B' &&
        !letters.includes('B') && !this.zoneSystem?.clearedZones?.has(zoneType)) {
      // Keep the forced 'B' off the north slot once north always leads to
      // gray — a gray-colored 'B' would carry the player out of the zone
      // whose miniboss it is meant to guarantee.
      const bossSlotClosed = this._northLeadsToGray(zoneType) ? new Set([...closedSlots, 0]) : closedSlots;
      forcedBossIndex = randomOpenSlot(bossSlotClosed);
      letters[forcedBossIndex] = 'B';
      this._keepStreakSlotOpen(letters, closedSlots, forcedBossIndex, progressionColor, currentDepth, zoneType, currentLetter);
    }

    this._guaranteeDungeonExit(letters, closedSlots, forcedBossIndex, currentDepth, currentLetter);
    this._guaranteeSettlementExit(letters, closedSlots, forcedBossIndex, currentLetter, zoneType);

    // Assign colors based on zone and progression state. The forced 'B' slot
    // is reserved: alt/streak colors are placed on the other open slots, so
    // the zone-color repaint below can never erase a streak color that would
    // otherwise have landed there (bug #355 — 2 cyan exits followed, the L5
    // room offered no 3rd).
    const reservedSlot = forcedBossIndex;
    const colors = this.assignExitColors(letters, zoneType, progressionColor, closedSlots, currentDepth, reservedSlot);

    // The guarantee is "this zone's miniboss is reachable" — room.zone (and
    // therefore which zone's miniboss pool spawns) follows the exit's COLOR,
    // not its letter, so assignExitColors' random alt-color pick must never
    // land on the forced slot. Same fix already applied to the other two
    // forced-'B' call sites (pre-boss/pre-miniboss gates below).
    if (forcedBossIndex !== -1) {
      colors[forcedBossIndex] = ZONES[zoneType].exitColor;
    }

    // A letter sequence in progress (B-O-S-S, D-R-A-W, A-R-T, ...) may force
    // or bias its next letter onto an open slot, per its authored offer
    // class. See resolveSequenceOffers for the single-winner tie-break — the
    // Path Amulet can only ever render one live sequence trail, so at most
    // one sequence is ever "in progress".
    const sequenceOffer = this.resolveSequenceOffers(this.zoneSystem?.pathHistory);
    let sequenceColors = colors;
    if (sequenceOffer && sequenceOffer.offerClass !== 'passive' && !letters.includes(sequenceOffer.letter)) {
      const forceIt = sequenceOffer.offerClass === 'always' ||
        (sequenceOffer.offerClass === 'sometimes' && Math.random() < 0.5);
      if (forceIt) {
        const candidates = [0, 1, 2].filter(i => i !== forcedBossIndex && !closedSlots.has(i));
        if (candidates.length > 0) {
          const slot = candidates[Math.floor(Math.random() * candidates.length)];
          letters[slot] = sequenceOffer.letter;
          // Letters changed after colors were assigned — recompute so the
          // new letter's color follows the same zone/alt-color rules as
          // every other slot, rather than inheriting the stale color that
          // belonged to whatever letter this slot held before.
          sequenceColors = this.assignExitColors(letters, zoneType, progressionColor, closedSlots, currentDepth, reservedSlot);
          if (forcedBossIndex !== -1) {
            sequenceColors[forcedBossIndex] = ZONES[zoneType].exitColor;
          }
        }
      }
    }

    // Settlement guarantee bookkeeping, on the letters actually offered.
    if (zoneType !== 'gray') {
      const offered = letters.some((l, i) => l === 'S' && !closedSlots.has(i));
      this.exitSetsSinceSettlement = offered ? 0 : this.exitSetsSinceSettlement + 1;
    }

    // Return exit objects with letter + color
    const exits = {
      north: { letter: letters[0], color: sequenceColors[0] },
      east: { letter: letters[1], color: sequenceColors[1] },
      west: { letter: letters[2], color: sequenceColors[2] },
      // South is boolean (return to REST); noRest zones have no way back.
      // Once Charon's farewell has sealed REST, every room keeps a south door
      // — shut and gray (ExitSystem collision, RestExitLabel) — even in gray,
      // so the player sees the way back is gone rather than merely absent.
      south: !ZONES[zoneType]?.noRest || !!this.game?.cursedRunSystem.isRestSealed(this.game)
    };

    // Every zone Boss defeated: the north exit always leads to gray. Its
    // letter stays whatever was rolled (or sequence-forced); only the color
    // changes, and forceZone makes the step immediate the same way a Ridge's
    // north exit does (main.js primes ZoneSystem.forceNextZone from it).
    this._pointNorthAtGray(exits, zoneType);

    // The inevitable call — once per run, at gray depth 3, the north exit's
    // own signage turns into '3'. Taking it routes to the Three Room (the
    // north-exit block in main.js intercepts exit.threeRoom); LOOK NORTH here
    // answers through EXIT_LETTERS['3'].
    // A Cursed run is never offered it again — the room withdraws once a slot
    // has cracked, which is what makes the mistake permanent rather than
    // something the player can walk back and correct.
    if (zoneType === 'gray' && currentDepth === 3 && !this.game?.grayThreeExitShown && !this.game?.cursedRun) {
      this.game.grayThreeExitShown = true;
      exits.north = { letter: '3', color: '#999999', threeRoom: true };
    }

    return exits;
  }

  selectExitLetter(depth, zoneType) {
    const weights = this.getLetterWeightsForZone(zoneType, depth);
    return this.weightedRandomChoice(weights);
  }

  // `depth` is the depth of the room these exits belong to. A fresh alt color
  // (the first step of a zone change) is only offered at a depth that is a
  // multiple of ZONE_CHANGE_DEPTH_STEP. null skips that rule (post-boss
  // recoloring, where a completed or post-Dragon rule decides the colors).
  // `reservedSlot` (-1 = none) is an open exit that must keep this zone's own
  // color (the forced miniboss 'B'): it never receives an alt or streak color,
  // but it does count as the one own-color exit every room keeps.
  assignExitColors(letters, zoneType, progressionColor = null, closedSlots = new Set(), depth = null, reservedSlot = -1) {
    const zone = ZONES[zoneType];
    const colors = [zone.exitColor, zone.exitColor, zone.exitColor];

    // Gray zone: all exits gray (no alternatives)
    if (zone.alternativeZones.length === 0) {
      return colors;
    }

    // Slots an alt/streak color may be placed on: open and not reserved.
    const paintBlocked = reservedSlot >= 0 ? new Set([...closedSlots, reservedSlot]) : closedSlots;

    // Goo Dragon defeated: every exit, in every drifting zone, rolls only
    // among the zones whose Boss still stands. Once none are left this
    // returns null and the completed-zone path below keeps each exit on
    // the zone's own color (north is overridden to gray in generateExits).
    const postDragonZones = this._postDragonExitZones(zoneType);
    if (postDragonZones) {
      return this.assignPostDragonColors(letters, postDragonZones, progressionColor, paintBlocked);
    }

    // Completed zone (its own boss already defeated): flip the usual ratio.
    // Only 1 exit keeps this zone's own color; the other 2 take alt-zone
    // colors, actively pushing the player to leave a zone with nothing left
    // to do. Paired with ZoneSystem.peekZoneTransition's instant-transition
    // check, each of those 2 alt exits leaves on a single step rather than
    // needing a 3-color streak. Universal rule for any completed zone, not
    // just green (post-L15 Goo Dragon).
    if (this.zoneSystem?.isZoneDefeated(zoneType)) {
      return this.assignCompletedZoneColors(letters, zone, paintBlocked);
    }

    // Pick a random OPEN exit as the first alternative-color slot. A player
    // following a color trail reads "one exit of my color is always on offer"
    // as the rule; putting the alt color on the exit an Ocean room is about to
    // wall off silently breaks the trail with no way to tell it happened.
    //
    // A letter's zoneBoosts of 0 is a hard gate against that DESTINATION zone
    // (same rule getLetterWeightsForZone enforces at selection time — resolved
    // bug #103), but each slot's letter was picked against the CURRENT zone's
    // weights, before any of this alt-color logic ever runs. Left unchecked,
    // a letter hard-gated against e.g. cyan could still get dressed in cyan's
    // color whenever the current zone's alt-zone pool offers it — reaching the
    // exact destination its own gate says it never should. Both branches below
    // filter each slot's candidate zones by that slot's letter.
    const altIndex = randomOpenSlot(paintBlocked);

    if (progressionColor && progressionColor !== zone.exitColor) {
      // Mid-progression: the streak guarantee ("a same-color exit is always on
      // offer") outranks which of the 3 slots carries it. Checking only the
      // randomly-picked altIndex meant a room where THAT slot's letter happened
      // to be hard-gated against the progression zone silently dropped the
      // color entirely — all 3 exits fell back to this zone's own color and a
      // 2-streak died with no 3rd same-color exit ever appearing (bug: 2 red
      // exits followed, 3rd room showed 3 green). Search every open slot for
      // one whose letter isn't gated before giving up on the streak.
      const progressionZone = zoneForColor(progressionColor);
      const openSlots = [0, 1, 2].filter(i => !paintBlocked.has(i));
      const eligible = openSlots.filter(i => EXIT_LETTERS[letters[i]]?.zoneBoosts?.[progressionZone] !== 0);
      if (eligible.length > 0) {
        const slot = eligible.includes(altIndex) ? altIndex : eligible[Math.floor(Math.random() * eligible.length)];
        colors[slot] = progressionColor;
      }
      // Every open slot's letter is hard-gated against this destination —
      // exceedingly rare (all 3 letters would need to share the gate) — the
      // streak simply breaks this room rather than force a color onto a
      // letter that explicitly refuses that zone.
    } else if ((depth == null || offersZoneChangeAt(depth)) &&
               (zoneType === 'green' || Math.random() < ALT_EXIT_CHANCE_NON_GREEN)) {
      // No progression: offer TWO different alternative zones, excluding
      // zones whose boss is defeated. Only at L3, L6, ...: a zone change can
      // only start there, and the streak branch above carries whichever color
      // the player takes on through the next two rooms. Green always offers
      // the choice; other zones only sometimes (gate above). One open exit
      // always keeps this zone's own color, so when Ocean walls off a slot
      // only one alt color fits.
      // A reserved slot is the kept own-color exit, so it counts toward
      // openSlots (how many alts fit) but is never itself painted.
      const openSlots = [0, 1, 2].filter(i => !closedSlots.has(i));
      const paintableSlots = openSlots.filter(i => !paintBlocked.has(i));
      const altCount = Math.min(2, Math.max(1, openSlots.length - 1));
      const altSlots = [altIndex, ...paintableSlots.filter(i => i !== altIndex).sort(() => Math.random() - 0.5)]
        .slice(0, altCount);
      const offered = new Set();
      for (const slot of altSlots) {
        const slotBoosts = EXIT_LETTERS[letters[slot]]?.zoneBoosts;
        const available = zone.alternativeZones.filter(
          z => !this.zoneSystem.isZoneDefeated(z) && slotBoosts?.[z] !== 0 && !offered.has(z)
        );
        if (available.length === 0) continue;
        const altZone = available[Math.floor(Math.random() * available.length)];
        offered.add(altZone);
        colors[slot] = ZONE_COLORS[altZone];
      }
      // A slot with no eligible alt zone left (defeated, gated for its letter,
      // or already offered next door) keeps the current zone color.
    }

    return colors;
  }

  /**
   * Completed-zone exit coloring: 2 of the 3 slots take an alt-zone color
   * instead of the usual 1, leaving exactly 1 exit still colored for this
   * zone. Each alt slot independently picks from the zones this zone can
   * lead to, same eligibility filters as the normal single-alt path (not
   * already defeated, not hard-gated for that slot's letter) — the two picks
   * can land on the same alt zone, which is fine, same as 2 same-color exits
   * being ordinary in the non-completed case.
   */
  assignCompletedZoneColors(letters, zone, closedSlots) {
    const colors = [zone.exitColor, zone.exitColor, zone.exitColor];
    const open = [0, 1, 2].filter(i => !closedSlots.has(i));
    const altSlots = [...open].sort(() => Math.random() - 0.5).slice(0, Math.min(2, open.length));

    for (const slot of altSlots) {
      const altLetterBoosts = EXIT_LETTERS[letters[slot]]?.zoneBoosts;
      const altZoneGated = z => altLetterBoosts?.[z] === 0;
      const available = zone.alternativeZones.filter(
        z => !this.zoneSystem.isZoneDefeated(z) && !altZoneGated(z)
      );
      if (available.length > 0) {
        colors[slot] = ZONE_COLORS[available[Math.floor(Math.random() * available.length)]];
      }
      // If none available for this slot, it stays the zone's own color.
    }

    return colors;
  }

  /**
   * Post-Goo-Dragon exit coloring: each of the 3 slots independently takes
   * the color of one of `remainingZones` (zone Bosses still standing),
   * honoring the slot letter's zoneBoosts hard gate. _slotRefuses already
   * rerolls letters gated against every remaining zone, so the ungated
   * fallback only catches a letter forced in after rolling (a sequence
   * step) — the exit rule outranks the gate there.
   *
   * An in-progress color streak toward a remaining zone keeps its usual
   * guarantee: if no open slot rolled the streak color, one eligible open
   * slot is repainted with it, so a 2-streak can still complete.
   */
  assignPostDragonColors(letters, remainingZones, progressionColor, closedSlots) {
    const pick = arr => arr[Math.floor(Math.random() * arr.length)];
    const letterAllows = (letter, z) => EXIT_LETTERS[letter]?.zoneBoosts?.[z] !== 0;

    const colors = letters.map(letter => {
      const eligible = remainingZones.filter(z => letterAllows(letter, z));
      return ZONE_COLORS[pick(eligible.length > 0 ? eligible : remainingZones)];
    });

    const progressionZone = progressionColor ? zoneForColor(progressionColor) : null;
    if (progressionZone && remainingZones.includes(progressionZone)) {
      const openSlots = [0, 1, 2].filter(i => !closedSlots.has(i));
      const alreadyOffered = openSlots.some(i => colors[i] === progressionColor);
      const eligible = openSlots.filter(i => letterAllows(letters[i], progressionZone));
      if (!alreadyOffered && eligible.length > 0) colors[pick(eligible)] = progressionColor;
    }

    return colors;
  }

  /**
   * Called once when a zone Boss room clears. Its exits were generated while
   * the Boss still stood, so a kill that just defeated the Goo Dragon (or the
   * last zone Boss) would otherwise leave the player choosing among colors
   * the rule now forbids. Keeps each exit's letter and any other flags; only
   * the color (and, for gray north, forceZone) changes. The kill also makes
   * this a completed zone, so even before the Goo Dragon falls the room
   * re-dresses under the completed-zone rule (1 own-color exit, 2 alt-zone
   * exits) — otherwise every zone Boss room left all 3 exits in its own
   * color (Frosted Maw, turtle shell). A no-op only if the Boss isn't
   * actually marked defeated.
   */
  recolorExitsAfterZoneBoss(room) {
    if (!room?.isZoneBossRoom) return;
    const zone = room.zone || 'green';
    if (!this.zoneSystem?.isZoneDefeated(zone) &&
        !this._postDragonExitZones(zone) && !this._northLeadsToGray(zone)) return;

    const slots = ['north', 'east', 'west'];
    const exits = slots.map(s => room.exits?.[s]);
    const closedSlots = new Set(slots.map((_, i) => i).filter(i => !exits[i]?.letter));
    const colors = this.assignExitColors(exits.map(e => e?.letter), zone, null, closedSlots);
    slots.forEach((s, i) => {
      if (exits[i]?.letter) room.exits[s] = { ...exits[i], color: colors[i] };
    });

    this._pointNorthAtGray(room.exits, zone);
  }

  getLetterWeightsForZone(zoneType, depth) {
    const weights = {};
    const blessed = !!this.game?.player?.luckBlessed;

    // Build weights from EXIT_LETTERS
    for (const [letter, data] of Object.entries(EXIT_LETTERS)) {
      let weight = data.weight;

      // Apply zone boosts if defined. A boost of 0 is a hard zone gate, so the
      // check must be !== undefined, not truthy (resolved bug #103).
      if (data.zoneBoosts && data.zoneBoosts[zoneType] !== undefined) {
        weight *= data.zoneBoosts[zoneType];
      }

      // Boss mini-room: locked out before L5, then ramps from x2 at L5 up to
      // x8 at L9, where the miniboss becomes mandatory (see main.js). Also
      // locked out once every bossPool encounter for this zone has been
      // beaten this run — zones with no bossPool (e.g. yellow) are never
      // "exhausted" and keep the normal ramp (generic fallback boss).
      if (letter === 'B') {
        if (depth < 5 || this.zoneSystem?.isMinibossPoolExhausted(zoneType)) {
          weight = 0;
        } else {
          const t = Math.min(depth, 9) - 5; // 0 at depth 5, 4 at depth 9+
          weight *= 2 + (6 * t / 4);        // 2 -> 8 linearly over depths 5..9
        }
      }

      // Dungeon: only rolled on the L3/L6/L9 beat (offersDungeonAt).
      if (letter === 'D' && !offersDungeonAt(depth)) {
        weight = 0;
      }

      // Lucky blessing reshapes the route: more vaults, key rooms, mystery,
      // and camps. Boss is intentionally excluded — depth pacing owns it.
      if (blessed && LUCKY_BOOST[letter]) {
        weight *= LUCKY_BOOST[letter];
      }

      weights[letter] = weight;
    }

    // Penalize recently visited letters so the same room type is less likely to
    // repeat. Most-recent = heaviest penalty; penalty fades over 5 rooms.
    const history = this.game?.zoneSystem?.pathHistory;
    if (history?.length) {
      const RECENCY_PENALTIES = [0.1, 0.25, 0.45, 0.65, 0.82];
      const penalized = new Set();
      for (let i = 0; i < history.length && i < RECENCY_PENALTIES.length; i++) {
        const recent = history[history.length - 1 - i].letter;
        if (!penalized.has(recent) && weights[recent] !== undefined) {
          weights[recent] *= RECENCY_PENALTIES[i];
          penalized.add(recent);
        }
      }
    }

    return weights;
  }

  weightedRandomChoice(weights) {
    const total = Object.values(weights).reduce((a, b) => a + b, 0);
    let random = Math.random() * total;

    for (const [letter, weight] of Object.entries(weights)) {
      random -= weight;
      if (random <= 0) return letter;
    }
    return 'X'; // Fallback to Crossroads
  }

  checkSecretPattern(pathHistory) {
    if (!pathHistory || pathHistory.length < 3) return null;

    // Extract letters from exit objects
    const letterPath = pathHistory.map(exit => exit.letter);
    const fullPath = letterPath.join('-');

    // Prefer the most specific (longest) matching pattern rather than
    // whichever happens to be declared first in SECRET_PATTERNS — an
    // authoring accident, not a rule. Not reachable today (B-O-S-S and
    // B-A-T diverge at letter 2), but removes a latent bug for the next
    // sequence someone authors.
    let best = null;
    for (const [pattern, data] of Object.entries(SECRET_PATTERNS)) {
      if (!fullPath.includes(pattern)) continue;
      const patternLength = pattern.split('-').length;
      const lastNLetters = letterPath.slice(-patternLength).join('-');
      if (lastNLetters !== pattern) continue;
      if (!best || patternLength > best.patternLength) {
        best = { pattern, patternLength, data };
      }
    }
    return best ? { pattern: best.pattern, ...best.data } : null;
  }

  /**
   * Finds the single in-progress letter sequence, if any, and what class of
   * offer its next letter should get. Because the Path Amulet can only ever
   * render one live sequence trail (a single text readout of pathHistory),
   * at most one sequence is ever "in progress" — this resolves to exactly
   * one winner, never a list.
   *
   * Every SECRET_PATTERNS entry participates in the search (not just
   * sequence-bearing ones): a longer coincidental match on a legacy pattern
   * must still suppress a shorter sequence match on the same tail letters
   * (e.g. in-progress B-A-T outranks a fresh A-R start off the shared 'A'),
   * even though the legacy entry itself grants no forced offer.
   */
  resolveSequenceOffers(pathHistory) {
    if (!pathHistory || pathHistory.length === 0) return null;
    const tailLetters = pathHistory.map(e => e.letter);

    // Two passes: first find the deepest match depth across ALL entries
    // (legacy patterns included, since a deeper coincidental match must
    // still suppress a shallower sequence match on the same tail letters).
    // Then, among only the entries tied at that depth, prefer one with a
    // `sequence` field — declaration order alone must not let an unrelated
    // legacy pattern (e.g. B-A-T, no `sequence`) blot out a same-depth
    // sequence-bearing sibling (e.g. B-O-S-S) sharing the same head letter.
    let bestK = 0;
    let matchesAtBestK = [];

    for (const [pattern, data] of Object.entries(SECRET_PATTERNS)) {
      const letters = pattern.split('-');
      const maxK = Math.min(letters.length - 1, tailLetters.length);
      for (let k = maxK; k >= 1; k--) {
        const tailSlice = tailLetters.slice(-k).join('-');
        const prefixSlice = letters.slice(0, k).join('-');
        if (tailSlice === prefixSlice) {
          if (k > bestK) {
            bestK = k;
            matchesAtBestK = [{ data, letters }];
          } else if (k === bestK) {
            matchesAtBestK.push({ data, letters });
          }
          break; // only the deepest match per entry matters
        }
      }
    }

    const winner = matchesAtBestK.find(m => m.data.sequence);
    if (!winner) return null;
    const stepCount = winner.letters.length - 1;
    const offerSteps = normalizeOfferSteps(winner.data.sequence.offerSteps, stepCount);
    return { letter: winner.letters[bestK], offerClass: offerSteps[bestK - 1] };
  }

  /**
   * Which REST exit the player is crossing this frame, or null.
   *
   * REST's exits are gated to the 3-cell warp column under the arrows, so other
   * interactives near an edge (the gravestone sits by the north wall) can't
   * drift across the threshold and trigger a transition. North also accepts a
   * one-frame crossing of the threshold, because a fast enough approach can
   * step clean over the band between two updates; south is only reachable at
   * walking pace off a Cursed run's opened wall and needs no such catch.
   *
   * @param {object} room - the REST room, read for its open edges
   * @param {Player} player
   * @param {number} previousY - the player's y at the end of the last frame
   * @returns {'north'|'south'|null}
   */
  restExitCrossing(room, player, previousY) {
    const centerX = Math.floor(GRID.COLS / 2);
    const gridX = Math.floor(player.position.x / GRID.CELL_SIZE);
    if (gridX < centerX - 1 || gridX > centerX + 1) return null;

    const northThreshold = GRID.CELL_SIZE * 2 - 10;
    const crossedNorth = previousY >= northThreshold && player.position.y < northThreshold;
    if (room?.exits?.north && (player.position.y < northThreshold || crossedNorth)) return 'north';

    const southThreshold = (GRID.ROWS - 2) * GRID.CELL_SIZE + 10;
    if (room?.exits?.south && player.position.y > southThreshold) return 'south';

    return null;
  }

  updateExitCollisions(room, player) {
    if (!room || !room.collisionMap) return;

    const centerX = Math.floor(GRID.COLS / 2);
    const centerY = Math.floor(GRID.ROWS / 2);
    const locked = !!room.exitsLocked;

    if (room.exits.north) {
      room.collisionMap[0][centerX] = locked;
    }
    if (room.exits.south) {
      room.collisionMap[GRID.ROWS - 1][centerX] = locked;
    }
    if (room.exits.east) {
      room.collisionMap[centerY][GRID.COLS - 1] = locked;
    }
    if (room.exits.west) {
      room.collisionMap[centerY][0] = locked;
    }

    // Escape route: south wall must be physically passable when the room is
    // locked but the player has no items (matches the renderer's open-door
    // visual at ExploreRenderer.js — otherwise the player walks into an
    // invisible wall at row ROWS-1 col centerX). Overrides the south lock
    // set above for this one case.
    if (room.exits.south && locked && this.game?.playerHasNoItems()) {
      room.collisionMap[GRID.ROWS - 1][centerX] = false;
    }
    // Charon's farewell shut the way back to REST for the run — no escape route.
    if (room.exits.south && this.game?.cursedRunSystem.isRestSealed(this.game)) {
      room.collisionMap[GRID.ROWS - 1][centerX] = true;
    }

    // Don't overwrite the player's collision map while inside an Interior
    if (!isInteriorActive(this.game)) {
      player.setCollisionMap(room.collisionMap);
    }
  }

  /**
   * Per-frame room-clear / exit-lock transition, called every ExploreState
   * frame from main.js's updateExploreState. Hidden mimics don't block clear
   * — they're still in the enemies array, so if they reveal post-clear they
   * fight normally, but exits and clear-side effects fire on visible-enemy
   * defeat. Skips entirely mid ascent-lava fill (own state machine).
   *
   * Two directions:
   *  - Counted enemies hit zero → unlock exits. One-time clear rewards
   *    (captive spawn, secret events, bat belfry, pre-boss/pre-miniboss
   *    gates) fire the first time only; Quagmire wave escalation defers
   *    unlocking while rounds remain (RoundCombatSystem.advanceIfPending).
   *  - A counted enemy appears after exits already opened (revealed mimic,
   *    grass-ambush beast — see InteractionSystem, etc.) → re-lock, matching
   *    the invariant EnemyUpdateSystem's exit-despawn guard already assumes
   *    ("Rooms lock their exits while any counted enemy remains"). Pacifist
   *    game animals (Hunting) and uncounted post-clear hazards (Quagmire
   *    Hag) are excluded from _countedEnemies specifically so they don't
   *    trip this branch. `cleared` is left untouched on re-lock — one-time
   *    reward logic above must never re-fire; only physical passage re-locks.
   */
  updateRoomClearState() {
    const game = this.game;
    const room = game.currentRoom;
    // Ask the Ascent hazard whether it is mid-flood rather than re-listing its
    // phase names here — `PhasedHazardSystem.isHazardActive()` reads the same
    // FILL_PHASES the system itself schedules against, so renaming or adding a
    // fill phase can't leave this gate silently out of date (#142 drift shape).
    // The cyan Ascent has no phases: its Maw Shadow never holds the exits.
    if (game.lavaAscentSystem?.isHazardActive(room)) return;

    if (game._countedEnemies(room.enemies).length === 0) {
      // Quagmire: spawn the next wave instead of clearing while rounds remain.
      if (room.cleared || !game.roundCombatSystem.advanceIfPending(room)) {
        // Only process room clear once
        if (!room.cleared) {
          room.cleared = true;

          // Track room clear in current zone (for per-zone captive spawning)
          const currentZone = room.zone || 'green';
          game.zoneSystem.recordRoomClear(currentZone);
          game.zoneSystem.recordMinibossRoomClear(room);

          // Check if we should spawn a captive (miniboss just defeated in this zone)
          if (game.zoneSystem.shouldSpawnCaptive(currentZone, room)) {
            const captive = game.characterSystem.spawnCaptive(currentZone); // Spawn captive matching zone
            if (captive) {
              game.captives.push(captive);
              game.zoneSystem.markZoneCleared(currentZone);
              console.log(`Spawned ${currentZone} captive! (miniboss defeated in ${currentZone} zone)`);
            }
          }

          // Apply secret events (key glitter, leshy chase, etc.)
          // Uses priority system - only 1 event per room
          game.secretEventSystem.applySecretEvents(room);
          // Compass (⌖) — one-shot beep the instant a findable secret goes live
          game.compassSystem?.onSecretRevealed(room);

          // Gray Ascent: shrink plateau on room clear
          game.mistAscentSystem?.onRoomClear(room);

          // E-room: spawn the errand traveler after enemies are cleared
          if (room.letterTemplate?.neutralAfterClear) {
            const errandChar = game.errandSystem.onRoomClear(game.player, room);
            if (errandChar) game.neutralCharacters.push(errandChar);
          }

          // Bat belfry reward: unlock a new consumable slot
          if (room.isBatBelfry) {
            game.inventorySystem.unlockConsumableSlot();
            if (game.player) {
              game.player.equippedConsumables = [...game.inventorySystem.equippedConsumables];
            }
            game.menuSystem.showPickupMessage('NEW CONSUMABLE SLOT');
            game.renderer.markBackgroundDirty();
            game.updateUI();
          }

          // Pearl-guide fairy: if it's still around at room clear, the player
          // missed (or skipped) the heal/bottle touch. Reveal the pedestal so
          // they can complete the offering and unlock the pedestal's east exit.
          game.pearlSystem.revealPearlPedestal();

          // A zone Boss room's exits were rolled before the kill; re-dress
          // them under the completed-zone / post-Goo-Dragon rules it unlocked.
          this.recolorExitsAfterZoneBoss(room);

          // Pre-boss gate: depth (bossDepth - 1) cleared → north-only 'B' exit + anticipation music.
          // Uses >= (not ===) as a self-correcting safety net: if the player somehow
          // ends up clearing a non-boss room at or past bossDepth with the boss still
          // undefeated (e.g. depth-jump cheat, corrupted state), the very next room is
          // still forced to the boss via the same gate rather than staying stuck.
          const preBossZone = room.zone || 'green';
          const preBossDepth = game.zoneDepths[preBossZone] || 0;
          const preBossZoneBossDepth = ZONES[preBossZone]?.bossDepth;
          if (preBossZoneBossDepth != null && preBossDepth >= preBossZoneBossDepth - 1 && !game.zoneSystem.defeatedBosses?.has(preBossZone)) {
            game.preBossGateActive = true;
            room.exits.east = null;
            room.exits.west = null;
            // Color MUST match the current zone's exitColor so recordExit keeps
            // the streak intact in checkZoneTransition. ExploreRenderer paints
            // the pulse from preBossGateActive, not from this stored color.
            room.exits.north = { letter: 'B', color: ZONES[preBossZone].exitColor };
            // The room already generated (and may have raised a Barricade
            // across this same lane) before this retrofit existed to consult
            // it — clear any plug now blocking the forced gate (bug #298).
            game.barricadeSystem.liftForGate(room);
            game.audioSystem.startBossAnticipation();
          }

          // Pre-miniboss gate: depth 8 cleared → north-only 'B' exit steering
          // toward the depth-9 mandatory miniboss.
          game.zoneSystem.applyPreMinibossGate(game);
        }

        // Unlock exits (letters are already generated)
        room.exitsLocked = false;
        // Update collision map to open exits
        game.updateExitCollisions();
      } // end finalize (no pending wave)
    } else if (!room.exitsLocked) {
      room.exitsLocked = true;
      game.updateExitCollisions();
    }
  }
}
