import { GRID, BACKGROUND_OBJECTS, BACKGROUND_OBJECT_VARIANTS, OBJECT_ANIMATIONS, WATER_COLORS } from '../game/GameConfig.js';
import { ITEMS, INGREDIENTS } from '../data/items.js';

// A player's shot from a gun or a bow (the Slingshot's bullet included) —
// what a Barricade Target answers to. A boomerang flies as an arrow but is a
// thrown weapon, not a shot.
function isGunOrBowShot(proj) {
  if (proj.boomerang) return false;
  const weaponType = ITEMS[proj.weaponChar]?.weaponType;
  return weaponType === 'GUN' || weaponType === 'BOW';
}

// Concurrency window for `registerSpark()` — mirrors FireSystem's
// EMBER_STACK_WINDOW (the same "close together counts, spread out doesn't"
// shape used for the player's own ember-contact burn threshold).
const SPARK_WINDOW = 2.0;

// Linear-interpolate between two #rrggbb colors. t in [0, 1].
function _lerpHex(a, b, t) {
  const ar = parseInt(a.slice(1, 3), 16), ag = parseInt(a.slice(3, 5), 16), ab = parseInt(a.slice(5, 7), 16);
  const br = parseInt(b.slice(1, 3), 16), bg = parseInt(b.slice(3, 5), 16), bb = parseInt(b.slice(5, 7), 16);
  const r = Math.round(ar + (br - ar) * t);
  const g = Math.round(ag + (bg - ag) * t);
  const bl = Math.round(ab + (bb - ab) * t);
  return '#' + [r, g, bl].map(v => v.toString(16).padStart(2, '0')).join('');
}

export class BackgroundObject {
  constructor(char, x, y, options = {}) {
    this.char = char;

    // Variant identity — decouples behavior from render char
    // If typeId is provided, use variant data as primary data source
    this.typeId = options.typeId || null;
    this._variantData = null;
    if (this.typeId) {
      const base = BACKGROUND_OBJECT_VARIANTS[this.typeId];
      this._variantData = options.variantOverrides
        ? { ...base, ...options.variantOverrides }
        : base || null;
      // Use variant data as primary data, falling back to BACKGROUND_OBJECTS for missing keys
      this.data = this._variantData;
    } else {
      // Handle unknown characters (e.g., item chars in recipe signs)
      // Fallback chain: BACKGROUND_OBJECTS → ITEMS → INGREDIENTS → default
      if (BACKGROUND_OBJECTS[char]) {
        this.data = BACKGROUND_OBJECTS[char];
      } else {
        // For recipe signs: use item/ingredient colors if available
        const itemData = ITEMS[char] || INGREDIENTS[char];
        this.data = {
          name: itemData ? itemData.name : 'Unknown',
          color: itemData ? itemData.color : '#888888',
          solid: false,
          hp: null,
          bulletInteraction: 'pass-through',
          indestructible: true
        };
      }
    }
    this.position = { x, y };
    this.originalChar = char;
    this.color = this.data.color;
    this.destroyed = false;

    // Deep water — a darker-tinted '~' tile (see WATER_COLORS.deep) that drowns
    // non-immune entities and blocks dodge-roll activation; set by RoomGenerator
    // on Lake-center and off-coast Ocean cells. Read by PhysicsSystem, never by
    // this class beyond the render-color override in update()/getRenderPosition().
    this.deepWater = options.deepWater || false;

    // Sunken Glint — a deep tile in a green Ocean hiding a coin or sea find,
    // shown only as a twinkle (see SunkenGlintSystem). Cleared on discovery.
    this.sunkenGlint = options.sunkenGlint || false;

    // Obsidian flag — unbreakable rock (darker gray rendering)
    this.obsidian = options.obsidian || false;
    if (this.obsidian && char === '0') {
      this.color = '#333333';
      this.indestructible = true;
    }

    // Rock poke drop ('/' interaction → zone mineral) is claimable once per rock.
    this.pokeMineralClaimed = false;

    // Mana gem instance fields (set at placement for boss room gems)
    this.manaGemColor = options.manaGemColor || this.data.manaGemColor || null;
    this.pulseTimer = 0;

    this.animationTimer = 0;
    this.currentAnimation = null;
    this.animationOffset = { x: 0, y: 0 };
    this.animationChar = char;
    this.animationColor = this.color;

    this.destroyAfterAnimation = false;

    this.hasCollision = false;

    // Part of a generated structure (hut walls, well ring, maze shell, …) —
    // exempt from the post-generation stray cleanup pass (roomFeatures.js).
    this.structural = false;

    // Set at placement to skip the data dropChance roll for this one instance
    // (e.g. the Caldera's one guaranteed Fire Berry bush). See passesDropRoll().
    this.guaranteedDrop = false;

    // Special-case hitboxes for certain char types, then fall through to
    // data-driven hitbox (from BACKGROUND_OBJECTS), then to the render-size default.
    const isGroundLiquid = char === '=' || char === '~' || char === '!';
    const isRock = char === '0';
    const isTreeOrStump = char === 'Y' || char === 'ŋ';

    if (isRock) {
      // Narrow elliptical collision — rock is round, not square.
      // collisionShape: 'ellipse' is set in data; semi-axes a=3 b=6.
      this.width = 3;
      this.height = GRID.CELL_SIZE * 0.375;   // 6px
      this.hitboxOffsetX = 7;                 // centers 3px box in 16px cell
      this.hitboxOffsetY = GRID.CELL_SIZE * 0.3125; // 5px
    } else if (isGroundLiquid) {
      // Ground-level contact region — lower third of cell, centered horizontally.
      // Gives the illusion that the liquid/fire sits on the floor plane.
      this.width = GRID.CELL_SIZE * 0.4;     // 6px
      this.height = GRID.CELL_SIZE * 0.3;    // 5px
      this.hitboxOffsetX = GRID.CELL_SIZE * 0.25; // 4px
      this.hitboxOffsetY = GRID.CELL_SIZE * 0.6;  // 10px (bottom third)
    } else if (isTreeOrStump) {
      // Narrow trunk hitbox — used only for slowdown overlap, not solid blocking.
      this.width = 6;
      this.height = 10;
      this.hitboxOffsetX = 5;
      this.hitboxOffsetY = 3;
    } else if (this.data.hitbox) {
      // Data-driven hitbox: BACKGROUND_OBJECTS entries can declare
      //   hitbox: { w: <widthFraction>, h: <heightFraction> }
      // Offsets are auto-calculated to center the box inside the cell.
      const hb = this.data.hitbox;
      this.width  = Math.round(GRID.CELL_SIZE * hb.w);
      this.height = Math.round(GRID.CELL_SIZE * hb.h);
      this.hitboxOffsetX = Math.floor((GRID.CELL_SIZE - this.width)  / 2);
      this.hitboxOffsetY = Math.floor((GRID.CELL_SIZE - this.height) / 2);
    } else {
      // Default: mirror the rendered glyph footprint.
      // Unifont at 16px renders ASCII glyphs ~8px wide × ~12px tall, centered
      // in the 16×16 cell.  Full-cell collision creates invisible walls; this
      // keeps the collision box flush with what the player actually sees.
      this.width  = Math.round(GRID.CELL_SIZE * 0.5);   // 8px
      this.height = Math.round(GRID.CELL_SIZE * 0.75);  // 12px
      this.hitboxOffsetX = Math.floor((GRID.CELL_SIZE - this.width)  / 2); // 4px
      this.hitboxOffsetY = Math.floor((GRID.CELL_SIZE - this.height) / 2); // 2px
    }

    // Bullet interaction properties. Environmental terrain (water, lava, mud,
    // deep snow) is ground a projectile flies over: a typeId variant's data
    // replaces its char's outright, so without this default those variants
    // fell back to 'block' — deep snow (borrowing the solid '█') stopped arrows.
    this.bulletInteraction = this.data.bulletInteraction
      || (this.isEnvironmental() ? 'pass-through' : 'block');
    this.indestructible = this.data.indestructible || false;
    // Set by deplete(): a `depletedColor` object (Sand) spent in place.
    this.depleted = false;
    this.conductivity = this.data.conductivity || 'none';
    this.flammability = this.data.flammability || 'none';

    // Interaction-type enum (see INTERACTION_TYPES in GameConfig). Default
    // omits 'spacebar' so trees/rocks keep harvest-only semantics — only
    // containers opt in to direct player opening.
    this.acceptsInteractions = this.data.acceptsInteractions || ['blade', 'bullet', 'blunt'];

    this.collisionShape = this.data.collisionShape || 'rectangle'; // 'rectangle' or 'ellipse'

    // HP system
    this.maxHp = this.data.hp !== undefined ? this.data.hp : null;
    this.hp = this.maxHp;

    // Custom-sprite damage staging (e.g. Fractured Rock) — separate from the
    // single-threshold animationChar swap below; recomputed in takeDamage().
    this.damageStage = 0;

    // Fire propagation state
    this.onFire = false;
    this.fireDuration = 0;
    this.fireTimer = 0;

    // Spark accumulation gate (optional, data-declared — see `sparkThreshold`
    // on Tree in GameConfig.js). Ambient ignition sources (FireSystem's
    // adjacency spread, burning-entity contact) go through `registerSpark()`
    // instead of `ignite()` directly for any object that declares a
    // threshold, requiring that many roughly-concurrent sparks before it
    // actually catches — a single ember or one passing burning rat shouldn't
    // torch a tree the way it does a blade of grass. Direct fire-weapon
    // damage (CombatSystem._ignite) always calls `ignite()` itself and is
    // untouched by this gate.
    this.sparkThreshold = this.data.sparkThreshold || null;
    this.sparkStacks = 0;
    this.sparkTimer = 0;

    // Water state (only meaningful when this.char === '~')
    this.waterState = 'normal'; // 'normal' | 'frozen' | 'poisoned' | 'electrified'
    this.waterStateTimer = 0;
    // Weaker current this tile was electrified by ({ pips, source } — carried
    // over from an electric Imbue's slime trail, ElectricitySystem); null =
    // full-strength current.
    this.electricCurrent = null;

    // Drop tracking - prevents duplicate drops from same object
    this.hasDropped = false;

    // Spawn immunity — new chests (from grass drops) are briefly unhittable so
    // the swing that spawned them can't immediately open them.
    this.spawnImmunityTimer = 0;

    // Leshy chase event flags (set by RoomGenerator for secret events)
    this.isShaking = false;
    this.leshyBush = false;
    this.fairyGrass = false;
    this.shakeTimer = 0;

    // Per-instance override: ignores the normal rock/blunt-weapon damage gates
    // entirely (melee and bullet). Set by room generation for obstacles that must
    // never wall off the player regardless of loadout (e.g. the Centipede arena's
    // obstacle rocks) — see CombatSystem's melee gates and handleBulletCollision below.
    this.allWeaponsDamage = false;
    // Per-instance override: destroying this object yields nothing — no
    // dropEffect payload, no dropTable. The Centipede arena's any-weapon
    // rocks and its petrified segment husks wear a rock's body without its
    // rock harvest.
    this.dropsNothing = false;

    // Wand system properties
    this.rock = this.data.rock || false; // Negates magic/elemental effects
    this.electrified = false; // Electrical infusion trap
    this.electrifiedTimer = 0;

    // Fields that were previously lazy-initialized at runtime; declared here to avoid
    // undefined-vs-false ambiguity and to satisfy the constructor-completeness requirement.
    this.isCampfire = false;        // Set by RoomGenerator for campfire objects
    this._flickerTimer = 0;         // Campfire flicker countdown
    this.fountainWater = false;     // F-room water tile — drives shimmer cycle
    this.fountainWaterfall = false; // F-room waterfall tile — drives downward char cycle
    // Attunement colour for F-room pool/waterfall tiles, set by FountainSystem when
    // an elemental gem is offered. Deliberately NOT expressed as a waterState:
    // FountainSystem reads waterState to detect elemental corruption, so tinting
    // through it would anger the flock the moment the pool changed colour.
    this.fountainTint = null;
    this._fountainShimmerTimer = 0;
    this._fountainWaterfallTimer = 0;
    this._fountainWaterfallPhase = Math.floor(Math.random() * 4);
    this.electricBlinkTimer = 0;    // Electrified water blink interval timer
    this.electricBlinkOn = false;   // Electrified water blink state
    this.burnt = false;             // Set by burnGrass() after fire burns out
    this.damaging = false;          // Set by RoomGenerator for lava tiles
    this.isDryMud = false;          // Set by PhysicsSystem for drying mud tiles
    this.ratDug = false;            // Mud tile a tamed rat has already dug (NPCRat Dig) — one dig per tile

    // River-flow animation (yellow zone). Set by RoomGenerator on river center tiles.
    // animationChar is held at this._directionChar (`< > v ^`); color cycles blue→white
    // along flowDir with a per-tile phase offset to read as a traveling current.
    this.riverFlow = false;
    this.flowIndex = 0;
    this.flowDir = null;
    this._directionChar = null;
    this._flowTime = 0;
  }

  // Called by melee attacks (and can be called by any damage source).
  // Returns { destroyed, effect } where effect is the dropEffect string on kill.
  takeDamage(amount, isBlade = false, opts = {}) {
    // Block damage if already queued for destruction (prevents animation spam)
    if (this.destroyAfterAnimation) {
      return { destroyed: false, effect: null };
    }

    if (this.spawnImmunityTimer > 0) {
      return { destroyed: false, effect: null };
    }

    // Environmental terrain (water, lava, mud, Ascent slopes) is not a
    // hittable prop — a weapon passing through it never reacts (no shake,
    // no damage number). Its real interaction logic (freeze/poison/burn/
    // electrify/push) is handled by dedicated systems keying off
    // isWater()/isLava()/isMud()/slope directly, entirely separate from
    // this HP-based damage-number pipeline.
    if (this.isEnvironmental()) {
      return { destroyed: false, effect: null };
    }

    if (this.indestructible || this.hp === null) {
      this._playAnimation('shake');
      return { destroyed: false, effect: null };
    }

    // A shotOnly object (Barricade Target) takes damage from a gun's bullet or
    // a bow's arrow alone — handleBulletCollision passes `shot` for those.
    // Gating here rather than at each caller turns away every other path at
    // once: melee, explosions, rolls, boulders.
    if (this.data?.shotOnly && !opts.shot) {
      this._playAnimation('shake');
      return { destroyed: false, effect: null };
    }

    // Grass cutting: blade attacks convert tall grass to cut grass
    if (isBlade && this.data.cuttable && this.data.cutState) {
      this.cutGrass();
      return { destroyed: false, effect: 'cutGrass' };
    }

    // Puzzle-signal glitter objects (dungeon glitter_object unlock condition):
    // never destroyed; each hit pulses glitterHit for the lock-condition poll.
    // Distinct from K-room key glitter which IS destroyable (drops a key on death).
    if (this.puzzleSignal) {
      this.glitterHit = true;
      this._playAnimation('shake');
      return { destroyed: false, effect: 'glitterHit' };
    }

    this.hp = Math.max(0, this.hp - amount);

    if (this.data.customSprite) {
      this.damageStage = Math.min(4, Math.floor((this.maxHp - this.hp) / this.maxHp * 5));
    }

    if (this.hp <= 0) {
      // A `depletedColor` object yields its drop once and stays put, spent.
      if (this.data.depletedColor) {
        this.deplete();
        return { destroyed: true, effect: this.data.dropEffect || null };
      }
      this.destroyAfterAnimation = true;
      this._playAnimation('crack');
      return { destroyed: true, effect: this.data.dropEffect || null };
    }

    // Visual damage staging: swap to damagedChar at or below 50% hp
    if (this.data.damagedChar && this.hp / this.maxHp <= 0.5) {
      this.animationChar = this.data.damagedChar;
    }
    this._playAnimation('shake');
    return { destroyed: false, effect: null };
  }

  // Spend a `depletedColor` object in place (Sand scooped): it darkens and
  // becomes inert — indestructible with no HP, so isNonInteractive() holds
  // and no further hit can yield another drop.
  deplete() {
    this.depleted = true;
    this.color = this.data.depletedColor;
    this.animationColor = this.color;
    this.indestructible = true;
    this.hp = null;
    this.maxHp = null;
  }

  // Cut grass: transition from tall grass to cut grass
  cutGrass() {
    if (!this.data.cutState) return;

    const cutChar = this.data.cutState;
    this.char = cutChar;
    this.originalChar = cutChar;
    this.data = BACKGROUND_OBJECTS[cutChar];
    this.animationChar = cutChar;
    this.color = this.data.color;
    this.animationColor = this.color;

    // Update object properties from new data
    this.indestructible = this.data.indestructible || false;
    this.bulletInteraction = this.data.bulletInteraction || 'block';
    this.hp = null; // Cut grass has no HP
    this.maxHp = null;

    this._playAnimation('cutgrass');
  }

  // Open a closed Tomb ('T'): swap to the 't' (Open Tomb) state in place,
  // same char/data/color reassignment shape as cutGrass() above. Unlike
  // every other container, a Tomb is never destroyed — the loot/ghost rolls
  // (InteractionSystem's 'openTomb' effect branch) fire once on this
  // transition, but the object itself persists as inert dungeon dressing.
  openTomb() {
    const openChar = 't';
    this.char = openChar;
    this.data = BACKGROUND_OBJECTS[openChar];
    this.animationChar = openChar;
    this.color = this.data.color;
    this.animationColor = this.color;

    this.indestructible = this.data.indestructible || false;
    this.bulletInteraction = this.data.bulletInteraction || 'block';
    this.hp = null;
    this.maxHp = null;

    this._playAnimation('shake');
  }

  // The Shed Key opening a Shed: its small door ('▄') becomes a full Hut
  // Door ('∩') in place, same reassignment shape as openTomb() above.
  becomeHutDoor() {
    const doorChar = '∩';
    this.char = doorChar;
    this.originalChar = doorChar;
    this.data = BACKGROUND_OBJECTS[doorChar];
    this.animationChar = doorChar;
    this.color = this.data.color;
    this.animationColor = this.color;

    this.indestructible = this.data.indestructible || false;
    this.bulletInteraction = this.data.bulletInteraction || 'block';

    this._playAnimation('shake');
  }

  acceptsInteraction(type) {
    return this.acceptsInteractions.includes('all') || this.acceptsInteractions.includes(type);
  }

  // The one dropChance roll shared by the weapon-destroy path (main.js) and
  // the open-by-hand path (InteractionSystem). A dropsNothing instance never
  // passes. Key droppers always drop —
  // dungeon key skulls are visually identical Bones ('8') with dropChance 0.2,
  // so rolling them would silently lose the run's only key. guaranteedDrop is
  // the same bypass for a placement-time guarantee (Caldera Fire Berry bush).
  passesDropRoll() {
    if (this.dropsNothing) return false;
    if (this.dropsKey || this.dropsDungeonKey || this.guaranteedDrop) return true;
    const chance = this.data.dropChance;
    return chance === undefined || Math.random() < chance;
  }

  // Non-destructive interact (used by unarmed players, shrines, water, etc.)
  interact() {
    const interaction = this.data?.interactions?.default;
    if (!interaction) return { message: null, effect: null, object: this };

    this._playAnimation(interaction.animation);
    return {
      message: interaction.message,
      effect: interaction.effect,
      object: this
    };
  }

  _playAnimation(type) {
    if (this.isNonInteractive()) return; // see isNonInteractive()
    const animData = OBJECT_ANIMATIONS[type];
    if (animData) {
      this.currentAnimation = {
        type,
        data: animData,
        elapsed: 0
      };
    }
  }

  // Briefly tints the object to `color` then reverts — the interaction cue
  // for effects whose highlight color is decided by the caller (e.g. the
  // equipped weapon's own color) rather than one of OBJECT_ANIMATIONS'
  // fixed palettes. Held flat rather than faded so the color reads clearly
  // for the full duration; the currentAnimation machinery above already
  // restores this.color on expiry, same as any other animation ending.
  flashColor(color, duration = 0.25) {
    if (this.isNonInteractive()) return; // see isNonInteractive()
    this.currentAnimation = {
      type: 'flashColor',
      data: { duration, colorFrames: [color, color, color] },
      elapsed: 0
    };
  }

  update(deltaTime) {
    if (this.spawnImmunityTimer > 0) {
      this.spawnImmunityTimer = Math.max(0, this.spawnImmunityTimer - deltaTime);
    }

    // Mana gem pulse animation
    if (this.data.manaGem) {
      this.pulseTimer += deltaTime;
    }

    // Update fire state
    if (this.onFire) {
      this.fireTimer += deltaTime;
      if (this.fireTimer >= this.fireDuration) {
        this.onFire = false;
        this.fireTimer = 0;

        // Grass becomes burned instead of destroyed
        if (this.char === '|' || this.char === ',') {
          this.burnGrass();
        } else {
          this.destroyed = true;
        }
      }
    }

    // Spark accumulation decays if not reinforced within the window — sparks
    // have to land close together to count as "a few concurrent sparks",
    // not slowly add up over an entire fight.
    if (this.sparkStacks > 0) {
      this.sparkTimer -= deltaTime;
      if (this.sparkTimer <= 0) {
        this.sparkStacks = 0;
        this.sparkTimer = 0;
      }
    }

    // Tick water state timer (water only)
    if (this.char === '~' && this.waterState !== 'normal' && this.isWater()) {
      this.waterStateTimer -= deltaTime;
      if (this.waterStateTimer <= 0) {
        this.setWaterState('normal', 0);
      }
    }

    // Apply water state color and char (water only)
    if (this.char === '~' && this.isWater()) {
      if (this.waterState === 'frozen') {
        this.animationChar = '=';
        this.animationColor = WATER_COLORS.frozen;
      } else if (this.waterState === 'electrified') {
        this.animationChar = this.riverFlow ? this._directionChar : '~';
        // Blink between yellow and blue at 0.15s interval
        this.electricBlinkTimer = (this.electricBlinkTimer || 0) - deltaTime;
        if (this.electricBlinkTimer <= 0) {
          this.electricBlinkTimer = 0.15;
          this.electricBlinkOn = !this.electricBlinkOn;
        }
        this.animationColor = this.electricBlinkOn ? '#cccc00' : '#3366ff';
      } else if (this.riverFlow) {
        // River center: hold directional char, animate blue→white traveling wave
        // along flowDir. SPEED cells/sec × per-tile phase offset = a pulse that
        // visibly moves in the current direction.
        this.animationChar = this._directionChar;
        this.electricBlinkTimer = 0;
        this.electricBlinkOn = false;
        this._flowTime += deltaTime;
        const SPEED = 5;   // cells per second
        const PERIOD = 4;  // cells per wave
        const phase = (((this._flowTime * SPEED - this.flowIndex) % PERIOD) + PERIOD) % PERIOD;
        const t = phase / PERIOD;
        const intensity = 0.5 - 0.5 * Math.cos(t * Math.PI * 2); // 0..1, peaks white
        this.animationColor = _lerpHex('#3366ff', '#ffffff', intensity);
      } else {
        this.animationChar = '~';
        this.electricBlinkTimer = 0;
        this.electricBlinkOn = false;
        this.animationColor = this.deepWater ? WATER_COLORS.deep : (WATER_COLORS[this.waterState] || WATER_COLORS.normal);
      }
    }

    // Fountain water shimmer — cycle through wave chars per-tile.
    // Skipped while corrupted/elemental-affected so the underlying state-color shows through.
    if (this.fountainWater && this.waterState === 'normal' && !this.onFire) {
      this._fountainShimmerTimer -= deltaTime;
      if (this._fountainShimmerTimer <= 0) {
        this._fountainShimmerTimer = 0.10 + Math.random() * 0.08;
        const shimmer = ['~', '≈', '˜', '~'];
        this.animationChar = shimmer[Math.floor(Math.random() * shimmer.length)];
      }
    }

    // Fountain waterfall — downward-cycling char animation
    if (this.fountainWaterfall) {
      this._fountainWaterfallTimer -= deltaTime;
      if (this._fountainWaterfallTimer <= 0) {
        this._fountainWaterfallTimer = 0.10;
        const cycle = ['│', '┃', '╿', '╽'];
        this._fountainWaterfallPhase = (this._fountainWaterfallPhase + 1) % cycle.length;
        this.animationChar = cycle[this._fountainWaterfallPhase];
      }
    }

    // Campfire flicker — cycle through flame chars + warm-color jitter
    if (this.isCampfire) {
      this._flickerTimer = (this._flickerTimer || 0) - deltaTime;
      if (this._flickerTimer <= 0) {
        this._flickerTimer = 0.08 + Math.random() * 0.1;
        const chars = ['!', '*', '^', 'i'];
        const colors = ['#ff8822', '#ffaa33', '#ffcc44', '#ff6611'];
        this.animationChar = chars[Math.floor(Math.random() * chars.length)];
        this.animationColor = colors[Math.floor(Math.random() * colors.length)];
      }
    }

    // Leshy shaking bush animation (periodic shake every 3-5 seconds)
    if (this.isShaking) {
      this.shakeTimer += deltaTime;
      const shakeInterval = 3 + Math.random() * 2; // 3-5 seconds
      if (this.shakeTimer >= shakeInterval) {
        this._playAnimation('shake');
        this.shakeTimer = 0;
      }
    }

    if (!this.currentAnimation) return;

    this.currentAnimation.elapsed += deltaTime;
    const progress = this.currentAnimation.elapsed / this.currentAnimation.data.duration;

    if (progress >= 1.0) {
      this.currentAnimation = null;
      this.animationOffset = { x: 0, y: 0 };
      // Restore original char only if not damaged
      if (!this.data.damagedChar || this.hp === null || this.hp / this.maxHp > 0.5) {
        this.animationChar = this.originalChar;
      }
      this.animationColor = this.color;

      if (this.destroyAfterAnimation) {
        this.destroyed = true;
      }
      return;
    }

    const frames = this.currentAnimation.data.frames || this.currentAnimation.data.colorFrames;
    if (!frames) return;

    const frameIndex = Math.floor(progress * frames.length);
    const frame = frames[Math.min(frameIndex, frames.length - 1)];

    if (frame && frame.x !== undefined) {
      this.animationOffset.x = frame.x;
      this.animationOffset.y = frame.y;
    }
    if (frame && frame.char !== undefined) {
      this.animationChar = frame.char;
    }
    if (typeof frame === 'string') {
      this.animationColor = frame;
    }
  }

  getHitbox() {
    return {
      x: this.position.x + this.hitboxOffsetX,
      y: this.position.y + this.hitboxOffsetY,
      width: this.width,
      height: this.height
    };
  }

  getRenderPosition() {
    let color = this.onFire ? '#ff4400' : this.animationColor;
    // Water state color override (in case animationColor was reset by animation end)
    // Electrified is excluded: its per-frame blink value lives in animationColor and must not be replaced
    // Damaging liquids (lava) and mud beds excluded: they use their custom colors, not water colors
    if (!this.onFire && this.isWater() && this.waterState !== 'electrified' && !this.riverFlow) {
      color = (this.deepWater && this.waterState === 'normal') ? WATER_COLORS.deep : (WATER_COLORS[this.waterState] || WATER_COLORS.normal);
      // Frozen water also overrides the char for the static (non-animating) path
      if (this.waterState === 'frozen' && this.animationChar === this.originalChar) {
        return { x: this.position.x, y: this.position.y, char: '=', color };
      }
    }

    // Fountain attunement tint. Applied last so it wins over the water-state
    // colour above, but only while the pool is uncorrupted — once an element
    // actually touches the water, the corruption colour must show through.
    if (this.fountainTint && !this.onFire && this.waterState === 'normal') {
      color = this.fountainTint;
    }

    return {
      x: this.position.x,
      y: this.position.y,
      char: this.animationChar,
      color
    };
  }

  // Used by projectiles (bullets/arrows) — keeps existing bullet interaction logic.
  handleBulletCollision(bullet) {
    // Arrows pass through grass with slight speed decay — grass is not destroyed
    if (bullet.type === 'arrow' && (this.char === '|' || this.char === ',')) {
      this._playAnimation('shake');
      return {
        bulletBehavior: 'slow',
        speedMultiplier: 0.95,
        shouldDestroyBullet: false,
        effect: null,
        message: null,
        object: this
      };
    }

    // Rocks are nigh-indestructible — bullets ricochet with halved remaining range;
    // arrows simply stop. Neither drops M ingredient (only pickaxe/hammer melee can).
    // allWeaponsDamage instances skip this and fall through to the standard
    // bulletInteraction switch below (room generation points them at 'interact-destroy').
    if (this.char === '0' && !this.allWeaponsDamage) {
      this._playAnimation('bounce');
      if (bullet.type === 'bullet') {
        return {
          bulletBehavior: 'rockRicochet',
          effect: null,
          shouldDestroyBullet: false,
          message: null,
          object: this
        };
      }
      return {
        bulletBehavior: 'block',
        effect: null,
        shouldDestroyBullet: true,
        message: null,
        object: this
      };
    }

    // Puzzle-signal fixtures (dungeon puzzle-room switches/hook posts) take a hit from
    // any weapon, not just melee — takeDamage() itself short-circuits on puzzleSignal
    // before any HP mutation, pulsing glitterHit instead (see takeDamage above). Checked
    // ahead of the generic bulletInteraction switch below because these fixtures use
    // unregistered chars ('○'/'•'), which default to bulletInteraction: 'pass-through'
    // and would otherwise never call takeDamage() at all. shouldDestroyBullet: true so a
    // boomerang bounces into return mode off a struck switch exactly like it does off a wall.
    if (this.puzzleSignal) {
      const result = this.takeDamage(1);
      return { bulletBehavior: 'block', effect: result.effect, shouldDestroyBullet: true, message: null, object: this };
    }

    // Barricade Target: a gun's bullet or a bow's arrow breaks a block; any
    // other projectile (staff missile, thrown bolt, boomerang, enemy shot)
    // bounces off it like off a wall.
    if (this.data?.shotOnly) {
      if (!isGunOrBowShot(bullet)) {
        this._playAnimation('bounce');
        return { bulletBehavior: 'block', effect: null, shouldDestroyBullet: true, message: null, object: this };
      }
      const result = this.takeDamage(1, false, { shot: true });
      return { bulletBehavior: 'interact-destroy', effect: result.destroyed ? result.effect : null, shouldDestroyBullet: true, message: null, object: this };
    }

    // Mana gems: indestructible but projectiles pass through and gain affinity
    if (this.data.manaGem) {
      this._playAnimation('flash');
      if (bullet.manaGemCooldownUntil && performance.now() < bullet.manaGemCooldownUntil) {
        return { bulletBehavior: 'pass-through', effect: null, shouldDestroyBullet: false, message: null, object: this };
      }
      const gemColor = this.manaGemColor || this.data.manaGemColor;
      if (gemColor) {
        bullet.affinity = gemColor;
        bullet.manaGemCooldownUntil = performance.now() + 3000;
      }
      return { bulletBehavior: 'pass-through', effect: null, shouldDestroyBullet: false, message: null, object: this };
    }

    // Pass-through and pass-through-slow always win, even for indestructible objects
    if (this.bulletInteraction === 'pass-through' || this.bulletInteraction === 'pass-through-slow') {
      // fall through to switch below
    } else if (this.indestructible) {
      return {
        bulletBehavior: 'block',
        effect: null,
        shouldDestroyBullet: true,
        message: null
      };
    }

    let animation = 'shake';
    let effect = null;
    let bulletBehavior = this.bulletInteraction;
    let shouldDestroyBullet = false;

    switch (this.bulletInteraction) {
      case 'pass-through':
        shouldDestroyBullet = false;
        // Environmental terrain (water, lava, mud, slopes) doesn't shake as
        // if it were a hittable prop — see isEnvironmental().
        animation = this.isEnvironmental() ? null : 'shake';
        break;

      case 'block':
        shouldDestroyBullet = true;
        animation = 'bounce';
        break;

      case 'interact-destroy': {
        shouldDestroyBullet = true;
        // Route through HP system so bullets respect HP too
        const result = this.takeDamage(1);
        if (result.destroyed) {
          effect = result.effect;
        }
        return { bulletBehavior, effect, shouldDestroyBullet, message: null, object: this };
      }

      case 'interact-preserve':
        shouldDestroyBullet = true;
        animation = 'flash';
        if (this.char === '*') { // Crystal
          effect = 'reflectBullet';
        } else {
          const interaction = this.data.interactions['/'];
          if (interaction) effect = interaction.effect;
        }
        break;

      case 'pass-through-slow':
        shouldDestroyBullet = false;
        bulletBehavior = 'slow';
        animation = 'ripple';
        break;
    }

    this._playAnimation(animation);

    return {
      bulletBehavior,
      effect,
      shouldDestroyBullet,
      message: null,
      object: this
    };
  }

  ignite(duration = 5.0) {
    if (this.flammability === 'none') return false;
    if (this.onFire) return true; // Already burning — don't reset the timer
    this.onFire = true;
    // Use custom burn duration if defined, otherwise use provided duration
    this.fireDuration = this.data.burnDuration || duration;
    this.fireTimer = 0;
    return true;
  }

  // Ambient ignition entry point (FireSystem's adjacency spread and
  // burning-entity contact scan) for an object that declares `sparkThreshold`.
  // Accumulates one spark, resetting the concurrency window each time, and
  // only actually ignites once the threshold is reached within it — see the
  // `sparkStacks` field comment. Objects with no threshold ignite immediately
  // (same as calling `ignite()` directly), which is the unchanged behavior
  // for grass and everything else that never opted in. Returns true only on
  // the call that actually ignites, matching `ignite()`'s return contract.
  registerSpark(duration = 5.0) {
    if (!this.sparkThreshold) return this.ignite(duration);
    if (this.flammability === 'none' || this.onFire) return this.onFire;
    this.sparkStacks++;
    this.sparkTimer = SPARK_WINDOW;
    if (this.sparkStacks < this.sparkThreshold) return false;
    this.sparkStacks = 0;
    this.sparkTimer = 0;
    return this.ignite(duration);
  }

  isWater() {
    if (this.destroyed) return false;
    if (this.typeId) return this.typeId === 'water';
    // Legacy: '~' without typeId defaults to water if not lava/mud
    return this.char === '~' && !this.damaging && !this.isDryMud
        && !(this.slowing === true);
  }

  isLava() {
    if (this.destroyed) return false;
    if (this.typeId) return this.typeId === 'lava';
    return this.char === '~' && !!this.damaging;
  }

  // Transform this lava tile into a rock in-place (water quenches lava)
  solidifyToRock() {
    if (!this.isLava()) return;
    this.char = '0';
    this.originalChar = '0';
    this.typeId = null;
    this._variantData = null;
    this.data = BACKGROUND_OBJECTS['0'];
    this.color = '#888888';
    this.animationColor = '#888888';
    this.animationChar = '0';
    this.bulletInteraction = this.data.bulletInteraction || 'interact-preserve';
    this.indestructible = true;
    this.conductivity = 'none';
    this.flammability = 'none';
    this.collisionShape = 'ellipse';
    this.maxHp = 3;
    this.hp = 3;
    // Update hitbox to match rock collision (narrow ellipse, same as constructor)
    this.width = 3;
    this.height = GRID.CELL_SIZE * 0.375;
    this.hitboxOffsetX = 7;
    this.hitboxOffsetY = GRID.CELL_SIZE * 0.3125;
  }

  isMud() {
    if (this.destroyed) return false;
    if (this.typeId) return this.typeId === 'mud_dry' || this.typeId === 'mud_wet';
    return this.char === '~' && (!!this.isDryMud || this.slowing === true);
  }

  // Environmental terrain class — water, lava, mud (all via typeId variants
  // or the legacy '~' fallback data), and Ascent slope tiles (via their
  // hand-built `data`, see RoomGenerator.generateAscentRoom). Distinct from
  // "typical" background objects (rocks, trees, barrels, …): terrain models
  // the floor itself rather than a destructible/interactible prop, so it
  // never participates in the generic hit-reaction/damage-number system —
  // see the isEnvironmental() guard in takeDamage() and handleBulletCollision().
  isEnvironmental() {
    if (this._variantData) return !!this._variantData.environmental;
    return !!this.data?.environmental;
  }

  // Non-interactive class — an object that can be neither changed nor
  // destroyed: indestructible, and declaring `animation: 'none'` as its
  // default interaction, which is how the catalogue says "nothing happens
  // here". Walls, doors, tunnel mouths, chasms, sand, the Barricade plug.
  //
  // Such an object never animates, from any source: not a SPACE interact, not
  // a weapon strike, not a shockwave sweeping past. A reaction is a promise
  // that something can be acted on, and these can't be — a Barricade plug that
  // shakes when hit reads as a wall a big enough hammer would open, which is
  // the one thing it isn't. Enforced in _playAnimation() rather than at each
  // call site so a new animation source can't reopen the hole.
  isNonInteractive() {
    return this.indestructible && this.data?.interactions?.default?.animation === 'none';
  }

  // Used by CombatSystem to decide whether fire should suppress impact effects
  // and produce steam instead
  steamOnFire() {
    if (this._variantData) return !!this._variantData.steamOnFire;
    return this.isWater(); // legacy
  }

  setWaterState(state, duration, electricCurrent = null) {
    if (!this.isWater()) return; // Only real water supports water states
    // A Lead — the hole a Frosted Maw Breach punches in its frozen lake — never
    // closes again; the depleting floor is the whole point of that phase. The
    // guard lives here because freezing has seven entry points (boss ice stream,
    // player freeze weapons, traps, WaterLavaHitMechanic, the Freeze-Over sweep),
    // and the boss's own ice stream would otherwise repair the floor it is
    // destroying. Thawing a Lead is always allowed.
    if (this.isLead && state === 'frozen') return;
    // Ice is solid — nothing soaks into it. A frozen tile can only thaw (or be
    // refrozen); poison and charge both need liquid water to take.
    // ElectricitySystem already checked for this at its own call site, but
    // the poison paths (melee, projectile) did not, so a poison melee swing turned the Frosted Maw's
    // Freeze-Over sheet into a pool that then expired back to open water.
    // Guarded here for the same reason as the Lead above: one gate, not one
    // check per entry point.
    if (this.waterState === 'frozen' && state !== 'frozen' && state !== 'normal') return;
    this.waterState = state;
    this.waterStateTimer = duration;
    this.electricCurrent = state === 'electrified' ? electricCurrent : null;
    // conductivity handled by isConductive() checking waterState — no mutation needed
  }

  getWaterState() { return this.waterState; }

  isFlammable() {
    return this.flammability !== 'none';
  }

  isConductive() {
    if (this._variantData) {
      if (this._variantData.conductivity === 'none') return false;
      if (this.waterState === 'frozen') return false;
      return true;
    }
    // Legacy: frozen water loses conductivity
    if (this.char === '~' && this.waterState === 'frozen') return false;
    return this.conductivity !== 'none';
  }

  static createVariant(typeId, x, y, variantOverrides = {}) {
    const base = BACKGROUND_OBJECT_VARIANTS[typeId];
    if (!base) {
      console.warn(`BackgroundObject.createVariant: unknown typeId '${typeId}'`);
      return new BackgroundObject('~', x, y);
    }
    const obj = new BackgroundObject(base.char, x, y, {
      typeId,
      variantOverrides: Object.keys(variantOverrides).length ? variantOverrides : undefined
    });
    // Apply any color override to both color slots
    if (variantOverrides.color) {
      obj.color = variantOverrides.color;
      obj.animationColor = variantOverrides.color;
    } else {
      obj.color = base.color;
      obj.animationColor = base.color;
    }
    return obj;
  }

  // Burn grass: keep as cut grass but change color to burned
  burnGrass() {
    if (this.char !== '|' && this.char !== ',') return;

    // Convert to cut grass if tall grass
    if (this.char === '|') {
      this.char = ',';
      this.originalChar = ',';
      this.data = BACKGROUND_OBJECTS[','];
      this.bulletInteraction = this.data.bulletInteraction || 'block';
    }

    // Set burned color and make non-flammable
    this.color = '#443322';
    this.animationColor = '#443322';
    this.animationChar = ',';
    this.flammability = 'none'; // Burnt grass cannot ignite again
    this.burnt = true; // Mark as burnt for clarity
  }

  // Check if this object blocks vision
  blocksVision() {
    return this.data.blocksVision || false;
  }

  // Check if this object slows movement
  slowsMovement() {
    return this.data.slowing || false;
  }
}
